INSERT INTO `chauffeur_config` (`id`, `eyebrow`, `heading`, `subhead`, `route_label`, `route_title`, `vehicle_image`, `specs_eyebrow`, `card_title`, `airport_title`, `airport_desc`, `shuttle_title`, `shuttle_desc`, `vehicle_type_title`, `vehicle_type_desc`, `passenger_luggage_title`, `passenger_luggage_desc`, `amenities_note`, `cta_request_label`, `cta_add_booking_label`, `spec_items_json`, `created_at`, `updated_at`, `updated_by`, `extras_json`) VALUES (1, 'VIP Chauffeur & Transfers', 'ARRIVE. RELAX. WE\'LL TAKE CARE OF THE REST.', 'From the moment your flight touches down in Zanzibar, our private chauffeur service ensures your transition to Zanzirangi House is completely effortless, serene, and secure.', 'Abeid Amani Karume Int\'l (ZNZ) ➔ Zanzirangi House', 'Private Coastal Chauffeur Service', '/uploads/IMG_1823_1790845688338_3e6a1851.jpeg', 'Transfer Specifications', 'Private Sanctuary Chauffeur', 'Airport Transfer', 'Direct tarmac welcome and luggage assistance upon arrival.', 'Private Shuttle', 'Exclusive vehicles reserved solely for your traveling party.', 'VEHICLE TYPE', 'Executive SUV / Luxury Van (Details available on request)', 'PASSENGER & LUGGAGE', 'Tailored to group size (Details available on request)', 'Complimentary chilled mineral water, cool hand towels, and high-speed in-car Wi-Fi provided for every transfer.', 'REQUEST AIRPORT TRANSFER', 'ADD TO BOOKING', '[{\"id\":\"spec-1\",\"type\":\"airport\",\"title\":\"Airport Transfer\",\"description\":\"Direct tarmac welcome and luggage assistance upon arrival.\",\"icon\":\"Plane\",\"order\":1,\"visible\":true},{\"id\":\"spec-2\",\"type\":\"shuttle\",\"title\":\"Private Shuttle\",\"description\":\"Exclusive vehicles reserved solely for your traveling party.\",\"icon\":\"Car\",\"order\":2,\"visible\":true},{\"id\":\"spec-3\",\"type\":\"vehicle_type\",\"title\":\"VEHICLE TYPE\",\"description\":\"Executive SUV / Luxury Van (Details available on request)\",\"icon\":\"Car\",\"order\":3,\"visible\":true},{\"id\":\"spec-4\",\"type\":\"passenger_luggage\",\"title\":\"PASSENGER & LUGGAGE\",\"description\":\"Tailored to group size (Details available on request)\",\"icon\":\"Users\",\"order\":4,\"visible\":true}]', '2026-09-30 17:56:16', '2026-10-01 02:08:40', 'info@zanzirangihouse.com', '{\"visible\":true,\"vehicleImageAlt\":\"\",\"vehicleSubline\":\"\",\"passengerSubline\":\"\",\"whatsappMessage\":\"\"}');
