INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'chauffeur', 'amenitiesNote', 'مياه معدنية مبرّدة ومناشف يد باردة مجانية، وواي فاي عالي السرعة داخل السيارة في كل رحلة نقل.', 'Complimentary chilled mineral water, cool hand towels, and high-speed in-car Wi-Fi provided for every transfer.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
