INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'chauffeur', 'subhead', 'منذ لحظة هبوط رحلتك في زنجبار، تضمن خدمة السائق الخاص لدينا انتقالك إلى Zanzirangi House بكل سهولة وهدوء وأمان.', 'From the moment your flight touches down in Zanzibar, our private chauffeur service ensures your transition to Zanzirangi House is completely effortless, serene, and secure.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
