INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[arabic].description', 'احتفاء بإرث زنجبار العُماني الملكي الممتد لقرون وبطرق التجارة البحرية العربية. تذوّق لحومًا متبّلة مطهوّة ببطء، وخبزًا من الفرن الطيني، ومازة باردة وساخنة شهية، وأطباق أرز عطرية بالزعفران، وحلويات بماء الورد يُعدّها كبار الطهاة.', 'A celebration of Zanzibar’s centuries-old royal Omani heritage and Arabian sea routes. Savor slow-braised spiced meats, clay-oven flatbreads, exquisite cold and hot mezze, fragrant saffron-infused rice dishes, and sweet rosewater delicacies prepared by master chefs.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[arabic].name', 'المطبخ العربي والعُماني الأصيل', 'Authentic Arabic & Omani Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[arabic].signatureDishes[#0].description', 'لحم ضأن طري مطهو ببطء لمدة 24 ساعة مع القرنفل والهيل والكزبرة واللومي وأوراق الموز، يُقدَّم على أرز الكبسة الذهبي العطِر بالزعفران.', 'Tender lamb slow-cooked for 24 hours with cloves, cardamom, coriander, dry lime, and banana leaves, served over fragrant golden saffron Kabsa rice.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[arabic].signatureDishes[#0].name', 'شُوا عُماني: لحم ضأن متبّل مشوي ببطء', 'Omani Shuwa Spiced Slow-Roasted Lamb', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[arabic].signatureDishes[#1].description', 'حمّص مخملي مزيّن بدبس الرمان، ومتبّل مدخّن، وفلافل مقرمشة بالأعشاب، وخبز عربي مخبوز يدويًا على الحطب.', 'Velvety pomegranate-drizzled hummus, smoky Mutabal, crispy herbed falafel, and handmade wood-fired Arabic flatbreads.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[arabic].signatureDishes[#1].name', 'مازة ملكية وخبز بالزعتر الطازج', 'Royal Mezze & Fresh Za’atar Khubz', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[arabic].signatureDishes[#2].description', 'روبيان جامبو من خليج ميناي مشوي على الفحم، وحبّار، وصيد الشعاب المتبّل بفلفل حلب والسماق والثوم والأعشاب البرية.', 'Charcoal-grilled Menai Bay jumbo prawns, calamari, and reef catch seasoned with Aleppo pepper, sumac, garlic, and wild herbs.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[arabic].signatureDishes[#2].name', 'طبق مشاوي بحرية مع ليمون مشوي', 'Mashwi Seafood & Charred Lime Platter', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[arabic].signatureDishes[#3].description', 'عجينة فيلو رقيقة هشّة بطبقات من الفستق المحمّص وقطر زهر البرتقال بالهيل، تُقدَّم مع مهلبية الحليب بماء الورد المبرّدة.', 'Delicate flaky filo pastry layered with toasted pistachios and orange-blossom cardamom syrup alongside chilled rosewater milk pudding.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[arabic].signatureDishes[#3].name', 'بقلاوة دافئة بالفستق ومهلبية بماء الورد', 'Warm Pistachio Baklava & Rosewater Muhallabia', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[arabic].subtitle', 'إرث عُماني ملكي، ومشاوي الفرن الطيني، ومازة شرق أوسطية', 'Royal Omani Heritage, Clay-Oven Grills & Middle Eastern Mezze', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[arabic].tabLabel', 'عربي', 'Arabic', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[beverages].description', 'برنامج مشروبات راقٍ صُمّم للاستمتاع الاستوائي. استمتع بأنبذة عالمية المستوى من القبو، وعصائر زنجبار الاستوائية النقية المعصورة على البارد، ومشروبات نباتية غازية من صنع المنزل، ومياه معدنية فاخرة نقية تُقدَّم على الشاطئ أو بجانب المسبح.', 'An elevated beverage program curated for tropical indulgence. Enjoy world-class cellar vintages, pure cold-pressed Zanzibar tropical juices, house-crafted botanical soft drinks, and premium pristine mineral waters served beachfront or poolside.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[beverages].name', 'المشروبات والقبو والمرطّبات', 'Beverages, Cellar & Refreshments', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[beverages].signatureDishes[#0].description', 'مجموعات من العالمَين القديم والجديد، وشينين بلان وسوفينيون بلان المنعشان من جنوب أفريقيا، وشمبانيا فرنسية أنيقة، وأنبذة حمراء غنية من توسكانا وبوردو.', 'Old and New World collections, crisp South African Chenin Blanc & Sauvignon Blanc, elegant French Champagnes, and full-bodied Tuscan & Bordeaux reds.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[beverages].signatureDishes[#0].name', 'أنبذة وشمبانيا مختارة من القبو (النبيذ)', 'Curated Cellar Wines & Champagne (Wines)', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[beverages].signatureDishes[#1].description', 'فاكهة الشغف الناضجة تحت الشمس، ومانجو ألفونسو الحلوة، والأناناس المهروس بالنعناع الطازج، وماء جوز الهند الملكي الطازج من بساتين النخيل الساحلية مباشرةً.', 'Sun-ripened passion fruit, sweet Alfonso mango, crushed pineapple with fresh mint, and young King coconut water straight from coastal palm groves.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[beverages].signatureDishes[#1].name', 'رحيق زنجبار الاستوائي المعصور على البارد (العصائر)', 'Cold-Pressed Zanzibar Tropical Nectars (Juice)', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[beverages].signatureDishes[#2].description', 'بيرة زنجبيل لاذعة من صنع المنزل بعشبة الليمون المهروسة، ومشروب كركديه تنزاني فوّار منعش، وتونيك نباتي حِرفي، ومشروبات غازية كلاسيكية مثلّجة.', 'House-brewed fiery ginger beer with crushed lemongrass, sparkling Tanzanian hibiscus cooler, craft botanical tonics, and classic iced sodas.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[beverages].signatureDishes[#2].name', 'مشروبات غازية وتونيك نباتية محضّرة يدويًا (المشروبات الغازية)', 'Artisanal Botanical Sodas & Tonics (Soft Drinks)', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[beverages].signatureDishes[#3].description', 'مياه ينابيع فاخرة عادية وفوّارة من أوروبا وشرق أفريقيا، تُقدَّم شديدة البرودة مع خيار الحديقة الطازج والنعناع وليمون ماكوندوتشي.', 'Still and sparkling premium European & East African spring waters served crystal chilled with fresh garden cucumber, mint, and Makunduchi lime.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[beverages].signatureDishes[#3].name', 'مياه معدنية نقية (المياه)', 'Pristine Mineral Waters (Waters)', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[beverages].subtitle', 'نبيذ فاخر من القبو، وعصائر طازجة، ومشروبات غازية، ومياه معدنية', 'Fine Cellar Wines, Fresh Juices, Soft Drinks & Mineral Waters', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
