INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[fusion].description', 'بصمتنا في عالم الطهي. حوار مبدع بين التقنيات الفرنسية الكلاسيكية وثراء توابل زنجبار الاستثنائي. ترقّب تناغمات مثل زبدة الكركند المنكّهة بحبوب الفانيلا، وصلصات التمر الهندي المركّزة، وسوفليه فاكهة الشغف.', 'Our culinary signature. An imaginative dialogue between classical French technique and Zanzibar’s extraordinary spice terroir. Expect harmonious pairings like vanilla bean infused lobster butter, tamarind reductions, and passion fruit soufflés.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[fusion].name', 'المطبخ السواحيلي المعاصر المدمج', 'Swahili Contemporary Fusion', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[fusion].signatureDishes[#0].description', 'كركند حلو طري مطهو في زبدة فرنسية مصفّاة معطّرة بقرون فانيلا بيمبا الفوّاحة، مع مستحلب البطاطا الحلوة وهليون البحر.', 'Sweet succulent lobster poached in clarified French butter scented with fragrant Pemba vanilla pods, sweet potato emulsion, and sea asparagus.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[fusion].signatureDishes[#0].name', 'كركند صخري مطهو بالزبدة مع فانيلا بيمبا', 'Butter-Poached Rock Lobster with Pemba Vanilla', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[fusion].signatureDishes[#1].description', 'صدر بط ماغريه بجلد مقرمش يُقدَّم متوسط النضج مع صلصة لامعة من زهرة الكركديه الحامضة وجزر صغير محمّص وهريس الكسافا المتبّل.', 'Crispy skin Magret duck breast served medium rare with a tart hibiscus flower glaze, roasted baby carrots, and spiced cassava purée.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[fusion].signatureDishes[#1].name', 'صدر بط محمّر بالتمر الهندي والكركديه', 'Seared Duck Breast with Tamarind & Hibiscus', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[fusion].signatureDishes[#2].description', 'كعكة شوكولاتة داكنة 70% بقلب ذائب ومعطّرة بالهيل الأخضر، تُقدَّم مع جيلاتو جوز الهند المصنوع في المنزل وصلصة فاكهة الشغف.', 'Molten dark 70% chocolate cake perfumed with green cardamom, served with house-spun coconut gelato and passionfruit coulis.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[fusion].signatureDishes[#2].name', 'فوندان شوكولاتة فالرونا بهيل زنجبار', 'Valrhona Chocolate & Zanzibar Cardamom Fondant', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[fusion].subtitle', 'حيث تلتقي الجزيرة الاستوائية بالمطبخ الفرنسي الراقي الحديث', 'Where Tropical Island Meets Modern French Haute Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[fusion].tabLabel', 'مدمج', 'Fusion', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[local].description', 'تلاقت قرون من التجارة البحرية العربية والفارسية والهندية والشرق أفريقية في مطابخ زنجبار الساحلية. يُعدّ كبار طهاتنا وصفات عريقة بحليب جوز الهند المعصور طازجًا والهيل العطِر وقرنفل بيمبا والمأكولات البحرية المصطادة بالخيط والتي تصل مباشرةً إلى شواطئنا.', 'Centuries of Arab, Persian, Indian, and East African maritime trade converged in Zanzibar’s coastal kitchens. Our executive chefs prepare time-honored recipes featuring freshly harvested coconut milk, aromatic cardamom, cloves from Pemba, and line-caught seafood brought straight to our shores.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[local].name', 'المطبخ السواحيلي الأصيل', 'Authentic Swahili Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[local].signatureDishes[#0].description', 'سمك نهّاش بري من الشعاب محمّر في المقلاة ومطهو على نار هادئة مع الكزبرة الخضراء الطازجة والكركم المطحون بالحجر وحليب جوز الهند الساحلي المعصور يدويًا، يُقدَّم مع أرز الزعفران.', 'Pan-seared wild reef snapper simmered with fresh green coriander, stone-ground turmeric, and hand-squeezed coastal coconut milk served with saffron rice.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[local].signatureDishes[#0].name', 'سمك النهّاش الزنجباري من الشعاب المرجانية بجوز الهند والكركم', 'Zanzibari Coral Reef Snapper in Coconut & Turmeric', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[local].signatureDishes[#1].description', 'مرق حامض منعش من المانجو والتمر الهندي مطهو على نار هادئة مع روبيان طري ورقائق كسافا متبّلة وسامبال جوز الهند بالفلفل الحار المجروش.', 'A tangy, slow-simmered mango and tamarind broth with tender prawns, spiced cassava crisps, and crushed chili coconut sambal.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[local].signatureDishes[#1].name', 'أوروجو التنزاني ويخنة الروبيان النمر', 'Tanzanian Urojo & Tiger Prawn Stew', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[local].signatureDishes[#2].description', 'لحم ضأن محلي شديد الطراوة منكّه باليانسون النجمي وأعواد القرفة والهيل الأسود، يُقدَّم مع سلطة الكاتشومباري المخللة.', 'Fork-tender local lamb infused with star anise, cinnamon quills, and black cardamom, accompanied by pickled kachumbari salad.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[local].signatureDishes[#2].name', 'لحم ماعز مطهو ببطء بتوابل البيلاو', 'Slow-Braised Goat with Pilau Spices', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[local].subtitle', 'نكهات تراثية وتوابل زنجبار', 'Heritage Flavors & Zanzibar Spices', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[local].tabLabel', 'سواحيلي', 'Swahili', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[western].description', 'صُمّم لأذواق الضيوف الدوليين الباحثين عن نكهات مألوفة مريحة تُحضَّر بأرقى تقنيات المطاعم الفاخرة. قطع لحم بقري مستوردة ممتازة، وسلطات متوسطية طازجة، ومعكرونة منزلية مصنوعة يدويًا، وحلويات فاخرة تُنفَّذ بدقة طهوية متقنة.', 'Designed for international palates seeking comforting familiarity prepared with the highest fine-dining techniques. Prime imported beef cuts, fresh Mediterranean salads, homemade handmade pasta, and decadent desserts executed with crisp culinary precision.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[western].name', 'فن الطهي الغربي العصري', 'Modern Western Gastronomy', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[western].signatureDishes[#0].description', 'مشوي على الفحم إلى حدّ الكمال، يُقدَّم مع موسلين الجزر الأبيض الناعم وطماطم الكرمة المحمّصة وصلصة نبيذ أحمر مركّزة على مدى 24 ساعة.', 'Char-grilled to perfection, paired with smooth parsnip mousseline, blistered vine tomatoes, and a 24-hour reduced red wine jus.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[western].signatureDishes[#0].name', 'فيليه واغيو ممتاز بصلصة الكمأة', 'Prime Wagyu Tenderloin with Truffle Glaze', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[western].signatureDishes[#1].description', 'تونة محلية مصطادة بالخيط مقطّعة مع أفوكادو هاس وزيت زيتون معصور على البارد وثمار الكبر ورقائق خبز العجين المخمّر المخبوز في المنزل.', 'Line-caught local tuna diced with Hass avocado, cold-pressed olive oil, caper berries, and house-baked sourdough crisps.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[western].signatureDishes[#1].name', 'تارتار التونة البرية صفراء الزعانف مع الأفوكادو', 'Wild Yellowfin Tuna Tartare with Avocado', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[western].signatureDishes[#2].description', 'معكرونة بيض طازجة مع ذيل الكركند الصخري الحلو من كيزيمكازي، وثوم كونفي، وطماطم كرزية صغيرة، وبيسك خفيف بنبيذ بينو غريجيو.', 'Fresh egg pasta tossed with sweet Kizimkazi rock lobster tail, garlic confit, baby cherry tomatoes, and a light Pinot Grigio bisque.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'categories[western].signatureDishes[#2].name', 'تالييوليني مصنوعة يدويًا مع الكركند الصخري', 'Handmade Tagliolini with Rock Lobster', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
