INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'gardenBadge', 'حديقة المنتجع', 'Estate Garden', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'gardenDesc', 'تختبئ داخل أراضي Zanzirangi House حديقتنا النباتية الخاصة، حيث يزرع فريق مطبخنا عشبة الليمون العضوية والفلفل الأخضر والريحان البري والنعناع الحلو والهيل العطِر والخضروات الموسمية. وما يُقطف صباحًا يصوغ مباشرةً قوائم التذوّق اليومية لدينا، ليجمع حيوية خيرات الأرض مع صيد مياه جنوب زنجبار الطازج.', 'Tucked within the grounds of Zanzirangi House is our private botanical garden, where our kitchen team cultivates organic lemongrass, green chilies, wild basil, sweet mint, fragrant cardamom, and seasonal vegetables. What is harvested in the morning directly shapes our daily tasting menus, pairing earth-grown vitality with the fresh catch of southern Zanzibar’s waters.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'gardenEyebrow', 'حكايات الطهي', 'Culinary Storytelling', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'gardenTitle', 'من حديقتنا إلى مائدتك', 'FROM OUR GARDEN TO YOUR TABLE', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'heading', 'تذوّق زنجبار', 'TASTE ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'intro', 'تلتقي على موائدنا قرون من التجارة البحرية السواحيلية والعُمانية وتجارة المحيط الهندي. من الأسماك المصطادة بالخيط والتي تصل إلى الشاطئ مع شروق الشمس إلى أطباق الكاري العطرية المطهوّة على نار هادئة، يُعدّ تناول الطعام في Zanzirangi House رحلة حسيّة أصيلة.', 'Centuries of Swahili, Omani, and Indian Ocean sea trade come together at our tables. From line-caught fish brought ashore at sunrise to slow-simmered aromatic curries, dining at Zanzirangi House is an authentic sensory journey.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'moments[#0].desc', 'بابايا استوائية، وكريمة فاكهة الشغف، وبريوش دافئ مخبوز طازجًا، وقهوة تنزانية بالتوابل، تُقدَّم مع إطلالة على المحيط في الصباح.', 'Tropical papaya, passion fruit curds, warm freshly-baked brioche, and spiced Tanzanian coffee served overlooking the morning ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'moments[#0].time', '07:00 – 10:30 صباحًا', '07:00 – 10:30 AM', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'moments[#0].title', 'إفطار محضّر يدويًا', 'Artisanal Breakfast', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'moments[#1].desc', 'تارتار التونة صفراء الزعانف المصطادة بالخيط، وسلطات الكركند الصخري، وخبز مسطّح مخبوز على الحطب، وماء جوز الهند الملكي الطازج تحت ظلال النخيل.', 'Line-caught yellowfin tuna tartare, rock lobster salads, wood-fired flatbreads, and young King coconut water under the palms.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'moments[#1].time', '12:30 – 03:30 مساءً', '12:30 – 03:30 PM', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
