INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'moments[#2].desc', 'رقائق الموز المقرمشة، وروبيان بالتمر الهندي المتبّل، ونبيذ من قبونا، وكوكتيلات نباتية محضّرة يدويًا بينما يتلوّن أفق المحيط بالبنفسجي.', 'Crisp plantain crisps, spiced tamarind prawns, cellar wines, and handcrafted botanical cocktails as the ocean horizon turns violet.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
