INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'moments[#3].desc', 'أطباق كاري زنجبارية بجوز الهند مطهوّة على نار هادئة، ولحم ضأن مطهو ببطء بالتوابل العُمانية، وفوندان شوكولاتة فالرونا بالهيل.', 'Slow-simmered Zanzibari coconut curries, Omani spiced braised lamb, and Valrhona chocolate cardamom fondants.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
