INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'dining', 'tagZeroMiles', '🌱 من المزرعة مباشرةً دون مسافات', '🌱 Zero Food Miles', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-cultural].description', 'زُر قرية الصيد التاريخية في كيزيمكازي ومسجد ديمباني العريق (الذي يعود إلى عام 1107 م). التقِ كبار الحرفيين المحليين وهم ينحتون المراكب الشراعية التقليدية يدويًا، وشارك في ورشة طهي سواحيلية، أو استمتع بأمسية خاصة من موسيقى الطرب بالكمان والقانون تحت نجوم الليل.', 'Visit the historic Kizimkazi fishing settlement and the ancient Dimbani Mosque (dating to 1107 AD). Meet local master craftsmen carving traditional dhows by hand, participate in a Swahili culinary workshop, or enjoy private taarab violin and kanun music under the night stars.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-cultural].duration', '3.5 ساعات (توقيت حسب الطلب)', '3.5 Hours (Custom Timing)', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-cultural].priceNote', 'السعر عند الطلب', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-cultural].shortDescription', 'تفاعل بأصالة مع الحرفيين المحليين على الساحل، وتعلّم نسج سعف النخيل وترميم المراكب الشراعية، واكتشف الإرث السواحيلي العريق.', 'Engage authentically with local coastal artisans, learn palm-weaving and dhow restoration, and discover ancient Swahili heritage.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-cultural].tag', 'تجارب ثقافية', 'Cultural Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-cultural].title', 'التقاليد السواحيلية وأنغام الطرب وحياة القرية', 'Swahili Traditions, Taarab & Village Life', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-cultural].whatsappMessage', 'مرحبًا كونسيرج Zanzirangi House، أودّ معرفة المزيد عن التجارب الثقافية السواحيلية.', 'Hello Zanzirangi House Concierge, I would like to learn more about Swahili Cultural Experiences.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-dolphins].description', 'يمنحنا موقعنا في كيزيمكازي على الساحل الجنوبي لزنجبار وصولًا مباشرًا إلى أشهر محمية للدلافين في شرق أفريقيا. انطلق عند الفجر على متن مركب شراعي خاص أو قارب آلي لمشاهدة أسراب الدلافين وهي تلهو في موطنها الطبيعي، ثم عُد للاستمتاع بالإفطار في المنتجع.', 'Our location in Kizimkazi on Zanzibar’s southern coast provides direct access to East Africa’s most famous dolphin sanctuary. Depart at dawn on a private dhow or motor launch to watch dolphin pods playing in their natural ocean habitat before enjoying breakfast back at the property.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-dolphins].duration', '3.5 ساعات (رحلة باكرة عند الفجر)', '3.5 Hours (Early Morning Dawn Cruise)', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-dolphins].priceNote', 'السعر عند الطلب', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-dolphins].shortDescription', 'أبحر مع شروق الشمس من كيزيمكازي إلى المياه المحمية في خليج ميناي لتشاهد أسراب الدلافين الدوّارة والدلافين قارورية الأنف المقيمة.', 'Set sail at sunrise from Kizimkazi into the protected waters of Menai Bay to witness pods of resident spinner and bottlenose dolphins.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-dolphins].tag', 'تجربة الدلافين', 'Dolphin Experience', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-dolphins].title', 'لقاء الدلافين البرية في كيزيمكازي', 'Kizimkazi Wild Dolphin Encounter', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-dolphins].whatsappMessage', 'مرحبًا كونسيرج Zanzirangi House، أودّ خوض تجربة لقاء الدلافين البرية في كيزيمكازي.', 'Hello Zanzirangi House Concierge, I would like to experience the Kizimkazi Wild Dolphin Encounter.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-fishing].description', 'على متن قارب صيد رياضي مستأجر للمياه البعيدة ومجهّز بأذرع صيد جانبية ومعدات Shimano وأحدث الإلكترونيات الملاحية، عِش حماس صيد الأسماك الكبيرة في التيارات العميقة للمحيط الهندي. نلتزم التزامًا صارمًا ببروتوكولات الصيد والإطلاق لأسماك الخرمان.', 'Aboard our chartered offshore sportfisher equipped with outriggers, Shimano tackle, and modern nautical electronics, experience the adrenaline of big game fishing in the deep currents of the Indian Ocean. Strictly adheres to catch-and-release protocols for billfish.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-fishing].duration', 'نصف يوم (5 ساعات) أو يوم كامل (8 ساعات)', 'Half Day (5 Hours) or Full Day (8 Hours)', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-fishing].priceNote', 'السعر عند الطلب', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-fishing].shortDescription', 'انطلق إلى أعماق قناتي بيمبا وزنجبار لتجربة صيد رياضي عالمي المستوى تستهدف التونة صفراء الزعانف وسمك الشراع والواهو.', 'Venture into the deep Pemba and Zanzibar channels for world-class sport fishing targeting yellowfin tuna, sailfish, and wahoo.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-fishing].tag', 'صيد أعماق البحر', 'Deep Sea Fishing', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
