INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-fishing].whatsappMessage', 'مرحبًا كونسيرج Zanzirangi House، أودّ معرفة تفاصيل رحلات الصيد الرياضي في أعماق البحر.', 'Hello Zanzirangi House Concierge, I would like details on Deep Sea Sport Fishing trips.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-island-hopping].description', 'ارسم مسارك الخاص عبر المياه الفيروزية في جنوب زنجبار وغربها. انزل على كثبان رملية ناصعة البياض لا تظهر إلا عند الجزر، واسبح في مياه دافئة صافية، وتذوّق غداءً محضّرًا طازجًا من كركند خليج ميناي المشوي والحبّار والفواكه الاستوائية.', 'Chart your own course across the turquoise waters of southern and western Zanzibar. Disembark onto ephemeral powder-white sandbanks that emerge only at low tide, swim in warm crystalline waters, and savor a freshly prepared lunch of grilled Menai Bay lobster, calamari, and tropical fruit.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-island-hopping].duration', 'يوم كامل (قارب سريع خاص)', 'Full Day (Private Speedboat)', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-island-hopping].priceNote', 'السعر عند الطلب', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-island-hopping].shortDescription', 'أبحر إلى جزر مرجانية صغيرة منعزلة غير مأهولة، واسبح في بحيرات مدّ وجزر خالية، واستمتع بغداء من المأكولات البحرية المشوية على كثيب رملي خاص.', 'Cruise to secluded uninhabited coral islets, swim in deserted tidal lagoons, and enjoy a grilled seafood lunch on a private sandbank.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-island-hopping].tag', 'التنقّل بين الجزر', 'Island Hopping', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-island-hopping].title', 'جولة خاصة بين الجزر وسفاري الكثبان الرملية', 'Private Island Hopping & Sandbank Safari', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-island-hopping].whatsappMessage', 'مرحبًا كونسيرج Zanzirangi House، أودّ الاستفسار عن الجولة الخاصة بين الجزر وسفاري الكثبان الرملية.', 'Hello Zanzirangi House Concierge, I would like to inquire about the Private Island Hopping Sandbank Safari.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-mnemba].description', 'تقع جزيرة منيمبا المرجانية قبالة الساحل الشمالي الشرقي لزنجبار، وتشتهر عالميًا ببيئتها البكر تحت الماء. استمتع بالتنقّل بقارب خاص، وغطس سطحي حصري فوق القمم المرجانية، ونزهة فاخرة على الشاطئ يُعدّها طاهينا الخاص.', 'Located off Zanzibar’s northeast coast, Mnemba Atoll is recognized globally for its pristine underwater conditions. Enjoy private boat transfers, exclusive snorkeling over coral pinnacles, and a beachside gourmet picnic arranged by our private chef.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-mnemba].duration', 'رحلة استكشافية خاصة ليوم كامل', 'Full Day Private Expedition', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-mnemba].priceNote', 'السعر عند الطلب', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-mnemba].shortDescription', 'أبحر إلى جوهرة تاج المحميات البحرية في زنجبار: صفاء فيروزي لا يُضاهى، وحدائق مرجانية بكر، وبحيرات السلاحف البحرية.', 'Sail to the crown jewel of Zanzibar marine reserves: unmatched turquoise clarity, pristine coral gardens, and sea turtle lagoons.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-mnemba].tag', 'جزيرة منيمبا', 'Mnemba Island', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
