INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-mnemba].whatsappMessage', 'مرحبًا كونسيرج Zanzirangi House، أودّ حجز الرحلة الاستكشافية إلى محمية جزيرة منيمبا البحرية.', 'Hello Zanzirangi House Concierge, I would like to book the Mnemba Island Marine Sanctuary expedition.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-nature-jozani].description', 'برفقة مرشد طبيعي معتمد من المتنزه الوطني، انطلق في غابات الأخشاب الصلبة العريقة المحمية داخل متنزه جوزاني تشواكا باي الوطني. شاهد جماعات القرود وهي تتأرجح بين الأغصان، وامشِ على الممر الخشبي المرتفع فوق أشجار المانغروف، وتعرّف على النباتات النادرة التي تنفرد بها زنجبار.', 'Led by an authorized national park naturalist, journey into ancient hardwood forests protected within Jozani Chwaka Bay National Park. Observe monkey troops swinging through the canopy, walk the elevated mangrove boardwalk, and learn about the rare flora unique to Zanzibar.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-nature-jozani].duration', '4 ساعات (يُنصح بالصباح)', '4 Hours (Morning Recommended)', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-nature-jozani].priceNote', 'السعر عند الطلب', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-nature-jozani].shortDescription', 'تجوّل في غابة الماهوجني البكر لتلتقي قرد الكولوبس الأحمر الزنجباري المرح المستوطن في الجزيرة.', 'Trek through virgin groundwater mahogany forest to encounter the playful, endemic Zanzibar Red Colobus monkey.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
