INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-nature-jozani].title', 'غابة جوزاني والمحمية البيئية لقرود الكولوبس الحمراء', 'Jozani Forest & Red Colobus Eco-Sanctuary', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-nature-jozani].whatsappMessage', 'مرحبًا كونسيرج Zanzirangi House، أودّ حجز تجربة الطبيعة في غابة جوزاني.', 'Hello Zanzirangi House Concierge, I would like to reserve the Jozani Forest Nature Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-snorkeling-diving].description', 'تزخر الشعاب المرجانية الحاجزة في زنجبار بتنوّع حيوي استوائي مذهل. مزوّدًا بأفضل المعدات الاحترافية وبرفقة مرشدي غوص معتمدين من PADI، اكتشف منحدرات خلّابة وكهوفًا يمكن السباحة عبرها ورؤية صافية تمتد حتى 30 مترًا.', 'Zanzibar’s barrier reefs are teeming with tropical biodiversity. Equipped with top-tier professional gear and accompanied by certified PADI divemasters, discover stunning drop-offs, swim-through caves, and crystal visibility extending up to 30 meters.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-snorkeling-diving].duration', 'رحلة لنصف يوم أو يوم كامل', 'Half Day or Full Day Excursion', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-snorkeling-diving].priceNote', 'السعر عند الطلب', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-snorkeling-diving].shortDescription', 'استكشف حدائق مرجانية نابضة بالألوان وجدرانًا بحرية تحت الماء، والتقِ السلاحف البحرية وأسماك الراي النسرية المرقّطة وأنواعًا غريبة من أسماك الشعاب.', 'Explore vibrant coral gardens, underwater marine walls, and meet sea turtles, spotted eagle rays, and exotic reef species.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-snorkeling-diving].tag', 'الغطس والغوص', 'Snorkeling & Diving', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-snorkeling-diving].title', 'الغطس السطحي في الشعاب المرجانية والغوص العميق', 'Coral Reef Snorkeling & Deep Scuba Diving', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-snorkeling-diving].whatsappMessage', 'مرحبًا كونسيرج Zanzirangi House، أودّ ترتيب رحلة للغطس السطحي والغوص.', 'Hello Zanzirangi House Concierge, I would like to arrange a Snorkeling & Diving excursion.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-spice-farm].description', 'تجوّل برفقة خبراء نبات محليين عبر مزارع ريفية خضراء. المس التوابل الخام واشتمّها وتذوّقها مباشرةً من الأشجار والكروم، ومنها الفلفل الأسود وجوزة الطيب والزنجبيل وعشبة الليمون والكركم، لتختتم رحلتك بماء جوز الهند الملكي الطازج المقطوف من أعالي النخيل.', 'Walk alongside expert local botanists through verdant rural plantations. Touch, smell, and taste raw spices directly from the trees and vines—including black pepper, nutmeg, ginger, lemongrass, and turmeric—concluding with fresh King coconut water harvested high in the canopy.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-spice-farm].duration', '4 ساعات (صباحًا أو بعد الظهر)', '4 Hours (Morning or Afternoon)', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-spice-farm].priceNote', 'السعر عند الطلب', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-spice-farm].shortDescription', 'أطلق العنان لحواسك في قرون من التاريخ العطِر: اقطف القرفة الطازجة، واسحق الهيل الأخضر، وتذوّق حبوب الفانيلا البرية.', 'Immerse your senses in centuries of aromatic history: pluck fresh cinnamon, crush green cardamom, and taste wild vanilla bean.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-spice-farm].tag', 'مزرعة التوابل', 'Spice Farm', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-spice-farm].title', 'رحلة إلى مزرعة التوابل النباتية العضوية', 'Organic Botanical Spice Farm Journey', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-spice-farm].whatsappMessage', 'مرحبًا كونسيرج Zanzirangi House، أنا مهتم برحلة مزرعة التوابل النباتية العضوية.', 'Hello Zanzirangi House Concierge, I am interested in the Organic Botanical Spice Farm Journey.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-stonetown].description', 'رحلة خاصة عبر ستون تاون المدرجة على قائمة اليونسكو للتراث العالمي. برفقة مؤرّخ سواحيلي مقيم، استكشف بيت العجائب، والقلعة القديمة التي تعود إلى القرن السابع عشر، والكاتدرائية الأنجليكانية ونُصب سوق الرقيق القديم، وورش الحرفيين المتخصّصة في المجوهرات الفضية والمنسوجات اليدوية.', 'A private journey through UNESCO World Heritage Stone Town. Led by a resident Swahili historian, explore the House of Wonders, the 17th-century Old Fort, the Anglican Cathedral and Old Slave Market memorial, and artisan workshops specializing in silver jewelry and woven textiles.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-stonetown].duration', 'يوم كامل (سائق ومرشد خاصان)', 'Full Day (Private Chauffeur & Guide)', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-stonetown].priceNote', 'السعر عند الطلب', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-stonetown].shortDescription', 'تجوّل في أزقّة متاهية من حجر المرجان، وبين الأبواب العُمانية المنحوتة من خشب الساج، وأسواق التوابل التاريخية، وقصر السلطان.', 'Walk through labyrinthine coral ragstone alleyways, ornate Omani carved teak doors, historical spice bazaars, and the Sultan’s Palace.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-stonetown].tag', 'الثقافة والتراث', 'Culture & Heritage', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-stonetown].title', 'تراث ستون تاون وأحياؤها التاريخية', 'Stone Town Heritage & Historic Quarters', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-stonetown].whatsappMessage', 'مرحبًا كونسيرج Zanzirangi House، أرغب في حجز تجربة تراث ستون تاون الخاصة.', 'Hello Zanzirangi House Concierge, I am interested in booking the private Stone Town Heritage Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-sunset-cruise].description', 'اصعد على متن مركب شراعي سواحيلي مصنوع يدويًا من خشب الماهوجني المحلي. استرخِ على وسائد وثيرة مع شمبانيا مبرّدة ومقبّلات محضّرة يدويًا، وأصوات نسيم المحيط الساحرة وألحان الطرب الصوتية بينما يتلاشى ضوء النهار في الغسق.', 'Step aboard a handcrafted Swahili sailing dhow carved from indigenous mahogany. Relax upon plush cushions with chilled Champagne, artisanal canapés, and the hypnotic sounds of the ocean breeze and acoustic taarab melodies as daylight fades into dusk.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-sunset-cruise].duration', '2.5 ساعة (الساعة الذهبية في آخر العصر)', '2.5 Hours (Late Afternoon Golden Hour)', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-sunset-cruise].priceNote', 'السعر عند الطلب', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-sunset-cruise].shortDescription', 'انساب فوق المحيط الهندي الهادئ تحت أشرعة قماشية منتفخة، بينما ترسم شمس خط الاستواء السماء بدرجات الكهرمان والذهب الوردي.', 'Glide across the calm Indian Ocean under billowed canvas sails as the equatorial sun paints the sky in shades of amber and rose gold.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-sunset-cruise].tag', 'رحلة الغروب البحرية', 'Sunset Cruise', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-sunset-cruise].title', 'رحلة الغروب على مركب شراعي خشبي تقليدي', 'Traditional Wooden Dhow Sunset Cruise', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'experiences', '[exp-sunset-cruise].whatsappMessage', 'مرحبًا كونسيرج Zanzirangi House، أودّ حجز رحلة غروب خاصة على مركب شراعي.', 'Hello Zanzirangi House Concierge, I would like to book a private Sunset Dhow Cruise.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[bbq].category', 'أمسيات الالتقاء', 'Evening Gathering', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[bbq].description', 'حين تغيب الشمس في المحيط الهندي، اجتمع حول موقد النار على الشاطئ لتتذوّق الكركند المشوي وروبيان النمر وشرائح اللحم المتبّلة المطهوّة على قشور جوز الهند تحت النجوم الأفريقية.', 'As the sun dips into the Indian Ocean, gather around our shoreline firepit for grilled lobster, tiger prawns, and spiced tenderloins cooked over coconut husks under the African constellations.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[bbq].highlight', 'عشاء على ضوء الشموع على شاطئ المحيط مع موسيقى طرب حيّة', 'Oceanfront candlelit dining with live acoustic Taarab music', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
