INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[breakfast].category', 'طقوس الصباح', 'Morning Ritual', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[breakfast].description', 'استيقظ على أطباق الفواكه الاستوائية من البساتين المحلية، والبريوش المخبوز طازجًا، وكريمة فاكهة الشغف، وقهوة الأرابيكا التنزانية، والبيض المطهو حسب رغبتك في فيلتك أو على شاطئ البحر.', 'Awaken to tropical fruit platters from local orchards, freshly baked brioche, passion fruit curd, Tanzanian arabica coffee, and eggs cooked to your preference in your villa or by the sea.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[breakfast].highlight', 'مجاني لجميع النزلاء المقيمين', 'Complimentary for all staying guests', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
