INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[dining].description', 'جناح في الهواء الطلق تحت سقف ماكوتي مقبّب من القش، يوفر إطلالات بانورامية على المحيط. استمتع بتجربة طعام راقية تفوح منها روائح توابل زنجبار وأطازج صيد اليوم.', 'An open-air pavilion beneath vaulted Makuti thatch offering panoramic ocean views. Experience fine dining infused with the aromas of Zanzibar spices and the freshest catches of the day.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[dining].highlight', 'منتجات عضوية من المزرعة إلى المائدة ومأكولات بحرية طازجة يوميًا', 'Farm-to-table organic produce & fresh daily seafood', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
