INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[massage].category', 'العافية الشاملة', 'Holistic Wellness', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[massage].description', 'أجنحة سبا منعزلة في الهواء الطلق بين الحدائق الساحلية. دلّل نفسك بجلسات مساج مصمّمة خصيصًا لك بزيت جوز الهند الزنجباري المعصور على البارد وعشبة الليمون والقرنفل المطحون والنباتات الأفريقية المحلية.', 'Secluded open-air spa salas nestled in coastal gardens. Indulge in bespoke massages using cold-pressed Zanzibar coconut oil, lemongrass, ground cloves, and indigenous African botanicals.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[massage].highlight', 'علاج عطري أصيل بالقرنفل وعشبة الليمون', 'Authentic Clove & Lemongrass Aromatherapy', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
