INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[pool].description', 'يتعلّق مسبحنا اللامتناهي بالمياه العذبة بطول 25 مترًا فوق أمواج المحيط الهندي الفيروزية، ليعكس آفاق السماء والمحيط، مع أسرّة تشمّس غائرة وخدمة متيقّظة بجانب المسبح.', 'Suspended above the turquoise tides of the Indian Ocean, our 25-meter freshwater infinity pool mirrors the sky and ocean horizons with sunken sunbeds and attentive poolside service.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'facilities', '[pool].highlight', 'خادم شخصي مخصّص داخل الفيلا', 'Bespoke In-Villa Butler', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
