INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'homepage', 'hero.description', 'عِش تجربة فلل زنجبار الفاخرة بمسابحها الخاصة في Zanzirangi House بكيزيمكازي؛ ملاذ حميم يضم 8 فلل، يقدّم مأكولات طازجة من البحر إلى المائدة ورحلات مصمّمة خصيصًا لاكتشاف الجزيرة.', 'Experience Zanzibar luxury villas with private plunge pools at Zanzirangi House in Kizimkazi. An intimate 8-villa sanctuary offering ocean-to-table dining and bespoke island journeys.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
