INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'homepage', 'hero.slides[slide-02].description', 'تختبئ بين أشجار الفرانجيباني العطرة ونخيل جوز الهند في جنوب زنجبار، لتمنحك عزلة تامة ودشًا حجريًا في الهواء الطلق وشرفة هادئة تطل على الحديقة.', 'Tucked within fragrant frangipani and coconut palms in southern Zanzibar, offering total seclusion, an open-air stone shower, and serene garden verandah.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
