INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'homepage', 'hero.slides[slide-03].description', 'المقر الأرقى المطل على المحيط في Zanzirangi House، بمسبح لا متناهٍ معلّق وجناح معيشة رحب وعشاء يُعدّه طاهٍ خاص، مع باقات سفاري جوية مباشرة إلى سيرينغيتي.', 'The premier oceanfront residence at Zanzirangi House featuring a suspended infinity pool, expansive living pavilion, private chef dining, and direct Serengeti fly-in safari packages.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
