INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'homepage', 'intro.description', 'Zanzirangi House منتجع بوتيكي فائق الفخامة يضم 8 فلل خاصة بمسابح صغيرة، تنعزل على امتداد الساحل الجنوبي الهادئ لزنجبار في كيزيمكازي ديمباني.', 'Zanzirangi House is an ultra-boutique retreat featuring 8 private plunge-pool villas secluded along the peaceful southern coast of Zanzibar in Kizimkazi Dimbani.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'homepage', 'intro.eyebrow', 'أكثر من مجرد إقامة', 'MORE THAN A STAY', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'homepage', 'intro.title', 'ملاذ حميم بين نسيم المحيط والإرث السواحيلي', 'An intimate sanctuary between the ocean breeze and Swahili heritage', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[about].description', 'يقع Zanzirangi House على الساحل المرجاني الجنوبي البكر في كيزيمكازي ديمباني، وهو ملاذ خاص بوتيكي فائق الفخامة صُمّم ليمنحك عزلة تامة وتناغمًا معماريًا وضيافة زنجبارية حميمة.', 'Nestled along the pristine southern coral coast of Kizimkazi Dimbani, Zanzirangi House is an ultra-boutique private sanctuary designed to offer total seclusion, architectural harmony, and intimate Zanzibar hospitality.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
