INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[about].title', 'عن Zanzirangi House', 'About Zanzirangi House', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[contact].description', 'خطّط لإقامتك المصمّمة خصيصًا لك مع فريق الكونسيرج لدينا. سواء أكان الأمر يتعلق بالتحقق من توفر الفلل الخاصة، أو النقل من مطار ZNZ في رحلة تستغرق 45 دقيقة، أو برامج سفاري مخصّصة في تنزانيا، فنحن في خدمتك على مدار الساعة.', 'Plan your bespoke stay with our concierge team. Whether arranging private villa availability, 45-minute airport transfers from ZNZ, or custom Tanzania safari itineraries, we are available 24/7.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
