INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[dining].description', 'تذوّق إرث زنجبار الأصيل في فنون الطهي، حيث تمتزج التوابل السواحيلية بمأكولات المحيط الهندي البحرية التي يصطادها يوميًا صيادو كيزيمكازي على مراكبهم التقليدية. استمتع بتناول الطعام على شرفتك الخاصة، وحفلات الشواء على الشاطئ، وأمسيات عشاء خاصة على ضوء الشموع تحت النجوم.', 'Taste authentic Zanzibar culinary heritage blending Swahili spices with Indian Ocean seafood caught daily by Kizimkazi artisanal dhow fishermen. Enjoy private veranda dining, beach barbecues, and bespoke candlelit dinners under the stars.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
