INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[experiences].description', 'من لقاءات مسؤولة مع الدلافين البرية في محمية خليج ميناي البحرية إلى جولات خاصة في تراث ستون تاون المدرج على قائمة اليونسكو، ومسارات التوابل العضوية، والإبحار على المراكب الشراعية عند الغروب، اكتشف زنجبار برفقة مرشدينا الخاصين.', 'From ethical wild dolphin encounters in the Menai Bay Marine Reserve to private Stone Town UNESCO heritage tours, organic spice trails, and sunset dhow sailing—experience Zanzibar with our dedicated private guides.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
