INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[page_stay].description', 'اكتشف فللنا البحرية الثماني بمسابحها الخاصة ومساكننا على الشاطئ، المصمّمة بطابع سواحيلي بسيط ومستوحى من الطبيعة.', 'Discover our 8 private plunge pool ocean villas and beachfront residences crafted in organic Swahili minimalism.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
