INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.introText', 'في Zanzirangi House (المتاح عبر https://zanzirangihouse.com/)، نولي حماية البيانات الشخصية لنزلائنا وخصوصيتهم أقصى درجات الأهمية. توضّح سياسة الخصوصية هذه كيفية جمعنا للمعلومات واستخدامها وحمايتها عند زيارتكم لموقعنا الإلكتروني، أو تقديم استفسارات الحجز، أو التواصل مع فريق الكونسيرج لدينا.', 'At Zanzirangi House (accessible from https://zanzirangihouse.com/), safeguarding our guests’ personal data and privacy is of utmost importance. This Privacy Policy details how we collect, use, and protect information when you visit our website, submit booking inquiries, or communicate with our concierge team.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.lastUpdated', 'سبتمبر 2026', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.sections[#0].body', 'عند تقديم استفسار أو حجز فيلا خاصة، قد تزوّدوننا ببيانات تشمل اسمكم الكامل، وعنوان بريدكم الإلكتروني، ورقم الهاتف/واتساب، وتاريخَي الوصول والمغادرة، وعدد أفراد المجموعة، وأي تفضيلات خاصة تتعلق بالضيافة أو النظام الغذائي.', 'When submitting an inquiry or reserving a private villa, you may provide details including your full name, email address, telephone/WhatsApp number, arrival/departure dates, guest party size, and special hospitality or dietary preferences.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.sections[#0].title', '1. المعلومات التي نجمعها', '1. Information We Collect', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.sections[#1].items[#0]', 'تيسير استفسارات الحجز والتحقق من توفر الغرف.', 'Facilitating reservation inquiries and room availability checks.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.sections[#1].items[#1]', 'تنسيق خدمات النقل بسائق خاص من مطار عبيد أماني كرومي الدولي (ZNZ).', 'Coordinating airport chauffeur transfers from Abeid Amani Karume International Airport (ZNZ).', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.sections[#1].items[#2]', 'تخصيص تجارب الطعام الخاصة وجولات مشاهدة الدلافين البحرية وربطها برحلات السفاري في البرّ التنزاني.', 'Customizing private dining, marine dolphin tours, and mainland Tanzania safari connections.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.sections[#1].items[#3]', 'توفير التواصل مع الخادم الشخصي والكونسيرج على مدار الساعة.', 'Providing 24/7 personal butler and concierge communications.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.sections[#1].title', '2. كيفية استخدامنا لمعلوماتكم', '2. How We Use Your Information', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.sections[#2].body', 'نطبّق ضمانات تقنية وإدارية صارمة. ولا نبيع معلومات النزلاء أو نؤجّرها أو نمنح حق استخدامها لشبكات التسويق التجاري التابعة لأطراف ثالثة. ولا تُشارَك البيانات إلا مع مقدّمي الخدمات المحليين المرخّصين (مثل مشغّلي رحلات السفاري الجوية المعتمدين لدى هيئة المتنزهات الوطنية التنزانية TANAPA)، وذلك حصرًا بغرض تنفيذ برنامج رحلتكم المتفق عليه.', 'We implement strict technical and administrative safeguards. We do not sell, rent, or lease guest information to third-party commercial marketing networks. Data is shared exclusively with licensed local service providers (such as official TANAPA safari charter operators) strictly to fulfill your agreed itinerary.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.sections[#2].title', '3. أمن البيانات والإفصاح لأطراف ثالثة', '3. Data Security & Third-Party Disclosure', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.sections[#3].body', 'لأي استفسارات تتعلق بالخصوصية أو لطلب حذف بياناتكم، يُرجى التواصل مباشرةً مع فريق حماية البيانات لدينا عبر concierge@zanzirangihouse.com أو عبر الهاتف الرسمي +255 777 890 123.', 'For any privacy inquiries or to request data removal, contact our data protection team directly at concierge@zanzirangihouse.com or via official telephone at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].contentJson.sections[#3].title', '4. التواصل مع فريق الكونسيرج', '4. Contact Our Concierge', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[privacy].description', 'في Zanzirangi House، نولي حماية البيانات الشخصية لنزلائنا وخصوصيتهم أقصى درجات الأهمية.', 'At Zanzirangi House, safeguarding our guests’ personal data and privacy is of utmost importance.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
