INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[safari].description', 'اجمع بين إقامتك الفاخرة الهادئة في زنجبار ورحلات سفاري عالمية المستوى في البرّ الرئيسي. ننسّق رحلات طيران خاصة مستأجرة مدتها 90 دقيقة مباشرةً إلى متنزه سيرينغيتي الوطني وفوهة نغورونغورو وجبل كليمنجارو، مع الإقامة في أرقى مخيّمات السفاري الفاخرة.', 'Combine your barefoot luxury retreat in Zanzibar with world-class mainland safaris. We coordinate 90-minute private air charters directly to Serengeti National Park, Ngorongoro Crater, and Mount Kilimanjaro with premier luxury safari camps.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
