INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[terms].contentJson.introText', 'مرحبًا بكم في Zanzirangi House. بدخولكم إلى موقعنا الإلكتروني (https://zanzirangihouse.com/) أو تقديم طلبات الإقامة والرحلات، فإنكم توافقون على الالتزام بشروط الضيافة وإرشادات الحجز التالية.', 'Welcome to Zanzirangi House. By accessing our website (https://zanzirangihouse.com/) or submitting accommodation and excursion requests, you agree to comply with the following hospitality terms and reservation guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[terms].contentJson.lastUpdated', 'سبتمبر 2026', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[terms].contentJson.sections[#0].body', 'تتراوح أسعار الفلل لليلة الواحدة بين $390 و$480+ دولار أمريكي، وتشمل استخدام المسبح الخاص والإفطار الفاخر وخدمة الخادم الشخصي المخصّص على مدار الساعة. ويتطلب تأكيد الحجز دفع عربون متفق عليه أو تقديم قسيمة عبر قنوات الحجز الرسمية.', 'Nightly villa rates range between $390 and $480+ USD and include private plunge pool access, gourmet breakfast, and 24/7 dedicated butler service. Confirmation requires an agreed deposit or voucher via official reservation channels.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[terms].contentJson.sections[#0].title', '1. الحجوزات والمدفوعات', '1. Reservations & Payments', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[terms].contentJson.sections[#1].body', 'يبدأ تسجيل الوصول المعتاد من الساعة 14:00 (2:00 مساءً)، ويكون تسجيل المغادرة بحلول الساعة 11:00 (11:00 صباحًا). ويمكن طلب الوصول المبكر أو المغادرة المتأخرة عبر الكونسيرج الشخصي الخاص بكم، وذلك رهنًا بتوفّر الفيلا.', 'Standard check-in is from 14:00 (2:00 PM), and check-out is by 11:00 (11:00 AM). Early arrival or late departure may be requested through your personal concierge, subject to villa availability.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[terms].contentJson.sections[#1].title', '2. مواعيد تسجيل الوصول والمغادرة', '2. Check-In & Check-Out Times', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[terms].contentJson.sections[#2].body', 'يحاذي Zanzirangi House منطقة خليج ميناي للحماية البحرية. ويوافق النزلاء المشاركون في رحلات الإبحار على المراكب الشراعية ومشاهدة الدلافين على اتباع البروتوكولات الأخلاقية للتعامل مع الحياة البرية، والحفاظ على مسافات مناسبة من الكائنات البحرية امتثالًا للأنظمة البيئية المحلية.', 'Zanzirangi House borders the Menai Bay Marine Conservation Area. Guests participating in dhow sailing and dolphin excursions agree to follow ethical wildlife protocols, maintaining respectful distances from marine wildlife in compliance with local environmental regulations.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[terms].contentJson.sections[#2].title', '3. الحفاظ على البيئة البحرية وآداب التعامل مع الحياة البرية', '3. Marine Conservation & Wildlife Etiquette', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[terms].contentJson.sections[#3].body', 'لتعديل الحجز أو إلغائه، يُرجى التواصل مباشرةً مع فريق الكونسيرج عبر البريد الإلكتروني concierge@zanzirangihouse.com أو عبر واتساب على الرقم +255 777 890 123.', 'To modify or cancel a reservation, contact our concierge directly via email at concierge@zanzirangihouse.com or WhatsApp at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[terms].contentJson.sections[#3].title', '4. الاستفسارات والإلغاءات', '4. Inquiries & Cancellations', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[terms].description', 'مرحبًا بكم في Zanzirangi House. بدخولكم إلى موقعنا الإلكتروني أو تقديم طلبات الحجز، فإنكم توافقون على الالتزام بإرشادات الضيافة الخاصة بنا.', 'Welcome to Zanzirangi House. By accessing our website or submitting reservation requests, you agree to comply with our hospitality guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
