INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'pages', '[villas].description', 'اكتشف مساكننا الخاصة الثمانية المصمّمة بحِرفية، والتي تتراوح مساحاتها بين 78 م² و95 م². تتميّز كل فيلا بمسبح خاص بالمياه العذبة بخصوصية تامة 100%، وعمارة سواحيلية أصيلة من حجر المرجان، وخدمة خادم شخصي مخصّص على مدار الساعة.', 'Discover our 8 private artisanal residences ranging from 78 m² to 95 m². Each villa features a 100% private freshwater plunge pool, authentic Swahili coral-stone architecture, and personalized 24/7 dedicated butler service.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
