INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'safari', '[dest-kilimanjaro].description', 'أعلى قمة في أفريقيا وأعلى جبل قائم بذاته في العالم، يرتفع بشموخ 5,895 مترًا فوق السهول الاستوائية. من رحلات الهليكوبتر الخاصة الخلّابة حول قمة أوهورو إلى رحلات المشي النهارية عبر مسارات الغابات المطيرة الخضراء ومزارع القهوة في سفوحه، عِش تجربة تاج تنزانيا الأيقوني.', 'Africa’s highest peak and the world’s tallest free-standing mountain rises majestically 5,895 meters above tropical plains. From scenic private helicopter flights encircling Uhuru Peak to day treks along lush lower rainforest trails and coffee estates, experience Tanzania’s iconic crown.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'safari', '[dest-kilimanjaro].flightTimeFromZanzibar', '1 س 10 د إلى مطار كليمنجارو الدولي', '1h 10m to Kilimanjaro Int’l', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
