INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'safari', '[dest-ngorongoro].bestFor', 'روعة جيولوجية وكثافة عالية للحياة البرية', 'Geological splendor & concentrated wildlife density', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'safari', '[dest-ngorongoro].description', 'أكبر فوهة بركانية سليمة في العالم، تشكّل ملاذًا بيئيًا متكاملًا بعمق 600 متر. انحدر عبر غابات الأكاسيا الضبابية على حافتها إلى مدرّج طبيعي عريق يعجّ بوحيد القرن الأسود المهدّد بالانقراض وأفراس النهر وآلاف طيور الفلامنغو الوردية الخائضة في بحيرة ماجادي.', 'The world’s largest intact volcanic caldera, creating a self-contained ecological haven 600 meters deep. Descend through misty rim acacia forests into an ancient amphitheater bustling with endangered black rhinos, hippos, and thousands of pink flamingos wading in Lake Magadi.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
