INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'safari', '[dest-serengeti].bestFor', 'مشاهدة الخمسة الكبار ومشاهد الحياة البرية المذهلة', 'Big Five sightings & dramatic wildlife spectacles', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'safari', '[dest-serengeti].description', 'سهول سافانا ذهبية شاسعة تمتد بلا نهاية حتى الأفق. شاهد ملايين حيوانات النو والحمر الوحشية وهي تعبر أنهارًا تعجّ بالتماسيح، برفقة قطعان الأسود المقيمة والفهود المنفردة، مع مخيّمات فاخرة في الأدغال تحت سماء استوائية مرصّعة بالنجوم.', 'Vast golden savannahs that stretch endlessly to the horizon. Witness millions of wildebeest and zebras braving crocodile-laden rivers, accompanied by resident prides of lions, solitary leopards, and luxury tented bush retreats under star-strewn equatorial skies.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
