INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'safari', '[dest-tarangire].bestFor', 'مناظر الباوباب ولقاءات حميمة مع الأفيال', 'Baobab landscapes & intimate elephant encounters', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'safari', '[dest-tarangire].description', 'يشتهر بأشجار الباوباب العتيقة العملاقة التي تقف كحرّاس صامتين على امتداد وادي نهر وعر. يحتضن تارانغيري أعلى تجمّع لقطعان الأفيال في شرق أفريقيا، حيث تقود الأمهات المهيبات صغارهن على ضفاف نهر تارانغيري واهب الحياة.', 'Famed for its colossal ancient baobab trees that stand like silent sentinels across a rugged river valley. Tarangire hosts East Africa’s highest concentration of elephant herds, where majestic family matriarchs guide their calves along the life-giving Tarangire River.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
