INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-01].country', 'المملكة المتحدة', 'United Kingdom', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-01].reviewText', 'منذ اللحظة التي استقبلنا فيها سائقنا الخاص في مطار زنجبار وحتى رحلتنا الأخيرة على المركب الشراعي عند الغروب، كان كل تفصيل منسّقًا بإتقان تام. وكان المسبح المطل على مدّ المحيط ساحرًا.', 'From the moment our private chauffeur welcomed us at Zanzibar Airport to our final sunset dhow sail, every detail was orchestrated to absolute perfection. The plunge pool perched over the ocean tide was magical.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-01].stayDate', 'نوفمبر 2025', 'November 2025', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
