INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-01].villaStayed', 'فيلا السلطان المطلة على المحيط', 'Sultan Oceanfront Villa', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-02].country', 'فرنسا', 'France', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-02].reviewText', 'ذكّرنا الطابع المعماري الهادئ، واستخدام حجر المرجان المحلي، وخدمة الخادم الشخصي المتيقّظة والمتكتّمة، بأرقى نُزل Aman أو Singita. وكان عشاء المأكولات البحرية السواحيلي بجوز الهند لا يُنسى.', 'The architectural restraint, use of indigenous coral stone, and attentive but discrete butler service reminded us of the very finest Aman or Singita lodges. The Swahili coconut seafood dinner was unforgettable.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-02].stayDate', 'يناير 2026', 'January 2026', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
