INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-02].villaStayed', 'ملاذ حديقة الماكوتي', 'Makuti Garden Sanctuary', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-03].country', 'السويد', 'Sweden', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-03].reviewText', 'سافرنا كعائلة من خمسة أفراد. إن امتلاكنا لمسبح لا متناهٍ خاص معلّق فوق البحيرة المرجانية، وطاهٍ شخصي يُعدّ لنا صيد اليوم الطازج كل مساء، أعاد تعريف معنى السفر الفاخر بالنسبة إلينا.', 'We traveled as a family of five. Having our own private infinity pool suspended above the coral lagoon and our personal chef preparing fresh catches each evening redefined what luxury travel means to us.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-03].stayDate', 'فبراير 2026', 'February 2026', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
