INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-04].country', 'الإمارات العربية المتحدة', 'United Arab Emirates', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-04].reviewText', 'صنعت الأبواب النحاسية المنحوتة العتيقة والمسبح الخاص أجواءً هادئة. وكان الاستيقاظ على نسائم المحيط ومشاهدة الدلافين البرية في رحلة المركب الشراعي عند الشروق من أجمل لحظات العمر.', 'The antique carved brass doors and private lap pool created a serene atmosphere. Waking up to ocean breezes and seeing wild dolphins on the sunrise dhow excursion was a lifelong highlight.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-04].stayDate', 'ديسمبر 2025', 'December 2025', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
