INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-05].country', 'جنوب أفريقيا', 'South Africa', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-05].reviewText', 'كان النزول مباشرةً من سطح فيلتنا إلى مياه المحيط الهندي الفيروزية الدافئة نعيمًا خالصًا. ودفء الطاقم واهتمامه بأدق التفاصيل جعلانا نشعر وكأننا من أفراد العائلة المكرّمين في تنزانيا.', 'Stepping directly from our villa deck into the warm turquoise Indian Ocean was pure bliss. The staff’s warmth and attention to detail made us feel like honored family in Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'testimonials', '[rev-05].stayDate', 'أكتوبر 2025', 'October 2025', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
