INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-01].description', 'تمثّل فيلا السلطان المطلة على المحيط ذروة الفخامة الحافية في زنجبار. استُلهمت من العمارة العُمانية الكلاسيكية والتقاليد البحرية السواحيلية، وتتميّز بأسقف خشبية عالية وجدران مكسوّة بالجص الجيري المصقول وواجهات زجاجية ممتدة من الأرض إلى السقف تُذيب الحدود بين الداخل والمحيط الهندي. اخرج إلى سطحك المشمس الخاص بمسبحه اللامتناهي، أو استرخِ في حوض النقع الحجري المنحوت مطلًا على المراكب الشراعية في المساء.', 'The Sultan Oceanfront Villa represents the pinnacle of barefoot luxury in Zanzibar. Inspired by classical Omani architecture and Swahili maritime traditions, this sanctuary features high timber ceilings, polished lime plaster walls, and expansive floor-to-ceiling glass that dissolves the boundary between indoors and the Indian Ocean. Step out onto your private sun deck with an infinity plunge pool, or unwind in the carved stone soak tub overlooking the evening dhows.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-01].name', 'فيلا السلطان المطلة على المحيط', 'Sultan Oceanfront Villa', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
