INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-01].shortDescription', 'تعتلي جرفًا مرجانيًا مباشرةً بإطلالات بحرية لا يحجبها شيء، مع مسبح خاص وخدمة خادم شخصي مخصّص.', 'Perched directly above the coral cliff with uninterrupted ocean vistas, private plunge pool, and dedicated butler service.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
