INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-02].bed', 'سرير كينغ بمظلة وبياضات مصرية فاخرة', 'King Canopy Bed with Fine Egyptian Linen', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-02].description', 'تغمر الفيلا 02 الحدائقُ الاستوائية المحلية، فتمنحك سكينة وخصوصية تامتين. شُيّدت من أخشاب مستدامة وسعف نخيل جوز الهند وحجر المرجان المحلي، فتبقى منعشة بشكل طبيعي تحت شمس خط الاستواء. استمتع بأمسيات هادئة تقرأ فيها على أريكة النهار بين أغاريد الطيور، أو دلّل نفسك بدش مطري في الهواء الطلق تحت سماء مرصّعة بالنجوم.', 'Immersed in indigenous tropical gardens, Villa 02 offers complete tranquility and privacy. Constructed using sustainably harvested timber, coconut palm thatch, and local coral ragstone, the villa remains naturally cool under the equatorial sun. Enjoy lazy afternoons reading on the daybed surrounded by birdsong, or indulge in an open-air rainwater shower under the canopy of night stars.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-02].name', 'ملاذ حديقة الماكوتي', 'Makuti Garden Sanctuary', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
