INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-02].shortDescription', 'تختبئ بين أشجار الفرانجيباني العطرة ونخيل جوز الهند، لتمنحك عزلة تامة ودشًا حجريًا في الهواء الطلق وشرفة هادئة تطل على الحديقة.', 'Tucked within fragrant frangipani and coconut palms, offering total seclusion, an open-air stone shower, and serene garden verandah.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
