INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-03].description', 'ملاذ على الشاطئ صُمّم لعشّاق البحر. توفر الفيلا 03 وصولًا مباشرًا وخاصًا إلى المياه الصافية في جنوب زنجبار. أثاث من الخشب الصلب مصنوع حسب الطلب، وأغطية كتانية منسوجة يدويًا، ومنحوتات أفريقية منتقاة بعناية تصنع أجواءً من الرقيّ الهادئ. اخرج حافي القدمين لتشاهد مراكب الصيادين التقليدية تنساب مع شروق الشمس.', 'A beachfront haven designed for ocean lovers. Villa 03 provides direct, private access to the crystalline waters of southern Zanzibar. Custom hardwood furnishings, hand-loomed linen throws, and curated African sculpture create an atmosphere of understated sophistication. Step outside barefoot to watch traditional fisherman dhows drift across the sunrise.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
