INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-03].shortDescription', 'استيقظ على حفيف النخيل الناعم، وانتقل من سطحك الخشبي مباشرةً إلى رمال المحيط الهندي البيضاء الناعمة.', 'Wake up to the soft rustle of palms and step straight from your wooden deck onto the powdery white sand of the Indian Ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
