INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-05].description', 'يتمحور هذا الجناح الرحب ذو غرفتي النوم حول شجرة باوباب عتيقة مبجّلة، ويوفر راحة استثنائية لرفاق السفر أو العائلات. يضم فناءً مركزيًا مظللًا للمعيشة، وجناحين رئيسيين مستقلين لكل منهما حمّامه في الهواء الطلق، وعريشة خاصة لتناول الطعام.', 'Centered around an ancient, revered Baobab tree, this generous two-bedroom pavilion provides exceptional comfort for traveling companions or families. Featuring a shaded central living courtyard, two independent master suites each with their own open-air bathroom, and a private dining pergola.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
