INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-05].shortDescription', 'ملاذ رحب بغرفتي نوم تحيط به أشجار الباوباب المهيبة، مثالي للعائلات أو المجموعات الصغيرة الباحثة عن فخامة هادئة.', 'A spacious two-bedroom sanctuary surrounded by sculptural baobabs, perfect for families or small groups seeking quiet luxury.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
