INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-06].description', 'تحية للعصر الذهبي للحِرف اليدوية في جزيرة التوابل. تتميّز الفيلا 06 بأبواب منحوتة أصيلة مرصّعة بالنحاس من صنع كبار النحّاتين في ستون تاون، وأرضيات تيرازو مصبوبة يدويًا، ومسبح سباحة خاص بالمياه العذبة بطول 12 مترًا تحفّه شجيرات القرنفل وعشبة الليمون.', 'A tribute to the Spice Island’s golden age of artisanal craftsmanship. Villa 06 features authentic brass-studded carved doors from Stone Town master carvers, hand-poured terrazzo floors, and a private 12-meter fresh water lap pool fringed by clove and lemongrass bushes.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
