INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-07].description', 'صُمّمت الفيلا 07 للمسافر الشغوف بالتصميم، فتمزج بساطة الطراز الياباني الإسكندنافي بدفء الطبيعة الشرق أفريقية. ألوان محايدة مريحة، وسجاد سيزال منسوج يدويًا، وسطح خاص على السطح مجهّز بأرائك نهارية، تجعلها ملاذًا للاسترخاء تحت ضوء القمر والتأمل الهادئ.', 'Conceived for the design-conscious traveler, Villa 07 fuses Japanese-Scandinavian minimalism with East African earthiness. Soothing neutral tones, hand-woven sisal carpets, and an exclusive rooftop observation deck equipped with daybeds make this a haven for moonlit relaxation and tranquil meditation.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
