INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-08].architecturalFeature', 'مسبح لا متناهٍ خاص، ومطبخ تحضير للطاهي، ورصيف خاص للمراكب الشراعية، وفريق خدم مخصّص على مدار 24 ساعة', 'Private infinity pool, chef prep kitchen, private dhow jetty, and dedicated 24-hour butler team', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-08].bathroom', '3 حمّامات داخلية فاخرة + حمّام للضيوف', '3 Luxurious En-Suite Bathrooms + Powder Room', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-08].bed', 'جناحان رئيسيان بسريرَي كينغ + غرفة نوم بسريرين منفصلين', '2 King Master Suites + Twin Bedroom', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-08].description', 'العنوان الأكثر حصرية في المنتجع. تقع الفيلا الرئاسية الملكية على نتوء صخري منعزل خاص بها، وتوفر استقلالية تامة، وصالونات واسعة للضيافة، ومسبحًا لا متناهيًا خاصًا مطلًا على المحيط ومعلّقًا فوق البحيرة المرجانية، وخدمة طاهٍ خاص عند الطلب، ووصولًا مباشرًا إلى شاطئ خاص.', 'The estate’s most exclusive address. Set on its own secluded promontory, The Royal Presidential Villa offers total autonomy, expansive entertaining salons, a private oceanfront infinity pool suspended over the coral lagoon, a private chef service on request, and direct private beach access.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-08].name', 'الفيلا الرئاسية الملكية', 'The Royal Presidential Villa', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-08].roomNumber', 'الفيلا 08', 'VILLA 08', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'villas', '[villa-08].shortDescription', 'المقر الأبرز في Zanzirangi House؛ فخامة لا تضاهى على شاطئ المحيط، ومسابح لا متناهية متعددة المستويات، وضيافة خاصة بكل تكتّم.', 'The flagship residence of Zanzirangi House. Unparalleled oceanfront grandeur, multi-level infinity pools, and discrete private hosting.', 'info@zanzirangihouse.com', '2026-09-30 22:33:23');
