INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'eyebrow', 'ما يميّز ملاذنا', 'The Sanctuary Difference', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'heading', 'لماذا Zanzirangi House', 'WHY ZANZIRANGI HOUSE', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'pillars[pillar-1].description', 'يقع على الساحل الجنوبي البكر لكيزيمكازي، بعيدًا عن زحام السياح. هنا يُقاس الوقت بمدّ البحر وجزره، وحفيف النخيل، وآفاق المحيط المفتوحة بلا حدود.', 'Tucked along the pristine southern coastline of Kizimkazi, far from tourist congestion. Here, time is measured by the tidal ebb and flow, the rustle of palms, and unobstructed ocean horizons.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'pillars[pillar-1].tagline', 'ملاذ خاص بعيدًا عن الزحام.', 'A private sanctuary away from the crowds.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'pillars[pillar-1].title', 'خصوصية وهدوء', 'PRIVATE & PEACEFUL', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'pillars[pillar-2].description', 'من كبار النحّاتين السواحيليين وأجنحة الماكوتي المسقوفة بالقش منذ قرون، إلى التوابل العضوية المقطوفة يوميًا من حدائق منتجعنا، عِش الروح الأصيلة لجزيرة التوابل.', 'From master Swahili woodcarvers and centuries-old makuti thatched pavilions to organic spices harvested daily from our estate gardens, experience the genuine soul of the Spice Island.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'pillars[pillar-2].tagline', 'اكتشف الجزيرة من خلال أهلها ونكهاتها وثقافتها.', 'Experience the island through its people, flavours and culture.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'pillars[pillar-2].title', 'زنجبار الأصيلة', 'AUTHENTIC ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'pillars[pillar-3].description', 'فريق مضيفين وكونسيرج مخصّص يلبّي كل احتياجاتك؛ استقبال خاص على مدرج المطار، ورحلات بحرية بقوارب مستأجرة، وتناول الطعام داخل الفيلا، وضيافة شخصية متكتّمة طوال إقامتك.', 'A dedicated host and concierge team attentive to your every need. Private airport tarmac greetings, chartered boat launches, in-villa dining, and discreet personal hospitality throughout.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'pillars[pillar-3].tagline', 'من لحظة الوصول إلى المطار حتى التخطيط للسفاري.', 'From airport arrival to safari planning.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'pillars[pillar-3].title', 'كونسيرج شخصي', 'PERSONAL CONCIERGE', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'pillars[pillar-4].description', 'اجمع بسلاسة بين الاسترخاء على شاطئ المحيط ورحلات سفاري جوية مستأجرة إلى سيرينغيتي وفوهة نغورونغورو وتارانغيري، لتعيش رحلة متكاملة لا تُنسى في شرق أفريقيا.', 'Seamlessly combine oceanfront rest with chartered fly-in bush safaris to the Serengeti, Ngorongoro Crater, and Tarangire, creating a complete and unforgettable East African journey.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'pillars[pillar-4].tagline', 'اربط إقامتك في زنجبار بعجائب البرّ التنزاني.', 'Connect your Zanzibar stay with the wonders of mainland Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'pillars[pillar-4].title', 'ما وراء تنزانيا', 'TANZANIA BEYOND', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('ar', 'whystay', 'subhead', 'أربع قيم راسخة تصوغ كل لحظة في منتجعنا، لتخلق أجواءً نادرة من السكينة والتفرّد والارتباط العميق بتنزانيا.', 'Four guiding values define every moment at our retreat, creating a rare atmosphere of calm, exclusivity, and profound connection to Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:33:24');
