INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'chauffeur', 'subhead', 'Desde el momento en que su vuelo aterriza en Zanzíbar, nuestro servicio de chófer privado garantiza que su llegada a Zanzirangi House sea totalmente fluida, serena y segura.', 'From the moment your flight touches down in Zanzibar, our private chauffeur service ensures your transition to Zanzirangi House is completely effortless, serene, and secure.', 'info@zanzirangihouse.com', '2026-09-30 22:26:13');
