INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[arabic].description', 'Una celebración de la centenaria herencia real omaní de Zanzíbar y de las rutas marítimas de Arabia. Saboree carnes especiadas estofadas a fuego lento, panes planos de horno de barro, exquisitos mezze fríos y calientes, fragantes arroces al azafrán y dulces delicias de agua de rosas elaboradas por maestros cocineros.', 'A celebration of Zanzibar’s centuries-old royal Omani heritage and Arabian sea routes. Savor slow-braised spiced meats, clay-oven flatbreads, exquisite cold and hot mezze, fragrant saffron-infused rice dishes, and sweet rosewater delicacies prepared by master chefs.', 'info@zanzirangihouse.com', '2026-09-30 22:25:39');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[arabic].name', 'Auténtica Cocina Árabe y Omaní', 'Authentic Arabic & Omani Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:25:36');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[arabic].signatureDishes[#0].description', 'Tierno cordero cocinado lentamente durante 24 horas con clavo, cardamomo, cilantro, lima seca y hojas de plátano, servido sobre un fragante arroz Kabsa dorado al azafrán.', 'Tender lamb slow-cooked for 24 hours with cloves, cardamom, coriander, dry lime, and banana leaves, served over fragrant golden saffron Kabsa rice.', 'info@zanzirangihouse.com', '2026-09-30 22:25:44');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[arabic].signatureDishes[#0].name', 'Cordero Shuwa Omaní Asado a Fuego Lento con Especias', 'Omani Shuwa Spiced Slow-Roasted Lamb', 'info@zanzirangihouse.com', '2026-09-30 22:25:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[arabic].signatureDishes[#1].description', 'Hummus aterciopelado con un toque de granada, Mutabal ahumado, falafel crujiente a las hierbas y panes planos árabes hechos a mano al horno de leña.', 'Velvety pomegranate-drizzled hummus, smoky Mutabal, crispy herbed falafel, and handmade wood-fired Arabic flatbreads.', 'info@zanzirangihouse.com', '2026-09-30 22:25:44');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[arabic].signatureDishes[#1].name', 'Mezze Real y Khubz Fresco con Za’atar', 'Royal Mezze & Fresh Za’atar Khubz', 'info@zanzirangihouse.com', '2026-09-30 22:25:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[arabic].signatureDishes[#2].description', 'Langostinos gigantes de Menai Bay, calamares y pesca de arrecife a la brasa de carbón, sazonados con pimienta de Alepo, zumaque, ajo y hierbas silvestres.', 'Charcoal-grilled Menai Bay jumbo prawns, calamari, and reef catch seasoned with Aleppo pepper, sumac, garlic, and wild herbs.', 'info@zanzirangihouse.com', '2026-09-30 22:25:44');
