INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[beverages].description', 'Una propuesta de bebidas de alto nivel pensada para el placer tropical. Disfrute de añadas de bodega de categoría mundial, zumos tropicales de Zanzíbar puros y prensados en frío, refrescos botánicos elaborados en casa y aguas minerales premium de máxima pureza, servidos frente a la playa o junto a la piscina.', 'An elevated beverage program curated for tropical indulgence. Enjoy world-class cellar vintages, pure cold-pressed Zanzibar tropical juices, house-crafted botanical soft drinks, and premium pristine mineral waters served beachfront or poolside.', 'info@zanzirangihouse.com', '2026-09-30 22:25:39');
