INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[beverages].signatureDishes[#0].description', 'Colecciones del Viejo y del Nuevo Mundo, frescos Chenin Blanc y Sauvignon Blanc sudafricanos, elegantes champanes franceses y tintos con cuerpo de la Toscana y Burdeos.', 'Old and New World collections, crisp South African Chenin Blanc & Sauvignon Blanc, elegant French Champagnes, and full-bodied Tuscan & Bordeaux reds.', 'info@zanzirangihouse.com', '2026-09-30 22:25:46');
