INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[beverages].signatureDishes[#1].description', 'Maracuyá madurado al sol, dulce mango Alfonso, piña triturada con menta fresca y agua de coco King tierno recién traída de los palmerales costeros.', 'Sun-ripened passion fruit, sweet Alfonso mango, crushed pineapple with fresh mint, and young King coconut water straight from coastal palm groves.', 'info@zanzirangihouse.com', '2026-09-30 22:25:46');
