INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[beverages].signatureDishes[#2].description', 'Intensa cerveza de jengibre elaborada en casa con hierba limón machacada, refrescante bebida espumosa de hibisco tanzano, tónicas botánicas artesanales y refrescos clásicos bien fríos.', 'House-brewed fiery ginger beer with crushed lemongrass, sparkling Tanzanian hibiscus cooler, craft botanical tonics, and classic iced sodas.', 'info@zanzirangihouse.com', '2026-09-30 22:25:46');
