INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[beverages].signatureDishes[#3].description', 'Aguas de manantial premium europeas y de África Oriental, con y sin gas, servidas bien frías con pepino fresco del huerto, menta y lima de Makunduchi.', 'Still and sparkling premium European & East African spring waters served crystal chilled with fresh garden cucumber, mint, and Makunduchi lime.', 'info@zanzirangihouse.com', '2026-09-30 22:25:46');
