INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[fusion].description', 'Nuestra firma culinaria. Un diálogo imaginativo entre la técnica francesa clásica y el extraordinario terruño de especias de Zanzíbar. Descubra maridajes armoniosos como la mantequilla de langosta infusionada con vainilla en rama, reducciones de tamarindo y soufflés de maracuyá.', 'Our culinary signature. An imaginative dialogue between classical French technique and Zanzibar’s extraordinary spice terroir. Expect harmonious pairings like vanilla bean infused lobster butter, tamarind reductions, and passion fruit soufflés.', 'info@zanzirangihouse.com', '2026-09-30 22:25:39');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[fusion].name', 'Fusión Suajili Contemporánea', 'Swahili Contemporary Fusion', 'info@zanzirangihouse.com', '2026-09-30 22:25:36');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[fusion].signatureDishes[#0].description', 'Langosta dulce y suculenta pochada en mantequilla francesa clarificada perfumada con fragantes vainas de vainilla de Pemba, emulsión de boniato y espárragos de mar.', 'Sweet succulent lobster poached in clarified French butter scented with fragrant Pemba vanilla pods, sweet potato emulsion, and sea asparagus.', 'info@zanzirangihouse.com', '2026-09-30 22:25:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[fusion].signatureDishes[#0].name', 'Langosta Espinosa Pochada en Mantequilla con Vainilla de Pemba', 'Butter-Poached Rock Lobster with Pemba Vanilla', 'info@zanzirangihouse.com', '2026-09-30 22:25:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[fusion].signatureDishes[#1].description', 'Magret de pato con piel crujiente servido al punto, con un glaseado ácido de flor de hibisco, zanahorias baby asadas y puré de mandioca especiado.', 'Crispy skin Magret duck breast served medium rare with a tart hibiscus flower glaze, roasted baby carrots, and spiced cassava purée.', 'info@zanzirangihouse.com', '2026-09-30 22:25:45');
