INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[fusion].signatureDishes[#2].description', 'Coulant de chocolate negro al 70% perfumado con cardamomo verde, servido con helado de coco elaborado en casa y coulis de maracuyá.', 'Molten dark 70% chocolate cake perfumed with green cardamom, served with house-spun coconut gelato and passionfruit coulis.', 'info@zanzirangihouse.com', '2026-09-30 22:25:46');
