INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[fusion].tabLabel', 'Fusión', 'Fusion', 'info@zanzirangihouse.com', '2026-09-30 22:25:37');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[local].description', 'Siglos de comercio marítimo árabe, persa, indio y de África Oriental confluyeron en las cocinas costeras de Zanzíbar. Nuestros chefs ejecutivos preparan recetas de toda la vida con leche de coco recién extraída, cardamomo aromático, clavo de Pemba y marisco pescado con caña que llega directamente a nuestras costas.', 'Centuries of Arab, Persian, Indian, and East African maritime trade converged in Zanzibar’s coastal kitchens. Our executive chefs prepare time-honored recipes featuring freshly harvested coconut milk, aromatic cardamom, cloves from Pemba, and line-caught seafood brought straight to our shores.', 'info@zanzirangihouse.com', '2026-09-30 22:25:39');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[local].name', 'Auténtica Cocina Suajili', 'Authentic Swahili Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:25:36');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[local].signatureDishes[#0].description', 'Pargo salvaje de arrecife marcado en sartén y cocinado a fuego lento con cilantro fresco, cúrcuma molida a la piedra y leche de coco costera exprimida a mano, servido con arroz al azafrán.', 'Pan-seared wild reef snapper simmered with fresh green coriander, stone-ground turmeric, and hand-squeezed coastal coconut milk served with saffron rice.', 'info@zanzirangihouse.com', '2026-09-30 22:25:43');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[local].signatureDishes[#0].name', 'Pargo de Arrecife de Zanzíbar en Coco y Cúrcuma', 'Zanzibari Coral Reef Snapper in Coconut & Turmeric', 'info@zanzirangihouse.com', '2026-09-30 22:25:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[local].signatureDishes[#1].description', 'Un caldo ácido de mango y tamarindo cocinado a fuego lento con tiernos langostinos, crujientes de mandioca especiados y sambal de coco con guindilla machacada.', 'A tangy, slow-simmered mango and tamarind broth with tender prawns, spiced cassava crisps, and crushed chili coconut sambal.', 'info@zanzirangihouse.com', '2026-09-30 22:25:43');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[local].signatureDishes[#1].name', 'Urojo Tanzano y Guiso de Langostinos Tigre', 'Tanzanian Urojo & Tiger Prawn Stew', 'info@zanzirangihouse.com', '2026-09-30 22:25:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[local].signatureDishes[#2].description', 'Tierno cordero local que se deshace al tenedor, infusionado con anís estrellado, canela en rama y cardamomo negro, acompañado de ensalada kachumbari encurtida.', 'Fork-tender local lamb infused with star anise, cinnamon quills, and black cardamom, accompanied by pickled kachumbari salad.', 'info@zanzirangihouse.com', '2026-09-30 22:25:44');
