INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[western].description', 'Pensada para paladares internacionales que buscan sabores familiares y reconfortantes preparados con las más altas técnicas de la alta cocina. Cortes selectos de ternera importada, frescas ensaladas mediterráneas, pasta casera hecha a mano y postres irresistibles ejecutados con impecable precisión culinaria.', 'Designed for international palates seeking comforting familiarity prepared with the highest fine-dining techniques. Prime imported beef cuts, fresh Mediterranean salads, homemade handmade pasta, and decadent desserts executed with crisp culinary precision.', 'info@zanzirangihouse.com', '2026-09-30 22:25:39');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[western].name', 'Gastronomía Occidental Moderna', 'Modern Western Gastronomy', 'info@zanzirangihouse.com', '2026-09-30 22:25:36');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[western].signatureDishes[#0].description', 'A la parrilla en su punto perfecto, acompañado de una suave muselina de chirivía, tomates en rama confitados y un jugo de vino tinto reducido durante 24 horas.', 'Char-grilled to perfection, paired with smooth parsnip mousseline, blistered vine tomatoes, and a 24-hour reduced red wine jus.', 'info@zanzirangihouse.com', '2026-09-30 22:25:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[western].signatureDishes[#0].name', 'Solomillo de Wagyu Selecto con Glaseado de Trufa', 'Prime Wagyu Tenderloin with Truffle Glaze', 'info@zanzirangihouse.com', '2026-09-30 22:25:41');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[western].signatureDishes[#1].description', 'Atún local pescado con caña, cortado en dados con aguacate Hass, aceite de oliva prensado en frío, alcaparrones y crujientes de pan de masa madre horneado en casa.', 'Line-caught local tuna diced with Hass avocado, cold-pressed olive oil, caper berries, and house-baked sourdough crisps.', 'info@zanzirangihouse.com', '2026-09-30 22:25:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[western].signatureDishes[#1].name', 'Tartar de Atún de Aleta Amarilla Salvaje con Aguacate', 'Wild Yellowfin Tuna Tartare with Avocado', 'info@zanzirangihouse.com', '2026-09-30 22:25:41');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'categories[western].signatureDishes[#2].description', 'Pasta fresca al huevo salteada con cola de langosta espinosa de Kizimkazi, ajo confitado, tomates cherry y una ligera bisque al Pinot Grigio.', 'Fresh egg pasta tossed with sweet Kizimkazi rock lobster tail, garlic confit, baby cherry tomatoes, and a light Pinot Grigio bisque.', 'info@zanzirangihouse.com', '2026-09-30 22:25:45');
