INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'gardenBadge', 'Huerto de la Finca', 'Estate Garden', 'info@zanzirangihouse.com', '2026-09-30 22:25:31');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'gardenDesc', 'En los terrenos de Zanzirangi House se esconde nuestro jardín botánico privado, donde nuestro equipo de cocina cultiva de forma orgánica hierba limón, guindillas verdes, albahaca silvestre, hierbabuena, cardamomo aromático y verduras de temporada. Lo que se cosecha por la mañana define directamente nuestros menús degustación del día, uniendo la vitalidad de la tierra con la pesca fresca de las aguas del sur de Zanzíbar.', 'Tucked within the grounds of Zanzirangi House is our private botanical garden, where our kitchen team cultivates organic lemongrass, green chilies, wild basil, sweet mint, fragrant cardamom, and seasonal vegetables. What is harvested in the morning directly shapes our daily tasting menus, pairing earth-grown vitality with the fresh catch of southern Zanzibar’s waters.', 'info@zanzirangihouse.com', '2026-09-30 22:25:32');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'gardenEyebrow', 'Relatos Culinarios', 'Culinary Storytelling', 'info@zanzirangihouse.com', '2026-09-30 22:25:31');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'gardenTitle', 'DE NUESTRO HUERTO A SU MESA', 'FROM OUR GARDEN TO YOUR TABLE', 'info@zanzirangihouse.com', '2026-09-30 22:25:32');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'heading', 'SABOREE ZANZÍBAR', 'TASTE ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:25:31');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'intro', 'Siglos de comercio marítimo suajili, omaní y del océano Índico se dan cita en nuestras mesas. Desde el pescado capturado con caña y traído a la orilla al amanecer hasta los aromáticos currys cocinados a fuego lento, comer en Zanzirangi House es un auténtico viaje sensorial.', 'Centuries of Swahili, Omani, and Indian Ocean sea trade come together at our tables. From line-caught fish brought ashore at sunrise to slow-simmered aromatic curries, dining at Zanzirangi House is an authentic sensory journey.', 'info@zanzirangihouse.com', '2026-09-30 22:25:31');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'moments[#0].desc', 'Papaya tropical, crema de maracuyá, brioche recién horneado y café tanzano especiado, servidos frente al océano de la mañana.', 'Tropical papaya, passion fruit curds, warm freshly-baked brioche, and spiced Tanzanian coffee served overlooking the morning ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:25:35');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'moments[#0].time', '07:00 – 10:30 AM', '07:00 – 10:30 AM', 'info@zanzirangihouse.com', '2026-09-30 22:25:34');
