INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'moments[#1].desc', 'Tartar de atún de aleta amarilla pescado con caña, ensaladas de langosta espinosa, panes planos al horno de leña y agua de coco King tierno bajo las palmeras.', 'Line-caught yellowfin tuna tartare, rock lobster salads, wood-fired flatbreads, and young King coconut water under the palms.', 'info@zanzirangihouse.com', '2026-09-30 22:25:35');
