INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'dining', 'moments[#2].desc', 'Crujientes chips de plátano macho, langostinos especiados al tamarindo, vinos de bodega y cócteles botánicos artesanales mientras el horizonte del océano se tiñe de violeta.', 'Crisp plantain crisps, spiced tamarind prawns, cellar wines, and handcrafted botanical cocktails as the ocean horizon turns violet.', 'info@zanzirangihouse.com', '2026-09-30 22:25:35');
