INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-cultural].description', 'Visite el histórico asentamiento pesquero de Kizimkazi y la antigua Mezquita de Dimbani (que data del año 1107 d. C.). Conozca a maestros artesanos locales que tallan a mano dhows tradicionales, participe en un taller de cocina suajili o disfrute de un concierto privado de taarab con violín y kanun bajo las estrellas.', 'Visit the historic Kizimkazi fishing settlement and the ancient Dimbani Mosque (dating to 1107 AD). Meet local master craftsmen carving traditional dhows by hand, participate in a Swahili culinary workshop, or enjoy private taarab violin and kanun music under the night stars.', 'info@zanzirangihouse.com', '2026-09-30 22:25:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-cultural].duration', '3,5 Horas (Horario a Medida)', '3.5 Hours (Custom Timing)', 'info@zanzirangihouse.com', '2026-09-30 22:25:50');
