INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-cultural].shortDescription', 'Conviva de forma auténtica con artesanos de la costa, aprenda a tejer hoja de palma y a restaurar dhows, y descubra la antigua herencia suajili.', 'Engage authentically with local coastal artisans, learn palm-weaving and dhow restoration, and discover ancient Swahili heritage.', 'info@zanzirangihouse.com', '2026-09-30 22:25:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-cultural].tag', 'Experiencias Culturales', 'Cultural Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:25:52');
