INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-cultural].whatsappMessage', 'Hola, Concierge de Zanzirangi House: me gustaría saber más sobre las experiencias culturales suajilis.', 'Hello Zanzirangi House Concierge, I would like to learn more about Swahili Cultural Experiences.', 'info@zanzirangihouse.com', '2026-09-30 22:26:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-dolphins].description', 'Nuestra ubicación en Kizimkazi, en la costa sur de Zanzíbar, ofrece acceso directo al santuario de delfines más famoso de África Oriental. Parta al amanecer en un dhow privado o en lancha a motor para ver a los grupos de delfines jugando en su hábitat natural antes de disfrutar del desayuno de vuelta en la finca.', 'Our location in Kizimkazi on Zanzibar’s southern coast provides direct access to East Africa’s most famous dolphin sanctuary. Depart at dawn on a private dhow or motor launch to watch dolphin pods playing in their natural ocean habitat before enjoying breakfast back at the property.', 'info@zanzirangihouse.com', '2026-09-30 22:25:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-dolphins].duration', '3,5 Horas (Crucero al Amanecer)', '3.5 Hours (Early Morning Dawn Cruise)', 'info@zanzirangihouse.com', '2026-09-30 22:25:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-dolphins].priceNote', 'Precio a Consultar', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:25:53');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-dolphins].shortDescription', 'Zarpe al amanecer desde Kizimkazi hacia las aguas protegidas de Menai Bay para contemplar grupos de delfines giradores y mulares que habitan la zona.', 'Set sail at sunrise from Kizimkazi into the protected waters of Menai Bay to witness pods of resident spinner and bottlenose dolphins.', 'info@zanzirangihouse.com', '2026-09-30 22:25:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-dolphins].tag', 'Experiencia con Delfines', 'Dolphin Experience', 'info@zanzirangihouse.com', '2026-09-30 22:25:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-dolphins].title', 'Encuentro con Delfines Salvajes en Kizimkazi', 'Kizimkazi Wild Dolphin Encounter', 'info@zanzirangihouse.com', '2026-09-30 22:25:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-dolphins].whatsappMessage', 'Hola, Concierge de Zanzirangi House: me encantaría vivir el Encuentro con Delfines Salvajes en Kizimkazi.', 'Hello Zanzirangi House Concierge, I would like to experience the Kizimkazi Wild Dolphin Encounter.', 'info@zanzirangihouse.com', '2026-09-30 22:25:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-fishing].description', 'A bordo de nuestra embarcación de pesca deportiva de altura, equipada con tangones, aparejos Shimano y electrónica náutica moderna, viva la adrenalina de la pesca mayor en las profundas corrientes del océano Índico. Se aplican estrictamente los protocolos de captura y suelta para los picudos.', 'Aboard our chartered offshore sportfisher equipped with outriggers, Shimano tackle, and modern nautical electronics, experience the adrenaline of big game fishing in the deep currents of the Indian Ocean. Strictly adheres to catch-and-release protocols for billfish.', 'info@zanzirangihouse.com', '2026-09-30 22:25:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-fishing].duration', 'Medio Día (5 Horas) o Día Completo (8 Horas)', 'Half Day (5 Hours) or Full Day (8 Hours)', 'info@zanzirangihouse.com', '2026-09-30 22:25:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-fishing].priceNote', 'Precio a Consultar', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:25:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-fishing].shortDescription', 'Adéntrese en los profundos canales de Pemba y Zanzíbar para practicar pesca deportiva de primer nivel en busca de atún de aleta amarilla, pez vela y peto.', 'Venture into the deep Pemba and Zanzibar channels for world-class sport fishing targeting yellowfin tuna, sailfish, and wahoo.', 'info@zanzirangihouse.com', '2026-09-30 22:25:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-fishing].tag', 'Pesca de Altura', 'Deep Sea Fishing', 'info@zanzirangihouse.com', '2026-09-30 22:25:52');
