INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-fishing].whatsappMessage', 'Hola, Concierge de Zanzirangi House: me gustaría recibir información sobre las salidas de pesca deportiva de altura.', 'Hello Zanzirangi House Concierge, I would like details on Deep Sea Sport Fishing trips.', 'info@zanzirangihouse.com', '2026-09-30 22:26:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-island-hopping].description', 'Trace su propia ruta por las aguas turquesas del sur y el oeste de Zanzíbar. Desembarque en efímeros bancos de arena blanquísima que solo emergen con la marea baja, nade en aguas cálidas y cristalinas, y saboree un almuerzo recién preparado de langosta de Menai Bay a la parrilla, calamares y fruta tropical.', 'Chart your own course across the turquoise waters of southern and western Zanzibar. Disembark onto ephemeral powder-white sandbanks that emerge only at low tide, swim in warm crystalline waters, and savor a freshly prepared lunch of grilled Menai Bay lobster, calamari, and tropical fruit.', 'info@zanzirangihouse.com', '2026-09-30 22:25:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-island-hopping].duration', 'Día Completo (Lancha Rápida Privada)', 'Full Day (Private Speedboat)', 'info@zanzirangihouse.com', '2026-09-30 22:25:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-island-hopping].priceNote', 'Precio a Consultar', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:25:53');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-island-hopping].shortDescription', 'Navegue hasta islotes de coral apartados y deshabitados, báñese en lagunas de marea desiertas y disfrute de un almuerzo de marisco a la parrilla en un banco de arena privado.', 'Cruise to secluded uninhabited coral islets, swim in deserted tidal lagoons, and enjoy a grilled seafood lunch on a private sandbank.', 'info@zanzirangihouse.com', '2026-09-30 22:25:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-island-hopping].tag', 'Ruta por las Islas', 'Island Hopping', 'info@zanzirangihouse.com', '2026-09-30 22:25:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-island-hopping].title', 'Ruta Privada por las Islas y Safari en Bancos de Arena', 'Private Island Hopping & Sandbank Safari', 'info@zanzirangihouse.com', '2026-09-30 22:25:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-island-hopping].whatsappMessage', 'Hola, Concierge de Zanzirangi House: quisiera información sobre la Ruta Privada por las Islas y el Safari en Bancos de Arena.', 'Hello Zanzirangi House Concierge, I would like to inquire about the Private Island Hopping Sandbank Safari.', 'info@zanzirangihouse.com', '2026-09-30 22:25:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-mnemba].description', 'Situado frente a la costa noreste de Zanzíbar, el Atolón de Mnemba es reconocido mundialmente por sus inmaculadas condiciones submarinas. Disfrute de traslados privados en barco, esnórquel exclusivo sobre pináculos de coral y un pícnic gourmet junto a la playa preparado por nuestro chef privado.', 'Located off Zanzibar’s northeast coast, Mnemba Atoll is recognized globally for its pristine underwater conditions. Enjoy private boat transfers, exclusive snorkeling over coral pinnacles, and a beachside gourmet picnic arranged by our private chef.', 'info@zanzirangihouse.com', '2026-09-30 22:25:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-mnemba].duration', 'Expedición Privada de Día Completo', 'Full Day Private Expedition', 'info@zanzirangihouse.com', '2026-09-30 22:25:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-mnemba].priceNote', 'Precio a Consultar', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:25:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-mnemba].shortDescription', 'Navegue hasta la joya de la corona de las reservas marinas de Zanzíbar: una transparencia turquesa sin igual, jardines de coral intactos y lagunas de tortugas marinas.', 'Sail to the crown jewel of Zanzibar marine reserves: unmatched turquoise clarity, pristine coral gardens, and sea turtle lagoons.', 'info@zanzirangihouse.com', '2026-09-30 22:25:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-mnemba].tag', 'Isla de Mnemba', 'Mnemba Island', 'info@zanzirangihouse.com', '2026-09-30 22:25:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-mnemba].title', 'Santuario Marino de Lujo del Atolón de Mnemba', 'Mnemba Atoll Luxury Marine Sanctuary', 'info@zanzirangihouse.com', '2026-09-30 22:25:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-mnemba].whatsappMessage', 'Hola, Concierge de Zanzirangi House: me gustaría reservar la expedición al Santuario Marino de la Isla de Mnemba.', 'Hello Zanzirangi House Concierge, I would like to book the Mnemba Island Marine Sanctuary expedition.', 'info@zanzirangihouse.com', '2026-09-30 22:26:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-nature-jozani].description', 'Guiado por un naturalista autorizado del parque nacional, adéntrese en los antiguos bosques de maderas nobles protegidos dentro del Parque Nacional de Jozani Chwaka Bay. Observe tropas de monos balanceándose entre las copas de los árboles, recorra la pasarela elevada sobre el manglar y conozca la singular flora exclusiva de Zanzíbar.', 'Led by an authorized national park naturalist, journey into ancient hardwood forests protected within Jozani Chwaka Bay National Park. Observe monkey troops swinging through the canopy, walk the elevated mangrove boardwalk, and learn about the rare flora unique to Zanzibar.', 'info@zanzirangihouse.com', '2026-09-30 22:25:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-nature-jozani].duration', '4 Horas (Recomendado por la Mañana)', '4 Hours (Morning Recommended)', 'info@zanzirangihouse.com', '2026-09-30 22:25:50');
