INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-nature-jozani].shortDescription', 'Adéntrese en un bosque virgen de caobas para encontrarse con el juguetón colobo rojo de Zanzíbar, especie endémica de la isla.', 'Trek through virgin groundwater mahogany forest to encounter the playful, endemic Zanzibar Red Colobus monkey.', 'info@zanzirangihouse.com', '2026-09-30 22:25:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-nature-jozani].tag', 'Experiencias en la Naturaleza', 'Nature Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:25:52');
