INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-nature-jozani].whatsappMessage', 'Hola, Concierge de Zanzirangi House: me gustaría reservar la experiencia en la naturaleza del Bosque de Jozani.', 'Hello Zanzirangi House Concierge, I would like to reserve the Jozani Forest Nature Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:26:01');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-snorkeling-diving].description', 'Los arrecifes de barrera de Zanzíbar rebosan de biodiversidad tropical. Con equipo profesional de primera calidad y acompañado por divemasters certificados PADI, descubra impresionantes paredes, cuevas que se atraviesan a nado y una visibilidad cristalina de hasta 30 metros.', 'Zanzibar’s barrier reefs are teeming with tropical biodiversity. Equipped with top-tier professional gear and accompanied by certified PADI divemasters, discover stunning drop-offs, swim-through caves, and crystal visibility extending up to 30 meters.', 'info@zanzirangihouse.com', '2026-09-30 22:25:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-snorkeling-diving].duration', 'Excursión de Medio Día o Día Completo', 'Half Day or Full Day Excursion', 'info@zanzirangihouse.com', '2026-09-30 22:25:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-snorkeling-diving].priceNote', 'Precio a Consultar', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:25:53');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-snorkeling-diving].shortDescription', 'Explore vibrantes jardines de coral y paredes submarinas, y conozca tortugas marinas, mantarrayas águila moteadas y exóticas especies de arrecife.', 'Explore vibrant coral gardens, underwater marine walls, and meet sea turtles, spotted eagle rays, and exotic reef species.', 'info@zanzirangihouse.com', '2026-09-30 22:25:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-snorkeling-diving].tag', 'Esnórquel y Buceo', 'Snorkeling & Diving', 'info@zanzirangihouse.com', '2026-09-30 22:25:51');
