INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-snorkeling-diving].whatsappMessage', 'Hola, Concierge de Zanzirangi House: me gustaría organizar una excursión de esnórquel y buceo.', 'Hello Zanzirangi House Concierge, I would like to arrange a Snorkeling & Diving excursion.', 'info@zanzirangihouse.com', '2026-09-30 22:25:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-spice-farm].description', 'Pasee junto a expertos botánicos locales por exuberantes plantaciones rurales. Toque, huela y pruebe especias en crudo directamente de árboles y enredaderas —pimienta negra, nuez moscada, jengibre, hierba limón y cúrcuma, entre otras— y termine con agua fresca de coco King recolectado en lo alto de las palmeras.', 'Walk alongside expert local botanists through verdant rural plantations. Touch, smell, and taste raw spices directly from the trees and vines—including black pepper, nutmeg, ginger, lemongrass, and turmeric—concluding with fresh King coconut water harvested high in the canopy.', 'info@zanzirangihouse.com', '2026-09-30 22:25:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-spice-farm].duration', '4 Horas (Mañana o Tarde)', '4 Hours (Morning or Afternoon)', 'info@zanzirangihouse.com', '2026-09-30 22:25:50');
