INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-spice-farm].shortDescription', 'Sumerja sus sentidos en siglos de historia aromática: recoja canela fresca, triture cardamomo verde y pruebe la vainilla silvestre en rama.', 'Immerse your senses in centuries of aromatic history: pluck fresh cinnamon, crush green cardamom, and taste wild vanilla bean.', 'info@zanzirangihouse.com', '2026-09-30 22:25:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-spice-farm].tag', 'Granja de Especias', 'Spice Farm', 'info@zanzirangihouse.com', '2026-09-30 22:25:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-spice-farm].title', 'Recorrido por una Granja Orgánica de Especias', 'Organic Botanical Spice Farm Journey', 'info@zanzirangihouse.com', '2026-09-30 22:25:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-spice-farm].whatsappMessage', 'Hola, Concierge de Zanzirangi House: me interesa el Recorrido por una Granja Orgánica de Especias.', 'Hello Zanzirangi House Concierge, I am interested in the Organic Botanical Spice Farm Journey.', 'info@zanzirangihouse.com', '2026-09-30 22:26:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-stonetown].description', 'Un recorrido privado por Stone Town, Patrimonio de la Humanidad de la UNESCO. De la mano de un historiador suajili local, descubra la Casa de las Maravillas, el Fuerte Antiguo del siglo XVII, la Catedral Anglicana y el memorial del Antiguo Mercado de Esclavos, así como talleres artesanos especializados en joyería de plata y tejidos.', 'A private journey through UNESCO World Heritage Stone Town. Led by a resident Swahili historian, explore the House of Wonders, the 17th-century Old Fort, the Anglican Cathedral and Old Slave Market memorial, and artisan workshops specializing in silver jewelry and woven textiles.', 'info@zanzirangihouse.com', '2026-09-30 22:25:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-stonetown].duration', 'Día Completo (Chófer y Guía Privados)', 'Full Day (Private Chauffeur & Guide)', 'info@zanzirangihouse.com', '2026-09-30 22:25:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-stonetown].priceNote', 'Precio a Consultar', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:25:53');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-stonetown].shortDescription', 'Recorra laberínticos callejones de piedra de coral, ornamentadas puertas omaníes de teca tallada, históricos bazares de especias y el Palacio del Sultán.', 'Walk through labyrinthine coral ragstone alleyways, ornate Omani carved teak doors, historical spice bazaars, and the Sultan’s Palace.', 'info@zanzirangihouse.com', '2026-09-30 22:25:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-stonetown].tag', 'Cultura y Patrimonio', 'Culture & Heritage', 'info@zanzirangihouse.com', '2026-09-30 22:25:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-stonetown].title', 'Patrimonio de Stone Town y su Barrio Histórico', 'Stone Town Heritage & Historic Quarters', 'info@zanzirangihouse.com', '2026-09-30 22:25:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-stonetown].whatsappMessage', 'Hola, Concierge de Zanzirangi House: me gustaría reservar la experiencia privada por el patrimonio de Stone Town.', 'Hello Zanzirangi House Concierge, I am interested in booking the private Stone Town Heritage Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:25:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-sunset-cruise].description', 'Suba a bordo de un dhow suajili de vela construido artesanalmente en caoba autóctona. Relájese sobre mullidos cojines con champán frío, canapés artesanales y el sonido hipnótico de la brisa marina y las melodías acústicas de taarab mientras la luz del día se funde con el crepúsculo.', 'Step aboard a handcrafted Swahili sailing dhow carved from indigenous mahogany. Relax upon plush cushions with chilled Champagne, artisanal canapés, and the hypnotic sounds of the ocean breeze and acoustic taarab melodies as daylight fades into dusk.', 'info@zanzirangihouse.com', '2026-09-30 22:25:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-sunset-cruise].duration', '2,5 Horas (Hora Dorada de la Tarde)', '2.5 Hours (Late Afternoon Golden Hour)', 'info@zanzirangihouse.com', '2026-09-30 22:25:49');
