INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'experiences', '[exp-sunset-cruise].shortDescription', 'Deslícese por las tranquilas aguas del océano Índico bajo velas henchidas mientras el sol ecuatorial pinta el cielo en tonos ámbar y oro rosa.', 'Glide across the calm Indian Ocean under billowed canvas sails as the equatorial sun paints the sky in shades of amber and rose gold.', 'info@zanzirangihouse.com', '2026-09-30 22:25:56');
