INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'facilities', '[bbq].description', 'Mientras el sol se hunde en el océano Índico, reúnase junto a nuestra hoguera en la orilla para disfrutar de langosta a la parrilla, langostinos tigre y solomillos especiados cocinados sobre cáscaras de coco bajo las constelaciones africanas.', 'As the sun dips into the Indian Ocean, gather around our shoreline firepit for grilled lobster, tiger prawns, and spiced tenderloins cooked over coconut husks under the African constellations.', 'info@zanzirangihouse.com', '2026-09-30 22:26:20');
