INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'facilities', '[breakfast].description', 'Despierte con bandejas de fruta tropical de huertos locales, brioche recién horneado, crema de maracuyá, café arábica tanzano y huevos preparados a su gusto, en su villa o junto al mar.', 'Awaken to tropical fruit platters from local orchards, freshly baked brioche, passion fruit curd, Tanzanian arabica coffee, and eggs cooked to your preference in your villa or by the sea.', 'info@zanzirangihouse.com', '2026-09-30 22:26:21');
