INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'facilities', '[dining].description', 'Un pabellón al aire libre bajo una bóveda de techumbre de makuti con vistas panorámicas al océano. Disfrute de una alta cocina impregnada de los aromas de las especias de Zanzíbar y de la pesca más fresca del día.', 'An open-air pavilion beneath vaulted Makuti thatch offering panoramic ocean views. Experience fine dining infused with the aromas of Zanzibar spices and the freshest catches of the day.', 'info@zanzirangihouse.com', '2026-09-30 22:26:20');
