INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'facilities', '[massage].description', 'Recogidas salas de spa al aire libre entre jardines costeros. Déjese mimar con masajes a medida con aceite de coco de Zanzíbar prensado en frío, hierba limón, clavo molido y plantas botánicas autóctonas africanas.', 'Secluded open-air spa salas nestled in coastal gardens. Indulge in bespoke massages using cold-pressed Zanzibar coconut oil, lemongrass, ground cloves, and indigenous African botanicals.', 'info@zanzirangihouse.com', '2026-09-30 22:26:20');
