INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'facilities', '[pool].description', 'Suspendida sobre las mareas turquesas del océano Índico, nuestra piscina infinita de agua dulce de 25 metros refleja el cielo y el horizonte del océano, con tumbonas sumergidas y un atento servicio junto a la piscina.', 'Suspended above the turquoise tides of the Indian Ocean, our 25-meter freshwater infinity pool mirrors the sky and ocean horizons with sunken sunbeds and attentive poolside service.', 'info@zanzirangihouse.com', '2026-09-30 22:26:20');
