INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'facilities', '[wifi].description', 'Disfrute de internet satelital ultrarrápido y de baja latencia en toda la finca, en las villas privadas, en las tumbonas frente a la playa y en las terrazas del restaurante, para una comunicación fluida y un trabajo a distancia sin interrupciones.', 'Enjoy blazing-fast, low-latency satellite internet across the entire estate, private villas, beachfront loungers, and dining terraces, ensuring seamless communication and remote productivity.', 'info@zanzirangihouse.com', '2026-09-30 22:26:21');
