INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'homepage', 'intro.description', 'Zanzirangi House es un refugio ultraboutique con 8 villas privadas con piscina, recogidas a lo largo de la tranquila costa sur de Zanzíbar, en Kizimkazi Dimbani.', 'Zanzirangi House is an ultra-boutique retreat featuring 8 private plunge-pool villas secluded along the peaceful southern coast of Zanzibar in Kizimkazi Dimbani.', 'info@zanzirangihouse.com', '2026-09-30 22:24:57');
