INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[about].description', 'Situado en la virgen costa sur de coral de Kizimkazi Dimbani, Zanzirangi House es un santuario privado ultraboutique concebido para ofrecer total privacidad, armonía arquitectónica y la íntima hospitalidad de Zanzíbar.', 'Nestled along the pristine southern coral coast of Kizimkazi Dimbani, Zanzirangi House is an ultra-boutique private sanctuary designed to offer total seclusion, architectural harmony, and intimate Zanzibar hospitality.', 'info@zanzirangihouse.com', '2026-09-30 22:26:43');
