INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[contact].description', 'Planifique su estancia a medida con nuestro equipo de concierge. Ya sea para consultar la disponibilidad de villas privadas, organizar traslados de 45 minutos desde el aeropuerto de ZNZ o diseñar itinerarios de safari personalizados por Tanzania, estamos a su disposición 24/7.', 'Plan your bespoke stay with our concierge team. Whether arranging private villa availability, 45-minute airport transfers from ZNZ, or custom Tanzania safari itineraries, we are available 24/7.', 'info@zanzirangihouse.com', '2026-09-30 22:26:43');
