INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[dining].description', 'Saboree el auténtico patrimonio culinario de Zanzíbar, que combina las especias suajilis con el marisco del océano Índico capturado a diario por los pescadores artesanales de dhow de Kizimkazi. Disfrute de cenas privadas en su veranda, barbacoas en la playa y cenas a la luz de las velas bajo las estrellas, diseñadas a su medida.', 'Taste authentic Zanzibar culinary heritage blending Swahili spices with Indian Ocean seafood caught daily by Kizimkazi artisanal dhow fishermen. Enjoy private veranda dining, beach barbecues, and bespoke candlelit dinners under the stars.', 'info@zanzirangihouse.com', '2026-09-30 22:26:43');
