INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[experiences].description', 'Desde encuentros éticos con delfines salvajes en la Reserva Marina de Menai Bay hasta visitas privadas al Stone Town declarado Patrimonio de la UNESCO, rutas de especias orgánicas y travesías en dhow al atardecer: descubra Zanzíbar con nuestros guías privados dedicados.', 'From ethical wild dolphin encounters in the Menai Bay Marine Reserve to private Stone Town UNESCO heritage tours, organic spice trails, and sunset dhow sailing—experience Zanzibar with our dedicated private guides.', 'info@zanzirangihouse.com', '2026-09-30 22:26:44');
