INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.introText', 'En Zanzirangi House (accesible desde https://zanzirangihouse.com/), la protección de los datos personales y la privacidad de nuestros huéspedes es de suma importancia. La presente Política de Privacidad describe cómo recopilamos, utilizamos y protegemos la información cuando usted visita nuestro sitio web, envía consultas de reserva o se comunica con nuestro equipo de concierge.', 'At Zanzirangi House (accessible from https://zanzirangihouse.com/), safeguarding our guests’ personal data and privacy is of utmost importance. This Privacy Policy details how we collect, use, and protect information when you visit our website, submit booking inquiries, or communicate with our concierge team.', 'info@zanzirangihouse.com', '2026-09-30 22:26:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.lastUpdated', 'Septiembre de 2026', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:26:46');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.sections[#0].body', 'Al enviar una consulta o reservar una villa privada, usted puede facilitarnos datos como su nombre completo, dirección de correo electrónico, número de teléfono/WhatsApp, fechas de llegada y salida, número de huéspedes y preferencias especiales de hospitalidad o alimentación.', 'When submitting an inquiry or reserving a private villa, you may provide details including your full name, email address, telephone/WhatsApp number, arrival/departure dates, guest party size, and special hospitality or dietary preferences.', 'info@zanzirangihouse.com', '2026-09-30 22:26:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.sections[#0].title', '1. Información que Recopilamos', '1. Information We Collect', 'info@zanzirangihouse.com', '2026-09-30 22:26:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.sections[#1].items[#0]', 'Gestionar las consultas de reserva y la comprobación de disponibilidad de las villas.', 'Facilitating reservation inquiries and room availability checks.', 'info@zanzirangihouse.com', '2026-09-30 22:26:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.sections[#1].items[#1]', 'Coordinar los traslados con chófer desde el Aeropuerto Internacional Abeid Amani Karume (ZNZ).', 'Coordinating airport chauffeur transfers from Abeid Amani Karume International Airport (ZNZ).', 'info@zanzirangihouse.com', '2026-09-30 22:26:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.sections[#1].items[#2]', 'Personalizar cenas privadas, excursiones marinas para ver delfines y conexiones con safaris en la Tanzania continental.', 'Customizing private dining, marine dolphin tours, and mainland Tanzania safari connections.', 'info@zanzirangihouse.com', '2026-09-30 22:26:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.sections[#1].items[#3]', 'Prestar el servicio de comunicaciones de mayordomo personal y concierge 24/7.', 'Providing 24/7 personal butler and concierge communications.', 'info@zanzirangihouse.com', '2026-09-30 22:26:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.sections[#1].title', '2. Cómo Utilizamos su Información', '2. How We Use Your Information', 'info@zanzirangihouse.com', '2026-09-30 22:26:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.sections[#2].body', 'Aplicamos estrictas medidas de seguridad técnicas y administrativas. No vendemos, alquilamos ni cedemos la información de los huéspedes a redes comerciales de marketing de terceros. Los datos se comparten exclusivamente con proveedores de servicios locales autorizados (como los operadores oficiales de vuelos chárter de safari de TANAPA) con el único fin de cumplir el itinerario acordado.', 'We implement strict technical and administrative safeguards. We do not sell, rent, or lease guest information to third-party commercial marketing networks. Data is shared exclusively with licensed local service providers (such as official TANAPA safari charter operators) strictly to fulfill your agreed itinerary.', 'info@zanzirangihouse.com', '2026-09-30 22:26:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.sections[#2].title', '3. Seguridad de los Datos y Divulgación a Terceros', '3. Data Security & Third-Party Disclosure', 'info@zanzirangihouse.com', '2026-09-30 22:26:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.sections[#3].body', 'Para cualquier consulta relacionada con la privacidad o para solicitar la eliminación de sus datos, póngase en contacto directamente con nuestro equipo de protección de datos en concierge@zanzirangihouse.com o a través del teléfono oficial +255 777 890 123.', 'For any privacy inquiries or to request data removal, contact our data protection team directly at concierge@zanzirangihouse.com or via official telephone at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:26:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].contentJson.sections[#3].title', '4. Contacte con Nuestro Concierge', '4. Contact Our Concierge', 'info@zanzirangihouse.com', '2026-09-30 22:26:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[privacy].description', 'En Zanzirangi House, la protección de los datos personales y la privacidad de nuestros huéspedes es de suma importancia.', 'At Zanzirangi House, safeguarding our guests’ personal data and privacy is of utmost importance.', 'info@zanzirangihouse.com', '2026-09-30 22:26:44');
