INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[safari].description', 'Combine su refugio de lujo descalzo en Zanzíbar con safaris de primer nivel en el continente. Coordinamos vuelos chárter privados de 90 minutos directamente al Parque Nacional del Serengeti, al cráter del Ngorongoro y al monte Kilimanjaro, con los mejores campamentos de safari de lujo.', 'Combine your barefoot luxury retreat in Zanzibar with world-class mainland safaris. We coordinate 90-minute private air charters directly to Serengeti National Park, Ngorongoro Crater, and Mount Kilimanjaro with premier luxury safari camps.', 'info@zanzirangihouse.com', '2026-09-30 22:26:44');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[safari].eyebrow', 'EXPEDICIONES EN AVIONETA A LA SABANA Y LA PLAYA • TANZANIA CONTINENTAL', 'FLY-IN BUSH & BEACH EXPEDITIONS • TANZANIA MAINLAND', 'info@zanzirangihouse.com', '2026-09-30 22:26:38');
