INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[terms].contentJson.introText', 'Bienvenido a Zanzirangi House. Al acceder a nuestro sitio web (https://zanzirangihouse.com/) o enviar solicitudes de alojamiento y excursiones, usted acepta cumplir con los siguientes términos de hospitalidad y normas de reserva.', 'Welcome to Zanzirangi House. By accessing our website (https://zanzirangihouse.com/) or submitting accommodation and excursion requests, you agree to comply with the following hospitality terms and reservation guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:26:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[terms].contentJson.lastUpdated', 'Septiembre de 2026', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:26:46');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[terms].contentJson.sections[#0].body', 'Las tarifas por noche de las villas oscilan entre $390 y más de $480 USD e incluyen el acceso a la piscina privada, el desayuno gourmet y el servicio de mayordomo dedicado 24/7. La confirmación requiere un depósito acordado o un bono a través de los canales oficiales de reserva.', 'Nightly villa rates range between $390 and $480+ USD and include private plunge pool access, gourmet breakfast, and 24/7 dedicated butler service. Confirmation requires an agreed deposit or voucher via official reservation channels.', 'info@zanzirangihouse.com', '2026-09-30 22:26:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[terms].contentJson.sections[#0].title', '1. Reservas y Pagos', '1. Reservations & Payments', 'info@zanzirangihouse.com', '2026-09-30 22:26:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[terms].contentJson.sections[#1].body', 'La hora estándar de entrada es a partir de las 14:00 (2:00 PM) y la de salida, hasta las 11:00 (11:00 AM). La llegada anticipada o la salida tardía pueden solicitarse a través de su concierge personal, sujetas a la disponibilidad de la villa.', 'Standard check-in is from 14:00 (2:00 PM), and check-out is by 11:00 (11:00 AM). Early arrival or late departure may be requested through your personal concierge, subject to villa availability.', 'info@zanzirangihouse.com', '2026-09-30 22:26:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[terms].contentJson.sections[#1].title', '2. Horarios de Entrada y Salida', '2. Check-In & Check-Out Times', 'info@zanzirangihouse.com', '2026-09-30 22:26:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[terms].contentJson.sections[#2].body', 'Zanzirangi House limita con el Área de Conservación Marina de Menai Bay. Los huéspedes que participen en travesías en dhow y excursiones para ver delfines se comprometen a seguir protocolos éticos de observación de fauna, manteniendo una distancia respetuosa con los animales marinos de conformidad con la normativa medioambiental local.', 'Zanzirangi House borders the Menai Bay Marine Conservation Area. Guests participating in dhow sailing and dolphin excursions agree to follow ethical wildlife protocols, maintaining respectful distances from marine wildlife in compliance with local environmental regulations.', 'info@zanzirangihouse.com', '2026-09-30 22:26:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[terms].contentJson.sections[#2].title', '3. Conservación Marina y Normas de Conducta con la Fauna', '3. Marine Conservation & Wildlife Etiquette', 'info@zanzirangihouse.com', '2026-09-30 22:26:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[terms].contentJson.sections[#3].body', 'Para modificar o cancelar una reserva, póngase en contacto directamente con nuestro concierge por correo electrónico en concierge@zanzirangihouse.com o por WhatsApp en el +255 777 890 123.', 'To modify or cancel a reservation, contact our concierge directly via email at concierge@zanzirangihouse.com or WhatsApp at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:26:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[terms].contentJson.sections[#3].title', '4. Consultas y Cancelaciones', '4. Inquiries & Cancellations', 'info@zanzirangihouse.com', '2026-09-30 22:26:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[terms].description', 'Bienvenido a Zanzirangi House. Al acceder a nuestro sitio web o enviar solicitudes de reserva, usted acepta cumplir con nuestras normas de hospitalidad.', 'Welcome to Zanzirangi House. By accessing our website or submitting reservation requests, you agree to comply with our hospitality guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:26:45');
