INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'pages', '[villas].description', 'Descubra nuestras 8 residencias artesanales privadas, de 78 m² a 95 m². Cada villa cuenta con una piscina de agua dulce 100% privada, auténtica arquitectura suajili en piedra de coral y un servicio de mayordomo personalizado y dedicado 24/7.', 'Discover our 8 private artisanal residences ranging from 78 m² to 95 m². Each villa features a 100% private freshwater plunge pool, authentic Swahili coral-stone architecture, and personalized 24/7 dedicated butler service.', 'info@zanzirangihouse.com', '2026-09-30 22:26:45');
