INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'safari', '[dest-kilimanjaro].bestFor', 'Perspectivas aéreas icónicas y senderismo de montaña', 'Iconic aerial perspectives & alpine trekking', 'info@zanzirangihouse.com', '2026-09-30 22:26:09');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'safari', '[dest-kilimanjaro].description', 'La cumbre más alta de África y la montaña aislada más alta del mundo se alza majestuosa a 5,895 metros sobre las llanuras tropicales. Desde panorámicos vuelos privados en helicóptero alrededor del pico Uhuru hasta excursiones de un día por exuberantes senderos de selva baja y plantaciones de café, viva la corona emblemática de Tanzania.', 'Africa’s highest peak and the world’s tallest free-standing mountain rises majestically 5,895 meters above tropical plains. From scenic private helicopter flights encircling Uhuru Peak to day treks along lush lower rainforest trails and coffee estates, experience Tanzania’s iconic crown.', 'info@zanzirangihouse.com', '2026-09-30 22:26:05');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'safari', '[dest-kilimanjaro].flightTimeFromZanzibar', '1h 10m hasta el Aeropuerto Int. de Kilimanjaro', '1h 10m to Kilimanjaro Int’l', 'info@zanzirangihouse.com', '2026-09-30 22:26:04');
