INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'safari', '[dest-ngorongoro].bestFor', 'Esplendor geológico y gran densidad de fauna', 'Geological splendor & concentrated wildlife density', 'info@zanzirangihouse.com', '2026-09-30 22:26:08');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'safari', '[dest-ngorongoro].description', 'La mayor caldera volcánica intacta del mundo, un refugio ecológico autónomo de 600 metros de profundidad. Descienda por los brumosos bosques de acacias del borde hasta un antiguo anfiteatro repleto de rinocerontes negros en peligro de extinción, hipopótamos y miles de flamencos rosas que vadean el lago Magadi.', 'The world’s largest intact volcanic caldera, creating a self-contained ecological haven 600 meters deep. Descend through misty rim acacia forests into an ancient amphitheater bustling with endangered black rhinos, hippos, and thousands of pink flamingos wading in Lake Magadi.', 'info@zanzirangihouse.com', '2026-09-30 22:26:04');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'safari', '[dest-ngorongoro].flightTimeFromZanzibar', '1h 30m hasta la Pista de Manyara', '1h 30m to Manyara Airstrip', 'info@zanzirangihouse.com', '2026-09-30 22:26:04');
