INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'safari', '[dest-serengeti].bestFor', 'Avistamiento de los Cinco Grandes y espectáculos de fauna salvaje', 'Big Five sightings & dramatic wildlife spectacles', 'info@zanzirangihouse.com', '2026-09-30 22:26:08');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'safari', '[dest-serengeti].description', 'Vastas sabanas doradas que se extienden sin fin hasta el horizonte. Contemple a millones de ñus y cebras desafiando ríos plagados de cocodrilos, acompañados de manadas de leones residentes, leopardos solitarios y lujosos campamentos de tiendas en plena sabana bajo cielos ecuatoriales cuajados de estrellas.', 'Vast golden savannahs that stretch endlessly to the horizon. Witness millions of wildebeest and zebras braving crocodile-laden rivers, accompanied by resident prides of lions, solitary leopards, and luxury tented bush retreats under star-strewn equatorial skies.', 'info@zanzirangihouse.com', '2026-09-30 22:26:04');
