INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'safari', '[dest-tarangire].description', 'Célebre por sus colosales baobabs milenarios, que se alzan como centinelas silenciosos a lo largo de un agreste valle fluvial. Tarangire alberga la mayor concentración de manadas de elefantes de África Oriental, donde majestuosas matriarcas guían a sus crías junto al vivificante río Tarangire.', 'Famed for its colossal ancient baobab trees that stand like silent sentinels across a rugged river valley. Tarangire hosts East Africa’s highest concentration of elephant herds, where majestic family matriarchs guide their calves along the life-giving Tarangire River.', 'info@zanzirangihouse.com', '2026-09-30 22:26:05');
