INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'testimonials', '[rev-01].reviewText', 'Desde el momento en que nuestro chófer privado nos recibió en el aeropuerto de Zanzíbar hasta nuestra última travesía en dhow al atardecer, cada detalle estuvo orquestado a la perfección. La piscina privada asomada sobre la marea del océano fue mágica.', 'From the moment our private chauffeur welcomed us at Zanzibar Airport to our final sunset dhow sail, every detail was orchestrated to absolute perfection. The plunge pool perched over the ocean tide was magical.', 'info@zanzirangihouse.com', '2026-09-30 22:26:32');
