INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'testimonials', '[rev-03].reviewText', 'Viajamos en familia, los cinco. Tener nuestra propia piscina infinita suspendida sobre la laguna de coral y a nuestro chef personal preparando la pesca fresca cada noche redefinió para nosotros lo que significa viajar con lujo.', 'We traveled as a family of five. Having our own private infinity pool suspended above the coral lagoon and our personal chef preparing fresh catches each evening redefined what luxury travel means to us.', 'info@zanzirangihouse.com', '2026-09-30 22:26:33');
