INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'testimonials', '[rev-04].reviewText', 'Las antiguas puertas talladas de latón y la piscina privada de nado crearon una atmósfera serena. Despertar con la brisa del océano y ver delfines salvajes en la excursión en dhow al amanecer fue uno de los momentos más memorables de nuestra vida.', 'The antique carved brass doors and private lap pool created a serene atmosphere. Waking up to ocean breezes and seeing wild dolphins on the sunrise dhow excursion was a lifelong highlight.', 'info@zanzirangihouse.com', '2026-09-30 22:26:33');
