INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'testimonials', '[rev-05].reviewText', 'Pasar directamente de la terraza de nuestra villa al cálido turquesa del océano Índico fue pura felicidad. La calidez del personal y su atención al detalle nos hicieron sentir como parte de la familia en Tanzania.', 'Stepping directly from our villa deck into the warm turquoise Indian Ocean was pure bliss. The staff’s warmth and attention to detail made us feel like honored family in Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:26:33');
