INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'villas', '[villa-02].description', 'Inmersa en jardines tropicales autóctonos, la Villa 02 ofrece absoluta tranquilidad y privacidad. Construida con madera de cultivo sostenible, techumbre de hoja de cocotero y piedra de coral local, la villa se mantiene naturalmente fresca bajo el sol ecuatorial. Disfrute de tardes de lectura en la cama de día rodeado del canto de los pájaros o déjese llevar por una ducha de agua de lluvia al aire libre bajo un manto de estrellas.', 'Immersed in indigenous tropical gardens, Villa 02 offers complete tranquility and privacy. Constructed using sustainably harvested timber, coconut palm thatch, and local coral ragstone, the villa remains naturally cool under the equatorial sun. Enjoy lazy afternoons reading on the daybed surrounded by birdsong, or indulge in an open-air rainwater shower under the canopy of night stars.', 'info@zanzirangihouse.com', '2026-09-30 22:25:08');
