INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'villas', '[villa-02].shortDescription', 'Escondida entre fragantes frangipanis y cocoteros, ofrece total privacidad, una ducha de piedra al aire libre y una serena veranda ajardinada.', 'Tucked within fragrant frangipani and coconut palms, offering total seclusion, an open-air stone shower, and serene garden verandah.', 'info@zanzirangihouse.com', '2026-09-30 22:25:06');
