INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'villas', '[villa-03].shortDescription', 'Despierte con el suave murmullo de las palmeras y pase directamente de su terraza de madera a la fina arena blanca del océano Índico.', 'Wake up to the soft rustle of palms and step straight from your wooden deck onto the powdery white sand of the Indian Ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:25:06');
