INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'villas', '[villa-05].description', 'En torno a un antiguo y venerado baobab, este generoso pabellón de dos dormitorios ofrece un confort excepcional para compañeros de viaje o familias. Cuenta con un patio central sombreado para el día a día, dos suites principales independientes, cada una con su propio baño al aire libre, y una pérgola privada para comer.', 'Centered around an ancient, revered Baobab tree, this generous two-bedroom pavilion provides exceptional comfort for traveling companions or families. Featuring a shaded central living courtyard, two independent master suites each with their own open-air bathroom, and a private dining pergola.', 'info@zanzirangihouse.com', '2026-09-30 22:25:08');
