INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'villas', '[villa-06].description', 'Un homenaje a la edad de oro de la artesanía en la Isla de las Especias. La Villa 06 luce auténticas puertas talladas con tachuelas de latón obra de maestros tallistas de Stone Town, suelos de terrazo vertidos a mano y una piscina privada de nado de agua dulce de 12 metros bordeada de arbustos de clavo y hierba limón.', 'A tribute to the Spice Island’s golden age of artisanal craftsmanship. Villa 06 features authentic brass-studded carved doors from Stone Town master carvers, hand-poured terrazzo floors, and a private 12-meter fresh water lap pool fringed by clove and lemongrass bushes.', 'info@zanzirangihouse.com', '2026-09-30 22:25:08');
