INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'villas', '[villa-07].description', 'Concebida para el viajero amante del diseño, la Villa 07 fusiona el minimalismo japonés-escandinavo con la calidez terrenal de África Oriental. Tonos neutros relajantes, alfombras de sisal tejidas a mano y una exclusiva terraza mirador en la azotea equipada con camas de día la convierten en un refugio para relajarse a la luz de la luna y meditar con calma.', 'Conceived for the design-conscious traveler, Villa 07 fuses Japanese-Scandinavian minimalism with East African earthiness. Soothing neutral tones, hand-woven sisal carpets, and an exclusive rooftop observation deck equipped with daybeds make this a haven for moonlit relaxation and tranquil meditation.', 'info@zanzirangihouse.com', '2026-09-30 22:25:09');
