INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'villas', '[villa-08].description', 'La dirección más exclusiva de la finca. Situada en su propio promontorio apartado, The Royal Presidential Villa ofrece total independencia, amplios salones para recibir, una piscina infinita privada frente al mar suspendida sobre la laguna de coral, servicio de chef privado bajo petición y acceso directo a una playa privada.', 'The estate’s most exclusive address. Set on its own secluded promontory, The Royal Presidential Villa offers total autonomy, expansive entertaining salons, a private oceanfront infinity pool suspended over the coral lagoon, a private chef service on request, and direct private beach access.', 'info@zanzirangihouse.com', '2026-09-30 22:25:09');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'villas', '[villa-08].name', 'The Royal Presidential Villa', 'The Royal Presidential Villa', 'info@zanzirangihouse.com', '2026-09-30 22:25:02');
