INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'villas', '[villa-08].shortDescription', 'La residencia insignia de Zanzirangi House. Una grandeza frente al mar sin igual, piscinas infinitas en varios niveles y una atención privada y discreta.', 'The flagship residence of Zanzirangi House. Unparalleled oceanfront grandeur, multi-level infinity pools, and discrete private hosting.', 'info@zanzirangihouse.com', '2026-09-30 22:25:07');
