INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'eyebrow', 'La Diferencia del Santuario', 'The Sanctuary Difference', 'info@zanzirangihouse.com', '2026-09-30 22:26:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'heading', 'POR QUÉ ZANZIRANGI HOUSE', 'WHY ZANZIRANGI HOUSE', 'info@zanzirangihouse.com', '2026-09-30 22:26:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'pillars[pillar-1].description', 'Recogido a lo largo de la virgen costa sur de Kizimkazi, lejos de las aglomeraciones turísticas. Aquí, el tiempo se mide por el vaivén de las mareas, el murmullo de las palmeras y los horizontes despejados del océano.', 'Tucked along the pristine southern coastline of Kizimkazi, far from tourist congestion. Here, time is measured by the tidal ebb and flow, the rustle of palms, and unobstructed ocean horizons.', 'info@zanzirangihouse.com', '2026-09-30 22:26:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'pillars[pillar-1].tagline', 'Un santuario privado lejos de las multitudes.', 'A private sanctuary away from the crowds.', 'info@zanzirangihouse.com', '2026-09-30 22:26:11');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'pillars[pillar-1].title', 'PRIVADO Y SERENO', 'PRIVATE & PEACEFUL', 'info@zanzirangihouse.com', '2026-09-30 22:26:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'pillars[pillar-2].description', 'Desde maestros tallistas suajilis y centenarios pabellones con techumbre de makuti hasta especias orgánicas recolectadas a diario en los huertos de la finca, viva el alma genuina de la Isla de las Especias.', 'From master Swahili woodcarvers and centuries-old makuti thatched pavilions to organic spices harvested daily from our estate gardens, experience the genuine soul of the Spice Island.', 'info@zanzirangihouse.com', '2026-09-30 22:26:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'pillars[pillar-2].tagline', 'Descubra la isla a través de su gente, sus sabores y su cultura.', 'Experience the island through its people, flavours and culture.', 'info@zanzirangihouse.com', '2026-09-30 22:26:11');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'pillars[pillar-2].title', 'ZANZÍBAR AUTÉNTICO', 'AUTHENTIC ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:26:11');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'pillars[pillar-3].description', 'Un anfitrión y un equipo de concierge dedicados, atentos a cada uno de sus deseos. Recibimiento privado a pie de pista en el aeropuerto, salidas en barco fletado, cenas en la villa y una hospitalidad personal y discreta en todo momento.', 'A dedicated host and concierge team attentive to your every need. Private airport tarmac greetings, chartered boat launches, in-villa dining, and discreet personal hospitality throughout.', 'info@zanzirangihouse.com', '2026-09-30 22:26:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'pillars[pillar-3].tagline', 'Desde la llegada al aeropuerto hasta la planificación del safari.', 'From airport arrival to safari planning.', 'info@zanzirangihouse.com', '2026-09-30 22:26:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'pillars[pillar-3].title', 'CONCIERGE PERSONAL', 'PERSONAL CONCIERGE', 'info@zanzirangihouse.com', '2026-09-30 22:26:11');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'pillars[pillar-4].description', 'Combine sin esfuerzo el descanso frente al mar con safaris en avioneta fletada al Serengeti, el cráter del Ngorongoro y Tarangire, para crear un viaje por África Oriental completo e inolvidable.', 'Seamlessly combine oceanfront rest with chartered fly-in bush safaris to the Serengeti, Ngorongoro Crater, and Tarangire, creating a complete and unforgettable East African journey.', 'info@zanzirangihouse.com', '2026-09-30 22:26:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'pillars[pillar-4].tagline', 'Combine su estancia en Zanzíbar con las maravillas de la Tanzania continental.', 'Connect your Zanzibar stay with the wonders of mainland Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:26:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'pillars[pillar-4].title', 'TANZANIA Y MÁS ALLÁ', 'TANZANIA BEYOND', 'info@zanzirangihouse.com', '2026-09-30 22:26:11');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('es', 'whystay', 'subhead', 'Cuatro valores esenciales definen cada momento en nuestro refugio y crean una atmósfera única de calma, exclusividad y profunda conexión con Tanzania.', 'Four guiding values define every moment at our retreat, creating a rare atmosphere of calm, exclusivity, and profound connection to Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:26:10');
