INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'chauffeur', 'subhead', 'Dès l’atterrissage de votre vol à Zanzibar, notre service de chauffeur privé assure votre trajet jusqu’à Zanzirangi House en toute simplicité, sérénité et sécurité.', 'From the moment your flight touches down in Zanzibar, our private chauffeur service ensures your transition to Zanzirangi House is completely effortless, serene, and secure.', 'info@zanzirangihouse.com', '2026-09-30 22:32:15');
