INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[arabic].description', 'Une célébration de l’héritage royal omanais de Zanzibar, vieux de plusieurs siècles, et des routes maritimes arabes. Savourez des viandes épicées braisées lentement, des pains plats cuits au four en terre, de délicats mezzés froids et chauds, des plats de riz parfumés au safran et de douces gourmandises à l’eau de rose préparées par nos maîtres cuisiniers.', 'A celebration of Zanzibar’s centuries-old royal Omani heritage and Arabian sea routes. Savor slow-braised spiced meats, clay-oven flatbreads, exquisite cold and hot mezze, fragrant saffron-infused rice dishes, and sweet rosewater delicacies prepared by master chefs.', 'info@zanzirangihouse.com', '2026-09-30 22:31:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[arabic].name', 'Cuisine arabe et omanaise authentique', 'Authentic Arabic & Omani Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:31:37');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[arabic].signatureDishes[#0].description', 'Agneau tendre cuit lentement pendant 24 heures avec clous de girofle, cardamome, coriandre, citron séché et feuilles de bananier, servi sur un riz Kabsa doré et parfumé au safran.', 'Tender lamb slow-cooked for 24 hours with cloves, cardamom, coriander, dry lime, and banana leaves, served over fragrant golden saffron Kabsa rice.', 'info@zanzirangihouse.com', '2026-09-30 22:31:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[arabic].signatureDishes[#0].name', 'Agneau shuwa omanais rôti lentement aux épices', 'Omani Shuwa Spiced Slow-Roasted Lamb', 'info@zanzirangihouse.com', '2026-09-30 22:31:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[arabic].signatureDishes[#1].description', 'Houmous velouté nappé de grenade, moutabal fumé, falafels croustillants aux herbes et pains plats arabes faits main cuits au feu de bois.', 'Velvety pomegranate-drizzled hummus, smoky Mutabal, crispy herbed falafel, and handmade wood-fired Arabic flatbreads.', 'info@zanzirangihouse.com', '2026-09-30 22:31:46');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[arabic].signatureDishes[#1].name', 'Mezzés royaux et khubz frais au za’atar', 'Royal Mezze & Fresh Za’atar Khubz', 'info@zanzirangihouse.com', '2026-09-30 22:31:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[arabic].signatureDishes[#2].description', 'Gambas géantes de Menai Bay, calamars et poissons de récif grillés au charbon de bois, assaisonnés de piment d’Alep, de sumac, d’ail et d’herbes sauvages.', 'Charcoal-grilled Menai Bay jumbo prawns, calamari, and reef catch seasoned with Aleppo pepper, sumac, garlic, and wild herbs.', 'info@zanzirangihouse.com', '2026-09-30 22:31:46');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[arabic].signatureDishes[#2].name', 'Plateau de fruits de mer mashwi et citron vert grillé', 'Mashwi Seafood & Charred Lime Platter', 'info@zanzirangihouse.com', '2026-09-30 22:31:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[arabic].signatureDishes[#3].description', 'Délicate pâte filo feuilletée garnie de pistaches grillées et nappée d’un sirop à la fleur d’oranger et à la cardamome, accompagnée d’un flan au lait à l’eau de rose bien frais.', 'Delicate flaky filo pastry layered with toasted pistachios and orange-blossom cardamom syrup alongside chilled rosewater milk pudding.', 'info@zanzirangihouse.com', '2026-09-30 22:31:46');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[arabic].signatureDishes[#3].name', 'Baklava tiède à la pistache et muhallabia à l’eau de rose', 'Warm Pistachio Baklava & Rosewater Muhallabia', 'info@zanzirangihouse.com', '2026-09-30 22:31:43');
