INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[arabic].tabLabel', 'Arabe', 'Arabic', 'info@zanzirangihouse.com', '2026-09-30 22:31:38');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[beverages].description', 'Une carte des boissons d’exception pensée pour les plaisirs tropicaux. Savourez des millésimes de renommée mondiale, de purs jus tropicaux de Zanzibar pressés à froid, des boissons botaniques maison et des eaux minérales premium d’une grande pureté, servis sur la plage ou au bord de la piscine.', 'An elevated beverage program curated for tropical indulgence. Enjoy world-class cellar vintages, pure cold-pressed Zanzibar tropical juices, house-crafted botanical soft drinks, and premium pristine mineral waters served beachfront or poolside.', 'info@zanzirangihouse.com', '2026-09-30 22:31:41');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[beverages].name', 'Boissons, cave et rafraîchissements', 'Beverages, Cellar & Refreshments', 'info@zanzirangihouse.com', '2026-09-30 22:31:38');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[beverages].signatureDishes[#0].description', 'Collections de l’Ancien et du Nouveau Monde, Chenin Blanc et Sauvignon Blanc sud-africains vifs, élégants champagnes français et rouges charpentés de Toscane et de Bordeaux.', 'Old and New World collections, crisp South African Chenin Blanc & Sauvignon Blanc, elegant French Champagnes, and full-bodied Tuscan & Bordeaux reds.', 'info@zanzirangihouse.com', '2026-09-30 22:31:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[beverages].signatureDishes[#0].name', 'Vins de cave et champagnes sélectionnés (Vins)', 'Curated Cellar Wines & Champagne (Wines)', 'info@zanzirangihouse.com', '2026-09-30 22:31:44');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[beverages].signatureDishes[#1].description', 'Fruit de la passion mûri au soleil, douce mangue Alphonso, ananas pilé à la menthe fraîche et eau de jeune noix de coco King tout droit venue des palmeraies côtières.', 'Sun-ripened passion fruit, sweet Alfonso mango, crushed pineapple with fresh mint, and young King coconut water straight from coastal palm groves.', 'info@zanzirangihouse.com', '2026-09-30 22:31:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[beverages].signatureDishes[#1].name', 'Nectars tropicaux de Zanzibar pressés à froid (Jus)', 'Cold-Pressed Zanzibar Tropical Nectars (Juice)', 'info@zanzirangihouse.com', '2026-09-30 22:31:44');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[beverages].signatureDishes[#2].description', 'Ginger beer maison relevée à la citronnelle pilée, rafraîchissement pétillant à l’hibiscus tanzanien, tonics botaniques artisanaux et sodas classiques bien frais.', 'House-brewed fiery ginger beer with crushed lemongrass, sparkling Tanzanian hibiscus cooler, craft botanical tonics, and classic iced sodas.', 'info@zanzirangihouse.com', '2026-09-30 22:31:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[beverages].signatureDishes[#2].name', 'Sodas et tonics botaniques artisanaux (Boissons fraîches)', 'Artisanal Botanical Sodas & Tonics (Soft Drinks)', 'info@zanzirangihouse.com', '2026-09-30 22:31:44');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[beverages].signatureDishes[#3].description', 'Eaux de source premium européennes et est-africaines, plates ou pétillantes, servies bien fraîches avec concombre du jardin, menthe et citron vert de Makunduchi.', 'Still and sparkling premium European & East African spring waters served crystal chilled with fresh garden cucumber, mint, and Makunduchi lime.', 'info@zanzirangihouse.com', '2026-09-30 22:31:48');
