INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[fusion].description', 'Notre signature culinaire. Un dialogue inventif entre la technique française classique et l’extraordinaire terroir d’épices de Zanzibar. Laissez-vous surprendre par des accords harmonieux tels que le beurre de homard infusé à la gousse de vanille, les réductions de tamarin et les soufflés au fruit de la passion.', 'Our culinary signature. An imaginative dialogue between classical French technique and Zanzibar’s extraordinary spice terroir. Expect harmonious pairings like vanilla bean infused lobster butter, tamarind reductions, and passion fruit soufflés.', 'info@zanzirangihouse.com', '2026-09-30 22:31:41');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[fusion].name', 'Fusion swahilie contemporaine', 'Swahili Contemporary Fusion', 'info@zanzirangihouse.com', '2026-09-30 22:31:38');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[fusion].signatureDishes[#0].description', 'Langouste tendre et succulente pochée dans un beurre clarifié français parfumé aux gousses de vanille de Pemba, émulsion de patate douce et salicorne.', 'Sweet succulent lobster poached in clarified French butter scented with fragrant Pemba vanilla pods, sweet potato emulsion, and sea asparagus.', 'info@zanzirangihouse.com', '2026-09-30 22:31:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[fusion].signatureDishes[#0].name', 'Langouste pochée au beurre et vanille de Pemba', 'Butter-Poached Rock Lobster with Pemba Vanilla', 'info@zanzirangihouse.com', '2026-09-30 22:31:43');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[fusion].signatureDishes[#1].description', 'Magret de canard à la peau croustillante servi rosé, avec un glaçage acidulé à la fleur d’hibiscus, des mini-carottes rôties et une purée de manioc épicée.', 'Crispy skin Magret duck breast served medium rare with a tart hibiscus flower glaze, roasted baby carrots, and spiced cassava purée.', 'info@zanzirangihouse.com', '2026-09-30 22:31:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[fusion].signatureDishes[#1].name', 'Magret de canard snacké au tamarin et à l’hibiscus', 'Seared Duck Breast with Tamarind & Hibiscus', 'info@zanzirangihouse.com', '2026-09-30 22:31:44');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[fusion].signatureDishes[#2].description', 'Gâteau coulant au chocolat noir 70 % parfumé à la cardamome verte, servi avec un gelato coco maison et un coulis de fruit de la passion.', 'Molten dark 70% chocolate cake perfumed with green cardamom, served with house-spun coconut gelato and passionfruit coulis.', 'info@zanzirangihouse.com', '2026-09-30 22:31:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[fusion].signatureDishes[#2].name', 'Fondant au chocolat Valrhona et à la cardamome de Zanzibar', 'Valrhona Chocolate & Zanzibar Cardamom Fondant', 'info@zanzirangihouse.com', '2026-09-30 22:31:44');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[fusion].subtitle', 'Quand l’île tropicale rencontre la haute cuisine française moderne', 'Where Tropical Island Meets Modern French Haute Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:31:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[fusion].tabLabel', 'Fusion', 'Fusion', 'info@zanzirangihouse.com', '2026-09-30 22:31:39');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[local].description', 'Des siècles de commerce maritime arabe, perse, indien et est-africain ont convergé dans les cuisines côtières de Zanzibar. Nos chefs exécutifs revisitent des recettes séculaires à base de lait de coco fraîchement extrait, de cardamome parfumée, de clous de girofle de Pemba et de produits de la mer pêchés à la ligne et débarqués directement sur nos rivages.', 'Centuries of Arab, Persian, Indian, and East African maritime trade converged in Zanzibar’s coastal kitchens. Our executive chefs prepare time-honored recipes featuring freshly harvested coconut milk, aromatic cardamom, cloves from Pemba, and line-caught seafood brought straight to our shores.', 'info@zanzirangihouse.com', '2026-09-30 22:31:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[local].name', 'Cuisine swahilie authentique', 'Authentic Swahili Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:31:37');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[local].signatureDishes[#0].description', 'Vivaneau de récif sauvage saisi puis mijoté avec de la coriandre fraîche, du curcuma moulu à la pierre et du lait de coco côtier pressé à la main, servi avec un riz au safran.', 'Pan-seared wild reef snapper simmered with fresh green coriander, stone-ground turmeric, and hand-squeezed coastal coconut milk served with saffron rice.', 'info@zanzirangihouse.com', '2026-09-30 22:31:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[local].signatureDishes[#0].name', 'Vivaneau de récif zanzibarite au lait de coco et curcuma', 'Zanzibari Coral Reef Snapper in Coconut & Turmeric', 'info@zanzirangihouse.com', '2026-09-30 22:31:41');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[local].signatureDishes[#1].description', 'Un bouillon acidulé de mangue et de tamarin longuement mijoté, avec des crevettes fondantes, des chips de manioc épicées et un sambal de coco au piment pilé.', 'A tangy, slow-simmered mango and tamarind broth with tender prawns, spiced cassava crisps, and crushed chili coconut sambal.', 'info@zanzirangihouse.com', '2026-09-30 22:31:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[local].signatureDishes[#1].name', 'Urojo tanzanien et ragoût de crevettes tigrées', 'Tanzanian Urojo & Tiger Prawn Stew', 'info@zanzirangihouse.com', '2026-09-30 22:31:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[local].signatureDishes[#2].description', 'Agneau local fondant infusé à l’anis étoilé, aux bâtons de cannelle et à la cardamome noire, accompagné d’une salade kachumbari marinée.', 'Fork-tender local lamb infused with star anise, cinnamon quills, and black cardamom, accompanied by pickled kachumbari salad.', 'info@zanzirangihouse.com', '2026-09-30 22:31:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[local].signatureDishes[#2].name', 'Chevreau braisé lentement aux épices pilau', 'Slow-Braised Goat with Pilau Spices', 'info@zanzirangihouse.com', '2026-09-30 22:31:42');
