INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[local].tabLabel', 'Swahilie', 'Swahili', 'info@zanzirangihouse.com', '2026-09-30 22:31:38');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[western].description', 'Pensée pour les palais internationaux en quête de saveurs familières et réconfortantes, sublimées par les techniques de la haute gastronomie. Pièces de bœuf importées de premier choix, salades méditerranéennes fraîches, pâtes faites maison et desserts gourmands exécutés avec une précision culinaire irréprochable.', 'Designed for international palates seeking comforting familiarity prepared with the highest fine-dining techniques. Prime imported beef cuts, fresh Mediterranean salads, homemade handmade pasta, and decadent desserts executed with crisp culinary precision.', 'info@zanzirangihouse.com', '2026-09-30 22:31:41');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[western].name', 'Gastronomie occidentale moderne', 'Modern Western Gastronomy', 'info@zanzirangihouse.com', '2026-09-30 22:31:38');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[western].signatureDishes[#0].description', 'Grillé à la perfection, accompagné d’une mousseline de panais onctueuse, de tomates en grappe rôties et d’un jus au vin rouge réduit pendant 24 heures.', 'Char-grilled to perfection, paired with smooth parsnip mousseline, blistered vine tomatoes, and a 24-hour reduced red wine jus.', 'info@zanzirangihouse.com', '2026-09-30 22:31:46');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[western].signatureDishes[#0].name', 'Filet de wagyu premium, glaçage à la truffe', 'Prime Wagyu Tenderloin with Truffle Glaze', 'info@zanzirangihouse.com', '2026-09-30 22:31:43');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[western].signatureDishes[#1].description', 'Thon local pêché à la ligne, coupé en dés avec de l’avocat Hass, de l’huile d’olive pressée à froid, des fruits de câprier et des croustillants de pain au levain maison.', 'Line-caught local tuna diced with Hass avocado, cold-pressed olive oil, caper berries, and house-baked sourdough crisps.', 'info@zanzirangihouse.com', '2026-09-30 22:31:46');
