INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'categories[western].signatureDishes[#2].description', 'Pâtes fraîches aux œufs mêlées à une queue de langouste de Kizimkazi, de l’ail confit, des tomates cerises et une légère bisque au Pinot Grigio.', 'Fresh egg pasta tossed with sweet Kizimkazi rock lobster tail, garlic confit, baby cherry tomatoes, and a light Pinot Grigio bisque.', 'info@zanzirangihouse.com', '2026-09-30 22:31:47');
