INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'gardenBadge', 'Potager du domaine', 'Estate Garden', 'info@zanzirangihouse.com', '2026-09-30 22:31:33');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'gardenDesc', 'Niché au cœur du domaine de Zanzirangi House, notre jardin botanique privé permet à notre brigade de cultiver en bio citronnelle, piments verts, basilic sauvage, menthe douce, cardamome parfumée et légumes de saison. La récolte du matin façonne directement nos menus dégustation du jour, alliant la vitalité de la terre à la pêche fraîche des eaux du sud de Zanzibar.', 'Tucked within the grounds of Zanzirangi House is our private botanical garden, where our kitchen team cultivates organic lemongrass, green chilies, wild basil, sweet mint, fragrant cardamom, and seasonal vegetables. What is harvested in the morning directly shapes our daily tasting menus, pairing earth-grown vitality with the fresh catch of southern Zanzibar’s waters.', 'info@zanzirangihouse.com', '2026-09-30 22:31:33');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'gardenEyebrow', 'Récits culinaires', 'Culinary Storytelling', 'info@zanzirangihouse.com', '2026-09-30 22:31:33');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'gardenTitle', 'DE NOTRE JARDIN À VOTRE TABLE', 'FROM OUR GARDEN TO YOUR TABLE', 'info@zanzirangihouse.com', '2026-09-30 22:31:33');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'heading', 'SAVEURS DE ZANZIBAR', 'TASTE ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:31:32');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'intro', 'Des siècles de commerce maritime swahili, omanais et de l’océan Indien se retrouvent à nos tables. Des poissons pêchés à la ligne et ramenés au lever du soleil aux currys parfumés longuement mijotés, dîner à Zanzirangi House est un authentique voyage des sens.', 'Centuries of Swahili, Omani, and Indian Ocean sea trade come together at our tables. From line-caught fish brought ashore at sunrise to slow-simmered aromatic curries, dining at Zanzirangi House is an authentic sensory journey.', 'info@zanzirangihouse.com', '2026-09-30 22:31:33');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'moments[#0].desc', 'Papaye tropicale, crème de fruit de la passion, brioche tiède tout juste sortie du four et café tanzanien épicé, servis face à l’océan au petit matin.', 'Tropical papaya, passion fruit curds, warm freshly-baked brioche, and spiced Tanzanian coffee served overlooking the morning ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:31:36');
