INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'dining', 'moments[#2].desc', 'Chips de banane plantain croustillantes, crevettes épicées au tamarin, vins de notre cave et cocktails botaniques faits maison tandis que l’horizon océanique se teinte de violet.', 'Crisp plantain crisps, spiced tamarind prawns, cellar wines, and handcrafted botanical cocktails as the ocean horizon turns violet.', 'info@zanzirangihouse.com', '2026-09-30 22:31:37');
