INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-cultural].description', 'Visitez le village de pêcheurs historique de Kizimkazi et l’ancienne mosquée de Dimbani (datant de 1107 apr. J.-C.). Rencontrez les maîtres artisans qui façonnent à la main les boutres traditionnels, participez à un atelier culinaire swahili ou savourez un concert privé de taarab au violon et au kanoun sous les étoiles.', 'Visit the historic Kizimkazi fishing settlement and the ancient Dimbani Mosque (dating to 1107 AD). Meet local master craftsmen carving traditional dhows by hand, participate in a Swahili culinary workshop, or enjoy private taarab violin and kanun music under the night stars.', 'info@zanzirangihouse.com', '2026-09-30 22:32:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-cultural].duration', '3,5 heures (horaires sur mesure)', '3.5 Hours (Custom Timing)', 'info@zanzirangihouse.com', '2026-09-30 22:31:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-cultural].priceNote', 'Prix sur demande', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:31:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-cultural].shortDescription', 'Partagez des moments authentiques avec les artisans de la côte, initiez-vous au tressage des palmes et à la restauration des boutres, et découvrez l’ancien héritage swahili.', 'Engage authentically with local coastal artisans, learn palm-weaving and dhow restoration, and discover ancient Swahili heritage.', 'info@zanzirangihouse.com', '2026-09-30 22:31:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-cultural].tag', 'Expériences culturelles', 'Cultural Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:31:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-cultural].title', 'Traditions swahilies, taarab et vie villageoise', 'Swahili Traditions, Taarab & Village Life', 'info@zanzirangihouse.com', '2026-09-30 22:31:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-cultural].whatsappMessage', 'Bonjour à l’équipe Concierge de Zanzirangi House, j’aimerais en savoir plus sur les expériences culturelles swahilies.', 'Hello Zanzirangi House Concierge, I would like to learn more about Swahili Cultural Experiences.', 'info@zanzirangihouse.com', '2026-09-30 22:32:02');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-dolphins].description', 'Notre emplacement à Kizimkazi, sur la côte sud de Zanzibar, offre un accès direct au sanctuaire de dauphins le plus célèbre d’Afrique de l’Est. Partez à l’aube à bord d’un boutre privé ou d’une vedette pour observer les dauphins jouer dans leur habitat océanique naturel, avant de savourer un petit-déjeuner de retour au domaine.', 'Our location in Kizimkazi on Zanzibar’s southern coast provides direct access to East Africa’s most famous dolphin sanctuary. Depart at dawn on a private dhow or motor launch to watch dolphin pods playing in their natural ocean habitat before enjoying breakfast back at the property.', 'info@zanzirangihouse.com', '2026-09-30 22:31:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-dolphins].duration', '3,5 heures (sortie à l’aube)', '3.5 Hours (Early Morning Dawn Cruise)', 'info@zanzirangihouse.com', '2026-09-30 22:31:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-dolphins].priceNote', 'Prix sur demande', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:31:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-dolphins].shortDescription', 'Prenez la mer au lever du soleil depuis Kizimkazi vers les eaux protégées de Menai Bay pour observer les groupes de dauphins à long bec et de grands dauphins qui y résident.', 'Set sail at sunrise from Kizimkazi into the protected waters of Menai Bay to witness pods of resident spinner and bottlenose dolphins.', 'info@zanzirangihouse.com', '2026-09-30 22:31:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-dolphins].tag', 'Rencontre avec les dauphins', 'Dolphin Experience', 'info@zanzirangihouse.com', '2026-09-30 22:31:53');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-dolphins].title', 'Rencontre avec les dauphins sauvages de Kizimkazi', 'Kizimkazi Wild Dolphin Encounter', 'info@zanzirangihouse.com', '2026-09-30 22:31:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-dolphins].whatsappMessage', 'Bonjour à l’équipe Concierge de Zanzirangi House, j’aimerais vivre la rencontre avec les dauphins sauvages de Kizimkazi.', 'Hello Zanzirangi House Concierge, I would like to experience the Kizimkazi Wild Dolphin Encounter.', 'info@zanzirangihouse.com', '2026-09-30 22:32:01');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-fishing].description', 'À bord de notre bateau de pêche sportive affrété, équipé de tangons, de matériel Shimano et d’une électronique de navigation moderne, vivez l’adrénaline de la pêche au gros dans les courants profonds de l’océan Indien. Le protocole de pêche avec remise à l’eau est strictement appliqué pour les poissons à rostre.', 'Aboard our chartered offshore sportfisher equipped with outriggers, Shimano tackle, and modern nautical electronics, experience the adrenaline of big game fishing in the deep currents of the Indian Ocean. Strictly adheres to catch-and-release protocols for billfish.', 'info@zanzirangihouse.com', '2026-09-30 22:32:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-fishing].duration', 'Demi-journée (5 heures) ou journée complète (8 heures)', 'Half Day (5 Hours) or Full Day (8 Hours)', 'info@zanzirangihouse.com', '2026-09-30 22:31:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-fishing].priceNote', 'Prix sur demande', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:31:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-fishing].shortDescription', 'Aventurez-vous dans les profonds canaux de Pemba et de Zanzibar pour une pêche sportive de classe mondiale : thon albacore, voilier et thazard-bâtard.', 'Venture into the deep Pemba and Zanzibar channels for world-class sport fishing targeting yellowfin tuna, sailfish, and wahoo.', 'info@zanzirangihouse.com', '2026-09-30 22:31:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-fishing].tag', 'Pêche en haute mer', 'Deep Sea Fishing', 'info@zanzirangihouse.com', '2026-09-30 22:31:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-fishing].title', 'Pêche sportive au gros en haute mer', 'Deep Sea Big Game Sport Fishing', 'info@zanzirangihouse.com', '2026-09-30 22:31:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-fishing].whatsappMessage', 'Bonjour à l’équipe Concierge de Zanzirangi House, j’aimerais obtenir des détails sur les sorties de pêche sportive en haute mer.', 'Hello Zanzirangi House Concierge, I would like details on Deep Sea Sport Fishing trips.', 'info@zanzirangihouse.com', '2026-09-30 22:32:02');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-island-hopping].description', 'Tracez votre propre route à travers les eaux turquoise du sud et de l’ouest de Zanzibar. Débarquez sur d’éphémères bancs de sable d’un blanc poudreux qui n’émergent qu’à marée basse, baignez-vous dans des eaux chaudes et cristallines et savourez un déjeuner fraîchement préparé de langouste grillée de Menai Bay, de calamars et de fruits tropicaux.', 'Chart your own course across the turquoise waters of southern and western Zanzibar. Disembark onto ephemeral powder-white sandbanks that emerge only at low tide, swim in warm crystalline waters, and savor a freshly prepared lunch of grilled Menai Bay lobster, calamari, and tropical fruit.', 'info@zanzirangihouse.com', '2026-09-30 22:31:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-island-hopping].duration', 'Journée complète (vedette privée)', 'Full Day (Private Speedboat)', 'info@zanzirangihouse.com', '2026-09-30 22:31:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-island-hopping].priceNote', 'Prix sur demande', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:31:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-island-hopping].shortDescription', 'Naviguez vers des îlots coralliens isolés et inhabités, baignez-vous dans des lagons déserts et savourez un déjeuner de fruits de mer grillés sur un banc de sable privé.', 'Cruise to secluded uninhabited coral islets, swim in deserted tidal lagoons, and enjoy a grilled seafood lunch on a private sandbank.', 'info@zanzirangihouse.com', '2026-09-30 22:31:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-island-hopping].tag', 'D’île en île', 'Island Hopping', 'info@zanzirangihouse.com', '2026-09-30 22:31:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-island-hopping].title', 'Croisière privée d’île en île et safari sur banc de sable', 'Private Island Hopping & Sandbank Safari', 'info@zanzirangihouse.com', '2026-09-30 22:31:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-island-hopping].whatsappMessage', 'Bonjour à l’équipe Concierge de Zanzirangi House, j’aimerais avoir des informations sur la croisière privée d’île en île et le safari sur banc de sable.', 'Hello Zanzirangi House Concierge, I would like to inquire about the Private Island Hopping Sandbank Safari.', 'info@zanzirangihouse.com', '2026-09-30 22:32:01');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-mnemba].description', 'Situé au large de la côte nord-est de Zanzibar, l’atoll de Mnemba est réputé dans le monde entier pour ses fonds marins préservés. Profitez de transferts en bateau privé, de sessions de snorkeling exclusives au-dessus des pinacles coralliens et d’un pique-nique gourmet sur la plage préparé par notre chef privé.', 'Located off Zanzibar’s northeast coast, Mnemba Atoll is recognized globally for its pristine underwater conditions. Enjoy private boat transfers, exclusive snorkeling over coral pinnacles, and a beachside gourmet picnic arranged by our private chef.', 'info@zanzirangihouse.com', '2026-09-30 22:32:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-mnemba].duration', 'Expédition privée d’une journée', 'Full Day Private Expedition', 'info@zanzirangihouse.com', '2026-09-30 22:31:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-mnemba].priceNote', 'Prix sur demande', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:31:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-mnemba].shortDescription', 'Naviguez vers le joyau des réserves marines de Zanzibar : une transparence turquoise inégalée, des jardins de corail préservés et des lagons peuplés de tortues de mer.', 'Sail to the crown jewel of Zanzibar marine reserves: unmatched turquoise clarity, pristine coral gardens, and sea turtle lagoons.', 'info@zanzirangihouse.com', '2026-09-30 22:31:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-mnemba].tag', 'Île de Mnemba', 'Mnemba Island', 'info@zanzirangihouse.com', '2026-09-30 22:31:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-mnemba].title', 'Sanctuaire marin d’exception de l’atoll de Mnemba', 'Mnemba Atoll Luxury Marine Sanctuary', 'info@zanzirangihouse.com', '2026-09-30 22:31:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-mnemba].whatsappMessage', 'Bonjour à l’équipe Concierge de Zanzirangi House, je souhaiterais réserver l’expédition au sanctuaire marin de l’île de Mnemba.', 'Hello Zanzirangi House Concierge, I would like to book the Mnemba Island Marine Sanctuary expedition.', 'info@zanzirangihouse.com', '2026-09-30 22:32:02');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-nature-jozani].description', 'Accompagné d’un naturaliste agréé du parc national, partez à la découverte des anciennes forêts de bois précieux protégées au sein du parc national de Jozani Chwaka Bay. Observez les troupes de singes se balancer dans la canopée, empruntez la passerelle surélevée à travers la mangrove et découvrez une flore rare, unique à Zanzibar.', 'Led by an authorized national park naturalist, journey into ancient hardwood forests protected within Jozani Chwaka Bay National Park. Observe monkey troops swinging through the canopy, walk the elevated mangrove boardwalk, and learn about the rare flora unique to Zanzibar.', 'info@zanzirangihouse.com', '2026-09-30 22:32:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-nature-jozani].duration', '4 heures (matin recommandé)', '4 Hours (Morning Recommended)', 'info@zanzirangihouse.com', '2026-09-30 22:31:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-nature-jozani].priceNote', 'Prix sur demande', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:31:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-nature-jozani].shortDescription', 'Parcourez une forêt primaire d’acajous sur nappe phréatique pour rencontrer l’espiègle colobe rouge de Zanzibar, espèce endémique.', 'Trek through virgin groundwater mahogany forest to encounter the playful, endemic Zanzibar Red Colobus monkey.', 'info@zanzirangihouse.com', '2026-09-30 22:31:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-nature-jozani].tag', 'Expériences nature', 'Nature Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:31:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-nature-jozani].title', 'Forêt de Jozani et éco-sanctuaire du colobe rouge', 'Jozani Forest & Red Colobus Eco-Sanctuary', 'info@zanzirangihouse.com', '2026-09-30 22:31:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-nature-jozani].whatsappMessage', 'Bonjour à l’équipe Concierge de Zanzirangi House, je souhaiterais réserver l’expérience nature dans la forêt de Jozani.', 'Hello Zanzirangi House Concierge, I would like to reserve the Jozani Forest Nature Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:32:02');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-snorkeling-diving].description', 'Les barrières de corail de Zanzibar regorgent d’une biodiversité tropicale foisonnante. Muni d’un équipement professionnel haut de gamme et accompagné de divemasters certifiés PADI, découvrez des tombants spectaculaires, des grottes à traverser à la nage et une visibilité cristalline pouvant atteindre 30 mètres.', 'Zanzibar’s barrier reefs are teeming with tropical biodiversity. Equipped with top-tier professional gear and accompanied by certified PADI divemasters, discover stunning drop-offs, swim-through caves, and crystal visibility extending up to 30 meters.', 'info@zanzirangihouse.com', '2026-09-30 22:31:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-snorkeling-diving].duration', 'Excursion d’une demi-journée ou d’une journée', 'Half Day or Full Day Excursion', 'info@zanzirangihouse.com', '2026-09-30 22:31:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-snorkeling-diving].priceNote', 'Prix sur demande', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:31:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-snorkeling-diving].shortDescription', 'Explorez de vibrants jardins de corail et des tombants sous-marins, à la rencontre des tortues de mer, des raies léopards et d’espèces de récif exotiques.', 'Explore vibrant coral gardens, underwater marine walls, and meet sea turtles, spotted eagle rays, and exotic reef species.', 'info@zanzirangihouse.com', '2026-09-30 22:31:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-snorkeling-diving].tag', 'Snorkeling et plongée', 'Snorkeling & Diving', 'info@zanzirangihouse.com', '2026-09-30 22:31:53');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-snorkeling-diving].title', 'Snorkeling sur le récif et plongée sous-marine en profondeur', 'Coral Reef Snorkeling & Deep Scuba Diving', 'info@zanzirangihouse.com', '2026-09-30 22:31:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-snorkeling-diving].whatsappMessage', 'Bonjour à l’équipe Concierge de Zanzirangi House, je souhaiterais organiser une excursion de snorkeling et de plongée.', 'Hello Zanzirangi House Concierge, I would like to arrange a Snorkeling & Diving excursion.', 'info@zanzirangihouse.com', '2026-09-30 22:32:01');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-spice-farm].description', 'Promenez-vous aux côtés de botanistes locaux experts à travers de verdoyantes plantations rurales. Touchez, sentez et goûtez les épices brutes directement sur les arbres et les lianes — poivre noir, noix de muscade, gingembre, citronnelle et curcuma — avant de conclure avec une eau de noix de coco King fraîchement cueillie au sommet des palmiers.', 'Walk alongside expert local botanists through verdant rural plantations. Touch, smell, and taste raw spices directly from the trees and vines—including black pepper, nutmeg, ginger, lemongrass, and turmeric—concluding with fresh King coconut water harvested high in the canopy.', 'info@zanzirangihouse.com', '2026-09-30 22:31:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-spice-farm].duration', '4 heures (matin ou après-midi)', '4 Hours (Morning or Afternoon)', 'info@zanzirangihouse.com', '2026-09-30 22:31:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-spice-farm].priceNote', 'Prix sur demande', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:31:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-spice-farm].shortDescription', 'Plongez vos sens dans des siècles d’histoire parfumée : cueillez de la cannelle fraîche, écrasez de la cardamome verte et goûtez la gousse de vanille sauvage.', 'Immerse your senses in centuries of aromatic history: pluck fresh cinnamon, crush green cardamom, and taste wild vanilla bean.', 'info@zanzirangihouse.com', '2026-09-30 22:31:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-spice-farm].tag', 'Ferme d’épices', 'Spice Farm', 'info@zanzirangihouse.com', '2026-09-30 22:31:53');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-spice-farm].title', 'Voyage dans une ferme d’épices botanique et bio', 'Organic Botanical Spice Farm Journey', 'info@zanzirangihouse.com', '2026-09-30 22:31:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-spice-farm].whatsappMessage', 'Bonjour à l’équipe Concierge de Zanzirangi House, je suis intéressé(e) par la visite de la ferme d’épices botanique et bio.', 'Hello Zanzirangi House Concierge, I am interested in the Organic Botanical Spice Farm Journey.', 'info@zanzirangihouse.com', '2026-09-30 22:32:01');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-stonetown].description', 'Un voyage privé au cœur de Stone Town, classée au patrimoine mondial de l’UNESCO. Guidé par un historien swahili local, découvrez la Maison des Merveilles, le Vieux Fort du XVIIe siècle, la cathédrale anglicane et le mémorial de l’ancien marché aux esclaves, ainsi que des ateliers d’artisans spécialisés dans la bijouterie en argent et les textiles tissés.', 'A private journey through UNESCO World Heritage Stone Town. Led by a resident Swahili historian, explore the House of Wonders, the 17th-century Old Fort, the Anglican Cathedral and Old Slave Market memorial, and artisan workshops specializing in silver jewelry and woven textiles.', 'info@zanzirangihouse.com', '2026-09-30 22:31:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-stonetown].duration', 'Journée complète (chauffeur et guide privés)', 'Full Day (Private Chauffeur & Guide)', 'info@zanzirangihouse.com', '2026-09-30 22:31:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-stonetown].priceNote', 'Prix sur demande', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:31:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-stonetown].shortDescription', 'Flânez dans un dédale de ruelles en pierre de corail, devant des portes omanaises en teck ouvragé, à travers les bazars d’épices historiques jusqu’au palais du Sultan.', 'Walk through labyrinthine coral ragstone alleyways, ornate Omani carved teak doors, historical spice bazaars, and the Sultan’s Palace.', 'info@zanzirangihouse.com', '2026-09-30 22:31:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-stonetown].tag', 'Culture et patrimoine', 'Culture & Heritage', 'info@zanzirangihouse.com', '2026-09-30 22:31:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-stonetown].title', 'Patrimoine et quartiers historiques de Stone Town', 'Stone Town Heritage & Historic Quarters', 'info@zanzirangihouse.com', '2026-09-30 22:31:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-stonetown].whatsappMessage', 'Bonjour à l’équipe Concierge de Zanzirangi House, je souhaiterais réserver l’expérience privée « Patrimoine de Stone Town ».', 'Hello Zanzirangi House Concierge, I am interested in booking the private Stone Town Heritage Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:32:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-sunset-cruise].description', 'Embarquez à bord d’un boutre swahili artisanal taillé dans l’acajou indigène. Détendez-vous sur de moelleux coussins avec du champagne frais et des canapés raffinés, bercé par la brise océane et les mélodies acoustiques du taarab, tandis que le jour cède place au crépuscule.', 'Step aboard a handcrafted Swahili sailing dhow carved from indigenous mahogany. Relax upon plush cushions with chilled Champagne, artisanal canapés, and the hypnotic sounds of the ocean breeze and acoustic taarab melodies as daylight fades into dusk.', 'info@zanzirangihouse.com', '2026-09-30 22:31:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-sunset-cruise].duration', '2,5 heures (fin d’après-midi, à l’heure dorée)', '2.5 Hours (Late Afternoon Golden Hour)', 'info@zanzirangihouse.com', '2026-09-30 22:31:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-sunset-cruise].priceNote', 'Prix sur demande', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:31:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-sunset-cruise].shortDescription', 'Glissez sur l’océan Indien apaisé, voiles gonflées par le vent, tandis que le soleil équatorial colore le ciel de nuances d’ambre et d’or rose.', 'Glide across the calm Indian Ocean under billowed canvas sails as the equatorial sun paints the sky in shades of amber and rose gold.', 'info@zanzirangihouse.com', '2026-09-30 22:31:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'experiences', '[exp-sunset-cruise].tag', 'Croisière au coucher du soleil', 'Sunset Cruise', 'info@zanzirangihouse.com', '2026-09-30 22:31:53');
