INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'facilities', '[bbq].category', 'Soirées conviviales', 'Evening Gathering', 'info@zanzirangihouse.com', '2026-09-30 22:32:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'facilities', '[bbq].description', 'Lorsque le soleil plonge dans l’océan Indien, retrouvez-vous autour de notre feu de camp sur le rivage pour savourer langouste grillée, crevettes tigrées et filets épicés cuits sur des coques de noix de coco, sous les constellations africaines.', 'As the sun dips into the Indian Ocean, gather around our shoreline firepit for grilled lobster, tiger prawns, and spiced tenderloins cooked over coconut husks under the African constellations.', 'info@zanzirangihouse.com', '2026-09-30 22:32:22');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'facilities', '[bbq].highlight', 'Dîner aux chandelles face à l’océan au son du taarab acoustique en live', 'Oceanfront candlelit dining with live acoustic Taarab music', 'info@zanzirangihouse.com', '2026-09-30 22:32:24');
