INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'facilities', '[breakfast].description', 'Éveillez-vous avec des assiettes de fruits tropicaux des vergers locaux, une brioche tout juste sortie du four, une crème de fruit de la passion, du café arabica tanzanien et des œufs préparés selon vos envies, servis en villa ou face à la mer.', 'Awaken to tropical fruit platters from local orchards, freshly baked brioche, passion fruit curd, Tanzanian arabica coffee, and eggs cooked to your preference in your villa or by the sea.', 'info@zanzirangihouse.com', '2026-09-30 22:32:22');
