INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'facilities', '[dining].description', 'Un pavillon à ciel ouvert sous une voûte de chaume makuti, offrant une vue panoramique sur l’océan. Savourez une cuisine raffinée aux arômes d’épices de Zanzibar et aux poissons les plus frais du jour.', 'An open-air pavilion beneath vaulted Makuti thatch offering panoramic ocean views. Experience fine dining infused with the aromas of Zanzibar spices and the freshest catches of the day.', 'info@zanzirangihouse.com', '2026-09-30 22:32:22');
