INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'facilities', '[massage].description', 'Des salas de spa à ciel ouvert, nichées dans les jardins côtiers. Offrez-vous des massages sur mesure à l’huile de coco de Zanzibar pressée à froid, à la citronnelle, aux clous de girofle moulus et aux plantes africaines indigènes.', 'Secluded open-air spa salas nestled in coastal gardens. Indulge in bespoke massages using cold-pressed Zanzibar coconut oil, lemongrass, ground cloves, and indigenous African botanicals.', 'info@zanzirangihouse.com', '2026-09-30 22:32:22');
