INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'facilities', '[pool].description', 'Suspendue au-dessus des marées turquoise de l’océan Indien, notre piscine à débordement de 25 mètres à l’eau douce reflète le ciel et l’horizon, avec ses transats immergés et un service attentionné au bord de l’eau.', 'Suspended above the turquoise tides of the Indian Ocean, our 25-meter freshwater infinity pool mirrors the sky and ocean horizons with sunken sunbeds and attentive poolside service.', 'info@zanzirangihouse.com', '2026-09-30 22:32:21');
