INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'facilities', '[wifi].description', 'Profitez d’un internet par satellite ultrarapide et à faible latence sur l’ensemble du domaine, dans les villas privées, sur les transats en bord de plage et les terrasses de restauration, pour une communication fluide et un télétravail sans contrainte.', 'Enjoy blazing-fast, low-latency satellite internet across the entire estate, private villas, beachfront loungers, and dining terraces, ensuring seamless communication and remote productivity.', 'info@zanzirangihouse.com', '2026-09-30 22:32:22');
