INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'homepage', 'intro.description', 'Zanzirangi House est une retraite ultra-boutique de 8 villas avec piscine privée, nichée à l’écart sur la paisible côte sud de Zanzibar, à Kizimkazi Dimbani.', 'Zanzirangi House is an ultra-boutique retreat featuring 8 private plunge-pool villas secluded along the peaceful southern coast of Zanzibar in Kizimkazi Dimbani.', 'info@zanzirangihouse.com', '2026-09-30 22:30:58');
