INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[about].description', 'Niché le long de la côte corallienne préservée du sud, à Kizimkazi Dimbani, Zanzirangi House est un sanctuaire privé ultra-boutique conçu pour offrir une intimité totale, une harmonie architecturale et une hospitalité zanzibarite chaleureuse et personnelle.', 'Nestled along the pristine southern coral coast of Kizimkazi Dimbani, Zanzirangi House is an ultra-boutique private sanctuary designed to offer total seclusion, architectural harmony, and intimate Zanzibar hospitality.', 'info@zanzirangihouse.com', '2026-09-30 22:32:44');
