INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[contact].description', 'Organisez votre séjour sur mesure avec notre équipe de conciergerie. Qu’il s’agisse de vérifier la disponibilité des villas privées, d’organiser vos transferts de 45 minutes depuis l’aéroport de ZNZ ou de concevoir un itinéraire de safari personnalisé en Tanzanie, nous sommes disponibles 24/7.', 'Plan your bespoke stay with our concierge team. Whether arranging private villa availability, 45-minute airport transfers from ZNZ, or custom Tanzania safari itineraries, we are available 24/7.', 'info@zanzirangihouse.com', '2026-09-30 22:32:44');
