INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[dining].description', 'Découvrez l’authentique patrimoine culinaire de Zanzibar, mariant épices swahilies et fruits de mer de l’océan Indien pêchés chaque jour par les pêcheurs artisanaux en boutre de Kizimkazi. Profitez de repas privés sur la véranda, de barbecues sur la plage et de dîners aux chandelles sur mesure sous les étoiles.', 'Taste authentic Zanzibar culinary heritage blending Swahili spices with Indian Ocean seafood caught daily by Kizimkazi artisanal dhow fishermen. Enjoy private veranda dining, beach barbecues, and bespoke candlelit dinners under the stars.', 'info@zanzirangihouse.com', '2026-09-30 22:32:45');
