INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[experiences].description', 'Des rencontres éthiques avec les dauphins sauvages de la réserve marine de Menai Bay aux visites privées du patrimoine de Stone Town classé à l’UNESCO, en passant par les sentiers d’épices bio et la navigation en boutre au coucher du soleil, découvrez Zanzibar avec nos guides privés dédiés.', 'From ethical wild dolphin encounters in the Menai Bay Marine Reserve to private Stone Town UNESCO heritage tours, organic spice trails, and sunset dhow sailing—experience Zanzibar with our dedicated private guides.', 'info@zanzirangihouse.com', '2026-09-30 22:32:45');
