INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.introText', 'Chez Zanzirangi House (accessible à l’adresse https://zanzirangihouse.com/), la protection des données personnelles et de la vie privée de nos hôtes est de la plus haute importance. La présente Politique de confidentialité décrit la manière dont nous collectons, utilisons et protégeons vos informations lorsque vous consultez notre site web, soumettez des demandes de réservation ou communiquez avec notre équipe de conciergerie.', 'At Zanzirangi House (accessible from https://zanzirangihouse.com/), safeguarding our guests’ personal data and privacy is of utmost importance. This Privacy Policy details how we collect, use, and protect information when you visit our website, submit booking inquiries, or communicate with our concierge team.', 'info@zanzirangihouse.com', '2026-09-30 22:32:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.lastUpdated', 'Septembre 2026', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:32:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.sections[#0].body', 'Lorsque vous soumettez une demande ou réservez une villa privée, vous pouvez être amené(e) à nous communiquer des informations telles que vos nom et prénom, votre adresse e-mail, votre numéro de téléphone/WhatsApp, vos dates d’arrivée et de départ, le nombre de personnes de votre groupe ainsi que vos préférences particulières en matière d’accueil ou d’alimentation.', 'When submitting an inquiry or reserving a private villa, you may provide details including your full name, email address, telephone/WhatsApp number, arrival/departure dates, guest party size, and special hospitality or dietary preferences.', 'info@zanzirangihouse.com', '2026-09-30 22:32:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.sections[#0].title', '1. Informations que nous collectons', '1. Information We Collect', 'info@zanzirangihouse.com', '2026-09-30 22:32:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.sections[#1].items[#0]', 'Traiter les demandes de réservation et vérifier la disponibilité des chambres.', 'Facilitating reservation inquiries and room availability checks.', 'info@zanzirangihouse.com', '2026-09-30 22:32:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.sections[#1].items[#1]', 'Organiser les transferts avec chauffeur depuis l’aéroport international Abeid Amani Karume (ZNZ).', 'Coordinating airport chauffeur transfers from Abeid Amani Karume International Airport (ZNZ).', 'info@zanzirangihouse.com', '2026-09-30 22:32:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.sections[#1].items[#2]', 'Personnaliser les dîners privés, les excursions d’observation des dauphins et les liaisons vers les safaris en Tanzanie continentale.', 'Customizing private dining, marine dolphin tours, and mainland Tanzania safari connections.', 'info@zanzirangihouse.com', '2026-09-30 22:32:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.sections[#1].items[#3]', 'Assurer les communications de majordome et de conciergerie personnelles 24/7.', 'Providing 24/7 personal butler and concierge communications.', 'info@zanzirangihouse.com', '2026-09-30 22:32:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.sections[#1].title', '2. Utilisation de vos informations', '2. How We Use Your Information', 'info@zanzirangihouse.com', '2026-09-30 22:32:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.sections[#2].body', 'Nous mettons en œuvre des mesures de protection techniques et administratives strictes. Nous ne vendons, ne louons ni ne cédons les informations de nos hôtes à des réseaux de marketing commercial tiers. Les données sont partagées exclusivement avec des prestataires de services locaux agréés (tels que les opérateurs officiels de vols safari agréés par TANAPA), dans le strict but d’exécuter l’itinéraire convenu.', 'We implement strict technical and administrative safeguards. We do not sell, rent, or lease guest information to third-party commercial marketing networks. Data is shared exclusively with licensed local service providers (such as official TANAPA safari charter operators) strictly to fulfill your agreed itinerary.', 'info@zanzirangihouse.com', '2026-09-30 22:32:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.sections[#2].title', '3. Sécurité des données & communication à des tiers', '3. Data Security & Third-Party Disclosure', 'info@zanzirangihouse.com', '2026-09-30 22:32:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.sections[#3].body', 'Pour toute question relative à la confidentialité ou pour demander la suppression de vos données, contactez directement notre équipe chargée de la protection des données à l’adresse concierge@zanzirangihouse.com ou par téléphone officiel au +255 777 890 123.', 'For any privacy inquiries or to request data removal, contact our data protection team directly at concierge@zanzirangihouse.com or via official telephone at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:32:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].contentJson.sections[#3].title', '4. Contacter notre conciergerie', '4. Contact Our Concierge', 'info@zanzirangihouse.com', '2026-09-30 22:32:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[privacy].description', 'Chez Zanzirangi House, la protection des données personnelles et de la vie privée de nos hôtes est de la plus haute importance.', 'At Zanzirangi House, safeguarding our guests’ personal data and privacy is of utmost importance.', 'info@zanzirangihouse.com', '2026-09-30 22:32:45');
