INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[safari].description', 'Associez votre retraite de luxe pieds nus à Zanzibar à des safaris de classe mondiale sur le continent. Nous organisons des vols privés affrétés de 90 minutes directement vers le parc national du Serengeti, le cratère du Ngorongoro et le mont Kilimanjaro, avec les plus prestigieux camps de safari de luxe.', 'Combine your barefoot luxury retreat in Zanzibar with world-class mainland safaris. We coordinate 90-minute private air charters directly to Serengeti National Park, Ngorongoro Crater, and Mount Kilimanjaro with premier luxury safari camps.', 'info@zanzirangihouse.com', '2026-09-30 22:32:46');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[safari].eyebrow', 'EXPÉDITIONS BROUSSE & PLAGE EN AVION • TANZANIE CONTINENTALE', 'FLY-IN BUSH & BEACH EXPEDITIONS • TANZANIA MAINLAND', 'info@zanzirangihouse.com', '2026-09-30 22:32:39');
