INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[terms].contentJson.introText', 'Bienvenue à Zanzirangi House. En accédant à notre site web (https://zanzirangihouse.com/) ou en soumettant des demandes d’hébergement et d’excursions, vous acceptez de respecter les conditions d’accueil et les règles de réservation suivantes.', 'Welcome to Zanzirangi House. By accessing our website (https://zanzirangihouse.com/) or submitting accommodation and excursion requests, you agree to comply with the following hospitality terms and reservation guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:32:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[terms].contentJson.lastUpdated', 'Septembre 2026', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:32:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[terms].contentJson.sections[#0].body', 'Les tarifs des villas par nuit varient de $390 à $480+ USD et incluent l’accès à la piscine privée, le petit-déjeuner gourmet et un service de majordome dédié 24/7. La confirmation de la réservation requiert le versement d’un acompte convenu ou la présentation d’un bon d’échange via les canaux de réservation officiels.', 'Nightly villa rates range between $390 and $480+ USD and include private plunge pool access, gourmet breakfast, and 24/7 dedicated butler service. Confirmation requires an agreed deposit or voucher via official reservation channels.', 'info@zanzirangihouse.com', '2026-09-30 22:32:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[terms].contentJson.sections[#0].title', '1. Réservations & paiements', '1. Reservations & Payments', 'info@zanzirangihouse.com', '2026-09-30 22:32:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[terms].contentJson.sections[#1].body', 'L’arrivée standard s’effectue à partir de 14:00 (2:00 PM) et le départ au plus tard à 11:00 (11:00 AM). Une arrivée anticipée ou un départ tardif peut être demandé auprès de votre concierge personnel, sous réserve de disponibilité de la villa.', 'Standard check-in is from 14:00 (2:00 PM), and check-out is by 11:00 (11:00 AM). Early arrival or late departure may be requested through your personal concierge, subject to villa availability.', 'info@zanzirangihouse.com', '2026-09-30 22:32:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[terms].contentJson.sections[#1].title', '2. Horaires d’arrivée & de départ', '2. Check-In & Check-Out Times', 'info@zanzirangihouse.com', '2026-09-30 22:32:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[terms].contentJson.sections[#2].body', 'Zanzirangi House borde l’aire de conservation marine de Menai Bay. Les hôtes participant aux sorties en boutre et aux excursions d’observation des dauphins s’engagent à respecter les protocoles éthiques relatifs à la faune, en maintenant une distance respectueuse avec les animaux marins, conformément à la réglementation environnementale locale.', 'Zanzirangi House borders the Menai Bay Marine Conservation Area. Guests participating in dhow sailing and dolphin excursions agree to follow ethical wildlife protocols, maintaining respectful distances from marine wildlife in compliance with local environmental regulations.', 'info@zanzirangihouse.com', '2026-09-30 22:32:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[terms].contentJson.sections[#2].title', '3. Protection marine & respect de la faune', '3. Marine Conservation & Wildlife Etiquette', 'info@zanzirangihouse.com', '2026-09-30 22:32:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[terms].contentJson.sections[#3].body', 'Pour modifier ou annuler une réservation, contactez directement notre conciergerie par e-mail à l’adresse concierge@zanzirangihouse.com ou par WhatsApp au +255 777 890 123.', 'To modify or cancel a reservation, contact our concierge directly via email at concierge@zanzirangihouse.com or WhatsApp at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:32:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[terms].contentJson.sections[#3].title', '4. Demandes & annulations', '4. Inquiries & Cancellations', 'info@zanzirangihouse.com', '2026-09-30 22:32:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[terms].description', 'Bienvenue à Zanzirangi House. En accédant à notre site web ou en soumettant des demandes de réservation, vous acceptez de respecter nos conditions d’accueil.', 'Welcome to Zanzirangi House. By accessing our website or submitting reservation requests, you agree to comply with our hospitality guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:32:46');
