INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[villas].description', 'Découvrez nos 8 résidences privées artisanales, de 78 m² à 95 m². Chaque villa dispose d’une piscine privée à l’eau douce 100 % privative, d’une authentique architecture swahilie en pierre de corail et d’un service de majordome personnalisé dédié 24/7.', 'Discover our 8 private artisanal residences ranging from 78 m² to 95 m². Each villa features a 100% private freshwater plunge pool, authentic Swahili coral-stone architecture, and personalized 24/7 dedicated butler service.', 'info@zanzirangihouse.com', '2026-09-30 22:32:46');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'pages', '[villas].eyebrow', 'KIZIMKAZI DIMBANI • CÔTE SUD DE ZANZIBAR', 'KIZIMKAZI DIMBANI • SOUTH COAST ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:32:40');
