INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'safari', '[dest-kilimanjaro].bestFor', 'Vues aériennes emblématiques et randonnée en altitude', 'Iconic aerial perspectives & alpine trekking', 'info@zanzirangihouse.com', '2026-09-30 22:32:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'safari', '[dest-kilimanjaro].description', 'Plus haut sommet d’Afrique et plus haute montagne isolée du monde, il s’élève majestueusement à 5 895 mètres au-dessus des plaines tropicales. Des survols panoramiques en hélicoptère privé autour du pic Uhuru aux randonnées d’une journée sur les sentiers luxuriants de la forêt tropicale et dans les plantations de café, découvrez la couronne emblématique de la Tanzanie.', 'Africa’s highest peak and the world’s tallest free-standing mountain rises majestically 5,895 meters above tropical plains. From scenic private helicopter flights encircling Uhuru Peak to day treks along lush lower rainforest trails and coffee estates, experience Tanzania’s iconic crown.', 'info@zanzirangihouse.com', '2026-09-30 22:32:06');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'safari', '[dest-kilimanjaro].flightTimeFromZanzibar', '1h 10m jusqu’à l’aéroport int. du Kilimanjaro', '1h 10m to Kilimanjaro Int’l', 'info@zanzirangihouse.com', '2026-09-30 22:32:05');
