INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'safari', '[dest-ngorongoro].bestFor', 'Splendeur géologique et forte densité de faune', 'Geological splendor & concentrated wildlife density', 'info@zanzirangihouse.com', '2026-09-30 22:32:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'safari', '[dest-ngorongoro].description', 'La plus grande caldeira volcanique intacte au monde, véritable sanctuaire écologique autonome de 600 mètres de profondeur. Descendez à travers les forêts d’acacias embrumées de ses rebords jusqu’à un amphithéâtre ancestral où vivent des rhinocéros noirs menacés, des hippopotames et des milliers de flamants roses arpentant le lac Magadi.', 'The world’s largest intact volcanic caldera, creating a self-contained ecological haven 600 meters deep. Descend through misty rim acacia forests into an ancient amphitheater bustling with endangered black rhinos, hippos, and thousands of pink flamingos wading in Lake Magadi.', 'info@zanzirangihouse.com', '2026-09-30 22:32:06');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'safari', '[dest-ngorongoro].flightTimeFromZanzibar', '1h 30m jusqu’à la piste de Manyara', '1h 30m to Manyara Airstrip', 'info@zanzirangihouse.com', '2026-09-30 22:32:05');
