INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'safari', '[dest-serengeti].description', 'De vastes savanes dorées qui s’étendent à perte de vue. Assistez au spectacle de millions de gnous et de zèbres bravant des rivières infestées de crocodiles, aux côtés des troupes de lions, des léopards solitaires et de luxueux camps de toile en pleine brousse, sous des ciels équatoriaux constellés d’étoiles.', 'Vast golden savannahs that stretch endlessly to the horizon. Witness millions of wildebeest and zebras braving crocodile-laden rivers, accompanied by resident prides of lions, solitary leopards, and luxury tented bush retreats under star-strewn equatorial skies.', 'info@zanzirangihouse.com', '2026-09-30 22:32:06');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'safari', '[dest-serengeti].flightTimeFromZanzibar', '1h 45m en avion de brousse direct', '1h 45m Direct Bush Plane', 'info@zanzirangihouse.com', '2026-09-30 22:32:05');
