INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'safari', '[dest-tarangire].bestFor', 'Paysages de baobabs et rencontres intimes avec les éléphants', 'Baobab landscapes & intimate elephant encounters', 'info@zanzirangihouse.com', '2026-09-30 22:32:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'safari', '[dest-tarangire].description', 'Célèbre pour ses baobabs millénaires colossaux, dressés comme de silencieuses sentinelles au-dessus d’une vallée fluviale sauvage. Tarangire abrite la plus forte concentration de troupeaux d’éléphants d’Afrique de l’Est, où de majestueuses matriarches guident leurs petits le long de la rivière Tarangire, source de vie.', 'Famed for its colossal ancient baobab trees that stand like silent sentinels across a rugged river valley. Tarangire hosts East Africa’s highest concentration of elephant herds, where majestic family matriarchs guide their calves along the life-giving Tarangire River.', 'info@zanzirangihouse.com', '2026-09-30 22:32:06');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'safari', '[dest-tarangire].flightTimeFromZanzibar', '1h 20m de vol', '1h 20m Flight', 'info@zanzirangihouse.com', '2026-09-30 22:32:06');
