INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'testimonials', '[rev-02].reviewText', 'La sobriété architecturale, l’utilisation de la pierre de corail locale et un service de majordome attentionné mais discret nous ont rappelé les plus beaux lodges Aman ou Singita. Le dîner swahili de fruits de mer au lait de coco était inoubliable.', 'The architectural restraint, use of indigenous coral stone, and attentive but discrete butler service reminded us of the very finest Aman or Singita lodges. The Swahili coconut seafood dinner was unforgettable.', 'info@zanzirangihouse.com', '2026-09-30 22:32:34');
