INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'testimonials', '[rev-03].reviewText', 'Nous avons voyagé en famille, à cinq. Disposer de notre propre piscine à débordement suspendue au-dessus du lagon corallien et de notre chef personnel préparant chaque soir la pêche du jour a redéfini pour nous le sens du voyage de luxe.', 'We traveled as a family of five. Having our own private infinity pool suspended above the coral lagoon and our personal chef preparing fresh catches each evening redefined what luxury travel means to us.', 'info@zanzirangihouse.com', '2026-09-30 22:32:34');
