INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'testimonials', '[rev-05].reviewText', 'Descendre directement de la terrasse de notre villa dans les eaux chaudes et turquoise de l’océan Indien était un pur bonheur. La chaleur du personnel et son souci du détail nous ont fait nous sentir comme des membres de la famille, honorés, en Tanzanie.', 'Stepping directly from our villa deck into the warm turquoise Indian Ocean was pure bliss. The staff’s warmth and attention to detail made us feel like honored family in Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:32:34');
