INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'villas', '[villa-01].description', 'La Villa Sultan Front de Mer incarne le summum du luxe pieds nus à Zanzibar. Inspiré de l’architecture omanaise classique et des traditions maritimes swahilies, ce sanctuaire se distingue par ses hauts plafonds en bois, ses murs en enduit de chaux poli et ses vastes baies vitrées du sol au plafond qui effacent la frontière entre l’intérieur et l’océan Indien. Rejoignez votre terrasse privée et sa piscine à débordement, ou détendez-vous dans la baignoire en pierre sculptée face aux boutres du soir.', 'The Sultan Oceanfront Villa represents the pinnacle of barefoot luxury in Zanzibar. Inspired by classical Omani architecture and Swahili maritime traditions, this sanctuary features high timber ceilings, polished lime plaster walls, and expansive floor-to-ceiling glass that dissolves the boundary between indoors and the Indian Ocean. Step out onto your private sun deck with an infinity plunge pool, or unwind in the carved stone soak tub overlooking the evening dhows.', 'info@zanzirangihouse.com', '2026-09-30 22:31:09');
