INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'villas', '[villa-02].description', 'Immergée dans des jardins tropicaux indigènes, la Villa 02 offre une tranquillité et une intimité totales. Construite en bois issu de forêts gérées durablement, en chaume de palmier et en pierre de corail locale, la villa reste naturellement fraîche sous le soleil équatorial. Savourez de paresseux après-midis de lecture sur le lit de repos, bercé par le chant des oiseaux, ou offrez-vous une douche d’eau de pluie à ciel ouvert sous la voûte étoilée.', 'Immersed in indigenous tropical gardens, Villa 02 offers complete tranquility and privacy. Constructed using sustainably harvested timber, coconut palm thatch, and local coral ragstone, the villa remains naturally cool under the equatorial sun. Enjoy lazy afternoons reading on the daybed surrounded by birdsong, or indulge in an open-air rainwater shower under the canopy of night stars.', 'info@zanzirangihouse.com', '2026-09-30 22:31:09');
