INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'villas', '[villa-02].shortDescription', 'Nichée parmi les frangipaniers parfumés et les cocotiers, elle offre une intimité absolue, une douche en pierre à ciel ouvert et une paisible véranda sur jardin.', 'Tucked within fragrant frangipani and coconut palms, offering total seclusion, an open-air stone shower, and serene garden verandah.', 'info@zanzirangihouse.com', '2026-09-30 22:31:07');
