INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'villas', '[villa-03].description', 'Un havre en bord de plage pensé pour les amoureux de l’océan. La Villa 03 offre un accès direct et privé aux eaux cristallines du sud de Zanzibar. Mobilier sur mesure en bois précieux, plaids en lin tissés à la main et sculptures africaines choisies avec soin créent une atmosphère d’élégance discrète. Sortez pieds nus pour admirer les boutres des pêcheurs glisser au lever du soleil.', 'A beachfront haven designed for ocean lovers. Villa 03 provides direct, private access to the crystalline waters of southern Zanzibar. Custom hardwood furnishings, hand-loomed linen throws, and curated African sculpture create an atmosphere of understated sophistication. Step outside barefoot to watch traditional fisherman dhows drift across the sunrise.', 'info@zanzirangihouse.com', '2026-09-30 22:31:09');
