INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'villas', '[villa-03].shortDescription', 'Réveillez-vous au doux bruissement des palmes et descendez de votre terrasse en bois directement sur le sable blanc et poudreux de l’océan Indien.', 'Wake up to the soft rustle of palms and step straight from your wooden deck onto the powdery white sand of the Indian Ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:31:08');
