INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'villas', '[villa-04].shortDescription', 'Surélevée pour profiter pleinement des brises marines et d’horizons dégagés, elle dispose d’une vaste véranda panoramique idéale pour observer les dauphins.', 'Elevated for supreme sea breezes and unobstructed horizons, featuring a wide panoramic verandah perfect for dolphin watching.', 'info@zanzirangihouse.com', '2026-09-30 22:31:08');
