INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'villas', '[villa-05].description', 'Organisé autour d’un baobab ancestral et vénéré, ce généreux pavillon de deux chambres offre un confort exceptionnel aux compagnons de voyage comme aux familles. Il comprend une cour de vie centrale ombragée, deux suites de maître indépendantes dotées chacune de leur salle de bains à ciel ouvert, ainsi qu’une pergola privée pour les repas.', 'Centered around an ancient, revered Baobab tree, this generous two-bedroom pavilion provides exceptional comfort for traveling companions or families. Featuring a shaded central living courtyard, two independent master suites each with their own open-air bathroom, and a private dining pergola.', 'info@zanzirangihouse.com', '2026-09-30 22:31:10');
