INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'villas', '[villa-06].description', 'Un hommage à l’âge d’or de l’artisanat de l’île aux Épices. La Villa 06 arbore d’authentiques portes sculptées cloutées de laiton, œuvre des maîtres sculpteurs de Stone Town, des sols en terrazzo coulés à la main et un bassin de nage privé de 12 mètres à l’eau douce, bordé de girofliers et de citronnelle.', 'A tribute to the Spice Island’s golden age of artisanal craftsmanship. Villa 06 features authentic brass-studded carved doors from Stone Town master carvers, hand-poured terrazzo floors, and a private 12-meter fresh water lap pool fringed by clove and lemongrass bushes.', 'info@zanzirangihouse.com', '2026-09-30 22:31:10');
