INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'villas', '[villa-07].description', 'Conçue pour les voyageurs sensibles au design, la Villa 07 allie le minimalisme japonais-scandinave au caractère terrien de l’Afrique de l’Est. Des tons neutres apaisants, des tapis en sisal tissés à la main et une terrasse d’observation exclusive sur le toit, équipée de lits de repos, en font un havre propice à la détente au clair de lune et à la méditation.', 'Conceived for the design-conscious traveler, Villa 07 fuses Japanese-Scandinavian minimalism with East African earthiness. Soothing neutral tones, hand-woven sisal carpets, and an exclusive rooftop observation deck equipped with daybeds make this a haven for moonlit relaxation and tranquil meditation.', 'info@zanzirangihouse.com', '2026-09-30 22:31:10');
