INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'villas', '[villa-08].description', 'L’adresse la plus exclusive du domaine. Située sur son propre promontoire isolé, La Villa Royale Présidentielle offre une autonomie totale, de vastes salons de réception, une piscine à débordement privée en front de mer suspendue au-dessus du lagon corallien, un service de chef privé sur demande et un accès direct à une plage privée.', 'The estate’s most exclusive address. Set on its own secluded promontory, The Royal Presidential Villa offers total autonomy, expansive entertaining salons, a private oceanfront infinity pool suspended over the coral lagoon, a private chef service on request, and direct private beach access.', 'info@zanzirangihouse.com', '2026-09-30 22:31:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'villas', '[villa-08].name', 'La Villa Royale Présidentielle', 'The Royal Presidential Villa', 'info@zanzirangihouse.com', '2026-09-30 22:31:04');
