INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'villas', '[villa-08].shortDescription', 'La résidence phare de Zanzirangi House. Une grandeur inégalée en front de mer, des piscines à débordement sur plusieurs niveaux et un service privé d’une grande discrétion.', 'The flagship residence of Zanzirangi House. Unparalleled oceanfront grandeur, multi-level infinity pools, and discrete private hosting.', 'info@zanzirangihouse.com', '2026-09-30 22:31:09');
