INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'eyebrow', 'L’esprit du sanctuaire', 'The Sanctuary Difference', 'info@zanzirangihouse.com', '2026-09-30 22:32:11');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'heading', 'POURQUOI ZANZIRANGI HOUSE', 'WHY ZANZIRANGI HOUSE', 'info@zanzirangihouse.com', '2026-09-30 22:32:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'pillars[pillar-1].description', 'Niché le long du littoral préservé du sud de Kizimkazi, loin de l’affluence touristique. Ici, le temps se mesure au rythme des marées, au bruissement des palmes et aux horizons océaniques dégagés.', 'Tucked along the pristine southern coastline of Kizimkazi, far from tourist congestion. Here, time is measured by the tidal ebb and flow, the rustle of palms, and unobstructed ocean horizons.', 'info@zanzirangihouse.com', '2026-09-30 22:32:14');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'pillars[pillar-1].tagline', 'Un sanctuaire privé loin de la foule.', 'A private sanctuary away from the crowds.', 'info@zanzirangihouse.com', '2026-09-30 22:32:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'pillars[pillar-1].title', 'PRIVÉ & PAISIBLE', 'PRIVATE & PEACEFUL', 'info@zanzirangihouse.com', '2026-09-30 22:32:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'pillars[pillar-2].description', 'Des maîtres sculpteurs sur bois swahilis aux pavillons centenaires coiffés de chaume makuti, en passant par les épices bio cueillies chaque jour dans les jardins du domaine, découvrez l’âme véritable de l’île aux Épices.', 'From master Swahili woodcarvers and centuries-old makuti thatched pavilions to organic spices harvested daily from our estate gardens, experience the genuine soul of the Spice Island.', 'info@zanzirangihouse.com', '2026-09-30 22:32:14');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'pillars[pillar-2].tagline', 'Découvrez l’île à travers ses habitants, ses saveurs et sa culture.', 'Experience the island through its people, flavours and culture.', 'info@zanzirangihouse.com', '2026-09-30 22:32:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'pillars[pillar-2].title', 'ZANZIBAR AUTHENTIQUE', 'AUTHENTIC ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:32:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'pillars[pillar-3].description', 'Une équipe d’hôtes et de concierges dédiée, attentive à chacun de vos besoins. Accueil privé au pied de l’avion, départs en bateau affrété, repas servis en villa et hospitalité personnelle discrète tout au long de votre séjour.', 'A dedicated host and concierge team attentive to your every need. Private airport tarmac greetings, chartered boat launches, in-villa dining, and discreet personal hospitality throughout.', 'info@zanzirangihouse.com', '2026-09-30 22:32:14');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'pillars[pillar-3].tagline', 'De votre arrivée à l’aéroport à l’organisation de votre safari.', 'From airport arrival to safari planning.', 'info@zanzirangihouse.com', '2026-09-30 22:32:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'pillars[pillar-3].title', 'CONCIERGE PERSONNEL', 'PERSONAL CONCIERGE', 'info@zanzirangihouse.com', '2026-09-30 22:32:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'pillars[pillar-4].description', 'Associez en toute fluidité le repos en bord d’océan à des safaris en avion de brousse affrété vers le Serengeti, le cratère du Ngorongoro et Tarangire, pour un voyage complet et inoubliable en Afrique de l’Est.', 'Seamlessly combine oceanfront rest with chartered fly-in bush safaris to the Serengeti, Ngorongoro Crater, and Tarangire, creating a complete and unforgettable East African journey.', 'info@zanzirangihouse.com', '2026-09-30 22:32:14');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'pillars[pillar-4].tagline', 'Prolongez votre séjour à Zanzibar par les merveilles de la Tanzanie continentale.', 'Connect your Zanzibar stay with the wonders of mainland Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:32:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'pillars[pillar-4].title', 'AU-DELÀ, LA TANZANIE', 'TANZANIA BEYOND', 'info@zanzirangihouse.com', '2026-09-30 22:32:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('fr', 'whystay', 'subhead', 'Quatre valeurs fondatrices guident chaque instant de notre retraite et créent une atmosphère rare de sérénité, d’exclusivité et de lien profond avec la Tanzanie.', 'Four guiding values define every moment at our retreat, creating a rare atmosphere of calm, exclusivity, and profound connection to Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:32:12');
