INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'chauffeur', 'subhead', 'Dal momento in cui il vostro volo atterra a Zanzibar, il nostro servizio di autista privato rende il vostro trasferimento a Zanzirangi House del tutto semplice, sereno e sicuro.', 'From the moment your flight touches down in Zanzibar, our private chauffeur service ensures your transition to Zanzirangi House is completely effortless, serene, and secure.', 'info@zanzirangihouse.com', '2026-09-30 22:30:14');
