INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[arabic].description', 'Una celebrazione della secolare eredità reale omanita di Zanzibar e delle rotte marittime arabe. Assaporate carni speziate brasate lentamente, pani piatti cotti nel forno d\'argilla, squisiti mezze freddi e caldi, profumati piatti di riso allo zafferano e dolci delicatezze all\'acqua di rose preparati da maestri chef.', 'A celebration of Zanzibar’s centuries-old royal Omani heritage and Arabian sea routes. Savor slow-braised spiced meats, clay-oven flatbreads, exquisite cold and hot mezze, fragrant saffron-infused rice dishes, and sweet rosewater delicacies prepared by master chefs.', 'info@zanzirangihouse.com', '2026-09-30 22:29:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[arabic].name', 'Autentica cucina araba e omanita', 'Authentic Arabic & Omani Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:29:37');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[arabic].signatureDishes[#0].description', 'Tenero agnello cotto lentamente per 24 ore con chiodi di garofano, cardamomo, coriandolo, lime essiccato e foglie di banano, servito su profumato riso Kabsa dorato allo zafferano.', 'Tender lamb slow-cooked for 24 hours with cloves, cardamom, coriander, dry lime, and banana leaves, served over fragrant golden saffron Kabsa rice.', 'info@zanzirangihouse.com', '2026-09-30 22:29:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[arabic].signatureDishes[#0].name', 'Shuwa omanita: agnello speziato arrosto a cottura lenta', 'Omani Shuwa Spiced Slow-Roasted Lamb', 'info@zanzirangihouse.com', '2026-09-30 22:29:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[arabic].signatureDishes[#1].description', 'Vellutato hummus con un filo di melograno, Mutabal affumicato, croccanti falafel alle erbe e pani arabi fatti a mano cotti nel forno a legna.', 'Velvety pomegranate-drizzled hummus, smoky Mutabal, crispy herbed falafel, and handmade wood-fired Arabic flatbreads.', 'info@zanzirangihouse.com', '2026-09-30 22:29:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[arabic].signatureDishes[#1].name', 'Mezze reali e Khubz fresco allo za\'atar', 'Royal Mezze & Fresh Za’atar Khubz', 'info@zanzirangihouse.com', '2026-09-30 22:29:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[arabic].signatureDishes[#2].description', 'Gamberoni di Menai Bay, calamari e pescato di barriera grigliati alla brace, insaporiti con peperoncino di Aleppo, sommacco, aglio ed erbe selvatiche.', 'Charcoal-grilled Menai Bay jumbo prawns, calamari, and reef catch seasoned with Aleppo pepper, sumac, garlic, and wild herbs.', 'info@zanzirangihouse.com', '2026-09-30 22:29:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[arabic].signatureDishes[#2].name', 'Mashwi di mare e piatto al lime abbrustolito', 'Mashwi Seafood & Charred Lime Platter', 'info@zanzirangihouse.com', '2026-09-30 22:29:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[arabic].signatureDishes[#3].description', 'Delicata pasta fillo friabile stratificata con pistacchi tostati e sciroppo di fiori d\'arancio e cardamomo, accompagnata da un fresco budino di latte all\'acqua di rose.', 'Delicate flaky filo pastry layered with toasted pistachios and orange-blossom cardamom syrup alongside chilled rosewater milk pudding.', 'info@zanzirangihouse.com', '2026-09-30 22:29:46');
