INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[beverages].description', 'Una raffinata carta delle bevande pensata per l\'indulgenza tropicale. Gustate annate di cantina di livello mondiale, succhi tropicali di Zanzibar spremuti a freddo, bibite botaniche fatte in casa e pregiate acque minerali purissime, servite in spiaggia o a bordo piscina.', 'An elevated beverage program curated for tropical indulgence. Enjoy world-class cellar vintages, pure cold-pressed Zanzibar tropical juices, house-crafted botanical soft drinks, and premium pristine mineral waters served beachfront or poolside.', 'info@zanzirangihouse.com', '2026-09-30 22:29:41');
