INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[beverages].signatureDishes[#0].description', 'Selezioni del Vecchio e del Nuovo Mondo: freschi Chenin Blanc e Sauvignon Blanc sudafricani, eleganti Champagne francesi e rossi corposi toscani e bordolesi.', 'Old and New World collections, crisp South African Chenin Blanc & Sauvignon Blanc, elegant French Champagnes, and full-bodied Tuscan & Bordeaux reds.', 'info@zanzirangihouse.com', '2026-09-30 22:29:47');
