INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[beverages].signatureDishes[#1].description', 'Frutto della passione maturato al sole, dolce mango Alfonso, ananas frullato con menta fresca e acqua di cocco King appena raccolta dai palmeti costieri.', 'Sun-ripened passion fruit, sweet Alfonso mango, crushed pineapple with fresh mint, and young King coconut water straight from coastal palm groves.', 'info@zanzirangihouse.com', '2026-09-30 22:29:47');
