INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[beverages].signatureDishes[#2].description', 'Ginger beer piccante prodotta in casa con citronella pestata, frizzante rinfresco tanzaniano all\'ibisco, toniche botaniche artigianali e classiche bibite ghiacciate.', 'House-brewed fiery ginger beer with crushed lemongrass, sparkling Tanzanian hibiscus cooler, craft botanical tonics, and classic iced sodas.', 'info@zanzirangihouse.com', '2026-09-30 22:29:47');
