INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[fusion].description', 'La nostra firma culinaria. Un dialogo creativo tra la tecnica francese classica e lo straordinario terroir di spezie di Zanzibar. Abbinamenti armoniosi come burro all\'aragosta infuso alla vaniglia in bacca, riduzioni al tamarindo e soufflé al frutto della passione.', 'Our culinary signature. An imaginative dialogue between classical French technique and Zanzibar’s extraordinary spice terroir. Expect harmonious pairings like vanilla bean infused lobster butter, tamarind reductions, and passion fruit soufflés.', 'info@zanzirangihouse.com', '2026-09-30 22:29:41');
