INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[fusion].signatureDishes[#0].description', 'Succulenta aragosta pochée nel burro chiarificato francese profumato con bacche di vaniglia di Pemba, emulsione di patata dolce e asparagi di mare.', 'Sweet succulent lobster poached in clarified French butter scented with fragrant Pemba vanilla pods, sweet potato emulsion, and sea asparagus.', 'info@zanzirangihouse.com', '2026-09-30 22:29:46');
