INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[fusion].signatureDishes[#1].description', 'Petto d\'anatra Magret con pelle croccante servito al sangue con una glassa acidula ai fiori di ibisco, carotine arrosto e purè di manioca speziato.', 'Crispy skin Magret duck breast served medium rare with a tart hibiscus flower glaze, roasted baby carrots, and spiced cassava purée.', 'info@zanzirangihouse.com', '2026-09-30 22:29:47');
