INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[local].description', 'Secoli di commerci marittimi arabi, persiani, indiani e dell\'Africa orientale sono confluiti nelle cucine costiere di Zanzibar. I nostri executive chef preparano ricette tramandate nel tempo con latte di cocco appena estratto, cardamomo aromatico, chiodi di garofano di Pemba e pesce pescato all\'amo portato direttamente sulle nostre rive.', 'Centuries of Arab, Persian, Indian, and East African maritime trade converged in Zanzibar’s coastal kitchens. Our executive chefs prepare time-honored recipes featuring freshly harvested coconut milk, aromatic cardamom, cloves from Pemba, and line-caught seafood brought straight to our shores.', 'info@zanzirangihouse.com', '2026-09-30 22:29:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[local].name', 'Autentica cucina swahili', 'Authentic Swahili Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:29:37');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[local].signatureDishes[#0].description', 'Dentice selvatico di barriera scottato in padella e cotto lentamente con coriandolo fresco, curcuma macinata a pietra e latte di cocco spremuto a mano, servito con riso allo zafferano.', 'Pan-seared wild reef snapper simmered with fresh green coriander, stone-ground turmeric, and hand-squeezed coastal coconut milk served with saffron rice.', 'info@zanzirangihouse.com', '2026-09-30 22:29:44');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[local].signatureDishes[#0].name', 'Dentice della barriera corallina di Zanzibar al cocco e curcuma', 'Zanzibari Coral Reef Snapper in Coconut & Turmeric', 'info@zanzirangihouse.com', '2026-09-30 22:29:41');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[local].signatureDishes[#1].description', 'Un brodo acidulo di mango e tamarindo cotto a fuoco lento, con gamberi teneri, chips di manioca speziate e sambal al cocco con peperoncino tritato.', 'A tangy, slow-simmered mango and tamarind broth with tender prawns, spiced cassava crisps, and crushed chili coconut sambal.', 'info@zanzirangihouse.com', '2026-09-30 22:29:45');
