INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[local].signatureDishes[#2].description', 'Agnello locale tenerissimo profumato con anice stellato, stecche di cannella e cardamomo nero, accompagnato da insalata kachumbari in agrodolce.', 'Fork-tender local lamb infused with star anise, cinnamon quills, and black cardamom, accompanied by pickled kachumbari salad.', 'info@zanzirangihouse.com', '2026-09-30 22:29:45');
