INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[western].description', 'Pensata per i palati internazionali in cerca di sapori familiari e confortanti, preparati con le migliori tecniche dell\'alta cucina. Tagli pregiati di manzo d\'importazione, fresche insalate mediterranee, pasta fatta a mano e dessert golosi, eseguiti con impeccabile precisione culinaria.', 'Designed for international palates seeking comforting familiarity prepared with the highest fine-dining techniques. Prime imported beef cuts, fresh Mediterranean salads, homemade handmade pasta, and decadent desserts executed with crisp culinary precision.', 'info@zanzirangihouse.com', '2026-09-30 22:29:40');
