INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[western].signatureDishes[#0].description', 'Grigliato alla perfezione, accompagnato da una vellutata mousseline di pastinaca, pomodorini ramati scottati e un jus al vino rosso ridotto per 24 ore.', 'Char-grilled to perfection, paired with smooth parsnip mousseline, blistered vine tomatoes, and a 24-hour reduced red wine jus.', 'info@zanzirangihouse.com', '2026-09-30 22:29:46');
