INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[western].signatureDishes[#1].description', 'Tonno locale pescato all\'amo tagliato a cubetti con avocado Hass, olio d\'oliva spremuto a freddo, cucunci e croccanti di pane a lievitazione naturale sfornato in casa.', 'Line-caught local tuna diced with Hass avocado, cold-pressed olive oil, caper berries, and house-baked sourdough crisps.', 'info@zanzirangihouse.com', '2026-09-30 22:29:46');
