INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'categories[western].signatureDishes[#2].description', 'Pasta fresca all\'uovo saltata con coda di aragosta di Kizimkazi, aglio confit, pomodorini ciliegini e una leggera bisque al Pinot Grigio.', 'Fresh egg pasta tossed with sweet Kizimkazi rock lobster tail, garlic confit, baby cherry tomatoes, and a light Pinot Grigio bisque.', 'info@zanzirangihouse.com', '2026-09-30 22:29:46');
