INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'gardenDesc', 'Custodito all\'interno della tenuta di Zanzirangi House si trova il nostro giardino botanico privato, dove la brigata di cucina coltiva in modo biologico citronella, peperoncini verdi, basilico selvatico, menta dolce, cardamomo profumato e verdure di stagione. Ciò che viene raccolto al mattino ispira direttamente i nostri menu degustazione quotidiani, unendo la vitalità della terra al pescato fresco delle acque del sud di Zanzibar.', 'Tucked within the grounds of Zanzirangi House is our private botanical garden, where our kitchen team cultivates organic lemongrass, green chilies, wild basil, sweet mint, fragrant cardamom, and seasonal vegetables. What is harvested in the morning directly shapes our daily tasting menus, pairing earth-grown vitality with the fresh catch of southern Zanzibar’s waters.', 'info@zanzirangihouse.com', '2026-09-30 22:29:33');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'gardenEyebrow', 'Racconti culinari', 'Culinary Storytelling', 'info@zanzirangihouse.com', '2026-09-30 22:29:32');
