INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'heading', 'ASSAPORA ZANZIBAR', 'TASTE ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:29:32');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'intro', 'Secoli di commerci marittimi swahili, omaniti e dell\'Oceano Indiano si incontrano alle nostre tavole. Dal pesce pescato all\'amo e portato a riva all\'alba ai profumati curry cotti a fuoco lento, cenare a Zanzirangi House è un autentico viaggio dei sensi.', 'Centuries of Swahili, Omani, and Indian Ocean sea trade come together at our tables. From line-caught fish brought ashore at sunrise to slow-simmered aromatic curries, dining at Zanzirangi House is an authentic sensory journey.', 'info@zanzirangihouse.com', '2026-09-30 22:29:32');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'dining', 'moments[#0].desc', 'Papaya tropicale, crema al frutto della passione, brioche calde appena sfornate e caffè tanzaniano speziato, serviti con vista sull\'oceano al mattino.', 'Tropical papaya, passion fruit curds, warm freshly-baked brioche, and spiced Tanzanian coffee served overlooking the morning ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:29:36');
