INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-cultural].description', 'Visitate lo storico villaggio di pescatori di Kizimkazi e l\'antica moschea di Dimbani (risalente al 1107 d.C.). Incontrate i maestri artigiani che costruiscono a mano i tradizionali dhow, partecipate a un laboratorio di cucina swahili o godetevi un concerto privato di taarab con violino e kanun sotto le stelle.', 'Visit the historic Kizimkazi fishing settlement and the ancient Dimbani Mosque (dating to 1107 AD). Meet local master craftsmen carving traditional dhows by hand, participate in a Swahili culinary workshop, or enjoy private taarab violin and kanun music under the night stars.', 'info@zanzirangihouse.com', '2026-09-30 22:30:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-cultural].duration', '3,5 ore (orario personalizzabile)', '3.5 Hours (Custom Timing)', 'info@zanzirangihouse.com', '2026-09-30 22:29:51');
