INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-cultural].shortDescription', 'Entrate in contatto autentico con gli artigiani della costa, imparate l\'intreccio delle foglie di palma e il restauro dei dhow e scoprite l\'antica eredità swahili.', 'Engage authentically with local coastal artisans, learn palm-weaving and dhow restoration, and discover ancient Swahili heritage.', 'info@zanzirangihouse.com', '2026-09-30 22:29:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-cultural].tag', 'Esperienze culturali', 'Cultural Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:29:53');
