INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-cultural].whatsappMessage', 'Buongiorno Concierge di Zanzirangi House, vorrei saperne di più sulle esperienze culturali swahili.', 'Hello Zanzirangi House Concierge, I would like to learn more about Swahili Cultural Experiences.', 'info@zanzirangihouse.com', '2026-09-30 22:30:02');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-dolphins].description', 'La nostra posizione a Kizimkazi, sulla costa meridionale di Zanzibar, offre accesso diretto al più famoso santuario dei delfini dell\'Africa orientale. Partite all\'alba a bordo di un dhow privato o di una lancia a motore per osservare i branchi di delfini giocare nel loro habitat naturale, prima di rientrare per la colazione nella tenuta.', 'Our location in Kizimkazi on Zanzibar’s southern coast provides direct access to East Africa’s most famous dolphin sanctuary. Depart at dawn on a private dhow or motor launch to watch dolphin pods playing in their natural ocean habitat before enjoying breakfast back at the property.', 'info@zanzirangihouse.com', '2026-09-30 22:29:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-dolphins].duration', '3,5 ore (crociera all\'alba)', '3.5 Hours (Early Morning Dawn Cruise)', 'info@zanzirangihouse.com', '2026-09-30 22:29:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-dolphins].priceNote', 'Prezzo su richiesta', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:29:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-dolphins].shortDescription', 'Salpate all\'alba da Kizimkazi verso le acque protette di Menai Bay per ammirare i branchi stanziali di stenelle e tursiopi.', 'Set sail at sunrise from Kizimkazi into the protected waters of Menai Bay to witness pods of resident spinner and bottlenose dolphins.', 'info@zanzirangihouse.com', '2026-09-30 22:29:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-dolphins].tag', 'Esperienza con i delfini', 'Dolphin Experience', 'info@zanzirangihouse.com', '2026-09-30 22:29:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-dolphins].title', 'Incontro con i delfini selvatici di Kizimkazi', 'Kizimkazi Wild Dolphin Encounter', 'info@zanzirangihouse.com', '2026-09-30 22:29:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-dolphins].whatsappMessage', 'Buongiorno Concierge di Zanzirangi House, mi piacerebbe vivere l\'incontro con i delfini selvatici di Kizimkazi.', 'Hello Zanzirangi House Concierge, I would like to experience the Kizimkazi Wild Dolphin Encounter.', 'info@zanzirangihouse.com', '2026-09-30 22:30:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-fishing].description', 'A bordo della nostra imbarcazione da pesca sportiva d\'altura a noleggio, dotata di outrigger, attrezzatura Shimano ed elettronica nautica moderna, vivrete l\'adrenalina della pesca alla grande preda nelle profonde correnti dell\'Oceano Indiano. Per i pesci con rostro si applica rigorosamente la pratica del catch-and-release.', 'Aboard our chartered offshore sportfisher equipped with outriggers, Shimano tackle, and modern nautical electronics, experience the adrenaline of big game fishing in the deep currents of the Indian Ocean. Strictly adheres to catch-and-release protocols for billfish.', 'info@zanzirangihouse.com', '2026-09-30 22:29:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-fishing].duration', 'Mezza giornata (5 ore) o giornata intera (8 ore)', 'Half Day (5 Hours) or Full Day (8 Hours)', 'info@zanzirangihouse.com', '2026-09-30 22:29:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-fishing].priceNote', 'Prezzo su richiesta', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:29:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-fishing].shortDescription', 'Avventuratevi nei profondi canali di Pemba e Zanzibar per una pesca sportiva di livello mondiale a tonni pinna gialla, pesci vela e wahoo.', 'Venture into the deep Pemba and Zanzibar channels for world-class sport fishing targeting yellowfin tuna, sailfish, and wahoo.', 'info@zanzirangihouse.com', '2026-09-30 22:29:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-fishing].tag', 'Pesca d\'altura', 'Deep Sea Fishing', 'info@zanzirangihouse.com', '2026-09-30 22:29:53');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-fishing].title', 'Pesca sportiva d\'altura alla grande preda', 'Deep Sea Big Game Sport Fishing', 'info@zanzirangihouse.com', '2026-09-30 22:29:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-fishing].whatsappMessage', 'Buongiorno Concierge di Zanzirangi House, vorrei ricevere dettagli sulle uscite di pesca sportiva d\'altura.', 'Hello Zanzirangi House Concierge, I would like details on Deep Sea Sport Fishing trips.', 'info@zanzirangihouse.com', '2026-09-30 22:30:01');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-island-hopping].description', 'Tracciate la vostra rotta tra le acque turchesi del sud e dell\'ovest di Zanzibar. Sbarcate su effimeri banchi di sabbia bianchissima che emergono solo con la bassa marea, nuotate in acque calde e cristalline e assaporate un pranzo appena preparato a base di aragosta di Menai Bay alla griglia, calamari e frutta tropicale.', 'Chart your own course across the turquoise waters of southern and western Zanzibar. Disembark onto ephemeral powder-white sandbanks that emerge only at low tide, swim in warm crystalline waters, and savor a freshly prepared lunch of grilled Menai Bay lobster, calamari, and tropical fruit.', 'info@zanzirangihouse.com', '2026-09-30 22:29:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-island-hopping].duration', 'Giornata intera (motoscafo privato)', 'Full Day (Private Speedboat)', 'info@zanzirangihouse.com', '2026-09-30 22:29:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-island-hopping].priceNote', 'Prezzo su richiesta', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:29:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-island-hopping].shortDescription', 'Navigate verso isolotti corallini disabitati e appartati, nuotate in lagune deserte e gustate un pranzo di pesce alla griglia su un banco di sabbia privato.', 'Cruise to secluded uninhabited coral islets, swim in deserted tidal lagoons, and enjoy a grilled seafood lunch on a private sandbank.', 'info@zanzirangihouse.com', '2026-09-30 22:29:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-island-hopping].tag', 'Island hopping', 'Island Hopping', 'info@zanzirangihouse.com', '2026-09-30 22:29:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-island-hopping].title', 'Island hopping privato e safari sui banchi di sabbia', 'Private Island Hopping & Sandbank Safari', 'info@zanzirangihouse.com', '2026-09-30 22:29:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-island-hopping].whatsappMessage', 'Buongiorno Concierge di Zanzirangi House, vorrei avere informazioni sull\'island hopping privato con safari sui banchi di sabbia.', 'Hello Zanzirangi House Concierge, I would like to inquire about the Private Island Hopping Sandbank Safari.', 'info@zanzirangihouse.com', '2026-09-30 22:30:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-mnemba].description', 'Situato al largo della costa nord-orientale di Zanzibar, il Mnemba Atoll è rinomato in tutto il mondo per le sue condizioni sottomarine incontaminate. Godetevi trasferimenti privati in barca, snorkeling esclusivo sopra pinnacoli di corallo e un picnic gourmet in spiaggia organizzato dal nostro chef privato.', 'Located off Zanzibar’s northeast coast, Mnemba Atoll is recognized globally for its pristine underwater conditions. Enjoy private boat transfers, exclusive snorkeling over coral pinnacles, and a beachside gourmet picnic arranged by our private chef.', 'info@zanzirangihouse.com', '2026-09-30 22:29:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-mnemba].duration', 'Spedizione privata di un\'intera giornata', 'Full Day Private Expedition', 'info@zanzirangihouse.com', '2026-09-30 22:29:51');
