INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-mnemba].shortDescription', 'Navigate verso il gioiello delle riserve marine di Zanzibar: acque turchesi di limpidezza ineguagliabile, giardini di corallo incontaminati e lagune delle tartarughe marine.', 'Sail to the crown jewel of Zanzibar marine reserves: unmatched turquoise clarity, pristine coral gardens, and sea turtle lagoons.', 'info@zanzirangihouse.com', '2026-09-30 22:29:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-mnemba].tag', 'Isola di Mnemba', 'Mnemba Island', 'info@zanzirangihouse.com', '2026-09-30 22:29:53');
