INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-mnemba].whatsappMessage', 'Buongiorno Concierge di Zanzirangi House, vorrei prenotare la spedizione al santuario marino dell\'isola di Mnemba.', 'Hello Zanzirangi House Concierge, I would like to book the Mnemba Island Marine Sanctuary expedition.', 'info@zanzirangihouse.com', '2026-09-30 22:30:01');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-nature-jozani].description', 'Guidati da un naturalista autorizzato del parco nazionale, addentratevi nelle antiche foreste di latifoglie protette all\'interno del Jozani Chwaka Bay National Park. Osservate i gruppi di scimmie che si spostano tra le chiome degli alberi, percorrete la passerella sopraelevata tra le mangrovie e scoprite la rara flora esclusiva di Zanzibar.', 'Led by an authorized national park naturalist, journey into ancient hardwood forests protected within Jozani Chwaka Bay National Park. Observe monkey troops swinging through the canopy, walk the elevated mangrove boardwalk, and learn about the rare flora unique to Zanzibar.', 'info@zanzirangihouse.com', '2026-09-30 22:30:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-nature-jozani].duration', '4 ore (consigliata la mattina)', '4 Hours (Morning Recommended)', 'info@zanzirangihouse.com', '2026-09-30 22:29:52');
