INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-nature-jozani].shortDescription', 'Addentratevi in una foresta vergine di mogano alimentata dalle acque sotterranee per incontrare il giocoso colobo rosso di Zanzibar, specie endemica.', 'Trek through virgin groundwater mahogany forest to encounter the playful, endemic Zanzibar Red Colobus monkey.', 'info@zanzirangihouse.com', '2026-09-30 22:29:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-nature-jozani].tag', 'Esperienze nella natura', 'Nature Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:29:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-nature-jozani].title', 'Foresta di Jozani ed eco-santuario del colobo rosso', 'Jozani Forest & Red Colobus Eco-Sanctuary', 'info@zanzirangihouse.com', '2026-09-30 22:29:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-nature-jozani].whatsappMessage', 'Buongiorno Concierge di Zanzirangi House, vorrei prenotare l\'esperienza nella natura della foresta di Jozani.', 'Hello Zanzirangi House Concierge, I would like to reserve the Jozani Forest Nature Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:30:02');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-snorkeling-diving].description', 'Le barriere coralline di Zanzibar brulicano di biodiversità tropicale. Con attrezzatura professionale di prima qualità e accompagnati da divemaster certificati PADI, scoprirete spettacolari pareti, grotte da attraversare a nuoto e una visibilità cristallina fino a 30 metri.', 'Zanzibar’s barrier reefs are teeming with tropical biodiversity. Equipped with top-tier professional gear and accompanied by certified PADI divemasters, discover stunning drop-offs, swim-through caves, and crystal visibility extending up to 30 meters.', 'info@zanzirangihouse.com', '2026-09-30 22:29:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-snorkeling-diving].duration', 'Escursione di mezza giornata o giornata intera', 'Half Day or Full Day Excursion', 'info@zanzirangihouse.com', '2026-09-30 22:29:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-snorkeling-diving].priceNote', 'Prezzo su richiesta', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:29:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-snorkeling-diving].shortDescription', 'Esplorate vivaci giardini di corallo e pareti sottomarine, incontrando tartarughe marine, aquile di mare maculate e specie esotiche di barriera.', 'Explore vibrant coral gardens, underwater marine walls, and meet sea turtles, spotted eagle rays, and exotic reef species.', 'info@zanzirangihouse.com', '2026-09-30 22:29:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-snorkeling-diving].tag', 'Snorkeling e immersioni', 'Snorkeling & Diving', 'info@zanzirangihouse.com', '2026-09-30 22:29:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-snorkeling-diving].title', 'Snorkeling sulla barriera corallina e immersioni profonde', 'Coral Reef Snorkeling & Deep Scuba Diving', 'info@zanzirangihouse.com', '2026-09-30 22:29:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-snorkeling-diving].whatsappMessage', 'Buongiorno Concierge di Zanzirangi House, vorrei organizzare un\'escursione di snorkeling e immersioni.', 'Hello Zanzirangi House Concierge, I would like to arrange a Snorkeling & Diving excursion.', 'info@zanzirangihouse.com', '2026-09-30 22:30:01');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-spice-farm].description', 'Passeggiate accanto a esperti botanici locali tra rigogliose piantagioni rurali. Toccate, annusate e assaggiate spezie crude direttamente da alberi e rampicanti, tra cui pepe nero, noce moscata, zenzero, citronella e curcuma, per concludere con acqua di cocco King fresca raccolta in cima alle palme.', 'Walk alongside expert local botanists through verdant rural plantations. Touch, smell, and taste raw spices directly from the trees and vines—including black pepper, nutmeg, ginger, lemongrass, and turmeric—concluding with fresh King coconut water harvested high in the canopy.', 'info@zanzirangihouse.com', '2026-09-30 22:29:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-spice-farm].duration', '4 ore (mattina o pomeriggio)', '4 Hours (Morning or Afternoon)', 'info@zanzirangihouse.com', '2026-09-30 22:29:51');
