INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-spice-farm].shortDescription', 'Immergete i sensi in secoli di storia aromatica: cogliete cannella fresca, schiacciate cardamomo verde e assaggiate la vaniglia selvatica in bacca.', 'Immerse your senses in centuries of aromatic history: pluck fresh cinnamon, crush green cardamom, and taste wild vanilla bean.', 'info@zanzirangihouse.com', '2026-09-30 22:29:57');
