INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-stonetown].description', 'Un viaggio privato a Stone Town, Patrimonio Mondiale dell\'UNESCO. Accompagnati da uno storico swahili locale, esplorerete la Casa delle Meraviglie, l\'Old Fort del XVII secolo, la Cattedrale anglicana e il memoriale dell\'antico mercato degli schiavi, oltre a botteghe artigiane specializzate in gioielli d\'argento e tessuti intrecciati.', 'A private journey through UNESCO World Heritage Stone Town. Led by a resident Swahili historian, explore the House of Wonders, the 17th-century Old Fort, the Anglican Cathedral and Old Slave Market memorial, and artisan workshops specializing in silver jewelry and woven textiles.', 'info@zanzirangihouse.com', '2026-09-30 22:29:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-stonetown].duration', 'Giornata intera (autista e guida privati)', 'Full Day (Private Chauffeur & Guide)', 'info@zanzirangihouse.com', '2026-09-30 22:29:50');
