INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-stonetown].shortDescription', 'Passeggiate tra labirintici vicoli in pietra corallina, sontuose porte omanite in teak intagliato, storici bazar delle spezie e il Palazzo del Sultano.', 'Walk through labyrinthine coral ragstone alleyways, ornate Omani carved teak doors, historical spice bazaars, and the Sultan’s Palace.', 'info@zanzirangihouse.com', '2026-09-30 22:29:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-stonetown].tag', 'Cultura e patrimonio', 'Culture & Heritage', 'info@zanzirangihouse.com', '2026-09-30 22:29:52');
