INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-stonetown].whatsappMessage', 'Buongiorno Concierge di Zanzirangi House, vorrei prenotare l\'esperienza privata alla scoperta del patrimonio di Stone Town.', 'Hello Zanzirangi House Concierge, I am interested in booking the private Stone Town Heritage Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:30:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-sunset-cruise].description', 'Salite a bordo di un dhow swahili a vela realizzato a mano in mogano locale. Rilassatevi su morbidi cuscini con Champagne ghiacciato, canapé artigianali e il suono ipnotico della brezza marina e delle melodie acustiche taarab, mentre la luce del giorno sfuma nel crepuscolo.', 'Step aboard a handcrafted Swahili sailing dhow carved from indigenous mahogany. Relax upon plush cushions with chilled Champagne, artisanal canapés, and the hypnotic sounds of the ocean breeze and acoustic taarab melodies as daylight fades into dusk.', 'info@zanzirangihouse.com', '2026-09-30 22:29:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-sunset-cruise].duration', '2,5 ore (tardo pomeriggio, all\'ora dorata)', '2.5 Hours (Late Afternoon Golden Hour)', 'info@zanzirangihouse.com', '2026-09-30 22:29:51');
