INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'experiences', '[exp-sunset-cruise].shortDescription', 'Scivolate sulle acque calme dell\'Oceano Indiano con le vele gonfie al vento, mentre il sole equatoriale dipinge il cielo di sfumature ambra e oro rosa.', 'Glide across the calm Indian Ocean under billowed canvas sails as the equatorial sun paints the sky in shades of amber and rose gold.', 'info@zanzirangihouse.com', '2026-09-30 22:29:57');
