INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'facilities', '[bbq].description', 'Mentre il sole si tuffa nell\'Oceano Indiano, riunitevi attorno al nostro falò sulla riva per gustare aragosta alla griglia, gamberi tigre e filetti speziati cotti sui gusci di cocco sotto le costellazioni africane.', 'As the sun dips into the Indian Ocean, gather around our shoreline firepit for grilled lobster, tiger prawns, and spiced tenderloins cooked over coconut husks under the African constellations.', 'info@zanzirangihouse.com', '2026-09-30 22:30:21');
