INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'facilities', '[breakfast].description', 'Risvegliatevi con piatti di frutta tropicale dei frutteti locali, brioche appena sfornate, crema al frutto della passione, caffè arabica tanzaniano e uova cucinate a vostro piacimento, in villa o in riva al mare.', 'Awaken to tropical fruit platters from local orchards, freshly baked brioche, passion fruit curd, Tanzanian arabica coffee, and eggs cooked to your preference in your villa or by the sea.', 'info@zanzirangihouse.com', '2026-09-30 22:30:22');
