INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'facilities', '[dining].description', 'Un padiglione a cielo aperto sotto un tetto a volta in makuti, con vista panoramica sull\'oceano. Un\'esperienza di alta cucina impreziosita dai profumi delle spezie di Zanzibar e dal pescato più fresco del giorno.', 'An open-air pavilion beneath vaulted Makuti thatch offering panoramic ocean views. Experience fine dining infused with the aromas of Zanzibar spices and the freshest catches of the day.', 'info@zanzirangihouse.com', '2026-09-30 22:30:21');
