INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'facilities', '[massage].description', 'Appartati padiglioni spa all\'aperto immersi nei giardini costieri. Concedetevi massaggi su misura con olio di cocco di Zanzibar spremuto a freddo, citronella, chiodi di garofano macinati ed erbe botaniche africane autoctone.', 'Secluded open-air spa salas nestled in coastal gardens. Indulge in bespoke massages using cold-pressed Zanzibar coconut oil, lemongrass, ground cloves, and indigenous African botanicals.', 'info@zanzirangihouse.com', '2026-09-30 22:30:21');
