INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'facilities', '[pool].description', 'Sospesa sopra le maree turchesi dell\'Oceano Indiano, la nostra piscina a sfioro d\'acqua dolce di 25 metri riflette il cielo e l\'orizzonte, con lettini immersi e un attento servizio a bordo piscina.', 'Suspended above the turquoise tides of the Indian Ocean, our 25-meter freshwater infinity pool mirrors the sky and ocean horizons with sunken sunbeds and attentive poolside service.', 'info@zanzirangihouse.com', '2026-09-30 22:30:21');
