INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'homepage', 'intro.description', 'Zanzirangi House è un esclusivo boutique retreat con 8 ville private dotate di piscina, appartate lungo la tranquilla costa meridionale di Zanzibar, a Kizimkazi Dimbani.', 'Zanzirangi House is an ultra-boutique retreat featuring 8 private plunge-pool villas secluded along the peaceful southern coast of Zanzibar in Kizimkazi Dimbani.', 'info@zanzirangihouse.com', '2026-09-30 22:28:58');
