INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[about].description', 'Adagiata lungo l\'incontaminata costa corallina meridionale di Kizimkazi Dimbani, Zanzirangi House è un esclusivo rifugio privato ultra-boutique pensato per offrire totale riservatezza, armonia architettonica e un\'intima ospitalità zanzibarina.', 'Nestled along the pristine southern coral coast of Kizimkazi Dimbani, Zanzirangi House is an ultra-boutique private sanctuary designed to offer total seclusion, architectural harmony, and intimate Zanzibar hospitality.', 'info@zanzirangihouse.com', '2026-09-30 22:30:44');
