INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[contact].description', 'Pianificate il vostro soggiorno su misura con il nostro team di concierge. Che si tratti di verificare la disponibilità delle ville private, organizzare transfer di 45 minuti dall\'aeroporto di ZNZ o creare itinerari safari personalizzati in Tanzania, siamo a vostra disposizione 24/7.', 'Plan your bespoke stay with our concierge team. Whether arranging private villa availability, 45-minute airport transfers from ZNZ, or custom Tanzania safari itineraries, we are available 24/7.', 'info@zanzirangihouse.com', '2026-09-30 22:30:44');
