INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[dining].description', 'Assaporate l\'autentica tradizione culinaria di Zanzibar, che unisce le spezie swahili al pesce dell\'Oceano Indiano pescato ogni giorno dai pescatori artigianali di Kizimkazi a bordo dei loro dhow. Godetevi cene private in veranda, barbecue in spiaggia e cene a lume di candela su misura sotto le stelle.', 'Taste authentic Zanzibar culinary heritage blending Swahili spices with Indian Ocean seafood caught daily by Kizimkazi artisanal dhow fishermen. Enjoy private veranda dining, beach barbecues, and bespoke candlelit dinners under the stars.', 'info@zanzirangihouse.com', '2026-09-30 22:30:44');
