INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[experiences].description', 'Dagli incontri etici con i delfini selvatici nella riserva marina di Menai Bay ai tour privati del patrimonio UNESCO di Stone Town, dai percorsi biologici delle spezie alla navigazione in dhow al tramonto: vivete Zanzibar con le nostre guide private dedicate.', 'From ethical wild dolphin encounters in the Menai Bay Marine Reserve to private Stone Town UNESCO heritage tours, organic spice trails, and sunset dhow sailing—experience Zanzibar with our dedicated private guides.', 'info@zanzirangihouse.com', '2026-09-30 22:30:44');
