INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.introText', 'Per Zanzirangi House (accessibile all\'indirizzo https://zanzirangihouse.com/), la tutela dei dati personali e della privacy dei nostri ospiti è della massima importanza. La presente Informativa sulla privacy descrive le modalità con cui raccogliamo, utilizziamo e proteggiamo le informazioni quando visitate il nostro sito web, inviate richieste di prenotazione o comunicate con il nostro team di concierge.', 'At Zanzirangi House (accessible from https://zanzirangihouse.com/), safeguarding our guests’ personal data and privacy is of utmost importance. This Privacy Policy details how we collect, use, and protect information when you visit our website, submit booking inquiries, or communicate with our concierge team.', 'info@zanzirangihouse.com', '2026-09-30 22:30:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.lastUpdated', 'Settembre 2026', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:30:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.sections[#0].body', 'Nell\'inviare una richiesta o nel prenotare una villa privata, l\'utente può fornire dati quali nome e cognome, indirizzo email, numero di telefono/WhatsApp, date di arrivo e partenza, numero di ospiti ed eventuali preferenze particolari di ospitalità o alimentari.', 'When submitting an inquiry or reserving a private villa, you may provide details including your full name, email address, telephone/WhatsApp number, arrival/departure dates, guest party size, and special hospitality or dietary preferences.', 'info@zanzirangihouse.com', '2026-09-30 22:30:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.sections[#0].title', '1. Informazioni che raccogliamo', '1. Information We Collect', 'info@zanzirangihouse.com', '2026-09-30 22:30:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.sections[#1].items[#0]', 'Gestire le richieste di prenotazione e le verifiche di disponibilità delle camere.', 'Facilitating reservation inquiries and room availability checks.', 'info@zanzirangihouse.com', '2026-09-30 22:30:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.sections[#1].items[#1]', 'Coordinare i transfer con autista dall\'aeroporto internazionale Abeid Amani Karume (ZNZ).', 'Coordinating airport chauffeur transfers from Abeid Amani Karume International Airport (ZNZ).', 'info@zanzirangihouse.com', '2026-09-30 22:30:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.sections[#1].items[#2]', 'Personalizzare cene private, escursioni marine con i delfini e collegamenti per safari nella Tanzania continentale.', 'Customizing private dining, marine dolphin tours, and mainland Tanzania safari connections.', 'info@zanzirangihouse.com', '2026-09-30 22:30:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.sections[#1].items[#3]', 'Garantire comunicazioni 24/7 con il maggiordomo personale e il concierge.', 'Providing 24/7 personal butler and concierge communications.', 'info@zanzirangihouse.com', '2026-09-30 22:30:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.sections[#1].title', '2. Modalità di utilizzo delle informazioni', '2. How We Use Your Information', 'info@zanzirangihouse.com', '2026-09-30 22:30:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.sections[#2].body', 'Adottiamo rigorose misure di sicurezza tecniche e organizzative. Non vendiamo, noleggiamo né cediamo in locazione le informazioni degli ospiti a reti di marketing commerciale di terze parti. I dati vengono condivisi esclusivamente con fornitori di servizi locali autorizzati (come gli operatori ufficiali di voli charter per safari TANAPA) al solo fine di realizzare l\'itinerario concordato.', 'We implement strict technical and administrative safeguards. We do not sell, rent, or lease guest information to third-party commercial marketing networks. Data is shared exclusively with licensed local service providers (such as official TANAPA safari charter operators) strictly to fulfill your agreed itinerary.', 'info@zanzirangihouse.com', '2026-09-30 22:30:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.sections[#2].title', '3. Sicurezza dei dati e comunicazione a terzi', '3. Data Security & Third-Party Disclosure', 'info@zanzirangihouse.com', '2026-09-30 22:30:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.sections[#3].body', 'Per qualsiasi richiesta relativa alla privacy o per chiedere la cancellazione dei propri dati, è possibile contattare direttamente il nostro team per la protezione dei dati all\'indirizzo concierge@zanzirangihouse.com o al numero di telefono ufficiale +255 777 890 123.', 'For any privacy inquiries or to request data removal, contact our data protection team directly at concierge@zanzirangihouse.com or via official telephone at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:30:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[privacy].contentJson.sections[#3].title', '4. Contatta il nostro concierge', '4. Contact Our Concierge', 'info@zanzirangihouse.com', '2026-09-30 22:30:49');
