INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[safari].description', 'Unite il vostro soggiorno di lusso a piedi nudi a Zanzibar a safari di livello mondiale sul continente. Organizziamo voli charter privati di 90 minuti diretti al Serengeti National Park, al Cratere di Ngorongoro e al Monte Kilimanjaro, con i più prestigiosi campi safari di lusso.', 'Combine your barefoot luxury retreat in Zanzibar with world-class mainland safaris. We coordinate 90-minute private air charters directly to Serengeti National Park, Ngorongoro Crater, and Mount Kilimanjaro with premier luxury safari camps.', 'info@zanzirangihouse.com', '2026-09-30 22:30:45');
