INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[terms].contentJson.introText', 'Benvenuti a Zanzirangi House. Accedendo al nostro sito web (https://zanzirangihouse.com/) o inviando richieste di alloggio ed escursioni, l\'utente accetta di attenersi ai seguenti termini di ospitalità e alle linee guida per le prenotazioni.', 'Welcome to Zanzirangi House. By accessing our website (https://zanzirangihouse.com/) or submitting accommodation and excursion requests, you agree to comply with the following hospitality terms and reservation guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:30:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[terms].contentJson.lastUpdated', 'Settembre 2026', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:30:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[terms].contentJson.sections[#0].body', 'Le tariffe notturne delle ville variano tra $390 e $480+ USD e includono l\'accesso alla piscina privata, la colazione gourmet e il servizio di maggiordomo dedicato 24/7. La conferma della prenotazione richiede il versamento di un acconto concordato o di un voucher tramite i canali di prenotazione ufficiali.', 'Nightly villa rates range between $390 and $480+ USD and include private plunge pool access, gourmet breakfast, and 24/7 dedicated butler service. Confirmation requires an agreed deposit or voucher via official reservation channels.', 'info@zanzirangihouse.com', '2026-09-30 22:30:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[terms].contentJson.sections[#0].title', '1. Prenotazioni e pagamenti', '1. Reservations & Payments', 'info@zanzirangihouse.com', '2026-09-30 22:30:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[terms].contentJson.sections[#1].body', 'Il check-in standard è a partire dalle 14:00 (2:00 PM) e il check-out entro le 11:00 (11:00 AM). L\'arrivo anticipato o la partenza posticipata possono essere richiesti tramite il proprio concierge personale, in base alla disponibilità della villa.', 'Standard check-in is from 14:00 (2:00 PM), and check-out is by 11:00 (11:00 AM). Early arrival or late departure may be requested through your personal concierge, subject to villa availability.', 'info@zanzirangihouse.com', '2026-09-30 22:30:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[terms].contentJson.sections[#1].title', '2. Orari di check-in e check-out', '2. Check-In & Check-Out Times', 'info@zanzirangihouse.com', '2026-09-30 22:30:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[terms].contentJson.sections[#2].body', 'Zanzirangi House confina con la Menai Bay Marine Conservation Area. Gli ospiti che partecipano alle uscite in dhow e alle escursioni con i delfini si impegnano a rispettare i protocolli etici per la fauna selvatica, mantenendo una distanza rispettosa dagli animali marini in conformità con le normative ambientali locali.', 'Zanzirangi House borders the Menai Bay Marine Conservation Area. Guests participating in dhow sailing and dolphin excursions agree to follow ethical wildlife protocols, maintaining respectful distances from marine wildlife in compliance with local environmental regulations.', 'info@zanzirangihouse.com', '2026-09-30 22:30:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[terms].contentJson.sections[#2].title', '3. Tutela dell\'ambiente marino e comportamento verso la fauna', '3. Marine Conservation & Wildlife Etiquette', 'info@zanzirangihouse.com', '2026-09-30 22:30:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[terms].contentJson.sections[#3].body', 'Per modificare o cancellare una prenotazione, contattare direttamente il nostro concierge via email all\'indirizzo concierge@zanzirangihouse.com o tramite WhatsApp al numero +255 777 890 123.', 'To modify or cancel a reservation, contact our concierge directly via email at concierge@zanzirangihouse.com or WhatsApp at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:30:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[terms].contentJson.sections[#3].title', '4. Richieste e cancellazioni', '4. Inquiries & Cancellations', 'info@zanzirangihouse.com', '2026-09-30 22:30:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[terms].description', 'Benvenuti a Zanzirangi House. Accedendo al nostro sito web o inviando richieste di prenotazione, l\'utente accetta di attenersi alle nostre linee guida di ospitalità.', 'Welcome to Zanzirangi House. By accessing our website or submitting reservation requests, you agree to comply with our hospitality guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:30:45');
