INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'pages', '[villas].description', 'Scoprite le nostre 8 residenze private artigianali, da 78 m² a 95 m². Ogni villa dispone di una piscina privata d\'acqua dolce ad uso esclusivo al 100%, di un\'autentica architettura swahili in pietra corallina e di un servizio di maggiordomo personale dedicato 24/7.', 'Discover our 8 private artisanal residences ranging from 78 m² to 95 m². Each villa features a 100% private freshwater plunge pool, authentic Swahili coral-stone architecture, and personalized 24/7 dedicated butler service.', 'info@zanzirangihouse.com', '2026-09-30 22:30:46');
