INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'safari', '[dest-kilimanjaro].bestFor', 'Prospettive aeree iconiche e trekking d\'alta quota', 'Iconic aerial perspectives & alpine trekking', 'info@zanzirangihouse.com', '2026-09-30 22:30:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'safari', '[dest-kilimanjaro].description', 'La vetta più alta d\'Africa e la montagna isolata più alta del mondo si erge maestosa per 5.895 metri sopra le pianure tropicali. Dai panoramici voli privati in elicottero attorno all\'Uhuru Peak alle escursioni giornaliere lungo i sentieri della lussureggiante foresta pluviale e tra le piantagioni di caffè, vivete la corona iconica della Tanzania.', 'Africa’s highest peak and the world’s tallest free-standing mountain rises majestically 5,895 meters above tropical plains. From scenic private helicopter flights encircling Uhuru Peak to day treks along lush lower rainforest trails and coffee estates, experience Tanzania’s iconic crown.', 'info@zanzirangihouse.com', '2026-09-30 22:30:06');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'safari', '[dest-kilimanjaro].flightTimeFromZanzibar', '1h 10m fino al Kilimanjaro Int’l', '1h 10m to Kilimanjaro Int’l', 'info@zanzirangihouse.com', '2026-09-30 22:30:05');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'safari', '[dest-kilimanjaro].highlights[#0]', 'Tour panoramici in elicottero sopra la vetta e i suoi ghiacciai', 'Scenic helicopter mountain tours over the glacier summit', 'info@zanzirangihouse.com', '2026-09-30 22:30:08');
