INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'safari', '[dest-ngorongoro].bestFor', 'Splendore geologico e altissima densità di fauna', 'Geological splendor & concentrated wildlife density', 'info@zanzirangihouse.com', '2026-09-30 22:30:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'safari', '[dest-ngorongoro].description', 'La più grande caldera vulcanica intatta del mondo, che custodisce un rifugio ecologico autonomo profondo 600 metri. Scendete attraverso le nebbiose foreste di acacie del bordo del cratere fino a un antico anfiteatro brulicante di rinoceronti neri in via di estinzione, ippopotami e migliaia di fenicotteri rosa che guadano il Lago Magadi.', 'The world’s largest intact volcanic caldera, creating a self-contained ecological haven 600 meters deep. Descend through misty rim acacia forests into an ancient amphitheater bustling with endangered black rhinos, hippos, and thousands of pink flamingos wading in Lake Magadi.', 'info@zanzirangihouse.com', '2026-09-30 22:30:05');
