INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'safari', '[dest-serengeti].bestFor', 'Avvistamenti dei Big Five e spettacoli naturali straordinari', 'Big Five sightings & dramatic wildlife spectacles', 'info@zanzirangihouse.com', '2026-09-30 22:30:09');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'safari', '[dest-serengeti].description', 'Vaste savane dorate che si estendono all\'infinito fino all\'orizzonte. Assistete a milioni di gnu e zebre che sfidano fiumi popolati da coccodrilli, accompagnati da branchi stanziali di leoni, leopardi solitari e lussuosi campi tendati nella savana sotto cieli equatoriali trapuntati di stelle.', 'Vast golden savannahs that stretch endlessly to the horizon. Witness millions of wildebeest and zebras braving crocodile-laden rivers, accompanied by resident prides of lions, solitary leopards, and luxury tented bush retreats under star-strewn equatorial skies.', 'info@zanzirangihouse.com', '2026-09-30 22:30:05');
