INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'safari', '[dest-tarangire].bestFor', 'Paesaggi di baobab e incontri ravvicinati con gli elefanti', 'Baobab landscapes & intimate elephant encounters', 'info@zanzirangihouse.com', '2026-09-30 22:30:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'safari', '[dest-tarangire].description', 'Celebre per i suoi colossali e antichi baobab che si ergono come sentinelle silenziose lungo un\'aspra valle fluviale. Il Tarangire ospita la più alta concentrazione di branchi di elefanti dell\'Africa orientale, dove maestose matriarche guidano i piccoli lungo il vitale fiume Tarangire.', 'Famed for its colossal ancient baobab trees that stand like silent sentinels across a rugged river valley. Tarangire hosts East Africa’s highest concentration of elephant herds, where majestic family matriarchs guide their calves along the life-giving Tarangire River.', 'info@zanzirangihouse.com', '2026-09-30 22:30:06');
