INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'testimonials', '[rev-01].reviewText', 'Dal momento in cui il nostro autista privato ci ha accolti all\'aeroporto di Zanzibar fino all\'ultima navigazione in dhow al tramonto, ogni dettaglio è stato curato alla perfezione. La piscina affacciata sulla marea dell\'oceano era magica.', 'From the moment our private chauffeur welcomed us at Zanzibar Airport to our final sunset dhow sail, every detail was orchestrated to absolute perfection. The plunge pool perched over the ocean tide was magical.', 'info@zanzirangihouse.com', '2026-09-30 22:30:33');
