INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'testimonials', '[rev-02].reviewText', 'La sobrietà architettonica, l\'uso della pietra corallina locale e il servizio di maggiordomo attento ma discreto ci hanno ricordato i migliori lodge Aman o Singita. La cena swahili di pesce al cocco è stata indimenticabile.', 'The architectural restraint, use of indigenous coral stone, and attentive but discrete butler service reminded us of the very finest Aman or Singita lodges. The Swahili coconut seafood dinner was unforgettable.', 'info@zanzirangihouse.com', '2026-09-30 22:30:33');
