INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'testimonials', '[rev-03].reviewText', 'Abbiamo viaggiato come famiglia di cinque persone. Avere la nostra piscina a sfioro privata sospesa sopra la laguna corallina e il nostro chef personale che ogni sera preparava il pescato del giorno ha ridefinito per noi il significato del viaggio di lusso.', 'We traveled as a family of five. Having our own private infinity pool suspended above the coral lagoon and our personal chef preparing fresh catches each evening redefined what luxury travel means to us.', 'info@zanzirangihouse.com', '2026-09-30 22:30:34');
