INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'villas', '[villa-02].shortDescription', 'Immersa tra frangipani profumati e palme da cocco, offre totale riservatezza, una doccia in pietra a cielo aperto e una serena veranda sul giardino.', 'Tucked within fragrant frangipani and coconut palms, offering total seclusion, an open-air stone shower, and serene garden verandah.', 'info@zanzirangihouse.com', '2026-09-30 22:29:07');
