INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'villas', '[villa-03].shortDescription', 'Svegliatevi al dolce fruscio delle palme e scendete dalla vostra terrazza in legno direttamente sulla sabbia bianca e finissima dell\'Oceano Indiano.', 'Wake up to the soft rustle of palms and step straight from your wooden deck onto the powdery white sand of the Indian Ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:29:07');
