INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'villas', '[villa-05].description', 'Sorto attorno a un antico e venerato baobab, questo generoso padiglione con due camere da letto offre un comfort eccezionale a compagni di viaggio o famiglie. Dispone di un cortile living centrale ombreggiato, due master suite indipendenti, ciascuna con il proprio bagno a cielo aperto, e una pergola privata per cenare.', 'Centered around an ancient, revered Baobab tree, this generous two-bedroom pavilion provides exceptional comfort for traveling companions or families. Featuring a shaded central living courtyard, two independent master suites each with their own open-air bathroom, and a private dining pergola.', 'info@zanzirangihouse.com', '2026-09-30 22:29:10');
