INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'villas', '[villa-06].description', 'Un omaggio all\'età d\'oro dell\'artigianato dell\'Isola delle Spezie. La Villa 06 vanta autentiche porte intagliate con borchie in ottone realizzate dai maestri intagliatori di Stone Town, pavimenti in terrazzo colati a mano e una piscina privata d\'acqua dolce di 12 metri per il nuoto, incorniciata da cespugli di chiodi di garofano e citronella.', 'A tribute to the Spice Island’s golden age of artisanal craftsmanship. Villa 06 features authentic brass-studded carved doors from Stone Town master carvers, hand-poured terrazzo floors, and a private 12-meter fresh water lap pool fringed by clove and lemongrass bushes.', 'info@zanzirangihouse.com', '2026-09-30 22:29:10');
