INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'villas', '[villa-07].description', 'Pensata per il viaggiatore attento al design, la Villa 07 fonde il minimalismo giapponese-scandinavo con il calore materico dell\'Africa orientale. Toni neutri rilassanti, tappeti in sisal tessuti a mano e un\'esclusiva terrazza panoramica sul tetto arredata con daybed ne fanno un rifugio ideale per il relax al chiaro di luna e la meditazione.', 'Conceived for the design-conscious traveler, Villa 07 fuses Japanese-Scandinavian minimalism with East African earthiness. Soothing neutral tones, hand-woven sisal carpets, and an exclusive rooftop observation deck equipped with daybeds make this a haven for moonlit relaxation and tranquil meditation.', 'info@zanzirangihouse.com', '2026-09-30 22:29:10');
