INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'villas', '[villa-08].architecturalFeature', 'Piscina a sfioro privata, cucina di servizio per lo chef, pontile privato per dhow e team di maggiordomi dedicato 24 ore su 24', 'Private infinity pool, chef prep kitchen, private dhow jetty, and dedicated 24-hour butler team', 'info@zanzirangihouse.com', '2026-09-30 22:29:18');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'villas', '[villa-08].bathroom', '3 lussuosi bagni privati + toilette per gli ospiti', '3 Luxurious En-Suite Bathrooms + Powder Room', 'info@zanzirangihouse.com', '2026-09-30 22:29:15');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'villas', '[villa-08].bed', '2 master suite con letto king + camera con letti singoli', '2 King Master Suites + Twin Bedroom', 'info@zanzirangihouse.com', '2026-09-30 22:29:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'villas', '[villa-08].description', 'L\'indirizzo più esclusivo della tenuta. Situata sul proprio promontorio appartato, The Royal Presidential Villa offre totale autonomia, ampi saloni per ricevere, una piscina a sfioro privata fronte oceano sospesa sulla laguna corallina, servizio di chef privato su richiesta e accesso diretto a una spiaggia privata.', 'The estate’s most exclusive address. Set on its own secluded promontory, The Royal Presidential Villa offers total autonomy, expansive entertaining salons, a private oceanfront infinity pool suspended over the coral lagoon, a private chef service on request, and direct private beach access.', 'info@zanzirangihouse.com', '2026-09-30 22:29:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'villas', '[villa-08].name', 'The Royal Presidential Villa', 'The Royal Presidential Villa', 'info@zanzirangihouse.com', '2026-09-30 22:29:04');
