INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'villas', '[villa-08].shortDescription', 'La residenza di punta di Zanzirangi House. Una grandiosità fronte oceano senza pari, piscine a sfioro su più livelli e un\'ospitalità privata e discreta.', 'The flagship residence of Zanzirangi House. Unparalleled oceanfront grandeur, multi-level infinity pools, and discrete private hosting.', 'info@zanzirangihouse.com', '2026-09-30 22:29:09');
