INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'eyebrow', 'La differenza di un rifugio', 'The Sanctuary Difference', 'info@zanzirangihouse.com', '2026-09-30 22:30:11');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'heading', 'PERCHÉ ZANZIRANGI HOUSE', 'WHY ZANZIRANGI HOUSE', 'info@zanzirangihouse.com', '2026-09-30 22:30:11');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'pillars[pillar-1].description', 'Nascosto lungo l\'incontaminata costa meridionale di Kizimkazi, lontano dal turismo di massa. Qui il tempo è scandito dal flusso delle maree, dal fruscio delle palme e da orizzonti oceanici sconfinati.', 'Tucked along the pristine southern coastline of Kizimkazi, far from tourist congestion. Here, time is measured by the tidal ebb and flow, the rustle of palms, and unobstructed ocean horizons.', 'info@zanzirangihouse.com', '2026-09-30 22:30:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'pillars[pillar-1].tagline', 'Un rifugio privato lontano dalla folla.', 'A private sanctuary away from the crowds.', 'info@zanzirangihouse.com', '2026-09-30 22:30:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'pillars[pillar-1].title', 'PRIVACY E TRANQUILLITÀ', 'PRIVATE & PEACEFUL', 'info@zanzirangihouse.com', '2026-09-30 22:30:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'pillars[pillar-2].description', 'Dai maestri intagliatori swahili ai padiglioni con tetto in makuti di antica tradizione, fino alle spezie biologiche raccolte ogni giorno negli orti della tenuta: vivete l\'anima autentica dell\'Isola delle Spezie.', 'From master Swahili woodcarvers and centuries-old makuti thatched pavilions to organic spices harvested daily from our estate gardens, experience the genuine soul of the Spice Island.', 'info@zanzirangihouse.com', '2026-09-30 22:30:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'pillars[pillar-2].tagline', 'Vivete l\'isola attraverso la sua gente, i suoi sapori e la sua cultura.', 'Experience the island through its people, flavours and culture.', 'info@zanzirangihouse.com', '2026-09-30 22:30:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'pillars[pillar-2].title', 'LA VERA ZANZIBAR', 'AUTHENTIC ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:30:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'pillars[pillar-3].description', 'Un host e un team di concierge dedicati, attenti a ogni vostra esigenza. Accoglienza privata sulla pista dell\'aeroporto, uscite in barca a noleggio, cene in villa e un\'ospitalità personale e discreta in ogni momento.', 'A dedicated host and concierge team attentive to your every need. Private airport tarmac greetings, chartered boat launches, in-villa dining, and discreet personal hospitality throughout.', 'info@zanzirangihouse.com', '2026-09-30 22:30:14');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'pillars[pillar-3].tagline', 'Dall\'arrivo in aeroporto all\'organizzazione del safari.', 'From airport arrival to safari planning.', 'info@zanzirangihouse.com', '2026-09-30 22:30:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'pillars[pillar-3].title', 'CONCIERGE PERSONALE', 'PERSONAL CONCIERGE', 'info@zanzirangihouse.com', '2026-09-30 22:30:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'pillars[pillar-4].description', 'Unite senza soluzione di continuità il riposo sull\'oceano a fly-in safari con voli charter verso il Serengeti, il Cratere di Ngorongoro e il Tarangire, per un viaggio in Africa orientale completo e indimenticabile.', 'Seamlessly combine oceanfront rest with chartered fly-in bush safaris to the Serengeti, Ngorongoro Crater, and Tarangire, creating a complete and unforgettable East African journey.', 'info@zanzirangihouse.com', '2026-09-30 22:30:14');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'pillars[pillar-4].tagline', 'Unite il vostro soggiorno a Zanzibar alle meraviglie della Tanzania continentale.', 'Connect your Zanzibar stay with the wonders of mainland Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:30:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'pillars[pillar-4].title', 'OLTRE, IN TANZANIA', 'TANZANIA BEYOND', 'info@zanzirangihouse.com', '2026-09-30 22:30:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('it', 'whystay', 'subhead', 'Quattro valori guida definiscono ogni momento del nostro retreat, creando una rara atmosfera di calma, esclusività e profondo legame con la Tanzania.', 'Four guiding values define every moment at our retreat, creating a rare atmosphere of calm, exclusivity, and profound connection to Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:30:11');
