INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'chauffeur', 'amenitiesNote', 'Podczas każdego transferu zapewniamy bezpłatną schłodzoną wodę mineralną, chłodne ręczniki i szybkie Wi-Fi w samochodzie.', 'Complimentary chilled mineral water, cool hand towels, and high-speed in-car Wi-Fi provided for every transfer.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
