INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'chauffeur', 'subhead', 'Od chwili, gdy Twój samolot wyląduje na Zanzibarze, nasz prywatny szofer zadba o to, by podróż do Zanzirangi House była całkowicie bezwysiłkowa, spokojna i bezpieczna.', 'From the moment your flight touches down in Zanzibar, our private chauffeur service ensures your transition to Zanzirangi House is completely effortless, serene, and secure.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
