INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[arabic].description', 'Celebracja wielowiekowego królewskiego dziedzictwa Omanu na Zanzibarze i arabskich szlaków morskich. Delektuj się powoli duszonymi, korzennymi mięsami, podpłomykami z glinianego pieca, wybornymi zimnymi i ciepłymi mezze, aromatycznymi daniami z ryżu z szafranem oraz słodkimi przysmakami z wodą różaną, przygotowywanymi przez mistrzów kuchni.', 'A celebration of Zanzibar’s centuries-old royal Omani heritage and Arabian sea routes. Savor slow-braised spiced meats, clay-oven flatbreads, exquisite cold and hot mezze, fragrant saffron-infused rice dishes, and sweet rosewater delicacies prepared by master chefs.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[arabic].name', 'Autentyczna kuchnia arabska i omańska', 'Authentic Arabic & Omani Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[arabic].signatureDishes[#0].description', 'Delikatna jagnięcina pieczona przez 24 godziny z goździkami, kardamonem, kolendrą, suszoną limonką i w liściach bananowca, podawana na aromatycznym złotym ryżu kabsa z szafranem.', 'Tender lamb slow-cooked for 24 hours with cloves, cardamom, coriander, dry lime, and banana leaves, served over fragrant golden saffron Kabsa rice.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[arabic].signatureDishes[#0].name', 'Omańska shuwa – wolno pieczona jagnięcina z przyprawami', 'Omani Shuwa Spiced Slow-Roasted Lamb', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[arabic].signatureDishes[#1].description', 'Aksamitny hummus skropiony granatem, wędzony mutabal, chrupiący ziołowy falafel i ręcznie wyrabiane arabskie podpłomyki z pieca opalanego drewnem.', 'Velvety pomegranate-drizzled hummus, smoky Mutabal, crispy herbed falafel, and handmade wood-fired Arabic flatbreads.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[arabic].signatureDishes[#1].name', 'Królewskie mezze i świeży chlebek khubz z za’atarem', 'Royal Mezze & Fresh Za’atar Khubz', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[arabic].signatureDishes[#2].description', 'Grillowane na węglu drzewnym duże krewetki z Menai Bay, kalmary i ryby rafowe przyprawione papryką Aleppo, sumakiem, czosnkiem i dzikimi ziołami.', 'Charcoal-grilled Menai Bay jumbo prawns, calamari, and reef catch seasoned with Aleppo pepper, sumac, garlic, and wild herbs.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[arabic].signatureDishes[#2].name', 'Półmisek owoców morza mashwi z grillowaną limonką', 'Mashwi Seafood & Charred Lime Platter', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[arabic].signatureDishes[#3].description', 'Delikatne, kruche ciasto filo przekładane prażonymi pistacjami i syropem z kwiatu pomarańczy i kardamonu, podawane ze schłodzonym puddingiem mlecznym z wodą różaną.', 'Delicate flaky filo pastry layered with toasted pistachios and orange-blossom cardamom syrup alongside chilled rosewater milk pudding.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[arabic].signatureDishes[#3].name', 'Ciepła baklawa z pistacjami i muhallabia z wodą różaną', 'Warm Pistachio Baklava & Rosewater Muhallabia', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[arabic].subtitle', 'Królewskie dziedzictwo Omanu, grill z glinianego pieca i bliskowschodnie mezze', 'Royal Omani Heritage, Clay-Oven Grills & Middle Eastern Mezze', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[arabic].tabLabel', 'Arabska', 'Arabic', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[beverages].description', 'Wyrafinowana karta napojów stworzona z myślą o tropikalnej przyjemności. Ciesz się winami z najlepszych roczników świata, czystymi tłoczonymi na zimno sokami z tropikalnych owoców Zanzibaru, domowymi botanicznymi napojami bezalkoholowymi i krystalicznie czystymi wodami mineralnymi premium – na plaży lub przy basenie.', 'An elevated beverage program curated for tropical indulgence. Enjoy world-class cellar vintages, pure cold-pressed Zanzibar tropical juices, house-crafted botanical soft drinks, and premium pristine mineral waters served beachfront or poolside.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[beverages].name', 'Napoje, piwniczka i orzeźwienie', 'Beverages, Cellar & Refreshments', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[beverages].signatureDishes[#0].description', 'Kolekcje Starego i Nowego Świata, rześkie południowoafrykańskie Chenin Blanc i Sauvignon Blanc, eleganckie francuskie szampany oraz pełne czerwone wina z Toskanii i Bordeaux.', 'Old and New World collections, crisp South African Chenin Blanc & Sauvignon Blanc, elegant French Champagnes, and full-bodied Tuscan & Bordeaux reds.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[beverages].signatureDishes[#0].name', 'Wyselekcjonowane wina i szampany (wina)', 'Curated Cellar Wines & Champagne (Wines)', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[beverages].signatureDishes[#1].description', 'Dojrzewające w słońcu marakuje, słodkie mango Alfonso, kruszony ananas ze świeżą miętą i woda z młodego kokosa King prosto z nadmorskich gajów palmowych.', 'Sun-ripened passion fruit, sweet Alfonso mango, crushed pineapple with fresh mint, and young King coconut water straight from coastal palm groves.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[beverages].signatureDishes[#1].name', 'Tłoczone na zimno tropikalne nektary Zanzibaru (soki)', 'Cold-Pressed Zanzibar Tropical Nectars (Juice)', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[beverages].signatureDishes[#2].description', 'Domowe, ogniste piwo imbirowe z kruszoną trawą cytrynową, musujący tanzański napój z hibiskusa, rzemieślnicze toniki botaniczne i klasyczne schłodzone napoje gazowane.', 'House-brewed fiery ginger beer with crushed lemongrass, sparkling Tanzanian hibiscus cooler, craft botanical tonics, and classic iced sodas.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[beverages].signatureDishes[#2].name', 'Rzemieślnicze botaniczne lemoniady i toniki (napoje bezalkoholowe)', 'Artisanal Botanical Sodas & Tonics (Soft Drinks)', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[beverages].signatureDishes[#3].description', 'Niegazowane i gazowane wody źródlane premium z Europy i Afryki Wschodniej, podawane mocno schłodzone ze świeżym ogórkiem z ogrodu, miętą i limonką z Makunduchi.', 'Still and sparkling premium European & East African spring waters served crystal chilled with fresh garden cucumber, mint, and Makunduchi lime.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
