INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[fusion].description', 'Nasz kulinarny znak rozpoznawczy. Pełen wyobraźni dialog między klasyczną techniką francuską a niezwykłym przyprawowym terroir Zanzibaru. Spodziewaj się harmonijnych połączeń, takich jak masło z langusty aromatyzowane laską wanilii, redukcje z tamaryndowca czy suflety z marakui.', 'Our culinary signature. An imaginative dialogue between classical French technique and Zanzibar’s extraordinary spice terroir. Expect harmonious pairings like vanilla bean infused lobster butter, tamarind reductions, and passion fruit soufflés.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[fusion].name', 'Współczesna kuchnia fusion suahili', 'Swahili Contemporary Fusion', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[fusion].signatureDishes[#0].description', 'Słodka, soczysta langusta gotowana w klarowanym francuskim maśle aromatyzowanym laskami wanilii z Pemby, z emulsją z batatów i salicornią.', 'Sweet succulent lobster poached in clarified French butter scented with fragrant Pemba vanilla pods, sweet potato emulsion, and sea asparagus.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[fusion].signatureDishes[#0].name', 'Langusta gotowana w maśle z wanilią z Pemby', 'Butter-Poached Rock Lobster with Pemba Vanilla', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[fusion].signatureDishes[#1].description', 'Pierś z kaczki magret z chrupiącą skórką, podawana medium rare z kwaskową glazurą z kwiatu hibiskusa, pieczonymi młodymi marchewkami i korzennym purée z manioku.', 'Crispy skin Magret duck breast served medium rare with a tart hibiscus flower glaze, roasted baby carrots, and spiced cassava purée.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[fusion].signatureDishes[#1].name', 'Pierś z kaczki z tamaryndowcem i hibiskusem', 'Seared Duck Breast with Tamarind & Hibiscus', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[fusion].signatureDishes[#2].description', 'Płynne ciasto z 70% gorzkiej czekolady aromatyzowane zielonym kardamonem, podawane z domowymi lodami kokosowymi i coulis z marakui.', 'Molten dark 70% chocolate cake perfumed with green cardamom, served with house-spun coconut gelato and passionfruit coulis.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[fusion].signatureDishes[#2].name', 'Fondant z czekolady Valrhona i zanzibarskiego kardamonu', 'Valrhona Chocolate & Zanzibar Cardamom Fondant', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[fusion].subtitle', 'Gdzie tropikalna wyspa spotyka nowoczesną francuską haute cuisine', 'Where Tropical Island Meets Modern French Haute Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[fusion].tabLabel', 'Fusion', 'Fusion', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[local].description', 'W nadmorskich kuchniach Zanzibaru zbiegły się wieki arabskiego, perskiego, indyjskiego i wschodnioafrykańskiego handlu morskiego. Nasi szefowie kuchni przygotowują dania według dawnych receptur, sięgając po świeżo pozyskane mleko kokosowe, aromatyczny kardamon, goździki z Pemby oraz owoce morza łowione na wędkę i dostarczane prosto na nasz brzeg.', 'Centuries of Arab, Persian, Indian, and East African maritime trade converged in Zanzibar’s coastal kitchens. Our executive chefs prepare time-honored recipes featuring freshly harvested coconut milk, aromatic cardamom, cloves from Pemba, and line-caught seafood brought straight to our shores.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[local].name', 'Autentyczna kuchnia suahili', 'Authentic Swahili Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[local].signatureDishes[#0].description', 'Smażony na patelni dziki lucjan rafowy duszony ze świeżą kolendrą, kurkumą mieloną w kamiennych żarnach i ręcznie wyciskanym mlekiem kokosowym, podawany z ryżem szafranowym.', 'Pan-seared wild reef snapper simmered with fresh green coriander, stone-ground turmeric, and hand-squeezed coastal coconut milk served with saffron rice.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[local].signatureDishes[#0].name', 'Zanzibarski lucjan rafowy w kokosie i kurkumie', 'Zanzibari Coral Reef Snapper in Coconut & Turmeric', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[local].signatureDishes[#1].description', 'Wyrazisty, wolno gotowany bulion z mango i tamaryndowca z delikatnymi krewetkami, korzennymi chipsami z manioku i sambalem kokosowym z kruszonym chili.', 'A tangy, slow-simmered mango and tamarind broth with tender prawns, spiced cassava crisps, and crushed chili coconut sambal.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[local].signatureDishes[#1].name', 'Tanzańskie urojo z gulaszem z krewetek tygrysich', 'Tanzanian Urojo & Tiger Prawn Stew', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[local].signatureDishes[#2].description', 'Rozpływająca się w ustach lokalna jagnięcina aromatyzowana anyżem gwiaździstym, laskami cynamonu i czarnym kardamonem, podawane z marynowaną sałatką kachumbari.', 'Fork-tender local lamb infused with star anise, cinnamon quills, and black cardamom, accompanied by pickled kachumbari salad.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[local].signatureDishes[#2].name', 'Wolno duszona koźlina z przyprawami pilau', 'Slow-Braised Goat with Pilau Spices', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[local].subtitle', 'Tradycyjne smaki i przyprawy Zanzibaru', 'Heritage Flavors & Zanzibar Spices', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[local].tabLabel', 'Suahili', 'Swahili', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[western].description', 'Stworzona z myślą o międzynarodowych podniebieniach, które szukają znajomych smaków przygotowanych z zastosowaniem najwyższych technik fine dining. Najlepsze importowane kawałki wołowiny, świeże śródziemnomorskie sałatki, domowy ręcznie robiony makaron i wykwintne desery wykonane z kulinarną precyzją.', 'Designed for international palates seeking comforting familiarity prepared with the highest fine-dining techniques. Prime imported beef cuts, fresh Mediterranean salads, homemade handmade pasta, and decadent desserts executed with crisp culinary precision.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[western].name', 'Nowoczesna gastronomia zachodnia', 'Modern Western Gastronomy', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[western].signatureDishes[#0].description', 'Grillowana do perfekcji, podawana z gładkim musem z pasternaku, pieczonymi pomidorkami na gałązce i sosem z czerwonego wina redukowanym przez 24 godziny.', 'Char-grilled to perfection, paired with smooth parsnip mousseline, blistered vine tomatoes, and a 24-hour reduced red wine jus.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[western].signatureDishes[#0].name', 'Polędwica z wołowiny wagyu z glazurą truflową', 'Prime Wagyu Tenderloin with Truffle Glaze', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[western].signatureDishes[#1].description', 'Lokalny tuńczyk łowiony na wędkę, krojony w kostkę z awokado Hass, oliwą tłoczoną na zimno, owocami kaparów i domowymi chipsami z chleba na zakwasie.', 'Line-caught local tuna diced with Hass avocado, cold-pressed olive oil, caper berries, and house-baked sourdough crisps.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[western].signatureDishes[#1].name', 'Tatar z dzikiego tuńczyka żółtopłetwego z awokado', 'Wild Yellowfin Tuna Tartare with Avocado', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[western].signatureDishes[#2].description', 'Świeży makaron jajeczny ze słodkim ogonem langusty z Kizimkazi, czosnkowym confit, pomidorkami koktajlowymi i lekkim bisque z Pinot Grigio.', 'Fresh egg pasta tossed with sweet Kizimkazi rock lobster tail, garlic confit, baby cherry tomatoes, and a light Pinot Grigio bisque.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'categories[western].signatureDishes[#2].name', 'Ręcznie robione tagliolini z langustą', 'Handmade Tagliolini with Rock Lobster', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
