INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'eyebrow', 'Kulinarna dusza', 'Gastronomic Soul', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'gardenBadge', 'Ogród posiadłości', 'Estate Garden', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'gardenDesc', 'Na terenie Zanzirangi House kryje się nasz prywatny ogród botaniczny, w którym zespół kuchni uprawia ekologiczną trawę cytrynową, zielone chili, dziką bazylię, słodką miętę, aromatyczny kardamon i sezonowe warzywa. To, co zbieramy rano, kształtuje nasze codzienne menu degustacyjne, łącząc witalność plonów ziemi ze świeżym połowem z wód południowego Zanzibaru.', 'Tucked within the grounds of Zanzirangi House is our private botanical garden, where our kitchen team cultivates organic lemongrass, green chilies, wild basil, sweet mint, fragrant cardamom, and seasonal vegetables. What is harvested in the morning directly shapes our daily tasting menus, pairing earth-grown vitality with the fresh catch of southern Zanzibar’s waters.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'gardenEyebrow', 'Kulinarne opowieści', 'Culinary Storytelling', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'gardenTitle', 'Z NASZEGO OGRODU NA TWÓJ STÓŁ', 'FROM OUR GARDEN TO YOUR TABLE', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'heading', 'SMAK ZANZIBARU', 'TASTE ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'intro', 'Przy naszych stołach spotykają się wieki handlu morskiego suahili, Omanu i Oceanu Indyjskiego. Od ryb łowionych na wędkę i przywożonych na brzeg o świcie po aromatyczne curry duszone na wolnym ogniu – posiłki w Zanzirangi House to autentyczna podróż dla zmysłów.', 'Centuries of Swahili, Omani, and Indian Ocean sea trade come together at our tables. From line-caught fish brought ashore at sunrise to slow-simmered aromatic curries, dining at Zanzirangi House is an authentic sensory journey.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'moments[#0].desc', 'Tropikalna papaja, krem z marakui, ciepła świeżo upieczona brioszka i korzenna tanzańska kawa podawane z widokiem na poranny ocean.', 'Tropical papaya, passion fruit curds, warm freshly-baked brioche, and spiced Tanzanian coffee served overlooking the morning ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'moments[#0].time', '07:00 – 10:30', '07:00 – 10:30 AM', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'moments[#0].title', 'Rzemieślnicze śniadanie', 'Artisanal Breakfast', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'moments[#1].desc', 'Tatar z tuńczyka żółtopłetwego łowionego na wędkę, sałatki z langusty, podpłomyki z pieca opalanego drewnem i woda z młodego kokosa King w cieniu palm.', 'Line-caught yellowfin tuna tartare, rock lobster salads, wood-fired flatbreads, and young King coconut water under the palms.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'moments[#1].time', '12:30 – 15:30', '12:30 – 03:30 PM', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
