INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'moments[#2].desc', 'Chrupiące chipsy z plantanów, krewetki w pikantnym tamaryndowcu, wina z naszej piwniczki i ręcznie przygotowane koktajle botaniczne, gdy oceaniczny horyzont nabiera fioletu.', 'Crisp plantain crisps, spiced tamarind prawns, cellar wines, and handcrafted botanical cocktails as the ocean horizon turns violet.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
