INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'moments[#3].desc', 'Zanzibarskie curry kokosowe duszone na wolnym ogniu, duszona jagnięcina z omańskimi przyprawami i fondanty z czekolady Valrhona z kardamonem.', 'Slow-simmered Zanzibari coconut curries, Omani spiced braised lamb, and Valrhona chocolate cardamom fondants.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
