INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'moments[#4].desc', 'Otwarty pawilon restauracyjny pod strzechą makuti, chwytający chłodną bryzę znad Menai Bay.', 'Open-air makuti thatched dining pavilion capturing the cool cross-breezes of Menai Bay.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
