INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'subhead', '\"Świeże składniki, wyspiarskie smaki i autentyczna tanzańska gościnność.\"', '\"Fresh ingredients, island flavours and authentic Tanzanian hospitality.\"', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
