INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'dining', 'tagZeroMiles', '🌱 Zero kilometrów żywności', '🌱 Zero Food Miles', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-cultural].description', 'Odwiedź historyczną osadę rybacką Kizimkazi i starożytny meczet Dimbani (z 1107 roku). Poznaj miejscowych mistrzów rzemiosła, którzy ręcznie budują tradycyjne łodzie dau, weź udział w warsztatach kuchni suahili lub posłuchaj prywatnego koncertu taarab na skrzypcach i kanunie pod nocnym niebem.', 'Visit the historic Kizimkazi fishing settlement and the ancient Dimbani Mosque (dating to 1107 AD). Meet local master craftsmen carving traditional dhows by hand, participate in a Swahili culinary workshop, or enjoy private taarab violin and kanun music under the night stars.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-cultural].duration', '3,5 godziny (godziny do uzgodnienia)', '3.5 Hours (Custom Timing)', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-cultural].priceNote', 'Cena na zapytanie', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-cultural].shortDescription', 'Poznaj miejscowych rzemieślników z wybrzeża, naucz się plecenia z liści palmowych i odnawiania łodzi dau oraz odkryj dawne dziedzictwo suahili.', 'Engage authentically with local coastal artisans, learn palm-weaving and dhow restoration, and discover ancient Swahili heritage.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-cultural].tag', 'Doświadczenia kulturowe', 'Cultural Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-cultural].title', 'Tradycje suahili, taarab i życie wioski', 'Swahili Traditions, Taarab & Village Life', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-cultural].whatsappMessage', 'Dzień dobry, konsjerżu Zanzirangi House, chciałbym/chciałabym dowiedzieć się więcej o doświadczeniach kulturowych suahili.', 'Hello Zanzirangi House Concierge, I would like to learn more about Swahili Cultural Experiences.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-dolphins].description', 'Nasze położenie w Kizimkazi na południowym wybrzeżu Zanzibaru zapewnia bezpośredni dostęp do najsłynniejszego sanktuarium delfinów w Afryce Wschodniej. Wypłyń o świcie prywatną łodzią dau lub motorówką, by obserwować stada delfinów baraszkujących w ich naturalnym środowisku, a potem wróć na śniadanie do posiadłości.', 'Our location in Kizimkazi on Zanzibar’s southern coast provides direct access to East Africa’s most famous dolphin sanctuary. Depart at dawn on a private dhow or motor launch to watch dolphin pods playing in their natural ocean habitat before enjoying breakfast back at the property.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-dolphins].duration', '3,5 godziny (rejs o świcie)', '3.5 Hours (Early Morning Dawn Cruise)', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-dolphins].priceNote', 'Cena na zapytanie', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-dolphins].shortDescription', 'Wypłyń o wschodzie słońca z Kizimkazi na chronione wody Menai Bay, by zobaczyć stada zamieszkujących je delfinów długoszczękich i butlonosych.', 'Set sail at sunrise from Kizimkazi into the protected waters of Menai Bay to witness pods of resident spinner and bottlenose dolphins.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-dolphins].tag', 'Delfiny', 'Dolphin Experience', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-dolphins].title', 'Spotkanie z dzikimi delfinami w Kizimkazi', 'Kizimkazi Wild Dolphin Encounter', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-dolphins].whatsappMessage', 'Dzień dobry, konsjerżu Zanzirangi House, chciałbym/chciałabym wziąć udział w spotkaniu z dzikimi delfinami w Kizimkazi.', 'Hello Zanzirangi House Concierge, I would like to experience the Kizimkazi Wild Dolphin Encounter.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-fishing].description', 'Na pokładzie naszej czarterowej łodzi do połowów pełnomorskich, wyposażonej w outriggery, sprzęt Shimano i nowoczesną elektronikę nawigacyjną, poczuj adrenalinę połowów dużych ryb w głębokich prądach Oceanu Indyjskiego. Ryby z rodziny marlinowatych łowimy wyłącznie zgodnie z zasadą „złów i wypuść”.', 'Aboard our chartered offshore sportfisher equipped with outriggers, Shimano tackle, and modern nautical electronics, experience the adrenaline of big game fishing in the deep currents of the Indian Ocean. Strictly adheres to catch-and-release protocols for billfish.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-fishing].duration', 'Pół dnia (5 godzin) lub cały dzień (8 godzin)', 'Half Day (5 Hours) or Full Day (8 Hours)', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
