INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-fishing].shortDescription', 'Wyrusz na głębokie wody kanałów Pemby i Zanzibaru na światowej klasy połowy tuńczyka żółtopłetwego, żaglicy i wahoo.', 'Venture into the deep Pemba and Zanzibar channels for world-class sport fishing targeting yellowfin tuna, sailfish, and wahoo.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-fishing].tag', 'Wędkarstwo pełnomorskie', 'Deep Sea Fishing', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-fishing].title', 'Wędkarstwo pełnomorskie na duże ryby', 'Deep Sea Big Game Sport Fishing', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-fishing].whatsappMessage', 'Dzień dobry, konsjerżu Zanzirangi House, proszę o szczegóły dotyczące wypraw na wędkarstwo pełnomorskie.', 'Hello Zanzirangi House Concierge, I would like details on Deep Sea Sport Fishing trips.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-island-hopping].description', 'Wyznacz własny kurs po turkusowych wodach południowego i zachodniego Zanzibaru. Zejdź na ulotne, pudrowo białe łachy piasku, które wyłaniają się tylko podczas odpływu, pływaj w ciepłej, krystalicznej wodzie i delektuj się świeżo przygotowanym lunchem z grillowanej langusty z Menai Bay, kalmarów i tropikalnych owoców.', 'Chart your own course across the turquoise waters of southern and western Zanzibar. Disembark onto ephemeral powder-white sandbanks that emerge only at low tide, swim in warm crystalline waters, and savor a freshly prepared lunch of grilled Menai Bay lobster, calamari, and tropical fruit.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-island-hopping].duration', 'Cały dzień (prywatna łódź motorowa)', 'Full Day (Private Speedboat)', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-island-hopping].priceNote', 'Cena na zapytanie', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-island-hopping].shortDescription', 'Popłyń na ustronne, bezludne wysepki koralowe, kąp się w opustoszałych lagunach pływowych i delektuj się lunchem z grillowanych owoców morza na prywatnej piaszczystej łasze.', 'Cruise to secluded uninhabited coral islets, swim in deserted tidal lagoons, and enjoy a grilled seafood lunch on a private sandbank.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-island-hopping].tag', 'Rejs po wyspach', 'Island Hopping', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-island-hopping].title', 'Prywatny rejs po wyspach i safari na piaszczystych łachach', 'Private Island Hopping & Sandbank Safari', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-island-hopping].whatsappMessage', 'Dzień dobry, konsjerżu Zanzirangi House, chciałbym/chciałabym zapytać o prywatny rejs po wyspach z safari na piaszczystych łachach.', 'Hello Zanzirangi House Concierge, I would like to inquire about the Private Island Hopping Sandbank Safari.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-mnemba].description', 'Położony u północno-wschodniego wybrzeża Zanzibaru atol Mnemba słynie na całym świecie z nieskazitelnych warunków podwodnych. Ciesz się prywatnymi transferami łodzią, ekskluzywnym snorkelingiem nad koralowymi iglicami i wykwintnym piknikiem na plaży przygotowanym przez naszego prywatnego szefa kuchni.', 'Located off Zanzibar’s northeast coast, Mnemba Atoll is recognized globally for its pristine underwater conditions. Enjoy private boat transfers, exclusive snorkeling over coral pinnacles, and a beachside gourmet picnic arranged by our private chef.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-mnemba].duration', 'Całodniowa prywatna wyprawa', 'Full Day Private Expedition', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
