INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-mnemba].shortDescription', 'Popłyń do perły morskich rezerwatów Zanzibaru: niezrównanie przejrzysta turkusowa woda, nieskazitelne ogrody koralowe i laguny żółwi morskich.', 'Sail to the crown jewel of Zanzibar marine reserves: unmatched turquoise clarity, pristine coral gardens, and sea turtle lagoons.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
