INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-mnemba].whatsappMessage', 'Dzień dobry, konsjerżu Zanzirangi House, chciałbym/chciałabym zarezerwować wyprawę do rezerwatu morskiego wyspy Mnemba.', 'Hello Zanzirangi House Concierge, I would like to book the Mnemba Island Marine Sanctuary expedition.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-nature-jozani].description', 'W towarzystwie licencjonowanego przyrodnika parku narodowego wyrusz w głąb pradawnych lasów liściastych chronionych w Parku Narodowym Jozani Chwaka Bay. Obserwuj stada małp przeskakujące w koronach drzew, przejdź podwyższoną kładką przez namorzyny i poznaj rzadką florę występującą wyłącznie na Zanzibarze.', 'Led by an authorized national park naturalist, journey into ancient hardwood forests protected within Jozani Chwaka Bay National Park. Observe monkey troops swinging through the canopy, walk the elevated mangrove boardwalk, and learn about the rare flora unique to Zanzibar.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-nature-jozani].duration', '4 godziny (zalecane rano)', '4 Hours (Morning Recommended)', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-nature-jozani].priceNote', 'Cena na zapytanie', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-nature-jozani].shortDescription', 'Wędruj przez dziewiczy mahoniowy las bagienny, by spotkać figlarne, endemiczne gerezy czerwone z Zanzibaru.', 'Trek through virgin groundwater mahogany forest to encounter the playful, endemic Zanzibar Red Colobus monkey.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-nature-jozani].tag', 'Kontakt z naturą', 'Nature Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
