INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-nature-jozani].whatsappMessage', 'Dzień dobry, konsjerżu Zanzirangi House, chciałbym/chciałabym zarezerwować wycieczkę przyrodniczą do lasu Jozani.', 'Hello Zanzirangi House Concierge, I would like to reserve the Jozani Forest Nature Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-snorkeling-diving].description', 'Rafy barierowe Zanzibaru tętnią tropikalną bioróżnorodnością. Z najwyższej klasy profesjonalnym sprzętem i w towarzystwie certyfikowanych divemasterów PADI odkryjesz zapierające dech w piersiach uskoki, podwodne jaskinie do przepłynięcia i krystaliczną widoczność sięgającą 30 metrów.', 'Zanzibar’s barrier reefs are teeming with tropical biodiversity. Equipped with top-tier professional gear and accompanied by certified PADI divemasters, discover stunning drop-offs, swim-through caves, and crystal visibility extending up to 30 meters.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
