INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-snorkeling-diving].shortDescription', 'Odkrywaj barwne ogrody koralowe i podwodne ściany, spotykaj żółwie morskie, orleniki cętkowane i egzotyczne gatunki rafowe.', 'Explore vibrant coral gardens, underwater marine walls, and meet sea turtles, spotted eagle rays, and exotic reef species.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-snorkeling-diving].tag', 'Snorkeling i nurkowanie', 'Snorkeling & Diving', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
