INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-snorkeling-diving].whatsappMessage', 'Dzień dobry, konsjerżu Zanzirangi House, chciałbym/chciałabym zorganizować wycieczkę na snorkeling i nurkowanie.', 'Hello Zanzirangi House Concierge, I would like to arrange a Snorkeling & Diving excursion.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-spice-farm].description', 'Przespaceruj się z doświadczonymi miejscowymi botanikami po bujnych wiejskich plantacjach. Dotykaj, wąchaj i smakuj surowe przyprawy prosto z drzew i pnączy – m.in. czarny pieprz, gałkę muszkatołową, imbir, trawę cytrynową i kurkumę – a na koniec napij się świeżej wody z kokosa King zerwanego wysoko z korony palmy.', 'Walk alongside expert local botanists through verdant rural plantations. Touch, smell, and taste raw spices directly from the trees and vines—including black pepper, nutmeg, ginger, lemongrass, and turmeric—concluding with fresh King coconut water harvested high in the canopy.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-spice-farm].duration', '4 godziny (rano lub po południu)', '4 Hours (Morning or Afternoon)', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-spice-farm].priceNote', 'Cena na zapytanie', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-spice-farm].shortDescription', 'Zanurz zmysły w wiekach aromatycznej historii: zrywaj świeży cynamon, rozgniataj zielony kardamon i skosztuj dzikiej wanilii.', 'Immerse your senses in centuries of aromatic history: pluck fresh cinnamon, crush green cardamom, and taste wild vanilla bean.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-spice-farm].tag', 'Farma przypraw', 'Spice Farm', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-spice-farm].title', 'Wyprawa na ekologiczną farmę przypraw', 'Organic Botanical Spice Farm Journey', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-spice-farm].whatsappMessage', 'Dzień dobry, konsjerżu Zanzirangi House, interesuje mnie wyprawa na ekologiczną farmę przypraw.', 'Hello Zanzirangi House Concierge, I am interested in the Organic Botanical Spice Farm Journey.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-stonetown].description', 'Prywatna podróż po Stone Town, wpisanym na Listę Światowego Dziedzictwa UNESCO. W towarzystwie miejscowego historyka kultury suahili zwiedzisz Dom Cudów, XVII-wieczny Stary Fort, katedrę anglikańską i miejsce pamięci dawnego targu niewolników, a także pracownie rzemieślników specjalizujących się w srebrnej biżuterii i tkaninach.', 'A private journey through UNESCO World Heritage Stone Town. Led by a resident Swahili historian, explore the House of Wonders, the 17th-century Old Fort, the Anglican Cathedral and Old Slave Market memorial, and artisan workshops specializing in silver jewelry and woven textiles.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-stonetown].duration', 'Cały dzień (prywatny szofer i przewodnik)', 'Full Day (Private Chauffeur & Guide)', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-stonetown].priceNote', 'Cena na zapytanie', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-stonetown].shortDescription', 'Przemierz labirynt uliczek z kamienia koralowego, podziwiaj zdobione omańskie rzeźbione drzwi z drewna tekowego, historyczne bazary przypraw i Pałac Sułtana.', 'Walk through labyrinthine coral ragstone alleyways, ornate Omani carved teak doors, historical spice bazaars, and the Sultan’s Palace.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-stonetown].tag', 'Kultura i dziedzictwo', 'Culture & Heritage', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-stonetown].title', 'Dziedzictwo i historyczne dzielnice Stone Town', 'Stone Town Heritage & Historic Quarters', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-stonetown].whatsappMessage', 'Dzień dobry, konsjerżu Zanzirangi House, chciałbym/chciałabym zarezerwować prywatną wycieczkę po dziedzictwie Stone Town.', 'Hello Zanzirangi House Concierge, I am interested in booking the private Stone Town Heritage Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-sunset-cruise].description', 'Wejdź na pokład ręcznie wykonanej żaglowej łodzi dau suahili, wyrzeźbionej z rodzimego mahoniu. Odpocznij na miękkich poduszkach z kieliszkiem schłodzonego szampana i rzemieślniczymi kanapeczkami, wsłuchując się w hipnotyzujący szum oceanicznej bryzy i akustyczne melodie taarab, gdy dzień przechodzi w zmierzch.', 'Step aboard a handcrafted Swahili sailing dhow carved from indigenous mahogany. Relax upon plush cushions with chilled Champagne, artisanal canapés, and the hypnotic sounds of the ocean breeze and acoustic taarab melodies as daylight fades into dusk.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-sunset-cruise].duration', '2,5 godziny (późne popołudnie, złota godzina)', '2.5 Hours (Late Afternoon Golden Hour)', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-sunset-cruise].priceNote', 'Cena na zapytanie', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-sunset-cruise].shortDescription', 'Suń po spokojnym Oceanie Indyjskim pod wydętymi płóciennymi żaglami, gdy równikowe słońce maluje niebo odcieniami bursztynu i różowego złota.', 'Glide across the calm Indian Ocean under billowed canvas sails as the equatorial sun paints the sky in shades of amber and rose gold.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'experiences', '[exp-sunset-cruise].tag', 'Rejs o zachodzie słońca', 'Sunset Cruise', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
