INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'facilities', '[bbq].category', 'Wieczorne spotkania', 'Evening Gathering', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'facilities', '[bbq].description', 'Gdy słońce zanurza się w Oceanie Indyjskim, zbierz się przy naszym ognisku na brzegu, by skosztować grillowanej langusty, krewetek tygrysich i korzennej polędwicy pieczonych na łupinach kokosa pod afrykańskimi gwiazdozbiorami.', 'As the sun dips into the Indian Ocean, gather around our shoreline firepit for grilled lobster, tiger prawns, and spiced tenderloins cooked over coconut husks under the African constellations.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'facilities', '[bbq].highlight', 'Kolacja przy świecach nad oceanem przy akustycznej muzyce taarab na żywo', 'Oceanfront candlelit dining with live acoustic Taarab music', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
