INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'facilities', '[breakfast].description', 'Obudź się przy półmiskach tropikalnych owoców z lokalnych sadów, świeżo upieczonej brioszce, kremie z marakui, tanzańskiej kawie arabica i jajkach przygotowanych według Twoich upodobań – w willi lub nad morzem.', 'Awaken to tropical fruit platters from local orchards, freshly baked brioche, passion fruit curd, Tanzanian arabica coffee, and eggs cooked to your preference in your villa or by the sea.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
