INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'facilities', '[dining].description', 'Otwarty pawilon pod sklepionym dachem z makuti, z panoramicznym widokiem na ocean. Odkryj kuchnię fine dining przesyconą aromatem zanzibarskich przypraw i najświeższymi połowami dnia.', 'An open-air pavilion beneath vaulted Makuti thatch offering panoramic ocean views. Experience fine dining infused with the aromas of Zanzibar spices and the freshest catches of the day.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
