INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'facilities', '[massage].description', 'Ustronne sale spa pod gołym niebem, ukryte w nadmorskich ogrodach. Oddaj się indywidualnym masażom z tłoczonym na zimno olejem kokosowym z Zanzibaru, trawą cytrynową, mielonymi goździkami i rodzimymi afrykańskimi roślinami.', 'Secluded open-air spa salas nestled in coastal gardens. Indulge in bespoke massages using cold-pressed Zanzibar coconut oil, lemongrass, ground cloves, and indigenous African botanicals.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
