INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'facilities', '[pool].description', 'Zawieszony nad turkusowymi falami Oceanu Indyjskiego 25-metrowy basen infinity ze słodką wodą odbija niebo i oceaniczny horyzont, oferując zanurzone leżaki i troskliwą obsługę przy basenie.', 'Suspended above the turquoise tides of the Indian Ocean, our 25-meter freshwater infinity pool mirrors the sky and ocean horizons with sunken sunbeds and attentive poolside service.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
