INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'facilities', '[wifi].description', 'Ciesz się błyskawicznym internetem satelitarnym o niskich opóźnieniach na terenie całej posiadłości – w prywatnych willach, na leżakach przy plaży i tarasach restauracyjnych – zapewniającym płynną komunikację i wygodną pracę zdalną.', 'Enjoy blazing-fast, low-latency satellite internet across the entire estate, private villas, beachfront loungers, and dining terraces, ensuring seamless communication and remote productivity.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
