INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'homepage', 'hero.description', 'Odkryj luksusowe wille na Zanzibarze z prywatnymi basenami w Zanzirangi House w Kizimkazi. Kameralne sanktuarium złożone z 8 willi, oferujące kuchnię prosto z oceanu na stół i szyte na miarę wyprawy po wyspie.', 'Experience Zanzibar luxury villas with private plunge pools at Zanzirangi House in Kizimkazi. An intimate 8-villa sanctuary offering ocean-to-table dining and bespoke island journeys.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
