INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'homepage', 'hero.slides[slide-02].description', 'Ukryta wśród pachnących plumerii i palm kokosowych na południu Zanzibaru, zapewnia całkowite odosobnienie, kamienny prysznic pod gołym niebem i spokojną ogrodową werandę.', 'Tucked within fragrant frangipani and coconut palms in southern Zanzibar, offering total seclusion, an open-air stone shower, and serene garden verandah.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
