INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'homepage', 'hero.slides[slide-03].description', 'Najbardziej prestiżowa rezydencja nad oceanem w Zanzirangi House – z zawieszonym basenem infinity, przestronnym pawilonem wypoczynkowym, kolacjami od prywatnego szefa kuchni i pakietami safari z bezpośrednim przelotem do Serengeti.', 'The premier oceanfront residence at Zanzirangi House featuring a suspended infinity pool, expansive living pavilion, private chef dining, and direct Serengeti fly-in safari packages.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
