INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'homepage', 'intro.description', 'Zanzirangi House to ultrabutikowe ustronie z 8 prywatnymi willami z basenami, ukryte na spokojnym południowym wybrzeżu Zanzibaru w Kizimkazi Dimbani.', 'Zanzirangi House is an ultra-boutique retreat featuring 8 private plunge-pool villas secluded along the peaceful southern coast of Zanzibar in Kizimkazi Dimbani.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
