INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[about].description', 'Położony na dziewiczym południowym koralowym wybrzeżu Kizimkazi Dimbani, Zanzirangi House to ultrabutikowe prywatne sanktuarium stworzone, by zapewnić całkowite odosobnienie, architektoniczną harmonię i kameralną zanzibarską gościnność.', 'Nestled along the pristine southern coral coast of Kizimkazi Dimbani, Zanzirangi House is an ultra-boutique private sanctuary designed to offer total seclusion, architectural harmony, and intimate Zanzibar hospitality.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
