INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[contact].description', 'Zaplanuj swój pobyt szyty na miarę z naszym zespołem konsjerżów. Niezależnie od tego, czy chodzi o dostępność prywatnej willi, 45-minutowy transfer z lotniska ZNZ, czy indywidualny plan safari w Tanzanii – jesteśmy do dyspozycji 24/7.', 'Plan your bespoke stay with our concierge team. Whether arranging private villa availability, 45-minute airport transfers from ZNZ, or custom Tanzania safari itineraries, we are available 24/7.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
