INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[dining].description', 'Poznaj autentyczne dziedzictwo kulinarne Zanzibaru, łączące przyprawy suahili z owocami morza z Oceanu Indyjskiego, codziennie poławianymi przez rybaków z Kizimkazi z tradycyjnych łodzi dau. Ciesz się prywatnymi posiłkami na werandzie, grillem na plaży i indywidualnymi kolacjami przy świecach pod gwiazdami.', 'Taste authentic Zanzibar culinary heritage blending Swahili spices with Indian Ocean seafood caught daily by Kizimkazi artisanal dhow fishermen. Enjoy private veranda dining, beach barbecues, and bespoke candlelit dinners under the stars.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
