INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[experiences].description', 'Od etycznych spotkań z dzikimi delfinami w Rezerwacie Morskim Menai Bay po prywatne wycieczki po wpisanym na listę UNESCO Stone Town, ekologiczne szlaki przypraw i rejsy łodzią dau o zachodzie słońca – odkryj Zanzibar z naszymi oddanymi prywatnymi przewodnikami.', 'From ethical wild dolphin encounters in the Menai Bay Marine Reserve to private Stone Town UNESCO heritage tours, organic spice trails, and sunset dhow sailing—experience Zanzibar with our dedicated private guides.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
