INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.introText', 'W Zanzirangi House (strona dostępna pod adresem https://zanzirangihouse.com/) ochrona danych osobowych i prywatności naszych gości ma najwyższe znaczenie. Niniejsza Polityka prywatności określa, w jaki sposób gromadzimy, wykorzystujemy i chronimy informacje, gdy odwiedzają Państwo naszą stronę internetową, wysyłają zapytania rezerwacyjne lub kontaktują się z naszym zespołem konsjerżów.', 'At Zanzirangi House (accessible from https://zanzirangihouse.com/), safeguarding our guests’ personal data and privacy is of utmost importance. This Privacy Policy details how we collect, use, and protect information when you visit our website, submit booking inquiries, or communicate with our concierge team.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.lastUpdated', 'Wrzesień 2026', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.sections[#0].body', 'Wysyłając zapytanie lub rezerwując prywatną willę, mogą Państwo podać dane obejmujące imię i nazwisko, adres e-mail, numer telefonu/WhatsApp, daty przyjazdu i wyjazdu, liczbę gości oraz szczególne preferencje dotyczące pobytu lub diety.', 'When submitting an inquiry or reserving a private villa, you may provide details including your full name, email address, telephone/WhatsApp number, arrival/departure dates, guest party size, and special hospitality or dietary preferences.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.sections[#0].title', '1. Informacje, które gromadzimy', '1. Information We Collect', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.sections[#1].items[#0]', 'Obsługa zapytań rezerwacyjnych i sprawdzanie dostępności pokoi.', 'Facilitating reservation inquiries and room availability checks.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.sections[#1].items[#1]', 'Koordynacja transferów z szoferem z Międzynarodowego Portu Lotniczego Abeid Amani Karume (ZNZ).', 'Coordinating airport chauffeur transfers from Abeid Amani Karume International Airport (ZNZ).', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.sections[#1].items[#2]', 'Personalizacja prywatnych posiłków, wycieczek do delfinów oraz połączeń z safari w kontynentalnej Tanzanii.', 'Customizing private dining, marine dolphin tours, and mainland Tanzania safari connections.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.sections[#1].items[#3]', 'Zapewnianie całodobowej komunikacji z osobistym kamerdynerem i konsjerżem.', 'Providing 24/7 personal butler and concierge communications.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.sections[#1].title', '2. W jaki sposób wykorzystujemy Państwa dane', '2. How We Use Your Information', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.sections[#2].body', 'Stosujemy rygorystyczne zabezpieczenia techniczne i organizacyjne. Nie sprzedajemy, nie wynajmujemy ani nie udostępniamy w leasing danych gości komercyjnym sieciom marketingowym podmiotów trzecich. Dane są udostępniane wyłącznie licencjonowanym lokalnym usługodawcom (takim jak oficjalni operatorzy czarterów safari TANAPA) i wyłącznie w celu realizacji uzgodnionego planu podróży.', 'We implement strict technical and administrative safeguards. We do not sell, rent, or lease guest information to third-party commercial marketing networks. Data is shared exclusively with licensed local service providers (such as official TANAPA safari charter operators) strictly to fulfill your agreed itinerary.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.sections[#2].title', '3. Bezpieczeństwo danych i ujawnianie ich podmiotom trzecim', '3. Data Security & Third-Party Disclosure', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.sections[#3].body', 'W sprawie wszelkich zapytań dotyczących prywatności lub w celu złożenia wniosku o usunięcie danych prosimy o bezpośredni kontakt z naszym zespołem ds. ochrony danych pod adresem concierge@zanzirangihouse.com lub pod oficjalnym numerem telefonu +255 777 890 123.', 'For any privacy inquiries or to request data removal, contact our data protection team directly at concierge@zanzirangihouse.com or via official telephone at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].contentJson.sections[#3].title', '4. Kontakt z naszym konsjerżem', '4. Contact Our Concierge', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[privacy].description', 'W Zanzirangi House ochrona danych osobowych i prywatności naszych gości ma najwyższe znaczenie.', 'At Zanzirangi House, safeguarding our guests’ personal data and privacy is of utmost importance.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
