INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[safari].description', 'Połącz bosy luksus na Zanzibarze ze światowej klasy safari na kontynencie. Organizujemy 90-minutowe prywatne loty czarterowe bezpośrednio do Parku Narodowego Serengeti, krateru Ngorongoro i na Kilimandżaro, z pobytem w najlepszych luksusowych obozach safari.', 'Combine your barefoot luxury retreat in Zanzibar with world-class mainland safaris. We coordinate 90-minute private air charters directly to Serengeti National Park, Ngorongoro Crater, and Mount Kilimanjaro with premier luxury safari camps.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[safari].eyebrow', 'WYPRAWY Z PRZELOTEM: BUSZ I PLAŻA • KONTYNENTALNA TANZANIA', 'FLY-IN BUSH & BEACH EXPEDITIONS • TANZANIA MAINLAND', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
