INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[safari].subheading', 'Płynne połączenie buszu i plaży', 'Seamless Bush & Beach Connections', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[safari].title', 'Safari w Tanzanii', 'Tanzania Safari', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[terms].contentJson.introText', 'Witamy w Zanzirangi House. Korzystając z naszej strony internetowej (https://zanzirangihouse.com/) lub wysyłając zapytania dotyczące zakwaterowania i wycieczek, zobowiązują się Państwo do przestrzegania poniższych warunków pobytu i zasad rezerwacji.', 'Welcome to Zanzirangi House. By accessing our website (https://zanzirangihouse.com/) or submitting accommodation and excursion requests, you agree to comply with the following hospitality terms and reservation guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[terms].contentJson.lastUpdated', 'Wrzesień 2026', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[terms].contentJson.sections[#0].body', 'Ceny za noc w willi wynoszą od 390 $ do ponad 480 $ USD i obejmują dostęp do prywatnego basenu, wykwintne śniadanie oraz obsługę osobistego kamerdynera 24/7. Potwierdzenie rezerwacji wymaga wpłaty uzgodnionego depozytu lub przedstawienia vouchera za pośrednictwem oficjalnych kanałów rezerwacyjnych.', 'Nightly villa rates range between $390 and $480+ USD and include private plunge pool access, gourmet breakfast, and 24/7 dedicated butler service. Confirmation requires an agreed deposit or voucher via official reservation channels.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[terms].contentJson.sections[#0].title', '1. Rezerwacje i płatności', '1. Reservations & Payments', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[terms].contentJson.sections[#1].body', 'Standardowe zameldowanie odbywa się od godziny 14:00, a wymeldowanie do godziny 11:00. Wcześniejszy przyjazd lub późniejszy wyjazd można uzgodnić z osobistym konsjerżem, w zależności od dostępności willi.', 'Standard check-in is from 14:00 (2:00 PM), and check-out is by 11:00 (11:00 AM). Early arrival or late departure may be requested through your personal concierge, subject to villa availability.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[terms].contentJson.sections[#1].title', '2. Godziny zameldowania i wymeldowania', '2. Check-In & Check-Out Times', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[terms].contentJson.sections[#2].body', 'Zanzirangi House graniczy z Obszarem Ochrony Przyrody Morskiej Menai Bay. Goście uczestniczący w rejsach łodziami dau i wycieczkach do delfinów zobowiązują się przestrzegać etycznych zasad obcowania z dziką przyrodą, zachowując bezpieczną odległość od zwierząt morskich zgodnie z lokalnymi przepisami o ochronie środowiska.', 'Zanzirangi House borders the Menai Bay Marine Conservation Area. Guests participating in dhow sailing and dolphin excursions agree to follow ethical wildlife protocols, maintaining respectful distances from marine wildlife in compliance with local environmental regulations.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[terms].contentJson.sections[#2].title', '3. Ochrona środowiska morskiego i zasady obcowania z dziką przyrodą', '3. Marine Conservation & Wildlife Etiquette', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[terms].contentJson.sections[#3].body', 'W celu zmiany lub anulowania rezerwacji prosimy o bezpośredni kontakt z naszym konsjerżem drogą e-mailową pod adresem concierge@zanzirangihouse.com lub przez WhatsApp pod numerem +255 777 890 123.', 'To modify or cancel a reservation, contact our concierge directly via email at concierge@zanzirangihouse.com or WhatsApp at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[terms].contentJson.sections[#3].title', '4. Zapytania i anulowanie rezerwacji', '4. Inquiries & Cancellations', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[terms].description', 'Witamy w Zanzirangi House. Korzystając z naszej strony internetowej lub wysyłając zapytania rezerwacyjne, zobowiązują się Państwo do przestrzegania naszych zasad pobytu.', 'Welcome to Zanzirangi House. By accessing our website or submitting reservation requests, you agree to comply with our hospitality guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
