INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'pages', '[villas].description', 'Odkryj nasze 8 prywatnych, rzemieślniczo wykończonych rezydencji o powierzchni od 78 m² do 95 m². Każda willa ma w 100% prywatny basen ze słodką wodą, autentyczną architekturę suahili z kamienia koralowego i osobistego kamerdynera dostępnego 24/7.', 'Discover our 8 private artisanal residences ranging from 78 m² to 95 m². Each villa features a 100% private freshwater plunge pool, authentic Swahili coral-stone architecture, and personalized 24/7 dedicated butler service.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
