INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'safari', '[dest-kilimanjaro].bestFor', 'Ikoniczne widoki z lotu ptaka i wędrówki górskie', 'Iconic aerial perspectives & alpine trekking', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'safari', '[dest-kilimanjaro].description', 'Najwyższy szczyt Afryki i najwyższa wolnostojąca góra świata majestatycznie wznosi się na 5895 metrów ponad tropikalnymi równinami. Od malowniczych prywatnych lotów helikopterem wokół Uhuru Peak po jednodniowe wędrówki bujnymi szlakami niższego lasu deszczowego i plantacjami kawy – poznaj ikoniczną koronę Tanzanii.', 'Africa’s highest peak and the world’s tallest free-standing mountain rises majestically 5,895 meters above tropical plains. From scenic private helicopter flights encircling Uhuru Peak to day treks along lush lower rainforest trails and coffee estates, experience Tanzania’s iconic crown.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'safari', '[dest-kilimanjaro].flightTimeFromZanzibar', '1 h 10 min do międzynarodowego lotniska Kilimandżaro', '1h 10m to Kilimanjaro Int’l', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
