INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'safari', '[dest-ngorongoro].bestFor', 'Geologiczne piękno i niezwykłe zagęszczenie zwierząt', 'Geological splendor & concentrated wildlife density', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'safari', '[dest-ngorongoro].description', 'Największa na świecie nienaruszona kaldera wulkaniczna, tworząca samowystarczalną ekologiczną oazę o głębokości 600 metrów. Zjedź przez spowite mgłą akacjowe lasy na krawędzi krateru do pradawnego amfiteatru tętniącego życiem zagrożonych czarnych nosorożców, hipopotamów i tysięcy różowych flamingów brodzących w jeziorze Magadi.', 'The world’s largest intact volcanic caldera, creating a self-contained ecological haven 600 meters deep. Descend through misty rim acacia forests into an ancient amphitheater bustling with endangered black rhinos, hippos, and thousands of pink flamingos wading in Lake Magadi.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
