INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'safari', '[dest-serengeti].bestFor', 'Wielka Piątka i spektakularne widowiska przyrodnicze', 'Big Five sightings & dramatic wildlife spectacles', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'safari', '[dest-serengeti].description', 'Bezkresne złote sawanny ciągnące się aż po horyzont. Bądź świadkiem, jak miliony gnu i zebr przeprawiają się przez rzeki pełne krokodyli, w towarzystwie stad lwów, samotnych lampartów i luksusowych obozów namiotowych pod usianym gwiazdami równikowym niebem.', 'Vast golden savannahs that stretch endlessly to the horizon. Witness millions of wildebeest and zebras braving crocodile-laden rivers, accompanied by resident prides of lions, solitary leopards, and luxury tented bush retreats under star-strewn equatorial skies.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'safari', '[dest-serengeti].flightTimeFromZanzibar', '1 h 45 min bezpośrednim lotem awionetką', '1h 45m Direct Bush Plane', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
