INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'safari', '[dest-tarangire].bestFor', 'Krajobrazy baobabów i bliskie spotkania ze słoniami', 'Baobab landscapes & intimate elephant encounters', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'safari', '[dest-tarangire].description', 'Słynie z kolosalnych, wiekowych baobabów, które niczym milczący strażnicy stoją w surowej dolinie rzecznej. Tarangire to największe skupisko stad słoni w Afryce Wschodniej – majestatyczne matriarchinie prowadzą tu swoje młode wzdłuż życiodajnej rzeki Tarangire.', 'Famed for its colossal ancient baobab trees that stand like silent sentinels across a rugged river valley. Tarangire hosts East Africa’s highest concentration of elephant herds, where majestic family matriarchs guide their calves along the life-giving Tarangire River.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'safari', '[dest-tarangire].flightTimeFromZanzibar', '1 h 20 min lotu', '1h 20m Flight', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
