INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'testimonials', '[rev-01].reviewText', 'Od chwili, gdy nasz prywatny szofer powitał nas na lotnisku na Zanzibarze, aż po ostatni rejs łodzią dau o zachodzie słońca, każdy szczegół był dopracowany do perfekcji. Basen zawieszony nad oceanicznym przypływem był magiczny.', 'From the moment our private chauffeur welcomed us at Zanzibar Airport to our final sunset dhow sail, every detail was orchestrated to absolute perfection. The plunge pool perched over the ocean tide was magical.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
