INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'testimonials', '[rev-02].reviewText', 'Architektoniczna powściągliwość, wykorzystanie rodzimego kamienia koralowego i troskliwa, a zarazem dyskretna obsługa kamerdynera przypominały nam najlepsze lodże Aman czy Singita. Kolacja z owocami morza w kokosie po suahilijsku była niezapomniana.', 'The architectural restraint, use of indigenous coral stone, and attentive but discrete butler service reminded us of the very finest Aman or Singita lodges. The Swahili coconut seafood dinner was unforgettable.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'testimonials', '[rev-02].stayDate', 'Styczeń 2026', 'January 2026', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
