INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'testimonials', '[rev-03].reviewText', 'Podróżowaliśmy w pięcioosobowej rodzinie. Własny prywatny basen infinity zawieszony nad koralową laguną i osobisty szef kuchni przygotowujący co wieczór świeże połowy na nowo zdefiniowały dla nas znaczenie luksusowych podróży.', 'We traveled as a family of five. Having our own private infinity pool suspended above the coral lagoon and our personal chef preparing fresh catches each evening redefined what luxury travel means to us.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
