INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'testimonials', '[rev-04].reviewText', 'Zabytkowe rzeźbione drzwi z mosiądzem i prywatny basen pływacki tworzyły pogodną atmosferę. Budzenie się przy oceanicznej bryzie i widok dzikich delfinów podczas porannego rejsu łodzią dau to wspomnienie na całe życie.', 'The antique carved brass doors and private lap pool created a serene atmosphere. Waking up to ocean breezes and seeing wild dolphins on the sunrise dhow excursion was a lifelong highlight.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
