INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'testimonials', '[rev-05].reviewText', 'Zejście prosto z tarasu naszej willi do ciepłego, turkusowego Oceanu Indyjskiego było czystą rozkoszą. Serdeczność personelu i dbałość o szczegóły sprawiły, że czuliśmy się w Tanzanii jak honorowi członkowie rodziny.', 'Stepping directly from our villa deck into the warm turquoise Indian Ocean was pure bliss. The staff’s warmth and attention to detail made us feel like honored family in Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'testimonials', '[rev-05].stayDate', 'Październik 2025', 'October 2025', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
