INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'villas', '[villa-01].description', 'Willa Sułtańska nad Oceanem to szczyt bosego luksusu na Zanzibarze. Zainspirowane klasyczną architekturą omańską i morskimi tradycjami suahili sanktuarium urzeka wysokimi drewnianymi stropami, polerowanymi tynkami wapiennymi i rozległymi przeszkleniami od podłogi do sufitu, które zacierają granicę między wnętrzem a Oceanem Indyjskim. Wyjdź na prywatny taras słoneczny z basenem infinity lub odpręż się w rzeźbionej kamiennej wannie, podziwiając wieczorne łodzie dau.', 'The Sultan Oceanfront Villa represents the pinnacle of barefoot luxury in Zanzibar. Inspired by classical Omani architecture and Swahili maritime traditions, this sanctuary features high timber ceilings, polished lime plaster walls, and expansive floor-to-ceiling glass that dissolves the boundary between indoors and the Indian Ocean. Step out onto your private sun deck with an infinity plunge pool, or unwind in the carved stone soak tub overlooking the evening dhows.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
