INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'villas', '[villa-02].shortDescription', 'Ukryta wśród pachnących plumerii i palm kokosowych, zapewnia całkowite odosobnienie, kamienny prysznic pod gołym niebem i spokojną ogrodową werandę.', 'Tucked within fragrant frangipani and coconut palms, offering total seclusion, an open-air stone shower, and serene garden verandah.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
