INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'villas', '[villa-03].description', 'Nadmorska przystań stworzona dla miłośników oceanu. Willa 03 zapewnia bezpośredni, prywatny dostęp do krystalicznie czystych wód południowego Zanzibaru. Meble z litego drewna wykonane na zamówienie, ręcznie tkane lniane narzuty i starannie dobrane afrykańskie rzeźby tworzą atmosferę dyskretnego wyrafinowania. Wyjdź boso na zewnątrz i podziwiaj tradycyjne rybackie łodzie dau sunące przez wschód słońca.', 'A beachfront haven designed for ocean lovers. Villa 03 provides direct, private access to the crystalline waters of southern Zanzibar. Custom hardwood furnishings, hand-loomed linen throws, and curated African sculpture create an atmosphere of understated sophistication. Step outside barefoot to watch traditional fisherman dhows drift across the sunrise.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
