INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'villas', '[villa-04].shortDescription', 'Wyniesiona, by chwytać najlepszą morską bryzę i niczym nieprzesłonięty horyzont, z szeroką panoramiczną werandą idealną do obserwacji delfinów.', 'Elevated for supreme sea breezes and unobstructed horizons, featuring a wide panoramic verandah perfect for dolphin watching.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
