INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'villas', '[villa-05].description', 'Ten przestronny, dwusypialniany pawilon, zbudowany wokół wiekowego, czczonego baobabu, zapewnia wyjątkowy komfort przyjaciołom w podróży i rodzinom. Oferuje zacieniony centralny dziedziniec wypoczynkowy, dwa niezależne główne apartamenty – każdy z własną łazienką pod gołym niebem – oraz prywatną pergolę jadalnianą.', 'Centered around an ancient, revered Baobab tree, this generous two-bedroom pavilion provides exceptional comfort for traveling companions or families. Featuring a shaded central living courtyard, two independent master suites each with their own open-air bathroom, and a private dining pergola.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
