INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'villas', '[villa-06].description', 'Hołd dla złotego wieku rzemiosła na Wyspie Przypraw. Willa 06 zachwyca autentycznymi rzeźbionymi drzwiami nabijanymi mosiądzem, wykonanymi przez mistrzów snycerstwa ze Stone Town, ręcznie wylewanymi posadzkami z lastryko oraz prywatnym, 12-metrowym basenem pływackim ze słodką wodą, otoczonym krzewami goździkowca i trawy cytrynowej.', 'A tribute to the Spice Island’s golden age of artisanal craftsmanship. Villa 06 features authentic brass-studded carved doors from Stone Town master carvers, hand-poured terrazzo floors, and a private 12-meter fresh water lap pool fringed by clove and lemongrass bushes.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
