INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'villas', '[villa-06].shortDescription', 'Hołd dla legendarnej tradycji przyprawowej Zanzibaru: autentyczne rzeźbione drzwi, prywatny basen pływacki i aromatyczny botaniczny dziedziniec.', 'Celebrates Zanzibar’s fabled spice heritage with authentic carved doors, private lap pool, and aromatic botanical courtyard.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
