INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'villas', '[villa-07].description', 'Stworzona z myślą o podróżnikach ceniących design Willa 07 łączy japońsko-skandynawski minimalizm z ziemistym charakterem Afryki Wschodniej. Kojące neutralne barwy, ręcznie tkane dywany z sizalu i ekskluzywny taras widokowy na dachu z leżankami czynią ją przystanią relaksu w blasku księżyca i spokojnej medytacji.', 'Conceived for the design-conscious traveler, Villa 07 fuses Japanese-Scandinavian minimalism with East African earthiness. Soothing neutral tones, hand-woven sisal carpets, and an exclusive rooftop observation deck equipped with daybeds make this a haven for moonlit relaxation and tranquil meditation.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
