INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'villas', '[villa-08].bed', '2 główne apartamenty z łóżkami king size + sypialnia z dwoma łóżkami', '2 King Master Suites + Twin Bedroom', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'villas', '[villa-08].description', 'Najbardziej ekskluzywny adres w posiadłości. Królewska Willa Prezydencka, położona na własnym ustronnym cyplu, zapewnia pełną niezależność, przestronne salony do przyjmowania gości, prywatny basen infinity nad oceanem zawieszony nad koralową laguną, usługi prywatnego szefa kuchni na życzenie oraz bezpośredni dostęp do prywatnej plaży.', 'The estate’s most exclusive address. Set on its own secluded promontory, The Royal Presidential Villa offers total autonomy, expansive entertaining salons, a private oceanfront infinity pool suspended over the coral lagoon, a private chef service on request, and direct private beach access.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'villas', '[villa-08].name', 'Królewska Willa Prezydencka', 'The Royal Presidential Villa', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
