INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'villas', '[villa-08].shortDescription', 'Flagowa rezydencja Zanzirangi House. Niezrównany przepych nad oceanem, wielopoziomowe baseny infinity i dyskretna, prywatna gościnność.', 'The flagship residence of Zanzirangi House. Unparalleled oceanfront grandeur, multi-level infinity pools, and discrete private hosting.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
