INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'eyebrow', 'Wyjątkowość sanktuarium', 'The Sanctuary Difference', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'heading', 'DLACZEGO ZANZIRANGI HOUSE', 'WHY ZANZIRANGI HOUSE', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'pillars[pillar-1].description', 'Ukryte na dziewiczym południowym wybrzeżu Kizimkazi, z dala od turystycznego zgiełku. Tutaj czas odmierzają przypływy i odpływy, szum palm i niczym nieprzesłonięty oceaniczny horyzont.', 'Tucked along the pristine southern coastline of Kizimkazi, far from tourist congestion. Here, time is measured by the tidal ebb and flow, the rustle of palms, and unobstructed ocean horizons.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'pillars[pillar-1].tagline', 'Prywatne sanktuarium z dala od tłumów.', 'A private sanctuary away from the crowds.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'pillars[pillar-1].title', 'PRYWATNIE I SPOKOJNIE', 'PRIVATE & PEACEFUL', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'pillars[pillar-2].description', 'Od mistrzów snycerstwa suahili i wiekowych pawilonów krytych strzechą makuti po ekologiczne przyprawy zbierane codziennie w ogrodach posiadłości – poznaj prawdziwą duszę Wyspy Przypraw.', 'From master Swahili woodcarvers and centuries-old makuti thatched pavilions to organic spices harvested daily from our estate gardens, experience the genuine soul of the Spice Island.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'pillars[pillar-2].tagline', 'Poznaj wyspę poprzez jej ludzi, smaki i kulturę.', 'Experience the island through its people, flavours and culture.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'pillars[pillar-2].title', 'AUTENTYCZNY ZANZIBAR', 'AUTHENTIC ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'pillars[pillar-3].description', 'Oddany gospodarz i zespół konsjerżów, uważni na każdą Twoją potrzebę. Prywatne powitanie przy samolocie, czarterowe rejsy łodzią, posiłki w willi i dyskretna, osobista gościnność na każdym kroku.', 'A dedicated host and concierge team attentive to your every need. Private airport tarmac greetings, chartered boat launches, in-villa dining, and discreet personal hospitality throughout.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'pillars[pillar-3].tagline', 'Od przylotu na lotnisko po planowanie safari.', 'From airport arrival to safari planning.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'pillars[pillar-3].title', 'OSOBISTY KONSJERŻ', 'PERSONAL CONCIERGE', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'pillars[pillar-4].description', 'Płynnie połącz wypoczynek nad oceanem z czarterowymi safari z przelotem do Serengeti, krateru Ngorongoro i Tarangire, tworząc kompletną i niezapomnianą podróż po Afryce Wschodniej.', 'Seamlessly combine oceanfront rest with chartered fly-in bush safaris to the Serengeti, Ngorongoro Crater, and Tarangire, creating a complete and unforgettable East African journey.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'pillars[pillar-4].tagline', 'Połącz pobyt na Zanzibarze z cudami kontynentalnej Tanzanii.', 'Connect your Zanzibar stay with the wonders of mainland Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'pillars[pillar-4].title', 'TANZANIA I DALEJ', 'TANZANIA BEYOND', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('pl', 'whystay', 'subhead', 'Cztery przewodnie wartości określają każdą chwilę w naszym ustroniu, tworząc rzadką atmosferę spokoju, ekskluzywności i głębokiej więzi z Tanzanią.', 'Four guiding values define every moment at our retreat, creating a rare atmosphere of calm, exclusivity, and profound connection to Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:33:21');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'chauffeur', 'airportDesc', 'Mapokezi ya moja kwa moja uwanjani na msaada wa mizigo unapowasili.', 'Direct tarmac welcome and luggage assistance upon arrival.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
