INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'chauffeur', 'subhead', 'Tangu ndege yako inapotua Zanzibar, huduma yetu ya dereva binafsi inahakikisha safari yako hadi Zanzirangi House ni rahisi kabisa, tulivu, na salama.', 'From the moment your flight touches down in Zanzibar, our private chauffeur service ensures your transition to Zanzirangi House is completely effortless, serene, and secure.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'chauffeur', 'vehicleTypeDesc', 'SUV ya Kifahari / Van ya Kifahari (Maelezo yanapatikana kwa ombi)', 'Executive SUV / Luxury Van (Details available on request)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'chauffeur', 'vehicleTypeTitle', 'AINA YA GARI', 'VEHICLE TYPE', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[arabic].description', 'Sherehe ya urithi wa kifalme wa Kiomani wa Zanzibar wa karne nyingi na njia za bahari za Uarabuni. Furahia nyama zenye viungo zilizopikwa taratibu, mikate bapa ya tanuri la udongo, mezze maridadi za baridi na za moto, wali wenye harufu nzuri wa zafarani, na vitamu vya maji ya waridi vilivyoandaliwa na wapishi mahiri.', 'A celebration of Zanzibar’s centuries-old royal Omani heritage and Arabian sea routes. Savor slow-braised spiced meats, clay-oven flatbreads, exquisite cold and hot mezze, fragrant saffron-infused rice dishes, and sweet rosewater delicacies prepared by master chefs.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[arabic].name', 'Mapishi Halisi ya Kiarabu & Kiomani', 'Authentic Arabic & Omani Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[arabic].signatureDishes[#0].description', 'Kondoo laini aliyepikwa taratibu kwa saa 24 na karafuu, iliki, giligilani, ndimu kavu, na majani ya mgomba, akihudumiwa juu ya wali wa Kabsa wa zafarani wenye rangi ya dhahabu na harufu nzuri.', 'Tender lamb slow-cooked for 24 hours with cloves, cardamom, coriander, dry lime, and banana leaves, served over fragrant golden saffron Kabsa rice.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[arabic].signatureDishes[#0].name', 'Shuwa ya Kiomani: Kondoo wa Viungo Aliyechomwa Taratibu', 'Omani Shuwa Spiced Slow-Roasted Lamb', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[arabic].signatureDishes[#1].description', 'Hummus laini iliyomiminiwa komamanga, Mutabal yenye ladha ya moshi, falafel za mimea zinazokwaruza, na mikate bapa ya Kiarabu iliyotengenezwa kwa mkono na kuokwa kwa kuni.', 'Velvety pomegranate-drizzled hummus, smoky Mutabal, crispy herbed falafel, and handmade wood-fired Arabic flatbreads.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[arabic].signatureDishes[#1].name', 'Mezze ya Kifalme & Khubz Mbichi ya Za’atar', 'Royal Mezze & Fresh Za’atar Khubz', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[arabic].signatureDishes[#2].description', 'Kamba wakubwa wa Ghuba ya Menai, ngisi, na samaki wa miambani waliochomwa kwa mkaa na kukolezwa kwa pilipili ya Aleppo, sumac, kitunguu saumu, na mimea pori.', 'Charcoal-grilled Menai Bay jumbo prawns, calamari, and reef catch seasoned with Aleppo pepper, sumac, garlic, and wild herbs.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[arabic].signatureDishes[#2].name', 'Sahani ya Mashwi ya Vyakula vya Baharini & Ndimu Zilizochomwa', 'Mashwi Seafood & Charred Lime Platter', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[arabic].signatureDishes[#3].description', 'Tabaka laini za filo zilizopangwa pamoja na pistachio zilizokaangwa na sharubati ya iliki na maua ya mchungwa, zikiambatana na pudini baridi ya maziwa yenye maji ya waridi.', 'Delicate flaky filo pastry layered with toasted pistachios and orange-blossom cardamom syrup alongside chilled rosewater milk pudding.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[arabic].signatureDishes[#3].name', 'Baklava ya Pistachio ya Moto & Muhallabia ya Maji ya Waridi', 'Warm Pistachio Baklava & Rosewater Muhallabia', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[arabic].subtitle', 'Urithi wa Kifalme wa Kiomani, Nyama za Kuchoma kwa Tanuri la Udongo & Mezze ya Mashariki ya Kati', 'Royal Omani Heritage, Clay-Oven Grills & Middle Eastern Mezze', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[arabic].tabLabel', 'Kiarabu', 'Arabic', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[beverages].description', 'Mpango wa vinywaji wa hadhi ya juu ulioandaliwa kwa starehe ya kitropiki. Furahia mvinyo wa ghalani wa kiwango cha dunia, juisi safi za kitropiki za Zanzibar zilizokamuliwa kwa baridi, vinywaji baridi vya mimea vilivyotengenezwa nyumbani, na maji bora ya madini yanayohudumiwa ufukweni au kando ya bwawa.', 'An elevated beverage program curated for tropical indulgence. Enjoy world-class cellar vintages, pure cold-pressed Zanzibar tropical juices, house-crafted botanical soft drinks, and premium pristine mineral waters served beachfront or poolside.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[beverages].name', 'Vinywaji, Ghala la Mvinyo & Viburudisho', 'Beverages, Cellar & Refreshments', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[beverages].signatureDishes[#0].description', 'Mikusanyiko ya Ulimwengu wa Kale na Mpya, Chenin Blanc & Sauvignon Blanc safi za Afrika Kusini, Shampeni maridadi za Kifaransa, na mvinyo mwekundu mzito wa Tuscany & Bordeaux.', 'Old and New World collections, crisp South African Chenin Blanc & Sauvignon Blanc, elegant French Champagnes, and full-bodied Tuscan & Bordeaux reds.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[beverages].signatureDishes[#0].name', 'Mvinyo Teule wa Ghalani & Shampeni (Mvinyo)', 'Curated Cellar Wines & Champagne (Wines)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[beverages].signatureDishes[#1].description', 'Pasheni zilizoiva juani, embe tamu la Alfonso, nanasi lililopondwa na nanaa mbichi, na maji ya dafu changa moja kwa moja kutoka mashamba ya minazi ya pwani.', 'Sun-ripened passion fruit, sweet Alfonso mango, crushed pineapple with fresh mint, and young King coconut water straight from coastal palm groves.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[beverages].signatureDishes[#1].name', 'Nekta za Kitropiki za Zanzibar Zilizokamuliwa kwa Baridi (Juisi)', 'Cold-Pressed Zanzibar Tropical Nectars (Juice)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[beverages].signatureDishes[#2].description', 'Bia ya tangawizi kali iliyotengenezwa nyumbani pamoja na mchaichai uliopondwa, kinywaji baridi cha hibiscus cha Kitanzania chenye gesi, tonic za mimea za kitamaduni, na soda za kawaida zenye barafu.', 'House-brewed fiery ginger beer with crushed lemongrass, sparkling Tanzanian hibiscus cooler, craft botanical tonics, and classic iced sodas.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[beverages].signatureDishes[#2].name', 'Soda & Tonic za Mimea za Kitamaduni (Vinywaji Baridi)', 'Artisanal Botanical Sodas & Tonics (Soft Drinks)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[beverages].signatureDishes[#3].description', 'Maji bora ya chemchemi ya Ulaya & Afrika Mashariki, ya kawaida na yenye gesi, yanayohudumiwa yakiwa baridi kabisa pamoja na tango bichi la bustanini, nanaa, na ndimu ya Makunduchi.', 'Still and sparkling premium European & East African spring waters served crystal chilled with fresh garden cucumber, mint, and Makunduchi lime.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[beverages].signatureDishes[#3].name', 'Maji Safi ya Madini (Maji)', 'Pristine Mineral Waters (Waters)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[beverages].subtitle', 'Mvinyo Bora wa Ghalani, Juisi Safi, Vinywaji Baridi & Maji ya Madini', 'Fine Cellar Wines, Fresh Juices, Soft Drinks & Mineral Waters', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[beverages].tabLabel', 'Vinywaji', 'Beverages', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[fusion].description', 'Saini yetu ya mapishi. Mazungumzo ya kibunifu kati ya mbinu za jadi za Kifaransa na utajiri wa ajabu wa viungo wa Zanzibar. Tarajia michanganyiko yenye upatano kama siagi ya kamba-mti iliyotiwa vanila, michuzi mizito ya ukwaju, na soufflé za pasheni.', 'Our culinary signature. An imaginative dialogue between classical French technique and Zanzibar’s extraordinary spice terroir. Expect harmonious pairings like vanilla bean infused lobster butter, tamarind reductions, and passion fruit soufflés.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[fusion].name', 'Mchanganyiko wa Kisasa wa Kiswahili', 'Swahili Contemporary Fusion', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[fusion].signatureDishes[#0].description', 'Kamba-mti mtamu na laini aliyepikwa kwa siagi safi ya Kifaransa yenye harufu ya vijiti vya vanila ya Pemba, pamoja na emulsion ya viazi vitamu na asparagasi ya baharini.', 'Sweet succulent lobster poached in clarified French butter scented with fragrant Pemba vanilla pods, sweet potato emulsion, and sea asparagus.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[fusion].signatureDishes[#0].name', 'Kamba-Mti Aliyepikwa kwa Siagi na Vanila ya Pemba', 'Butter-Poached Rock Lobster with Pemba Vanilla', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[fusion].signatureDishes[#1].description', 'Kidari cha bata cha Magret chenye ngozi inayokwaruza, kinachohudumiwa kikiwa kimeiva nusu, pamoja na mng\'ao wa ua la hibiscus wenye uchachu, karoti changa zilizookwa, na puree ya muhogo yenye viungo.', 'Crispy skin Magret duck breast served medium rare with a tart hibiscus flower glaze, roasted baby carrots, and spiced cassava purée.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[fusion].signatureDishes[#1].name', 'Kidari cha Bata Kilichokaangwa na Ukwaju & Hibiscus', 'Seared Duck Breast with Tamarind & Hibiscus', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[fusion].signatureDishes[#2].description', 'Keki ya chokoleti nzito ya 70% inayoyeyuka ndani, yenye harufu ya iliki mbichi, ikihudumiwa na gelato ya nazi iliyotengenezwa nyumbani na coulis ya pasheni.', 'Molten dark 70% chocolate cake perfumed with green cardamom, served with house-spun coconut gelato and passionfruit coulis.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[fusion].signatureDishes[#2].name', 'Fondant ya Chokoleti ya Valrhona & Iliki ya Zanzibar', 'Valrhona Chocolate & Zanzibar Cardamom Fondant', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[fusion].subtitle', 'Kisiwa cha Kitropiki Kinapokutana na Mapishi ya Kisasa ya Kifaransa ya Hadhi ya Juu', 'Where Tropical Island Meets Modern French Haute Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[fusion].tabLabel', 'Mchanganyiko', 'Fusion', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[local].description', 'Karne za biashara ya baharini ya Waarabu, Waajemi, Wahindi na Waafrika Mashariki zilikutana katika majiko ya pwani ya Zanzibar. Wapishi wetu wakuu huandaa mapishi ya jadi yaliyodumu vizazi kwa tui la nazi lililokunwa sasa hivi, iliki yenye harufu nzuri, karafuu kutoka Pemba, na vyakula vya baharini vilivyovuliwa kwa ndoana na kuletwa moja kwa moja ufukweni kwetu.', 'Centuries of Arab, Persian, Indian, and East African maritime trade converged in Zanzibar’s coastal kitchens. Our executive chefs prepare time-honored recipes featuring freshly harvested coconut milk, aromatic cardamom, cloves from Pemba, and line-caught seafood brought straight to our shores.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[local].name', 'Mapishi Halisi ya Kiswahili', 'Authentic Swahili Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[local].signatureDishes[#0].description', 'Changu wa miambani aliyekaangwa kisha kupikwa taratibu na giligilani mbichi, manjano iliyosagwa kwa jiwe, na tui la nazi la pwani lililokamuliwa kwa mkono, akihudumiwa na wali wa zafarani.', 'Pan-seared wild reef snapper simmered with fresh green coriander, stone-ground turmeric, and hand-squeezed coastal coconut milk served with saffron rice.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[local].signatureDishes[#0].name', 'Changu wa Miamba ya Zanzibar kwa Nazi & Manjano', 'Zanzibari Coral Reef Snapper in Coconut & Turmeric', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[local].signatureDishes[#1].description', 'Supu ya embe na ukwaju yenye uchachu mtamu iliyopikwa taratibu, pamoja na kamba laini, chipsi za muhogo zenye viungo, na sambal ya nazi na pilipili iliyopondwa.', 'A tangy, slow-simmered mango and tamarind broth with tender prawns, spiced cassava crisps, and crushed chili coconut sambal.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[local].signatureDishes[#1].name', 'Urojo wa Kitanzania & Mchuzi wa Kamba Wakubwa', 'Tanzanian Urojo & Tiger Prawn Stew', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[local].signatureDishes[#2].description', 'Nyama ya kondoo wa kienyeji iliyoiva hadi kuwa laini kabisa, iliyokolezwa kwa nyota ya anise, vijiti vya mdalasini, na iliki nyeusi, ikiambatana na kachumbari.', 'Fork-tender local lamb infused with star anise, cinnamon quills, and black cardamom, accompanied by pickled kachumbari salad.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[local].signatureDishes[#2].name', 'Mbuzi Aliyepikwa Taratibu kwa Viungo vya Pilau', 'Slow-Braised Goat with Pilau Spices', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
