INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[western].description', 'Imebuniwa kwa ladha za kimataifa zinazotafuta vyakula vinavyozoeleka na kuliwaza, vilivyoandaliwa kwa mbinu za hali ya juu kabisa za mlo wa kifahari. Vipande bora vya nyama ya ng\'ombe kutoka nje, saladi safi za Mediterania, pasta iliyotengenezwa nyumbani kwa mkono, na vitindamlo vya kuvutia vilivyoandaliwa kwa ustadi kamili wa mapishi.', 'Designed for international palates seeking comforting familiarity prepared with the highest fine-dining techniques. Prime imported beef cuts, fresh Mediterranean salads, homemade handmade pasta, and decadent desserts executed with crisp culinary precision.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[western].name', 'Mapishi ya Kisasa ya Kimagharibi', 'Modern Western Gastronomy', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[western].signatureDishes[#0].description', 'Imechomwa kwa ukamilifu juu ya moto, ikiambatana na mousseline laini ya parsnip, nyanya za tawi zilizochomwa, na jus ya mvinyo mwekundu iliyopikwa kwa saa 24.', 'Char-grilled to perfection, paired with smooth parsnip mousseline, blistered vine tomatoes, and a 24-hour reduced red wine jus.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[western].signatureDishes[#0].name', 'Nyama Laini ya Wagyu yenye Mng\'ao wa Truffle', 'Prime Wagyu Tenderloin with Truffle Glaze', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[western].signatureDishes[#1].description', 'Jodari wa kienyeji aliyevuliwa kwa ndoana na kukatwa vipande vidogo pamoja na parachichi la Hass, mafuta ya zeituni yaliyokamuliwa kwa baridi, matunda ya caper, na chipsi za mkate wa sourdough uliookwa nyumbani.', 'Line-caught local tuna diced with Hass avocado, cold-pressed olive oil, caper berries, and house-baked sourdough crisps.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[western].signatureDishes[#1].name', 'Tartare ya Jodari Pori wa Yellowfin na Parachichi', 'Wild Yellowfin Tuna Tartare with Avocado', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[western].signatureDishes[#2].description', 'Pasta mbichi ya mayai iliyochanganywa na mkia mtamu wa kamba-mti wa Kizimkazi, kitunguu saumu cha confit, nyanya ndogo za cherry, na bisque nyepesi ya Pinot Grigio.', 'Fresh egg pasta tossed with sweet Kizimkazi rock lobster tail, garlic confit, baby cherry tomatoes, and a light Pinot Grigio bisque.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'categories[western].signatureDishes[#2].name', 'Tagliolini ya Kutengenezwa kwa Mkono na Kamba-Mti', 'Handmade Tagliolini with Rock Lobster', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
