INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'eyebrow', 'Roho ya Mapishi', 'Gastronomic Soul', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'gardenBadge', 'Bustani Yetu', 'Estate Garden', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'gardenDesc', 'Ndani ya viunga vya Zanzirangi House kuna bustani yetu binafsi ya mimea, ambapo timu yetu ya jikoni hulima kwa njia asilia mchaichai, pilipili mbichi, basil pori, nanaa tamu, iliki yenye harufu nzuri, na mboga za msimu. Kinachovunwa asubuhi huunda moja kwa moja menyu zetu za kila siku, kikiunganisha uhai wa ardhini na samaki wabichi wa maji ya kusini mwa Zanzibar.', 'Tucked within the grounds of Zanzirangi House is our private botanical garden, where our kitchen team cultivates organic lemongrass, green chilies, wild basil, sweet mint, fragrant cardamom, and seasonal vegetables. What is harvested in the morning directly shapes our daily tasting menus, pairing earth-grown vitality with the fresh catch of southern Zanzibar’s waters.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'gardenEyebrow', 'Simulizi za Mapishi', 'Culinary Storytelling', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'gardenTitle', 'KUTOKA BUSTANI YETU HADI MEZANI KWAKO', 'FROM OUR GARDEN TO YOUR TABLE', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'heading', 'ONJA ZANZIBAR', 'TASTE ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'intro', 'Karne za biashara ya baharini ya Waswahili, Waomani na Bahari ya Hindi hukutana kwenye meza zetu. Kuanzia samaki waliovuliwa kwa ndoana na kuletwa ufukweni alfajiri hadi michuzi ya viungo iliyopikwa taratibu, kula katika Zanzirangi House ni safari halisi ya hisia.', 'Centuries of Swahili, Omani, and Indian Ocean sea trade come together at our tables. From line-caught fish brought ashore at sunrise to slow-simmered aromatic curries, dining at Zanzirangi House is an authentic sensory journey.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'moments[#0].desc', 'Papai la kitropiki, krimu ya pasheni, brioche moto iliyookwa sasa hivi, na kahawa ya Kitanzania yenye viungo, vikihudumiwa ukitazama bahari ya asubuhi.', 'Tropical papaya, passion fruit curds, warm freshly-baked brioche, and spiced Tanzanian coffee served overlooking the morning ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'moments[#0].time', '07:00 – 10:30 Asubuhi', '07:00 – 10:30 AM', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'moments[#0].title', 'Kifungua Kinywa Maalum', 'Artisanal Breakfast', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'moments[#1].desc', 'Tartare ya jodari wa yellowfin aliyevuliwa kwa ndoana, saladi za kamba-mti, mikate bapa iliyookwa kwa kuni, na maji ya dafu changa chini ya minazi.', 'Line-caught yellowfin tuna tartare, rock lobster salads, wood-fired flatbreads, and young King coconut water under the palms.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
