INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'moments[#2].desc', 'Chipsi za ndizi zinazokwaruza, kamba wa ukwaju wenye viungo, mvinyo wa ghalani, na kokteli za mimea zilizotengenezwa kwa mkono huku upeo wa bahari ukigeuka zambarau.', 'Crisp plantain crisps, spiced tamarind prawns, cellar wines, and handcrafted botanical cocktails as the ocean horizon turns violet.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'moments[#2].time', '05:30 – 07:00 Jioni', '05:30 – 07:00 PM', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'moments[#2].title', 'Vitafunio vya Machweo & Taarab', 'Sunset Tapas & Taarab', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'moments[#3].desc', 'Mchuzi wa nazi wa Kizanzibari uliopikwa taratibu, nyama ya kondoo iliyopikwa kwa viungo vya Kiomani, na keki za fondant za chokoleti ya Valrhona na iliki.', 'Slow-simmered Zanzibari coconut curries, Omani spiced braised lamb, and Valrhona chocolate cardamom fondants.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'moments[#3].time', '07:30 – 10:30 Usiku', '07:30 – 10:30 PM', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
