INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'moments[#4].desc', 'Banda la wazi la kulia chakula lenye paa la makuti linalopokea upepo baridi mtambuka wa Ghuba ya Menai.', 'Open-air makuti thatched dining pavilion capturing the cool cross-breezes of Menai Bay.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
