INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'subhead', '\"Viungo vibichi, ladha za kisiwani na ukarimu halisi wa Kitanzania.\"', '\"Fresh ingredients, island flavours and authentic Tanzanian hospitality.\"', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'tagSeafood', '🐟 Vyakula vya Baharini vya Pwani kwa Njia Endelevu', '🐟 Sustainable Coastal Seafood', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
