INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'dining', 'tagZeroMiles', '🌱 Chakula cha Hapa Hapa', '🌱 Zero Food Miles', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-cultural].description', 'Tembelea makazi ya kihistoria ya wavuvi wa Kizimkazi na Msikiti wa kale wa Dimbani (wa mwaka 1107 BK). Kutana na mafundi mahiri wa kienyeji wanaochonga majahazi ya jadi kwa mkono, shiriki katika warsha ya mapishi ya Kiswahili, au furahia muziki binafsi wa taarab wa fidla na kanun chini ya nyota za usiku.', 'Visit the historic Kizimkazi fishing settlement and the ancient Dimbani Mosque (dating to 1107 AD). Meet local master craftsmen carving traditional dhows by hand, participate in a Swahili culinary workshop, or enjoy private taarab violin and kanun music under the night stars.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-cultural].duration', 'Saa 3.5 (Muda Unaopangwa Kwako)', '3.5 Hours (Custom Timing)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-cultural].priceNote', 'Bei kwa Ombi', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-cultural].shortDescription', 'Jumuika kwa dhati na mafundi wa pwani, jifunze kusuka makuti na kukarabati majahazi, na ugundue urithi wa kale wa Kiswahili.', 'Engage authentically with local coastal artisans, learn palm-weaving and dhow restoration, and discover ancient Swahili heritage.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-cultural].tag', 'Uzoefu wa Kitamaduni', 'Cultural Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-cultural].title', 'Mila za Kiswahili, Taarab & Maisha ya Kijijini', 'Swahili Traditions, Taarab & Village Life', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-cultural].whatsappMessage', 'Habari timu ya huduma kwa wageni ya Zanzirangi House, ningependa kujua zaidi kuhusu uzoefu wa kitamaduni wa Kiswahili.', 'Hello Zanzirangi House Concierge, I would like to learn more about Swahili Cultural Experiences.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-dolphins].description', 'Mahali petu Kizimkazi, kwenye pwani ya kusini ya Zanzibar, panatoa njia ya moja kwa moja hadi hifadhi ya pomboo maarufu zaidi Afrika Mashariki. Ondoka alfajiri kwa jahazi binafsi au boti ya injini kuwatazama makundi ya pomboo wakicheza katika makazi yao asilia baharini, kabla ya kufurahia kifungua kinywa ukirejea kwetu.', 'Our location in Kizimkazi on Zanzibar’s southern coast provides direct access to East Africa’s most famous dolphin sanctuary. Depart at dawn on a private dhow or motor launch to watch dolphin pods playing in their natural ocean habitat before enjoying breakfast back at the property.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-dolphins].duration', 'Saa 3.5 (Safari ya Alfajiri)', '3.5 Hours (Early Morning Dawn Cruise)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-dolphins].priceNote', 'Bei kwa Ombi', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-dolphins].shortDescription', 'Anza safari wakati wa mapambazuko kutoka Kizimkazi kuingia maji yaliyohifadhiwa ya Ghuba ya Menai kushuhudia makundi ya pomboo wakazi wa aina ya spinner na bottlenose.', 'Set sail at sunrise from Kizimkazi into the protected waters of Menai Bay to witness pods of resident spinner and bottlenose dolphins.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-dolphins].tag', 'Uzoefu wa Pomboo', 'Dolphin Experience', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-dolphins].title', 'Kukutana na Pomboo Pori wa Kizimkazi', 'Kizimkazi Wild Dolphin Encounter', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-dolphins].whatsappMessage', 'Habari timu ya huduma kwa wageni ya Zanzirangi House, ningependa kushiriki ziara ya Kukutana na Pomboo Pori wa Kizimkazi.', 'Hello Zanzirangi House Concierge, I would like to experience the Kizimkazi Wild Dolphin Encounter.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-fishing].description', 'Ukiwa ndani ya boti yetu ya kukodi ya uvuvi wa bahari kuu yenye milingoti ya pembeni ya kuvulia, zana za Shimano, na vifaa vya kisasa vya kielektroniki vya baharini, pata msisimko wa uvuvi wa samaki wakubwa katika mikondo ya kina ya Bahari ya Hindi. Tunafuata kikamilifu utaratibu wa kuvua na kuachia kwa samaki wenye pua ndefu.', 'Aboard our chartered offshore sportfisher equipped with outriggers, Shimano tackle, and modern nautical electronics, experience the adrenaline of big game fishing in the deep currents of the Indian Ocean. Strictly adheres to catch-and-release protocols for billfish.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-fishing].duration', 'Nusu Siku (Saa 5) au Siku Nzima (Saa 8)', 'Half Day (5 Hours) or Full Day (8 Hours)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-fishing].priceNote', 'Bei kwa Ombi', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-fishing].shortDescription', 'Ingia ndani ya mikondo ya kina ya Pemba na Zanzibar kwa uvuvi wa kimichezo wa kiwango cha dunia, ukiwalenga jodari wa yellowfin, samaki wa matanga, na wahoo.', 'Venture into the deep Pemba and Zanzibar channels for world-class sport fishing targeting yellowfin tuna, sailfish, and wahoo.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-fishing].tag', 'Uvuvi wa Bahari Kuu', 'Deep Sea Fishing', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-fishing].title', 'Uvuvi wa Kimichezo wa Samaki Wakubwa Bahari Kuu', 'Deep Sea Big Game Sport Fishing', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-fishing].whatsappMessage', 'Habari timu ya huduma kwa wageni ya Zanzirangi House, ningependa kupata maelezo kuhusu safari za uvuvi wa kimichezo wa bahari kuu.', 'Hello Zanzirangi House Concierge, I would like details on Deep Sea Sport Fishing trips.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-island-hopping].description', 'Panga njia yako mwenyewe kupitia maji ya samawati ya kusini na magharibi mwa Zanzibar. Shuka kwenye mafungu ya mchanga mweupe laini yanayoibuka tu wakati wa maji kupwa, ogelea katika maji ya joto yaliyo maangavu, na ufurahie chakula cha mchana kilichoandaliwa papo hapo cha kamba-mti wa Ghuba ya Menai waliochomwa, ngisi, na matunda ya kitropiki.', 'Chart your own course across the turquoise waters of southern and western Zanzibar. Disembark onto ephemeral powder-white sandbanks that emerge only at low tide, swim in warm crystalline waters, and savor a freshly prepared lunch of grilled Menai Bay lobster, calamari, and tropical fruit.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-island-hopping].duration', 'Siku Nzima (Boti Binafsi ya Mwendo Kasi)', 'Full Day (Private Speedboat)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-island-hopping].priceNote', 'Bei kwa Ombi', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-island-hopping].shortDescription', 'Safiri hadi visiwa vidogo vya matumbawe visivyokaliwa na watu, ogelea katika maziwa ya bahari yaliyo tulivu, na ufurahie chakula cha mchana cha vyakula vya baharini vilivyochomwa kwenye fungu binafsi la mchanga.', 'Cruise to secluded uninhabited coral islets, swim in deserted tidal lagoons, and enjoy a grilled seafood lunch on a private sandbank.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-island-hopping].tag', 'Safari za Visiwani', 'Island Hopping', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-island-hopping].title', 'Safari Binafsi za Visiwani & Fungu la Mchanga', 'Private Island Hopping & Sandbank Safari', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-island-hopping].whatsappMessage', 'Habari timu ya huduma kwa wageni ya Zanzirangi House, ningependa kuuliza kuhusu Safari Binafsi za Visiwani na Fungu la Mchanga.', 'Hello Zanzirangi House Concierge, I would like to inquire about the Private Island Hopping Sandbank Safari.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-mnemba].description', 'Kikiwa karibu na pwani ya kaskazini-mashariki ya Zanzibar, Kisiwa cha Mnemba kinatambulika duniani kote kwa hali yake safi ya chini ya bahari. Furahia usafiri binafsi wa boti, kuzamia kwa kipekee juu ya vilele vya matumbawe, na pikniki ya kifahari ufukweni iliyoandaliwa na mpishi wetu binafsi.', 'Located off Zanzibar’s northeast coast, Mnemba Atoll is recognized globally for its pristine underwater conditions. Enjoy private boat transfers, exclusive snorkeling over coral pinnacles, and a beachside gourmet picnic arranged by our private chef.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-mnemba].duration', 'Safari Binafsi ya Siku Nzima', 'Full Day Private Expedition', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-mnemba].priceNote', 'Bei kwa Ombi', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-mnemba].shortDescription', 'Safiri hadi kito cha thamani cha hifadhi za bahari za Zanzibar: maji ya samawati angavu yasiyo na mfano, bustani safi za matumbawe, na maziwa ya bahari yenye kasa.', 'Sail to the crown jewel of Zanzibar marine reserves: unmatched turquoise clarity, pristine coral gardens, and sea turtle lagoons.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-mnemba].tag', 'Kisiwa cha Mnemba', 'Mnemba Island', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-mnemba].title', 'Hifadhi ya Kifahari ya Bahari ya Mnemba', 'Mnemba Atoll Luxury Marine Sanctuary', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-mnemba].whatsappMessage', 'Habari timu ya huduma kwa wageni ya Zanzirangi House, ningependa kuweka nafasi ya safari ya Hifadhi ya Bahari ya Kisiwa cha Mnemba.', 'Hello Zanzirangi House Concierge, I would like to book the Mnemba Island Marine Sanctuary expedition.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-nature-jozani].description', 'Ukiongozwa na mtaalamu wa maumbile aliyeidhinishwa wa hifadhi ya taifa, safiri ndani ya misitu ya kale ya miti migumu iliyohifadhiwa ndani ya Hifadhi ya Taifa ya Jozani Chwaka Bay. Tazama makundi ya kima wakirukaruka kwenye vilele vya miti, tembea kwenye njia ya mbao iliyoinuliwa katikati ya mikoko, na ujifunze kuhusu mimea adimu inayopatikana Zanzibar pekee.', 'Led by an authorized national park naturalist, journey into ancient hardwood forests protected within Jozani Chwaka Bay National Park. Observe monkey troops swinging through the canopy, walk the elevated mangrove boardwalk, and learn about the rare flora unique to Zanzibar.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-nature-jozani].duration', 'Saa 4 (Asubuhi Inapendekezwa)', '4 Hours (Morning Recommended)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-nature-jozani].priceNote', 'Bei kwa Ombi', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-nature-jozani].shortDescription', 'Tembea ndani ya msitu asilia wa mikangazi unaostawi kwa maji ya ardhini ukutane na Kima Punju wa Zanzibar, mnyama mchangamfu anayepatikana hapa pekee.', 'Trek through virgin groundwater mahogany forest to encounter the playful, endemic Zanzibar Red Colobus monkey.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-nature-jozani].tag', 'Uzoefu wa Kimaumbile', 'Nature Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-nature-jozani].title', 'Msitu wa Jozani & Hifadhi ya Kima Punju', 'Jozani Forest & Red Colobus Eco-Sanctuary', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-nature-jozani].whatsappMessage', 'Habari timu ya huduma kwa wageni ya Zanzirangi House, ningependa kuweka nafasi ya ziara ya kimaumbile katika Msitu wa Jozani.', 'Hello Zanzirangi House Concierge, I would like to reserve the Jozani Forest Nature Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-snorkeling-diving].description', 'Miamba ya matumbawe ya Zanzibar imejaa viumbe hai vya kitropiki. Ukiwa na vifaa bora vya kitaalamu na kuambatana na wakuu wa mbizi wa PADI waliothibitishwa, gundua miteremko ya kuvutia chini ya bahari, mapango ya kupita ukiogelea, na uwazi wa maji unaofikia hadi mita 30.', 'Zanzibar’s barrier reefs are teeming with tropical biodiversity. Equipped with top-tier professional gear and accompanied by certified PADI divemasters, discover stunning drop-offs, swim-through caves, and crystal visibility extending up to 30 meters.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-snorkeling-diving].duration', 'Matembezi ya Nusu Siku au Siku Nzima', 'Half Day or Full Day Excursion', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-snorkeling-diving].priceNote', 'Bei kwa Ombi', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-snorkeling-diving].shortDescription', 'Gundua bustani za matumbawe zenye rangi angavu na kuta za chini ya bahari, na ukutane na kasa, taa wenye madoa, na samaki wa ajabu wa miambani.', 'Explore vibrant coral gardens, underwater marine walls, and meet sea turtles, spotted eagle rays, and exotic reef species.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-snorkeling-diving].tag', 'Kuzamia & Kupiga Mbizi', 'Snorkeling & Diving', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-snorkeling-diving].title', 'Kuzamia Miambani & Kupiga Mbizi kwa Kina', 'Coral Reef Snorkeling & Deep Scuba Diving', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-snorkeling-diving].whatsappMessage', 'Habari timu ya huduma kwa wageni ya Zanzirangi House, ningependa kupanga safari ya kuzamia na kupiga mbizi.', 'Hello Zanzirangi House Concierge, I would like to arrange a Snorkeling & Diving excursion.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-spice-farm].description', 'Tembea pamoja na wataalamu wa mimea wa kienyeji kupitia mashamba ya vijijini yaliyostawi. Gusa, nusa, na uonje viungo moja kwa moja kutoka mitini na mitamba—ikiwemo pilipili manga, kungumanga, tangawizi, mchaichai, na manjano—na kuhitimisha kwa maji ya dafu changa yaliyochumwa juu kabisa ya minazi.', 'Walk alongside expert local botanists through verdant rural plantations. Touch, smell, and taste raw spices directly from the trees and vines—including black pepper, nutmeg, ginger, lemongrass, and turmeric—concluding with fresh King coconut water harvested high in the canopy.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-spice-farm].duration', 'Saa 4 (Asubuhi au Mchana)', '4 Hours (Morning or Afternoon)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-spice-farm].priceNote', 'Bei kwa Ombi', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-spice-farm].shortDescription', 'Zamisha hisia zako katika karne za historia yenye harufu nzuri: chuma mdalasini mbichi, ponda iliki mbichi, na uonje vanila pori.', 'Immerse your senses in centuries of aromatic history: pluck fresh cinnamon, crush green cardamom, and taste wild vanilla bean.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-spice-farm].tag', 'Shamba la Viungo', 'Spice Farm', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-spice-farm].title', 'Safari ya Shamba la Viungo Asilia', 'Organic Botanical Spice Farm Journey', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-spice-farm].whatsappMessage', 'Habari timu ya huduma kwa wageni ya Zanzirangi House, ninavutiwa na Safari ya Shamba la Viungo Asilia.', 'Hello Zanzirangi House Concierge, I am interested in the Organic Botanical Spice Farm Journey.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-stonetown].description', 'Safari binafsi kupitia Mji Mkongwe, Eneo la Urithi wa Dunia la UNESCO. Ukiongozwa na mwanahistoria mkazi wa Kiswahili, gundua Beit al-Ajaib (Nyumba ya Maajabu), Ngome Kongwe ya karne ya 17, Kanisa Kuu la Kianglikana na kumbukumbu ya Soko la Watumwa la Zamani, pamoja na karakana za mafundi wa vito vya fedha na nguo za kufuma.', 'A private journey through UNESCO World Heritage Stone Town. Led by a resident Swahili historian, explore the House of Wonders, the 17th-century Old Fort, the Anglican Cathedral and Old Slave Market memorial, and artisan workshops specializing in silver jewelry and woven textiles.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-stonetown].duration', 'Siku Nzima (Dereva Binafsi & Mwongozaji)', 'Full Day (Private Chauffeur & Guide)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-stonetown].priceNote', 'Bei kwa Ombi', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-stonetown].shortDescription', 'Tembea kupitia vichochoro vinavyopindapinda vya mawe ya matumbawe, milango ya msaji iliyonakshiwa kwa mtindo wa Kiomani, masoko ya kihistoria ya viungo, na Kasri la Sultani.', 'Walk through labyrinthine coral ragstone alleyways, ornate Omani carved teak doors, historical spice bazaars, and the Sultan’s Palace.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-stonetown].tag', 'Utamaduni & Urithi', 'Culture & Heritage', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-stonetown].title', 'Urithi wa Mji Mkongwe & Mitaa ya Kihistoria', 'Stone Town Heritage & Historic Quarters', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-stonetown].whatsappMessage', 'Habari timu ya huduma kwa wageni ya Zanzirangi House, ningependa kuweka nafasi ya ziara binafsi ya Urithi wa Mji Mkongwe.', 'Hello Zanzirangi House Concierge, I am interested in booking the private Stone Town Heritage Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-sunset-cruise].description', 'Panda jahazi la Kiswahili la matanga lililotengenezwa kwa mkono kutoka mkangazi asilia. Pumzika juu ya mito laini ukiwa na Shampeni baridi, vitafunio maalum, na sauti za kuvutia za upepo wa bahari na nyimbo za taarab za ala za asili wakati mchana unapofifia kuwa jioni.', 'Step aboard a handcrafted Swahili sailing dhow carved from indigenous mahogany. Relax upon plush cushions with chilled Champagne, artisanal canapés, and the hypnotic sounds of the ocean breeze and acoustic taarab melodies as daylight fades into dusk.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-sunset-cruise].duration', 'Saa 2.5 (Jioni Wakati wa Mwanga wa Dhahabu)', '2.5 Hours (Late Afternoon Golden Hour)', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-sunset-cruise].priceNote', 'Bei kwa Ombi', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-sunset-cruise].shortDescription', 'Elea juu ya Bahari ya Hindi tulivu chini ya matanga yaliyojaa upepo huku jua la ikweta likipaka anga rangi za kaharabu na dhahabu ya waridi.', 'Glide across the calm Indian Ocean under billowed canvas sails as the equatorial sun paints the sky in shades of amber and rose gold.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-sunset-cruise].tag', 'Safari ya Machweo', 'Sunset Cruise', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-sunset-cruise].title', 'Safari ya Machweo kwa Jahazi la Jadi la Mbao', 'Traditional Wooden Dhow Sunset Cruise', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'experiences', '[exp-sunset-cruise].whatsappMessage', 'Habari timu ya huduma kwa wageni ya Zanzirangi House, ningependa kuweka nafasi ya safari binafsi ya machweo kwa jahazi.', 'Hello Zanzirangi House Concierge, I would like to book a private Sunset Dhow Cruise.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'facilities', '[bbq].category', 'Mikusanyiko ya Jioni', 'Evening Gathering', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'facilities', '[bbq].description', 'Jua linapozama ndani ya Bahari ya Hindi, kusanyikeni kuzunguka moto wetu wa ufukweni kwa kamba-mti wa kuchoma, kamba wakubwa, na nyama laini zenye viungo zilizochomwa kwa makumbi ya nazi chini ya nyota za Afrika.', 'As the sun dips into the Indian Ocean, gather around our shoreline firepit for grilled lobster, tiger prawns, and spiced tenderloins cooked over coconut husks under the African constellations.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'facilities', '[bbq].highlight', 'Mlo wa ufukweni kwa mwanga wa mishumaa pamoja na muziki wa Taarab wa moja kwa moja', 'Oceanfront candlelit dining with live acoustic Taarab music', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'facilities', '[bbq].hours', 'Machweo kuanzia 18:30', 'Sunset from 18:30', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
