INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'facilities', '[breakfast].category', 'Desturi ya Asubuhi', 'Morning Ritual', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'facilities', '[breakfast].description', 'Amka kwa sahani za matunda ya kitropiki kutoka mashamba ya kienyeji, brioche iliyookwa sasa hivi, krimu ya pasheni, kahawa ya arabika ya Kitanzania, na mayai yaliyopikwa upendavyo ndani ya villa yako au kando ya bahari.', 'Awaken to tropical fruit platters from local orchards, freshly baked brioche, passion fruit curd, Tanzanian arabica coffee, and eggs cooked to your preference in your villa or by the sea.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
