INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'facilities', '[dining].description', 'Banda la wazi chini ya paa la makuti lenye mandhari kamili ya bahari. Furahia mlo wa kifahari uliokolezwa kwa harufu za viungo vya Zanzibar na samaki wabichi zaidi wa siku.', 'An open-air pavilion beneath vaulted Makuti thatch offering panoramic ocean views. Experience fine dining infused with the aromas of Zanzibar spices and the freshest catches of the day.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
