INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'facilities', '[massage].description', 'Vibanda vya spa vya wazi vilivyojitenga ndani ya bustani za pwani. Jifurahishe kwa masaji maalum kwa kutumia mafuta ya nazi ya Zanzibar yaliyokamuliwa kwa baridi, mchaichai, karafuu iliyosagwa, na mimea asilia ya Kiafrika.', 'Secluded open-air spa salas nestled in coastal gardens. Indulge in bespoke massages using cold-pressed Zanzibar coconut oil, lemongrass, ground cloves, and indigenous African botanicals.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
