INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'facilities', '[pool].description', 'Likiwa juu ya mawimbi ya samawati ya Bahari ya Hindi, bwawa letu la infinity la maji matamu la mita 25 huakisi anga na upeo wa bahari, likiwa na vitanda vya jua vilivyozama majini na huduma makini kando ya bwawa.', 'Suspended above the turquoise tides of the Indian Ocean, our 25-meter freshwater infinity pool mirrors the sky and ocean horizons with sunken sunbeds and attentive poolside service.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
