INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'facilities', '[wifi].description', 'Furahia intaneti ya setilaiti yenye kasi kubwa na ucheleweshaji mdogo katika eneo lote, villa binafsi, viti vya kupumzikia ufukweni, na mitaro ya kulia chakula, ikihakikisha mawasiliano yasiyokatika na urahisi wa kufanya kazi ukiwa mbali.', 'Enjoy blazing-fast, low-latency satellite internet across the entire estate, private villas, beachfront loungers, and dining terraces, ensuring seamless communication and remote productivity.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
