INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'homepage', 'hero.slides[slide-03].description', 'Makazi bora kabisa ya ufukweni katika Zanzirangi House, yenye bwawa la infinity linaloelea juu, banda pana la kuishi, milo ya mpishi binafsi, na vifurushi vya safari kwa ndege moja kwa moja hadi Serengeti.', 'The premier oceanfront residence at Zanzirangi House featuring a suspended infinity pool, expansive living pavilion, private chef dining, and direct Serengeti fly-in safari packages.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
