INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'homepage', 'intro.description', 'Zanzirangi House ni mapumziko ya kifahari ya kipekee yenye villa 8 binafsi zenye mabwawa ya kuzamia, zilizojificha kando ya pwani tulivu ya kusini mwa Zanzibar, huko Kizimkazi Dimbani.', 'Zanzirangi House is an ultra-boutique retreat featuring 8 private plunge-pool villas secluded along the peaceful southern coast of Zanzibar in Kizimkazi Dimbani.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'homepage', 'intro.eyebrow', 'ZAIDI YA MALAZI', 'MORE THAN A STAY', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'homepage', 'intro.title', 'Hifadhi tulivu kati ya upepo wa bahari na urithi wa Kiswahili', 'An intimate sanctuary between the ocean breeze and Swahili heritage', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[about].description', 'Ikiwa kando ya pwani safi ya matumbawe ya kusini huko Kizimkazi Dimbani, Zanzirangi House ni hifadhi binafsi ya kifahari ya kipekee iliyobuniwa kutoa faragha kamili, upatano wa usanifu, na ukarimu wa karibu wa Kizanzibari.', 'Nestled along the pristine southern coral coast of Kizimkazi Dimbani, Zanzirangi House is an ultra-boutique private sanctuary designed to offer total seclusion, architectural harmony, and intimate Zanzibar hospitality.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
