INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[about].title', 'Kuhusu Zanzirangi House', 'About Zanzirangi House', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[contact].description', 'Panga ukaaji wako maalum pamoja na timu yetu ya huduma kwa wageni. Iwe ni kuthibitisha upatikanaji wa villa binafsi, usafiri wa dakika 45 kutoka uwanja wa ndege wa ZNZ, au ratiba maalum za safari za Tanzania, tunapatikana 24/7.', 'Plan your bespoke stay with our concierge team. Whether arranging private villa availability, 45-minute airport transfers from ZNZ, or custom Tanzania safari itineraries, we are available 24/7.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
