INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[dining].description', 'Onja urithi halisi wa mapishi ya Zanzibar unaochanganya viungo vya Kiswahili na vyakula vya baharini vya Bahari ya Hindi vinavyovuliwa kila siku na wavuvi wa jadi wa majahazi wa Kizimkazi. Furahia milo binafsi kwenye veranda, BBQ za ufukweni, na milo maalum ya usiku kwa mwanga wa mishumaa chini ya nyota.', 'Taste authentic Zanzibar culinary heritage blending Swahili spices with Indian Ocean seafood caught daily by Kizimkazi artisanal dhow fishermen. Enjoy private veranda dining, beach barbecues, and bespoke candlelit dinners under the stars.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
