INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[experiences].description', 'Kuanzia kukutana kwa maadili na pomboo pori katika Hifadhi ya Bahari ya Ghuba ya Menai hadi ziara binafsi za urithi wa UNESCO katika Mji Mkongwe, njia za viungo asilia, na safari za jahazi wakati wa machweo—furahia Zanzibar pamoja na waongozaji wetu binafsi waliojitolea.', 'From ethical wild dolphin encounters in the Menai Bay Marine Reserve to private Stone Town UNESCO heritage tours, organic spice trails, and sunset dhow sailing—experience Zanzibar with our dedicated private guides.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
