INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.introText', 'Katika Zanzirangi House (inayopatikana kupitia https://zanzirangihouse.com/), kulinda taarifa binafsi na faragha ya wageni wetu ni jambo la umuhimu mkubwa kabisa. Sera hii ya Faragha inaeleza jinsi tunavyokusanya, kutumia, na kulinda taarifa unapotembelea tovuti yetu, unapowasilisha maombi ya uhifadhi wa nafasi, au unapowasiliana na timu yetu ya huduma kwa wageni.', 'At Zanzirangi House (accessible from https://zanzirangihouse.com/), safeguarding our guests’ personal data and privacy is of utmost importance. This Privacy Policy details how we collect, use, and protect information when you visit our website, submit booking inquiries, or communicate with our concierge team.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.lastUpdated', 'Septemba 2026', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.sections[#0].body', 'Unapowasilisha ombi au kuhifadhi nafasi ya villa binafsi, unaweza kutoa taarifa zikiwemo jina lako kamili, anwani ya barua pepe, namba ya simu/WhatsApp, tarehe za kuwasili/kuondoka, idadi ya wageni, na mapendeleo maalum ya ukarimu au ya chakula.', 'When submitting an inquiry or reserving a private villa, you may provide details including your full name, email address, telephone/WhatsApp number, arrival/departure dates, guest party size, and special hospitality or dietary preferences.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.sections[#0].title', '1. Taarifa Tunazokusanya', '1. Information We Collect', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.sections[#1].items[#0]', 'Kushughulikia maombi ya uhifadhi wa nafasi na kuthibitisha upatikanaji wa vyumba.', 'Facilitating reservation inquiries and room availability checks.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.sections[#1].items[#1]', 'Kuratibu usafiri wa dereva kutoka Uwanja wa Ndege wa Kimataifa wa Abeid Amani Karume (ZNZ).', 'Coordinating airport chauffeur transfers from Abeid Amani Karume International Airport (ZNZ).', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.sections[#1].items[#2]', 'Kuandaa kulingana na mahitaji yako milo binafsi, ziara za pomboo baharini, na safari za kuunganisha na Tanzania Bara.', 'Customizing private dining, marine dolphin tours, and mainland Tanzania safari connections.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.sections[#1].items[#3]', 'Kutoa mawasiliano ya mhudumu binafsi na huduma kwa wageni 24/7.', 'Providing 24/7 personal butler and concierge communications.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.sections[#1].title', '2. Jinsi Tunavyotumia Taarifa Zako', '2. How We Use Your Information', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.sections[#2].body', 'Tunatekeleza hatua madhubuti za kiufundi na kiutawala za ulinzi. Hatuuzi, hatukodishi, wala hatupangishi taarifa za wageni kwa mitandao ya masoko ya kibiashara ya wahusika wengine. Taarifa hushirikishwa pekee na watoa huduma wa ndani wenye leseni (kama vile waendeshaji rasmi wa ndege za kukodi za safari wanaotambuliwa na TANAPA), kwa madhumuni ya kutekeleza ratiba yako iliyokubaliwa tu.', 'We implement strict technical and administrative safeguards. We do not sell, rent, or lease guest information to third-party commercial marketing networks. Data is shared exclusively with licensed local service providers (such as official TANAPA safari charter operators) strictly to fulfill your agreed itinerary.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.sections[#2].title', '3. Usalama wa Taarifa & Ufichuzi kwa Wahusika Wengine', '3. Data Security & Third-Party Disclosure', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.sections[#3].body', 'Kwa maswali yoyote kuhusu faragha au kuomba taarifa zako zifutwe, wasiliana moja kwa moja na timu yetu ya ulinzi wa taarifa kupitia concierge@zanzirangihouse.com au kwa simu rasmi +255 777 890 123.', 'For any privacy inquiries or to request data removal, contact our data protection team directly at concierge@zanzirangihouse.com or via official telephone at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].contentJson.sections[#3].title', '4. Wasiliana na Timu Yetu ya Huduma kwa Wageni', '4. Contact Our Concierge', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[privacy].description', 'Katika Zanzirangi House, kulinda taarifa binafsi na faragha ya wageni wetu ni jambo la umuhimu mkubwa kabisa.', 'At Zanzirangi House, safeguarding our guests’ personal data and privacy is of utmost importance.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
