INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[safari].description', 'Unganisha mapumziko yako ya kifahari ya peku Zanzibar na safari za kiwango cha dunia za Tanzania Bara. Tunaratibu ndege binafsi za kukodi za dakika 90 moja kwa moja hadi Hifadhi ya Taifa ya Serengeti, Kasoko ya Ngorongoro, na Mlima Kilimanjaro, pamoja na kambi bora za kifahari za safari.', 'Combine your barefoot luxury retreat in Zanzibar with world-class mainland safaris. We coordinate 90-minute private air charters directly to Serengeti National Park, Ngorongoro Crater, and Mount Kilimanjaro with premier luxury safari camps.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[safari].eyebrow', 'SAFARI ZA NDEGE PORINI & UFUKWENI • TANZANIA BARA', 'FLY-IN BUSH & BEACH EXPEDITIONS • TANZANIA MAINLAND', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
