INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[terms].contentJson.introText', 'Karibu Zanzirangi House. Kwa kutumia tovuti yetu (https://zanzirangihouse.com/) au kuwasilisha maombi ya malazi na matembezi, unakubali kuzingatia masharti yafuatayo ya ukarimu na miongozo ya uhifadhi wa nafasi.', 'Welcome to Zanzirangi House. By accessing our website (https://zanzirangihouse.com/) or submitting accommodation and excursion requests, you agree to comply with the following hospitality terms and reservation guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[terms].contentJson.lastUpdated', 'Septemba 2026', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[terms].contentJson.sections[#0].body', 'Bei za villa kwa usiku mmoja ni kati ya $390 na $480+ USD na zinajumuisha matumizi ya bwawa binafsi la kuzamia, kifungua kinywa maalum, na huduma maalum ya mhudumu binafsi 24/7. Uthibitisho unahitaji amana iliyokubaliwa au vocha kupitia njia rasmi za uhifadhi wa nafasi.', 'Nightly villa rates range between $390 and $480+ USD and include private plunge pool access, gourmet breakfast, and 24/7 dedicated butler service. Confirmation requires an agreed deposit or voucher via official reservation channels.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[terms].contentJson.sections[#0].title', '1. Uhifadhi wa Nafasi & Malipo', '1. Reservations & Payments', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[terms].contentJson.sections[#1].body', 'Muda wa kawaida wa kuingia ni kuanzia 14:00 (2:00 PM), na muda wa kutoka ni kabla ya 11:00 (11:00 AM). Kuwasili mapema au kuondoka kwa kuchelewa kunaweza kuombwa kupitia mhudumu wako binafsi wa huduma kwa wageni, kutegemea upatikanaji wa villa.', 'Standard check-in is from 14:00 (2:00 PM), and check-out is by 11:00 (11:00 AM). Early arrival or late departure may be requested through your personal concierge, subject to villa availability.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[terms].contentJson.sections[#1].title', '2. Muda wa Kuingia & Kutoka', '2. Check-In & Check-Out Times', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[terms].contentJson.sections[#2].body', 'Zanzirangi House inapakana na Eneo la Hifadhi ya Bahari la Ghuba ya Menai. Wageni wanaoshiriki katika safari za jahazi na ziara za pomboo wanakubali kufuata taratibu za kimaadili kuhusu wanyamapori, wakidumisha umbali wa heshima kutoka kwa viumbe wa baharini kwa mujibu wa kanuni za mazingira za eneo husika.', 'Zanzirangi House borders the Menai Bay Marine Conservation Area. Guests participating in dhow sailing and dolphin excursions agree to follow ethical wildlife protocols, maintaining respectful distances from marine wildlife in compliance with local environmental regulations.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[terms].contentJson.sections[#2].title', '3. Uhifadhi wa Mazingira ya Bahari & Maadili kwa Wanyamapori', '3. Marine Conservation & Wildlife Etiquette', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[terms].contentJson.sections[#3].body', 'Ili kubadilisha au kughairi uhifadhi wa nafasi, wasiliana moja kwa moja na timu yetu ya huduma kwa wageni kupitia barua pepe concierge@zanzirangihouse.com au WhatsApp +255 777 890 123.', 'To modify or cancel a reservation, contact our concierge directly via email at concierge@zanzirangihouse.com or WhatsApp at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[terms].contentJson.sections[#3].title', '4. Maswali & Kughairi', '4. Inquiries & Cancellations', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[terms].description', 'Karibu Zanzirangi House. Kwa kutumia tovuti yetu au kuwasilisha maombi ya uhifadhi wa nafasi, unakubali kuzingatia miongozo yetu ya ukarimu.', 'Welcome to Zanzirangi House. By accessing our website or submitting reservation requests, you agree to comply with our hospitality guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
