INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'pages', '[villas].description', 'Gundua makazi yetu 8 binafsi ya kipekee yenye ukubwa wa kuanzia 78 m² hadi 95 m². Kila villa ina bwawa la kuzamia la maji matamu lililo binafsi kwa 100%, usanifu halisi wa Kiswahili wa mawe ya matumbawe, na huduma maalum ya mhudumu binafsi 24/7.', 'Discover our 8 private artisanal residences ranging from 78 m² to 95 m². Each villa features a 100% private freshwater plunge pool, authentic Swahili coral-stone architecture, and personalized 24/7 dedicated butler service.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
