INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-kilimanjaro].bestFor', 'Mandhari maarufu kutoka angani & matembezi ya milimani', 'Iconic aerial perspectives & alpine trekking', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-kilimanjaro].description', 'Kilele cha juu zaidi barani Afrika na mlima mrefu zaidi duniani unaosimama peke yake huinuka kwa fahari mita 5,895 juu ya nyanda za kitropiki. Kuanzia safari binafsi za helikopta za kuvutia zinazozunguka Kilele cha Uhuru hadi matembezi ya siku moja kwenye njia za msitu mnene wa chini na mashamba ya kahawa, furahia taji maarufu la Tanzania.', 'Africa’s highest peak and the world’s tallest free-standing mountain rises majestically 5,895 meters above tropical plains. From scenic private helicopter flights encircling Uhuru Peak to day treks along lush lower rainforest trails and coffee estates, experience Tanzania’s iconic crown.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-kilimanjaro].flightTimeFromZanzibar', '1h 10m hadi Uwanja wa Kimataifa wa Kilimanjaro', '1h 10m to Kilimanjaro Int’l', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-kilimanjaro].highlights[#0]', 'Ziara za helikopta za kuvutia juu ya kilele chenye barafu', 'Scenic helicopter mountain tours over the glacier summit', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-kilimanjaro].highlights[#1]', 'Matembezi binafsi ya siku moja kwenye njia za msitu za Marangu au Machame', 'Private day hikes on Marangu or Machame rainforest routes', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
