INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-ngorongoro].bestFor', 'Fahari ya kijiolojia & wingi mkubwa wa wanyamapori', 'Geological splendor & concentrated wildlife density', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-ngorongoro].description', 'Kasoko kubwa zaidi duniani ya volkano iliyobaki kamili, inayounda kimbilio la kiikolojia linalojitosheleza lenye kina cha mita 600. Shuka kupitia misitu ya migunga yenye ukungu iliyo ukingoni hadi ndani ya uwanja wa kale uliojaa faru weusi walio hatarini kutoweka, viboko, na maelfu ya heroe wa rangi ya waridi wakitembea majini katika Ziwa Magadi.', 'The world’s largest intact volcanic caldera, creating a self-contained ecological haven 600 meters deep. Descend through misty rim acacia forests into an ancient amphitheater bustling with endangered black rhinos, hippos, and thousands of pink flamingos wading in Lake Magadi.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-ngorongoro].flightTimeFromZanzibar', '1h 30m hadi Kiwanja cha Ndege cha Manyara', '1h 30m to Manyara Airstrip', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-ngorongoro].highlights[#0]', 'Eneo la uhifadhi wa Faru Weusi walio hatarini sana kutoweka', 'Rare critically endangered Black Rhino conservation zone', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-ngorongoro].highlights[#1]', 'Safari ya kusisimua ya gari ikishuka 600m ndani ya kasoko', 'Dramatic 600m caldera descent drive', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-ngorongoro].highlights[#2]', 'Ziwa kubwa la magadi lenye makundi ya heroe yanayometameta', 'Massive soda lake with shimmering flamingo flocks', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
