INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-ngorongoro].tagline', 'Mojawapo ya mandhari asilia ya ajabu zaidi barani Afrika', 'One of Africa’s most extraordinary natural landscapes', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-serengeti].bestFor', 'Kuwaona Wanyama Watano Wakubwa & matukio ya kusisimua ya wanyamapori', 'Big Five sightings & dramatic wildlife spectacles', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-serengeti].description', 'Savana pana za dhahabu zinazoenea bila mwisho hadi upeo wa macho. Shuhudia mamilioni ya nyumbu na pundamilia wakivuka kwa ujasiri mito iliyojaa mamba, wakiambatana na makundi ya simba wakazi, chui wanaoishi peke yao, na kambi za kifahari za mahema porini chini ya anga la ikweta lililojaa nyota.', 'Vast golden savannahs that stretch endlessly to the horizon. Witness millions of wildebeest and zebras braving crocodile-laden rivers, accompanied by resident prides of lions, solitary leopards, and luxury tented bush retreats under star-strewn equatorial skies.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-serengeti].flightTimeFromZanzibar', '1h 45m kwa Ndege Ndogo Moja kwa Moja', '1h 45m Direct Bush Plane', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
