INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-tarangire].bestFor', 'Mandhari ya mibuyu & kukutana kwa karibu na tembo', 'Baobab landscapes & intimate elephant encounters', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-tarangire].description', 'Maarufu kwa mibuyu yake mikubwa ya kale inayosimama kama walinzi wakimya katika bonde la mto lenye mandhari ya porini. Tarangire ina idadi kubwa zaidi ya makundi ya tembo Afrika Mashariki, ambapo tembo-mama wenye fahari huongoza ndama wao kando ya Mto Tarangire unaotoa uhai.', 'Famed for its colossal ancient baobab trees that stand like silent sentinels across a rugged river valley. Tarangire hosts East Africa’s highest concentration of elephant herds, where majestic family matriarchs guide their calves along the life-giving Tarangire River.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-tarangire].flightTimeFromZanzibar', 'Safari ya Ndege ya 1h 20m', '1h 20m Flight', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
