INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'safari', '[dest-tarangire].highlights[#2]', 'Mikusanyiko ya wanyamapori kando ya mto wakati wa kiangazi', 'Dry-season wildlife congregations along the river', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
