INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'testimonials', '[rev-01].country', 'Uingereza', 'United Kingdom', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'testimonials', '[rev-01].reviewText', 'Tangu dereva wetu binafsi alipotukaribisha katika Uwanja wa Ndege wa Zanzibar hadi safari yetu ya mwisho ya jahazi wakati wa machweo, kila jambo lilipangwa kwa ukamilifu kabisa. Bwawa la kuzamia lililo juu ya mawimbi ya bahari lilikuwa la ajabu.', 'From the moment our private chauffeur welcomed us at Zanzibar Airport to our final sunset dhow sail, every detail was orchestrated to absolute perfection. The plunge pool perched over the ocean tide was magical.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'testimonials', '[rev-01].stayDate', 'Novemba 2025', 'November 2025', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
