INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'testimonials', '[rev-01].villaStayed', 'Villa ya Sultani Ufukweni', 'Sultan Oceanfront Villa', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
