INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'testimonials', '[rev-02].reviewText', 'Usanifu wa kiasi, matumizi ya mawe asilia ya matumbawe, na huduma ya mhudumu binafsi iliyo makini lakini ya staha vilitukumbusha nyumba bora kabisa za Aman au Singita. Chakula cha usiku cha vyakula vya baharini kwa nazi cha Kiswahili hakisahauliki.', 'The architectural restraint, use of indigenous coral stone, and attentive but discrete butler service reminded us of the very finest Aman or Singita lodges. The Swahili coconut seafood dinner was unforgettable.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'testimonials', '[rev-02].stayDate', 'Januari 2026', 'January 2026', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
