INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'testimonials', '[rev-03].reviewText', 'Tulisafiri kama familia ya watu watano. Kuwa na bwawa letu binafsi la infinity linaloelea juu ya ziwa la matumbawe na mpishi wetu binafsi akituandalia samaki wabichi kila jioni kulibadilisha kabisa maana ya safari ya kifahari kwetu.', 'We traveled as a family of five. Having our own private infinity pool suspended above the coral lagoon and our personal chef preparing fresh catches each evening redefined what luxury travel means to us.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'testimonials', '[rev-03].stayDate', 'Februari 2026', 'February 2026', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
