INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'testimonials', '[rev-04].reviewText', 'Milango ya kale iliyonakshiwa kwa shaba na bwawa binafsi la kuogelea viliunda mazingira tulivu. Kuamka kwa upepo wa bahari na kuona pomboo pori katika safari ya jahazi ya mapambazuko ni kumbukumbu ya maisha yetu yote.', 'The antique carved brass doors and private lap pool created a serene atmosphere. Waking up to ocean breezes and seeing wild dolphins on the sunrise dhow excursion was a lifelong highlight.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
