INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'testimonials', '[rev-05].reviewText', 'Kutoka moja kwa moja kwenye sitaha ya villa yetu hadi ndani ya Bahari ya Hindi yenye joto na rangi ya samawati ilikuwa raha tupu. Ukarimu na umakini wa wafanyakazi kwa kila undani vilitufanya tujihisi kama familia inayoheshimiwa nchini Tanzania.', 'Stepping directly from our villa deck into the warm turquoise Indian Ocean was pure bliss. The staff’s warmth and attention to detail made us feel like honored family in Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
