INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-01].description', 'Villa ya Sultani Ufukweni ni kilele cha anasa tulivu ya peku huko Zanzibar. Ikiwa imehamasishwa na usanifu wa jadi wa Kiomani na mila za ubaharia za Waswahili, hifadhi hii ina dari ndefu za mbao, kuta za chokaa zilizong\'arishwa, na vioo vipana kutoka sakafuni hadi darini vinavyofuta mpaka kati ya ndani na Bahari ya Hindi. Toka kwenye sitaha yako binafsi ya jua yenye bwawa la infinity la kuzamia, au pumzika ndani ya beseni la mawe lililochongwa ukitazama majahazi ya jioni.', 'The Sultan Oceanfront Villa represents the pinnacle of barefoot luxury in Zanzibar. Inspired by classical Omani architecture and Swahili maritime traditions, this sanctuary features high timber ceilings, polished lime plaster walls, and expansive floor-to-ceiling glass that dissolves the boundary between indoors and the Indian Ocean. Step out onto your private sun deck with an infinity plunge pool, or unwind in the carved stone soak tub overlooking the evening dhows.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-01].name', 'Villa ya Sultani Ufukweni', 'Sultan Oceanfront Villa', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
