INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-01].shortDescription', 'Imesimama juu kabisa ya genge la matumbawe ikiwa na mandhari ya bahari isiyozuiliwa, bwawa binafsi la kuzamia, na huduma maalum ya mhudumu binafsi.', 'Perched directly above the coral cliff with uninterrupted ocean vistas, private plunge pool, and dedicated butler service.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
