INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-02].shortDescription', 'Imejificha kati ya maua ya frangipani yenye harufu nzuri na minazi, ikitoa faragha kamili, bafu la wazi la mawe, na veranda tulivu ya bustanini.', 'Tucked within fragrant frangipani and coconut palms, offering total seclusion, an open-air stone shower, and serene garden verandah.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
