INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-03].shortDescription', 'Amka kwa mvumo mwororo wa minazi na utoke moja kwa moja kutoka sitaha yako ya mbao hadi kwenye mchanga mweupe laini wa Bahari ya Hindi.', 'Wake up to the soft rustle of palms and step straight from your wooden deck onto the powdery white sand of the Indian Ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
