INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-04].shortDescription', 'Imeinuliwa ili kupokea upepo safi wa bahari na upeo usiozuiliwa, ikiwa na veranda pana yenye mandhari kamili, bora kwa kutazama pomboo.', 'Elevated for supreme sea breezes and unobstructed horizons, featuring a wide panoramic verandah perfect for dolphin watching.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
