INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-05].description', 'Likiwa limezunguka mbuyu wa kale unaoheshimiwa, banda hili pana lenye vyumba viwili vya kulala linatoa starehe ya kipekee kwa wasafiri wenzako au familia. Lina ua wa kati wa kuishi wenye kivuli, vyumba viwili vikuu vinavyojitegemea kila kimoja na bafu lake la wazi, na pergola binafsi ya kulia chakula.', 'Centered around an ancient, revered Baobab tree, this generous two-bedroom pavilion provides exceptional comfort for traveling companions or families. Featuring a shaded central living courtyard, two independent master suites each with their own open-air bathroom, and a private dining pergola.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
