INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-06].bed', 'Kitanda cha King cha Msaji wa Zanzibar Kilichochongwa kwa Mkono', 'Hand-Carved Zanzibar Teak King Bed', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-06].description', 'Heshima kwa enzi ya dhahabu ya ufundi wa mikono wa Kisiwa cha Viungo. Villa 06 ina milango halisi iliyonakshiwa na kupambwa kwa vifungo vya shaba kutoka kwa mafundi mahiri wa Mji Mkongwe, sakafu za terrazzo zilizomiminwa kwa mkono, na bwawa binafsi la kuogelea la maji matamu la mita 12 lililozungukwa na mikarafuu na michaichai.', 'A tribute to the Spice Island’s golden age of artisanal craftsmanship. Villa 06 features authentic brass-studded carved doors from Stone Town master carvers, hand-poured terrazzo floors, and a private 12-meter fresh water lap pool fringed by clove and lemongrass bushes.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
