INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-06].shortDescription', 'Inasherehekea urithi maarufu wa viungo wa Zanzibar kwa milango halisi iliyonakshiwa, bwawa binafsi la kuogelea, na ua wa mimea yenye harufu nzuri.', 'Celebrates Zanzibar’s fabled spice heritage with authentic carved doors, private lap pool, and aromatic botanical courtyard.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
