INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-08].description', 'Anwani ya kipekee kabisa ya eneo letu. Ikiwa juu ya rasi yake binafsi iliyojitenga, Villa ya Kifalme ya Rais inatoa uhuru kamili, saluni pana za kukaribisha wageni, bwawa binafsi la infinity la ufukweni linaloelea juu ya ziwa la matumbawe, huduma ya mpishi binafsi kwa ombi, na njia binafsi ya moja kwa moja hadi ufukweni.', 'The estate’s most exclusive address. Set on its own secluded promontory, The Royal Presidential Villa offers total autonomy, expansive entertaining salons, a private oceanfront infinity pool suspended over the coral lagoon, a private chef service on request, and direct private beach access.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-08].name', 'Villa ya Kifalme ya Rais', 'The Royal Presidential Villa', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-08].roomNumber', 'VILLA 08', 'VILLA 08', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-08].shortDescription', 'Makazi makuu ya Zanzirangi House. Fahari isiyo na kifani ya ufukweni, mabwawa ya infinity ya ngazi nyingi, na ukarimu binafsi wa staha.', 'The flagship residence of Zanzirangi House. Unparalleled oceanfront grandeur, multi-level infinity pools, and discrete private hosting.', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-08].shortName', 'Villa ya Kifalme ya Rais', 'The Royal Presidential Villa', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
