INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-08].type', 'Makazi Makuu ya Kifahari ya Ghorofa Mbili', 'Grand Two-Story Master Estate', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'villas', '[villa-08].view', 'Mandhari Isiyo na Kifani ya 360° ya Bahari ya Hindi & Genge la Pwani', 'Unrivaled 360° Indian Ocean & Coastal Bluff', 'info@zanzirangihouse.com', '2026-09-30 22:33:25');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'eyebrow', 'Upekee wa Hifadhi Yetu', 'The Sanctuary Difference', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'heading', 'KWA NINI ZANZIRANGI HOUSE', 'WHY ZANZIRANGI HOUSE', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'pillars[pillar-1].description', 'Imejificha kando ya pwani safi ya kusini ya Kizimkazi, mbali na msongamano wa watalii. Hapa, muda hupimwa kwa kupwa na kujaa kwa bahari, mvumo wa minazi, na upeo wa bahari usiozuiliwa.', 'Tucked along the pristine southern coastline of Kizimkazi, far from tourist congestion. Here, time is measured by the tidal ebb and flow, the rustle of palms, and unobstructed ocean horizons.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'pillars[pillar-1].tagline', 'Hifadhi binafsi mbali na msongamano.', 'A private sanctuary away from the crowds.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'pillars[pillar-1].title', 'FARAGHA & UTULIVU', 'PRIVATE & PEACEFUL', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'pillars[pillar-2].description', 'Kuanzia mafundi mahiri wa uchongaji wa Kiswahili na mabanda ya makuti ya karne nyingi hadi viungo asilia vinavyovunwa kila siku kutoka bustani zetu, furahia roho halisi ya Kisiwa cha Viungo.', 'From master Swahili woodcarvers and centuries-old makuti thatched pavilions to organic spices harvested daily from our estate gardens, experience the genuine soul of the Spice Island.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'pillars[pillar-2].tagline', 'Gundua kisiwa kupitia watu wake, ladha zake na utamaduni wake.', 'Experience the island through its people, flavours and culture.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'pillars[pillar-2].title', 'ZANZIBAR HALISI', 'AUTHENTIC ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'pillars[pillar-3].description', 'Timu maalum ya wenyeji na huduma kwa wageni iliyo makini kwa kila hitaji lako. Mapokezi binafsi uwanjani mwa ndege, safari za boti za kukodi, milo ndani ya villa, na ukarimu binafsi wa staha wakati wote.', 'A dedicated host and concierge team attentive to your every need. Private airport tarmac greetings, chartered boat launches, in-villa dining, and discreet personal hospitality throughout.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'pillars[pillar-3].tagline', 'Kuanzia kuwasili uwanja wa ndege hadi kupanga safari.', 'From airport arrival to safari planning.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'pillars[pillar-3].title', 'HUDUMA BINAFSI KWA WAGENI', 'PERSONAL CONCIERGE', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'pillars[pillar-4].description', 'Unganisha kwa urahisi mapumziko ya ufukweni na safari za porini kwa ndege za kukodi hadi Serengeti, Kasoko ya Ngorongoro, na Tarangire, ukiunda safari kamili isiyosahaulika ya Afrika Mashariki.', 'Seamlessly combine oceanfront rest with chartered fly-in bush safaris to the Serengeti, Ngorongoro Crater, and Tarangire, creating a complete and unforgettable East African journey.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'pillars[pillar-4].tagline', 'Unganisha ukaaji wako Zanzibar na maajabu ya Tanzania Bara.', 'Connect your Zanzibar stay with the wonders of mainland Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'pillars[pillar-4].title', 'TANZANIA NA ZAIDI', 'TANZANIA BEYOND', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('sw', 'whystay', 'subhead', 'Maadili manne ya msingi huongoza kila wakati katika mapumziko yetu, yakiunda hali adimu ya utulivu, upekee, na uhusiano wa kina na Tanzania.', 'Four guiding values define every moment at our retreat, creating a rare atmosphere of calm, exclusivity, and profound connection to Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:33:26');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'chauffeur', 'airportDesc', '抵达时停机坪直接迎接，并协助搬运行李。', 'Direct tarmac welcome and luggage assistance upon arrival.', 'info@zanzirangihouse.com', '2026-09-30 22:28:16');
