INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'chauffeur', 'amenitiesNote', '每次接送均免费提供冰镇矿泉水、清凉毛巾及车内高速 Wi-Fi。', 'Complimentary chilled mineral water, cool hand towels, and high-speed in-car Wi-Fi provided for every transfer.', 'info@zanzirangihouse.com', '2026-09-30 22:28:17');
