INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'chauffeur', 'subhead', '从您的航班降落桑给巴尔的那一刻起，我们的私人专车服务确保您前往 Zanzirangi House 的旅程轻松惬意、宁静安心。', 'From the moment your flight touches down in Zanzibar, our private chauffeur service ensures your transition to Zanzirangi House is completely effortless, serene, and secure.', 'info@zanzirangihouse.com', '2026-09-30 22:28:14');
