INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[arabic].description', '颂扬桑给巴尔数百年的阿曼皇室传承与阿拉伯海上航路。品味慢炖香料肉类、泥炉烤扁面包、精致冷热拼盘、馥郁的藏红花米饭，以及由大师级主厨制作的玫瑰露甜点。', 'A celebration of Zanzibar’s centuries-old royal Omani heritage and Arabian sea routes. Savor slow-braised spiced meats, clay-oven flatbreads, exquisite cold and hot mezze, fragrant saffron-infused rice dishes, and sweet rosewater delicacies prepared by master chefs.', 'info@zanzirangihouse.com', '2026-09-30 22:27:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[arabic].name', '地道阿拉伯与阿曼美食', 'Authentic Arabic & Omani Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:27:37');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[arabic].signatureDishes[#0].description', '鲜嫩羊肉以丁香、豆蔻、芫荽籽、干青柠与香蕉叶慢烤 24 小时，铺于馥郁金黄的藏红花卡布萨饭上。', 'Tender lamb slow-cooked for 24 hours with cloves, cardamom, coriander, dry lime, and banana leaves, served over fragrant golden saffron Kabsa rice.', 'info@zanzirangihouse.com', '2026-09-30 22:27:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[arabic].signatureDishes[#0].name', '阿曼舒瓦香料慢烤羊肉', 'Omani Shuwa Spiced Slow-Roasted Lamb', 'info@zanzirangihouse.com', '2026-09-30 22:27:41');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[arabic].signatureDishes[#1].description', '淋石榴的丝滑鹰嘴豆泥、烟熏茄子泥、香草酥脆法拉费，以及手工柴火烤阿拉伯扁面包。', 'Velvety pomegranate-drizzled hummus, smoky Mutabal, crispy herbed falafel, and handmade wood-fired Arabic flatbreads.', 'info@zanzirangihouse.com', '2026-09-30 22:27:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[arabic].signatureDishes[#1].name', '皇家中东拼盘配新鲜扎塔尔胡布兹饼', 'Royal Mezze & Fresh Za’atar Khubz', 'info@zanzirangihouse.com', '2026-09-30 22:27:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[arabic].signatureDishes[#2].description', '炭烤梅奈湾巨虾、鱿鱼与礁区渔获，以阿勒颇辣椒、漆树粉、蒜蓉与野生香草调味。', 'Charcoal-grilled Menai Bay jumbo prawns, calamari, and reef catch seasoned with Aleppo pepper, sumac, garlic, and wild herbs.', 'info@zanzirangihouse.com', '2026-09-30 22:27:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[arabic].signatureDishes[#2].name', '炭烤海鲜配焦香青柠拼盘', 'Mashwi Seafood & Charred Lime Platter', 'info@zanzirangihouse.com', '2026-09-30 22:27:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[arabic].signatureDishes[#3].description', '层层酥薄的菲洛酥皮夹烤开心果，淋橙花豆蔻糖浆，搭配冰镇玫瑰露牛奶布丁。', 'Delicate flaky filo pastry layered with toasted pistachios and orange-blossom cardamom syrup alongside chilled rosewater milk pudding.', 'info@zanzirangihouse.com', '2026-09-30 22:27:45');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[arabic].signatureDishes[#3].name', '温热开心果果仁蜜饼配玫瑰露奶冻', 'Warm Pistachio Baklava & Rosewater Muhallabia', 'info@zanzirangihouse.com', '2026-09-30 22:27:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[arabic].subtitle', '阿曼皇室传承、泥炉烧烤与中东拼盘', 'Royal Omani Heritage, Clay-Oven Grills & Middle Eastern Mezze', 'info@zanzirangihouse.com', '2026-09-30 22:27:39');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[arabic].tabLabel', '阿拉伯', 'Arabic', 'info@zanzirangihouse.com', '2026-09-30 22:27:38');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[beverages].description', '为热带享乐精心策划的高端饮品体验。在海滩或泳池边，尽享世界级窖藏年份佳酿、纯正冷压桑给巴尔热带果汁、自制植物软饮，以及优质纯净矿泉水。', 'An elevated beverage program curated for tropical indulgence. Enjoy world-class cellar vintages, pure cold-pressed Zanzibar tropical juices, house-crafted botanical soft drinks, and premium pristine mineral waters served beachfront or poolside.', 'info@zanzirangihouse.com', '2026-09-30 22:27:41');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[beverages].name', '饮品、酒窖与清凉饮料', 'Beverages, Cellar & Refreshments', 'info@zanzirangihouse.com', '2026-09-30 22:27:37');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[beverages].signatureDishes[#0].description', '新旧世界佳酿典藏：清爽的南非白诗南与长相思、优雅的法国香槟，以及醇厚的托斯卡纳与波尔多红葡萄酒。', 'Old and New World collections, crisp South African Chenin Blanc & Sauvignon Blanc, elegant French Champagnes, and full-bodied Tuscan & Bordeaux reds.', 'info@zanzirangihouse.com', '2026-09-30 22:27:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[beverages].signatureDishes[#0].name', '精选窖藏葡萄酒与香槟（葡萄酒）', 'Curated Cellar Wines & Champagne (Wines)', 'info@zanzirangihouse.com', '2026-09-30 22:27:43');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[beverages].signatureDishes[#1].description', '日照成熟的百香果、香甜的阿方索芒果、鲜薄荷菠萝冰沙，以及采自海岸椰林的新鲜椰青水。', 'Sun-ripened passion fruit, sweet Alfonso mango, crushed pineapple with fresh mint, and young King coconut water straight from coastal palm groves.', 'info@zanzirangihouse.com', '2026-09-30 22:27:47');
