INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[beverages].signatureDishes[#2].description', '自酿香茅辛辣姜汁啤酒、气泡坦桑尼亚洛神花饮、手工植物汤力水，以及经典冰镇苏打。', 'House-brewed fiery ginger beer with crushed lemongrass, sparkling Tanzanian hibiscus cooler, craft botanical tonics, and classic iced sodas.', 'info@zanzirangihouse.com', '2026-09-30 22:27:47');
