INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[beverages].signatureDishes[#3].description', '欧洲与东非优质泉水，静水与气泡水均有，冰镇呈上，配花园新鲜黄瓜、薄荷与 Makunduchi 青柠。', 'Still and sparkling premium European & East African spring waters served crystal chilled with fresh garden cucumber, mint, and Makunduchi lime.', 'info@zanzirangihouse.com', '2026-09-30 22:27:47');
