INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[fusion].description', '我们的招牌料理。经典法式技法与桑给巴尔非凡香料风土之间一场充满想象力的对话。敬请期待香草荚风味龙虾黄油、罗望子浓缩酱汁与百香果舒芙蕾等和谐搭配。', 'Our culinary signature. An imaginative dialogue between classical French technique and Zanzibar’s extraordinary spice terroir. Expect harmonious pairings like vanilla bean infused lobster butter, tamarind reductions, and passion fruit soufflés.', 'info@zanzirangihouse.com', '2026-09-30 22:27:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[fusion].name', '斯瓦希里现代融合料理', 'Swahili Contemporary Fusion', 'info@zanzirangihouse.com', '2026-09-30 22:27:37');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[fusion].signatureDishes[#0].description', '鲜甜多汁的龙虾以法式澄清黄油低温浸煮，融入奔巴岛香草荚的芬芳，佐红薯乳液与海芦笋。', 'Sweet succulent lobster poached in clarified French butter scented with fragrant Pemba vanilla pods, sweet potato emulsion, and sea asparagus.', 'info@zanzirangihouse.com', '2026-09-30 22:27:46');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[fusion].signatureDishes[#0].name', '黄油低温岩龙虾配奔巴岛香草', 'Butter-Poached Rock Lobster with Pemba Vanilla', 'info@zanzirangihouse.com', '2026-09-30 22:27:43');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[fusion].signatureDishes[#1].description', '脆皮鸭胸（Magret）五分熟，淋酸香洛神花酱汁，配烤迷你胡萝卜与香料木薯泥。', 'Crispy skin Magret duck breast served medium rare with a tart hibiscus flower glaze, roasted baby carrots, and spiced cassava purée.', 'info@zanzirangihouse.com', '2026-09-30 22:27:46');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[fusion].signatureDishes[#1].name', '香煎鸭胸配罗望子与洛神花', 'Seared Duck Breast with Tamarind & Hibiscus', 'info@zanzirangihouse.com', '2026-09-30 22:27:43');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[fusion].signatureDishes[#2].description', '70% 黑巧克力熔岩蛋糕，散发青豆蔻芬芳，佐自制椰子意式冰淇淋与百香果酱。', 'Molten dark 70% chocolate cake perfumed with green cardamom, served with house-spun coconut gelato and passionfruit coulis.', 'info@zanzirangihouse.com', '2026-09-30 22:27:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[fusion].signatureDishes[#2].name', '法芙娜巧克力桑给巴尔豆蔻熔岩蛋糕', 'Valrhona Chocolate & Zanzibar Cardamom Fondant', 'info@zanzirangihouse.com', '2026-09-30 22:27:43');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[fusion].subtitle', '热带海岛与现代法式高级料理的邂逅', 'Where Tropical Island Meets Modern French Haute Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:27:39');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[fusion].tabLabel', '融合', 'Fusion', 'info@zanzirangihouse.com', '2026-09-30 22:27:38');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[local].description', '数百年来，阿拉伯、波斯、印度与东非的海上贸易在桑给巴尔的海滨厨房中汇聚交融。我们的行政主厨以新鲜现榨的椰奶、芬芳的豆蔻、奔巴岛丁香以及直送岸边的钓获海鲜，烹制历久弥新的传统菜肴。', 'Centuries of Arab, Persian, Indian, and East African maritime trade converged in Zanzibar’s coastal kitchens. Our executive chefs prepare time-honored recipes featuring freshly harvested coconut milk, aromatic cardamom, cloves from Pemba, and line-caught seafood brought straight to our shores.', 'info@zanzirangihouse.com', '2026-09-30 22:27:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[local].name', '地道斯瓦希里美食', 'Authentic Swahili Cuisine', 'info@zanzirangihouse.com', '2026-09-30 22:27:37');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[local].signatureDishes[#0].description', '香煎野生礁区鲷鱼，以新鲜芫荽、石磨姜黄和手工现榨的海岸椰奶慢煮，佐藏红花米饭。', 'Pan-seared wild reef snapper simmered with fresh green coriander, stone-ground turmeric, and hand-squeezed coastal coconut milk served with saffron rice.', 'info@zanzirangihouse.com', '2026-09-30 22:27:44');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[local].signatureDishes[#0].name', '椰奶姜黄桑给巴尔珊瑚礁鲷鱼', 'Zanzibari Coral Reef Snapper in Coconut & Turmeric', 'info@zanzirangihouse.com', '2026-09-30 22:27:41');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[local].signatureDishes[#1].description', '酸香浓郁、文火慢炖的芒果罗望子汤，配鲜嫩大虾、香料木薯脆片与碎辣椒椰子参巴酱。', 'A tangy, slow-simmered mango and tamarind broth with tender prawns, spiced cassava crisps, and crushed chili coconut sambal.', 'info@zanzirangihouse.com', '2026-09-30 22:27:44');
