INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[local].signatureDishes[#2].description', '软烂入味的本地羊肉，融入八角、肉桂卷与黑豆蔻的香气，佐腌制卡丘巴里沙拉。', 'Fork-tender local lamb infused with star anise, cinnamon quills, and black cardamom, accompanied by pickled kachumbari salad.', 'info@zanzirangihouse.com', '2026-09-30 22:27:45');
