INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[western].description', '专为追求熟悉滋味的国际宾客设计，以顶级精致餐饮技法呈现。进口优质牛肉、新鲜地中海沙拉、自制手工意面以及奢醇甜点，每一道都以利落精准的厨艺完成。', 'Designed for international palates seeking comforting familiarity prepared with the highest fine-dining techniques. Prime imported beef cuts, fresh Mediterranean salads, homemade handmade pasta, and decadent desserts executed with crisp culinary precision.', 'info@zanzirangihouse.com', '2026-09-30 22:27:40');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[western].name', '现代西式料理', 'Modern Western Gastronomy', 'info@zanzirangihouse.com', '2026-09-30 22:27:37');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[western].signatureDishes[#0].description', '炭烤至完美火候，搭配丝滑欧防风慕斯林、焦皮藤番茄，以及浓缩 24 小时的红酒汁。', 'Char-grilled to perfection, paired with smooth parsnip mousseline, blistered vine tomatoes, and a 24-hour reduced red wine jus.', 'info@zanzirangihouse.com', '2026-09-30 22:27:46');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[western].signatureDishes[#0].name', '顶级和牛里脊配松露酱汁', 'Prime Wagyu Tenderloin with Truffle Glaze', 'info@zanzirangihouse.com', '2026-09-30 22:27:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[western].signatureDishes[#1].description', '钓获本地金枪鱼切丁，拌哈斯牛油果、冷压橄榄油、刺山柑果，配自家烘焙酸面包脆片。', 'Line-caught local tuna diced with Hass avocado, cold-pressed olive oil, caper berries, and house-baked sourdough crisps.', 'info@zanzirangihouse.com', '2026-09-30 22:27:46');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[western].signatureDishes[#1].name', '野生黄鳍金枪鱼鞑靼配牛油果', 'Wild Yellowfin Tuna Tartare with Avocado', 'info@zanzirangihouse.com', '2026-09-30 22:27:42');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'categories[western].signatureDishes[#2].description', '新鲜鸡蛋意面拌 Kizimkazi 甜美岩龙虾尾、油封大蒜、迷你樱桃番茄与清爽的灰皮诺浓汤。', 'Fresh egg pasta tossed with sweet Kizimkazi rock lobster tail, garlic confit, baby cherry tomatoes, and a light Pinot Grigio bisque.', 'info@zanzirangihouse.com', '2026-09-30 22:27:46');
