INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'gardenBadge', '庄园花园', 'Estate Garden', 'info@zanzirangihouse.com', '2026-09-30 22:27:32');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'gardenDesc', 'Zanzirangi House 园区内藏着一座私人植物花园，厨房团队在此有机种植香茅、青辣椒、野生罗勒、甜薄荷、芬芳的豆蔻以及时令蔬菜。清晨采摘的收获直接决定每日的品鉴菜单，让大地孕育的鲜活滋味与桑给巴尔南部海域的新鲜渔获相得益彰。', 'Tucked within the grounds of Zanzirangi House is our private botanical garden, where our kitchen team cultivates organic lemongrass, green chilies, wild basil, sweet mint, fragrant cardamom, and seasonal vegetables. What is harvested in the morning directly shapes our daily tasting menus, pairing earth-grown vitality with the fresh catch of southern Zanzibar’s waters.', 'info@zanzirangihouse.com', '2026-09-30 22:27:33');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'gardenEyebrow', '以美食讲述故事', 'Culinary Storytelling', 'info@zanzirangihouse.com', '2026-09-30 22:27:32');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'gardenTitle', '从我们的花园到您的餐桌', 'FROM OUR GARDEN TO YOUR TABLE', 'info@zanzirangihouse.com', '2026-09-30 22:27:33');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'heading', '品味桑给巴尔', 'TASTE ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:27:32');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'intro', '斯瓦希里、阿曼与印度洋数百年的海上贸易，在我们的餐桌上交汇相融。从清晨靠岸的钓获鲜鱼，到文火慢炖的馥郁咖喱，在 Zanzirangi House 用餐是一场地道的感官之旅。', 'Centuries of Swahili, Omani, and Indian Ocean sea trade come together at our tables. From line-caught fish brought ashore at sunrise to slow-simmered aromatic curries, dining at Zanzirangi House is an authentic sensory journey.', 'info@zanzirangihouse.com', '2026-09-30 22:27:32');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'moments[#0].desc', '热带木瓜、百香果凝乳、新鲜出炉的温热布里欧修，以及香料坦桑尼亚咖啡，伴着晨间海景享用。', 'Tropical papaya, passion fruit curds, warm freshly-baked brioche, and spiced Tanzanian coffee served overlooking the morning ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:27:36');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'moments[#0].time', '上午 07:00 – 10:30', '07:00 – 10:30 AM', 'info@zanzirangihouse.com', '2026-09-30 22:27:35');
