INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'moments[#1].desc', '钓获黄鳍金枪鱼鞑靼、岩龙虾沙拉、柴火烤扁面包，以及棕榈树下的新鲜椰青水。', 'Line-caught yellowfin tuna tartare, rock lobster salads, wood-fired flatbreads, and young King coconut water under the palms.', 'info@zanzirangihouse.com', '2026-09-30 22:27:36');
