INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'moments[#2].desc', '香脆大蕉片、香料罗望子大虾、窖藏美酒与手工植物鸡尾酒，静待海平线染上紫罗兰色。', 'Crisp plantain crisps, spiced tamarind prawns, cellar wines, and handcrafted botanical cocktails as the ocean horizon turns violet.', 'info@zanzirangihouse.com', '2026-09-30 22:27:36');
