INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'dining', 'moments[#3].desc', '文火慢炖的桑给巴尔椰香咖喱、阿曼香料炖羊肉，以及法芙娜（Valrhona）巧克力豆蔻熔岩蛋糕。', 'Slow-simmered Zanzibari coconut curries, Omani spiced braised lamb, and Valrhona chocolate cardamom fondants.', 'info@zanzirangihouse.com', '2026-09-30 22:27:36');
