INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-cultural].description', '探访历史悠久的 Kizimkazi 渔村与古老的 Dimbani 清真寺（始建于公元 1107 年）。结识以双手雕造传统单桅帆船的当地工匠大师，参加斯瓦希里烹饪工作坊，或在满天繁星下欣赏私享的塔拉布小提琴与卡农琴演奏。', 'Visit the historic Kizimkazi fishing settlement and the ancient Dimbani Mosque (dating to 1107 AD). Meet local master craftsmen carving traditional dhows by hand, participate in a Swahili culinary workshop, or enjoy private taarab violin and kanun music under the night stars.', 'info@zanzirangihouse.com', '2026-09-30 22:27:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-cultural].duration', '3.5 小时（时间可定制）', '3.5 Hours (Custom Timing)', 'info@zanzirangihouse.com', '2026-09-30 22:27:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-cultural].priceNote', '价格请咨询', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:27:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-cultural].shortDescription', '与当地海滨手工艺人真诚交流，学习棕榈编织与单桅帆船修复，探寻古老的斯瓦希里传承。', 'Engage authentically with local coastal artisans, learn palm-weaving and dhow restoration, and discover ancient Swahili heritage.', 'info@zanzirangihouse.com', '2026-09-30 22:27:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-cultural].tag', '文化体验', 'Cultural Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:27:53');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-cultural].title', '斯瓦希里传统、塔拉布音乐与乡村生活', 'Swahili Traditions, Taarab & Village Life', 'info@zanzirangihouse.com', '2026-09-30 22:27:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-cultural].whatsappMessage', '您好，Zanzirangi House 礼宾团队，我想进一步了解斯瓦希里文化体验。', 'Hello Zanzirangi House Concierge, I would like to learn more about Swahili Cultural Experiences.', 'info@zanzirangihouse.com', '2026-09-30 22:28:01');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-dolphins].description', '我们位于桑给巴尔南海岸的 Kizimkazi，可直达东非最负盛名的海豚保护区。黎明时分乘私人单桅帆船或机动艇出发，观赏海豚群在自然海洋栖息地中嬉戏，之后返回庄园享用早餐。', 'Our location in Kizimkazi on Zanzibar’s southern coast provides direct access to East Africa’s most famous dolphin sanctuary. Depart at dawn on a private dhow or motor launch to watch dolphin pods playing in their natural ocean habitat before enjoying breakfast back at the property.', 'info@zanzirangihouse.com', '2026-09-30 22:27:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-dolphins].duration', '3.5 小时（清晨黎明巡游）', '3.5 Hours (Early Morning Dawn Cruise)', 'info@zanzirangihouse.com', '2026-09-30 22:27:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-dolphins].priceNote', '价格请咨询', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:27:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-dolphins].shortDescription', '日出时分自 Kizimkazi 扬帆，驶入梅奈湾受保护的海域，邂逅常驻于此的飞旋海豚与宽吻海豚群。', 'Set sail at sunrise from Kizimkazi into the protected waters of Menai Bay to witness pods of resident spinner and bottlenose dolphins.', 'info@zanzirangihouse.com', '2026-09-30 22:27:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-dolphins].tag', '海豚体验', 'Dolphin Experience', 'info@zanzirangihouse.com', '2026-09-30 22:27:52');
