INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-fishing].shortDescription', '深入奔巴与桑给巴尔海峡的深水区，体验世界级游钓，目标鱼种包括黄鳍金枪鱼、旗鱼与刺鲅。', 'Venture into the deep Pemba and Zanzibar channels for world-class sport fishing targeting yellowfin tuna, sailfish, and wahoo.', 'info@zanzirangihouse.com', '2026-09-30 22:27:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-fishing].tag', '深海垂钓', 'Deep Sea Fishing', 'info@zanzirangihouse.com', '2026-09-30 22:27:53');
