INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-fishing].whatsappMessage', '您好，Zanzirangi House 礼宾团队，我想了解深海游钓行程的详细信息。', 'Hello Zanzirangi House Concierge, I would like details on Deep Sea Sport Fishing trips.', 'info@zanzirangihouse.com', '2026-09-30 22:28:01');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-island-hopping].description', '在桑给巴尔南部与西部的碧蓝海域上自定航线。登上仅在退潮时浮现的粉白沙洲，畅游温暖澄澈的海水，享用新鲜烹制的午餐：炭烤梅奈湾龙虾、鱿鱼与热带水果。', 'Chart your own course across the turquoise waters of southern and western Zanzibar. Disembark onto ephemeral powder-white sandbanks that emerge only at low tide, swim in warm crystalline waters, and savor a freshly prepared lunch of grilled Menai Bay lobster, calamari, and tropical fruit.', 'info@zanzirangihouse.com', '2026-09-30 22:27:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-island-hopping].duration', '全天（私人快艇）', 'Full Day (Private Speedboat)', 'info@zanzirangihouse.com', '2026-09-30 22:27:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-island-hopping].priceNote', '价格请咨询', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:27:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-island-hopping].shortDescription', '航行至无人居住的幽静珊瑚小岛，在空寂的潮汐泻湖中畅游，并在私人沙洲上享用烤海鲜午餐。', 'Cruise to secluded uninhabited coral islets, swim in deserted tidal lagoons, and enjoy a grilled seafood lunch on a private sandbank.', 'info@zanzirangihouse.com', '2026-09-30 22:27:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-island-hopping].tag', '跳岛游', 'Island Hopping', 'info@zanzirangihouse.com', '2026-09-30 22:27:52');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-island-hopping].title', '私享跳岛与沙洲探秘之旅', 'Private Island Hopping & Sandbank Safari', 'info@zanzirangihouse.com', '2026-09-30 22:27:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-island-hopping].whatsappMessage', '您好，Zanzirangi House 礼宾团队，我想咨询一下私享跳岛与沙洲探秘之旅。', 'Hello Zanzirangi House Concierge, I would like to inquire about the Private Island Hopping Sandbank Safari.', 'info@zanzirangihouse.com', '2026-09-30 22:28:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-mnemba].description', '姆奈姆巴环礁位于桑给巴尔东北海岸外，以原始的水下环境享誉全球。尽享私人船只接送、珊瑚礁尖上的专属浮潜，以及由私人主厨精心安排的海滩美食野餐。', 'Located off Zanzibar’s northeast coast, Mnemba Atoll is recognized globally for its pristine underwater conditions. Enjoy private boat transfers, exclusive snorkeling over coral pinnacles, and a beachside gourmet picnic arranged by our private chef.', 'info@zanzirangihouse.com', '2026-09-30 22:27:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-mnemba].duration', '全日私人探险', 'Full Day Private Expedition', 'info@zanzirangihouse.com', '2026-09-30 22:27:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-mnemba].priceNote', '价格请咨询', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:27:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-mnemba].shortDescription', '航行至桑给巴尔海洋保护区的皇冠明珠：无与伦比的澄澈碧水、原始珊瑚花园与海龟泻湖。', 'Sail to the crown jewel of Zanzibar marine reserves: unmatched turquoise clarity, pristine coral gardens, and sea turtle lagoons.', 'info@zanzirangihouse.com', '2026-09-30 22:27:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-mnemba].tag', '姆奈姆巴岛', 'Mnemba Island', 'info@zanzirangihouse.com', '2026-09-30 22:27:53');
