INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-mnemba].whatsappMessage', '您好，Zanzirangi House 礼宾团队，我想预订姆奈姆巴岛海洋保护区探险之旅。', 'Hello Zanzirangi House Concierge, I would like to book the Mnemba Island Marine Sanctuary expedition.', 'info@zanzirangihouse.com', '2026-09-30 22:28:01');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-nature-jozani].description', '由国家公园认证的博物学家带领，深入受约扎尼-查卡湾国家公园保护的古老硬木森林。观赏猴群在林冠间腾跃，漫步高架红树林栈道，了解桑给巴尔独有的珍稀植物。', 'Led by an authorized national park naturalist, journey into ancient hardwood forests protected within Jozani Chwaka Bay National Park. Observe monkey troops swinging through the canopy, walk the elevated mangrove boardwalk, and learn about the rare flora unique to Zanzibar.', 'info@zanzirangihouse.com', '2026-09-30 22:28:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-nature-jozani].duration', '4 小时（建议上午）', '4 Hours (Morning Recommended)', 'info@zanzirangihouse.com', '2026-09-30 22:27:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-nature-jozani].priceNote', '价格请咨询', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:27:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-nature-jozani].shortDescription', '穿越原始的地下水滋养桃花心木森林，邂逅活泼可爱的桑给巴尔特有物种——桑给巴尔红疣猴。', 'Trek through virgin groundwater mahogany forest to encounter the playful, endemic Zanzibar Red Colobus monkey.', 'info@zanzirangihouse.com', '2026-09-30 22:27:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-nature-jozani].tag', '自然体验', 'Nature Experiences', 'info@zanzirangihouse.com', '2026-09-30 22:27:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-nature-jozani].title', '约扎尼森林与红疣猴生态保护区', 'Jozani Forest & Red Colobus Eco-Sanctuary', 'info@zanzirangihouse.com', '2026-09-30 22:27:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-nature-jozani].whatsappMessage', '您好，Zanzirangi House 礼宾团队，我想预约约扎尼森林自然体验。', 'Hello Zanzirangi House Concierge, I would like to reserve the Jozani Forest Nature Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:28:02');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-snorkeling-diving].description', '桑给巴尔的堡礁蕴藏着丰富的热带生物多样性。配备顶级专业装备，并由持证 PADI 潜水长全程陪同，探索令人惊叹的礁壁断层、可穿越的水下洞穴，以及能见度高达 30 米的澄澈海域。', 'Zanzibar’s barrier reefs are teeming with tropical biodiversity. Equipped with top-tier professional gear and accompanied by certified PADI divemasters, discover stunning drop-offs, swim-through caves, and crystal visibility extending up to 30 meters.', 'info@zanzirangihouse.com', '2026-09-30 22:27:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-snorkeling-diving].duration', '半日或全日行程', 'Half Day or Full Day Excursion', 'info@zanzirangihouse.com', '2026-09-30 22:27:50');
