INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-snorkeling-diving].shortDescription', '探索绚丽的珊瑚花园与水下礁壁，邂逅海龟、斑点鹞鲼及各种奇异礁栖鱼类。', 'Explore vibrant coral gardens, underwater marine walls, and meet sea turtles, spotted eagle rays, and exotic reef species.', 'info@zanzirangihouse.com', '2026-09-30 22:27:56');
