INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-snorkeling-diving].title', '珊瑚礁浮潜与深海水肺潜水', 'Coral Reef Snorkeling & Deep Scuba Diving', 'info@zanzirangihouse.com', '2026-09-30 22:27:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-snorkeling-diving].whatsappMessage', '您好，Zanzirangi House 礼宾团队，我想安排一次浮潜与潜水行程。', 'Hello Zanzirangi House Concierge, I would like to arrange a Snorkeling & Diving excursion.', 'info@zanzirangihouse.com', '2026-09-30 22:28:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-spice-farm].description', '与当地资深植物学家同行，漫步于青翠的乡间种植园。亲手触摸、嗅闻并品尝直接取自树木与藤蔓的天然香料——包括黑胡椒、肉豆蔻、生姜、香茅与姜黄——最后享用从高高树冠上采下的新鲜椰青水。', 'Walk alongside expert local botanists through verdant rural plantations. Touch, smell, and taste raw spices directly from the trees and vines—including black pepper, nutmeg, ginger, lemongrass, and turmeric—concluding with fresh King coconut water harvested high in the canopy.', 'info@zanzirangihouse.com', '2026-09-30 22:27:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-spice-farm].duration', '4 小时（上午或下午）', '4 Hours (Morning or Afternoon)', 'info@zanzirangihouse.com', '2026-09-30 22:27:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-spice-farm].priceNote', '价格请咨询', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:27:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-spice-farm].shortDescription', '让感官沉浸于数百年的芳香历史：采摘新鲜肉桂、碾碎青豆蔻，品尝野生香草荚。', 'Immerse your senses in centuries of aromatic history: pluck fresh cinnamon, crush green cardamom, and taste wild vanilla bean.', 'info@zanzirangihouse.com', '2026-09-30 22:27:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-spice-farm].tag', '香料农场', 'Spice Farm', 'info@zanzirangihouse.com', '2026-09-30 22:27:53');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-spice-farm].title', '有机植物香料农场之旅', 'Organic Botanical Spice Farm Journey', 'info@zanzirangihouse.com', '2026-09-30 22:27:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-spice-farm].whatsappMessage', '您好，Zanzirangi House 礼宾团队，我对有机植物香料农场之旅很感兴趣。', 'Hello Zanzirangi House Concierge, I am interested in the Organic Botanical Spice Farm Journey.', 'info@zanzirangihouse.com', '2026-09-30 22:28:01');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-stonetown].description', '一段穿越联合国教科文组织世界遗产石头城的私享之旅。在常驻当地的斯瓦希里历史学家带领下，探访奇迹之屋、17 世纪古堡、圣公会大教堂与旧奴隶市场纪念馆，以及专营银饰与编织布艺的手工作坊。', 'A private journey through UNESCO World Heritage Stone Town. Led by a resident Swahili historian, explore the House of Wonders, the 17th-century Old Fort, the Anglican Cathedral and Old Slave Market memorial, and artisan workshops specializing in silver jewelry and woven textiles.', 'info@zanzirangihouse.com', '2026-09-30 22:27:58');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-stonetown].duration', '全天（私人专车司机及导游）', 'Full Day (Private Chauffeur & Guide)', 'info@zanzirangihouse.com', '2026-09-30 22:27:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-stonetown].priceNote', '价格请咨询', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:27:54');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-stonetown].shortDescription', '漫步于珊瑚毛石砌成的迷宫小巷，欣赏华丽的阿曼雕花柚木门、历史悠久的香料集市与苏丹宫殿。', 'Walk through labyrinthine coral ragstone alleyways, ornate Omani carved teak doors, historical spice bazaars, and the Sultan’s Palace.', 'info@zanzirangihouse.com', '2026-09-30 22:27:56');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-stonetown].tag', '文化与遗产', 'Culture & Heritage', 'info@zanzirangihouse.com', '2026-09-30 22:27:52');
