INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-stonetown].whatsappMessage', '您好，Zanzirangi House 礼宾团队，我想预订石头城历史遗产私享体验。', 'Hello Zanzirangi House Concierge, I am interested in booking the private Stone Town Heritage Experience.', 'info@zanzirangihouse.com', '2026-09-30 22:28:00');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-sunset-cruise].description', '登上一艘以本土桃花心木手工打造的斯瓦希里单桅帆船。倚着柔软靠垫，品冰镇香槟与手工小食，在海风的低吟与原声塔拉布旋律中，静看天光渐暗、暮色降临。', 'Step aboard a handcrafted Swahili sailing dhow carved from indigenous mahogany. Relax upon plush cushions with chilled Champagne, artisanal canapés, and the hypnotic sounds of the ocean breeze and acoustic taarab melodies as daylight fades into dusk.', 'info@zanzirangihouse.com', '2026-09-30 22:27:59');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-sunset-cruise].duration', '2.5 小时（傍晚黄金时刻）', '2.5 Hours (Late Afternoon Golden Hour)', 'info@zanzirangihouse.com', '2026-09-30 22:27:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-sunset-cruise].priceNote', '价格请咨询', 'Price on Request', 'info@zanzirangihouse.com', '2026-09-30 22:27:55');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-sunset-cruise].shortDescription', '鼓满帆布的船帆下，滑过平静的印度洋，看赤道落日将天空染成琥珀与玫瑰金色。', 'Glide across the calm Indian Ocean under billowed canvas sails as the equatorial sun paints the sky in shades of amber and rose gold.', 'info@zanzirangihouse.com', '2026-09-30 22:27:57');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'experiences', '[exp-sunset-cruise].tag', '日落巡游', 'Sunset Cruise', 'info@zanzirangihouse.com', '2026-09-30 22:27:53');
