INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'facilities', '[bbq].description', '夕阳沉入印度洋之际，围坐于海岸篝火旁，在非洲星空下品尝以椰壳炭火烤制的龙虾、虎虾与香料里脊。', 'As the sun dips into the Indian Ocean, gather around our shoreline firepit for grilled lobster, tiger prawns, and spiced tenderloins cooked over coconut husks under the African constellations.', 'info@zanzirangihouse.com', '2026-09-30 22:28:21');
