INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'facilities', '[breakfast].description', '在当地果园的热带水果拼盘、新鲜出炉的布里欧修、百香果凝乳、坦桑尼亚阿拉比卡咖啡，以及按您喜好烹制的蛋品中醒来，可于别墅内或海边享用。', 'Awaken to tropical fruit platters from local orchards, freshly baked brioche, passion fruit curd, Tanzanian arabica coffee, and eggs cooked to your preference in your villa or by the sea.', 'info@zanzirangihouse.com', '2026-09-30 22:28:22');
