INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'facilities', '[dining].description', '高耸马库提茅草顶下的露天亭阁，坐拥全景海景。在桑给巴尔香料的馥郁芬芳与当日最新鲜的渔获中，享受精致美食。', 'An open-air pavilion beneath vaulted Makuti thatch offering panoramic ocean views. Experience fine dining infused with the aromas of Zanzibar spices and the freshest catches of the day.', 'info@zanzirangihouse.com', '2026-09-30 22:28:21');
