INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'facilities', '[massage].description', '隐于海岸花园中的私密露天水疗亭。以冷压桑给巴尔椰子油、香茅、丁香粉及非洲本土植物，享受量身定制的按摩疗程。', 'Secluded open-air spa salas nestled in coastal gardens. Indulge in bespoke massages using cold-pressed Zanzibar coconut oil, lemongrass, ground cloves, and indigenous African botanicals.', 'info@zanzirangihouse.com', '2026-09-30 22:28:21');
