INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'facilities', '[pool].description', '我们 25 米长的淡水无边泳池悬于印度洋碧蓝潮水之上，倒映着天空与海平线，配有下沉式日光躺床与贴心的池畔服务。', 'Suspended above the turquoise tides of the Indian Ocean, our 25-meter freshwater infinity pool mirrors the sky and ocean horizons with sunken sunbeds and attentive poolside service.', 'info@zanzirangihouse.com', '2026-09-30 22:28:21');
