INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'facilities', '[wifi].description', '整个庄园、私人别墅、海滩躺椅与用餐露台均覆盖极速、低延迟的卫星网络，确保沟通顺畅、远程办公高效无忧。', 'Enjoy blazing-fast, low-latency satellite internet across the entire estate, private villas, beachfront loungers, and dining terraces, ensuring seamless communication and remote productivity.', 'info@zanzirangihouse.com', '2026-09-30 22:28:22');
