INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'homepage', 'hero.description', '在 Kizimkazi 的 Zanzirangi House，尽享配备私人浸泳池的桑给巴尔奢华别墅。这处仅有 8 栋别墅的私密秘境，为您呈献从海洋到餐桌的鲜味佳肴与量身定制的海岛之旅。', 'Experience Zanzibar luxury villas with private plunge pools at Zanzirangi House in Kizimkazi. An intimate 8-villa sanctuary offering ocean-to-table dining and bespoke island journeys.', 'info@zanzirangihouse.com', '2026-09-30 22:26:57');
