INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'homepage', 'hero.slides[slide-02].description', '隐于桑给巴尔南部芬芳的鸡蛋花与椰林之间，尽享全然的私密、露天石砌淋浴与静谧的花园露台。', 'Tucked within fragrant frangipani and coconut palms in southern Zanzibar, offering total seclusion, an open-air stone shower, and serene garden verandah.', 'info@zanzirangihouse.com', '2026-09-30 22:26:54');
