INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'homepage', 'hero.slides[slide-03].description', 'Zanzirangi House 的顶级海滨官邸，坐拥悬空无边泳池、宽敞的起居亭阁、私人主厨餐饮，以及直飞塞伦盖蒂的狩猎套餐。', 'The premier oceanfront residence at Zanzirangi House featuring a suspended infinity pool, expansive living pavilion, private chef dining, and direct Serengeti fly-in safari packages.', 'info@zanzirangihouse.com', '2026-09-30 22:26:55');
