INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'homepage', 'intro.description', 'Zanzirangi House 是一处极致精品度假居所，8 栋配备私人浸泳池的别墅静卧于桑给巴尔宁静的南部海岸 Kizimkazi Dimbani。', 'Zanzirangi House is an ultra-boutique retreat featuring 8 private plunge-pool villas secluded along the peaceful southern coast of Zanzibar in Kizimkazi Dimbani.', 'info@zanzirangihouse.com', '2026-09-30 22:26:58');
