INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[about].description', 'Zanzirangi House 静卧于 Kizimkazi Dimbani 原始的南部珊瑚海岸，是一处极致精品私人秘境，致力于为您带来全然的私密、和谐的建筑美学与亲切的桑给巴尔式款待。', 'Nestled along the pristine southern coral coast of Kizimkazi Dimbani, Zanzirangi House is an ultra-boutique private sanctuary designed to offer total seclusion, architectural harmony, and intimate Zanzibar hospitality.', 'info@zanzirangihouse.com', '2026-09-30 22:28:44');
