INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[contact].description', '与我们的礼宾团队一同规划您的定制之旅。无论是查询私人别墅空房、安排从 ZNZ 出发约 45 分钟的机场接送，还是定制坦桑尼亚狩猎行程，我们均 24/7 竭诚为您服务。', 'Plan your bespoke stay with our concierge team. Whether arranging private villa availability, 45-minute airport transfers from ZNZ, or custom Tanzania safari itineraries, we are available 24/7.', 'info@zanzirangihouse.com', '2026-09-30 22:28:44');
