INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[dining].description', '品味地道的桑给巴尔饮食传承：斯瓦希里香料与 Kizimkazi 传统单桅帆船渔民每日捕获的印度洋海鲜完美融合。尽享私人露台用餐、海滩烧烤，以及星空下的定制烛光晚宴。', 'Taste authentic Zanzibar culinary heritage blending Swahili spices with Indian Ocean seafood caught daily by Kizimkazi artisanal dhow fishermen. Enjoy private veranda dining, beach barbecues, and bespoke candlelit dinners under the stars.', 'info@zanzirangihouse.com', '2026-09-30 22:28:44');
