INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[experiences].description', '从梅奈湾海洋保护区内负责任的野生海豚邂逅，到联合国教科文组织世界遗产石头城私享导览、有机香料之旅与单桅帆船日落航行——由我们的专属私人导游陪伴您体验桑给巴尔。', 'From ethical wild dolphin encounters in the Menai Bay Marine Reserve to private Stone Town UNESCO heritage tours, organic spice trails, and sunset dhow sailing—experience Zanzibar with our dedicated private guides.', 'info@zanzirangihouse.com', '2026-09-30 22:28:44');
