INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.introText', '在 Zanzirangi House（网址：https://zanzirangihouse.com/），保护宾客的个人数据与隐私是我们的重中之重。本隐私政策详细说明当您访问我们的网站、提交预订咨询或与我们的礼宾团队沟通时，我们如何收集、使用和保护您的信息。', 'At Zanzirangi House (accessible from https://zanzirangihouse.com/), safeguarding our guests’ personal data and privacy is of utmost importance. This Privacy Policy details how we collect, use, and protect information when you visit our website, submit booking inquiries, or communicate with our concierge team.', 'info@zanzirangihouse.com', '2026-09-30 22:28:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.lastUpdated', '2026 年 9 月', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:28:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.sections[#0].body', '当您提交咨询或预订私人别墅时，您可能会提供以下信息：全名、电子邮件地址、电话/WhatsApp 号码、抵离日期、同行宾客人数，以及特殊服务或饮食偏好。', 'When submitting an inquiry or reserving a private villa, you may provide details including your full name, email address, telephone/WhatsApp number, arrival/departure dates, guest party size, and special hospitality or dietary preferences.', 'info@zanzirangihouse.com', '2026-09-30 22:28:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.sections[#0].title', '1. 我们收集的信息', '1. Information We Collect', 'info@zanzirangihouse.com', '2026-09-30 22:28:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.sections[#1].items[#0]', '处理预订咨询及查询客房空房情况。', 'Facilitating reservation inquiries and room availability checks.', 'info@zanzirangihouse.com', '2026-09-30 22:28:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.sections[#1].items[#1]', '安排往返阿贝德·阿马尼·卡鲁姆国际机场 (ZNZ) 的专车接送。', 'Coordinating airport chauffeur transfers from Abeid Amani Karume International Airport (ZNZ).', 'info@zanzirangihouse.com', '2026-09-30 22:28:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.sections[#1].items[#2]', '定制私人餐饮、海洋海豚之旅及坦桑尼亚大陆狩猎行程衔接。', 'Customizing private dining, marine dolphin tours, and mainland Tanzania safari connections.', 'info@zanzirangihouse.com', '2026-09-30 22:28:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.sections[#1].items[#3]', '提供 24/7 私人管家及礼宾沟通服务。', 'Providing 24/7 personal butler and concierge communications.', 'info@zanzirangihouse.com', '2026-09-30 22:28:51');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.sections[#1].title', '2. 我们如何使用您的信息', '2. How We Use Your Information', 'info@zanzirangihouse.com', '2026-09-30 22:28:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.sections[#2].body', '我们采取严格的技术与管理保障措施。我们不会向第三方商业营销网络出售、出租或租赁宾客信息。数据仅会与持有执照的当地服务提供商（例如经官方认可的 TANAPA 狩猎包机运营商）共享，且仅限于履行您已确认的行程安排。', 'We implement strict technical and administrative safeguards. We do not sell, rent, or lease guest information to third-party commercial marketing networks. Data is shared exclusively with licensed local service providers (such as official TANAPA safari charter operators) strictly to fulfill your agreed itinerary.', 'info@zanzirangihouse.com', '2026-09-30 22:28:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.sections[#2].title', '3. 数据安全与第三方披露', '3. Data Security & Third-Party Disclosure', 'info@zanzirangihouse.com', '2026-09-30 22:28:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.sections[#3].body', '如有任何隐私相关咨询或需申请删除数据，请直接通过 concierge@zanzirangihouse.com 或官方电话 +255 777 890 123 联系我们的数据保护团队。', 'For any privacy inquiries or to request data removal, contact our data protection team directly at concierge@zanzirangihouse.com or via official telephone at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:28:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[privacy].contentJson.sections[#3].title', '4. 联系我们的礼宾团队', '4. Contact Our Concierge', 'info@zanzirangihouse.com', '2026-09-30 22:28:48');
