INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[safari].description', '将您在桑给巴尔的赤足奢华之旅与世界级的坦桑尼亚大陆狩猎之旅相结合。我们可为您安排约 90 分钟的私人包机，直飞塞伦盖蒂国家公园、恩戈罗恩戈罗火山口及乞力马扎罗山，入住顶级奢华狩猎营地。', 'Combine your barefoot luxury retreat in Zanzibar with world-class mainland safaris. We coordinate 90-minute private air charters directly to Serengeti National Park, Ngorongoro Crater, and Mount Kilimanjaro with premier luxury safari camps.', 'info@zanzirangihouse.com', '2026-09-30 22:28:45');
