INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[terms].contentJson.introText', '欢迎来到 Zanzirangi House。访问我们的网站（https://zanzirangihouse.com/）或提交住宿及游览请求，即表示您同意遵守以下住宿条款及预订指引。', 'Welcome to Zanzirangi House. By accessing our website (https://zanzirangihouse.com/) or submitting accommodation and excursion requests, you agree to comply with the following hospitality terms and reservation guidelines.', 'info@zanzirangihouse.com', '2026-09-30 22:28:48');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[terms].contentJson.lastUpdated', '2026 年 9 月', 'September 2026', 'info@zanzirangihouse.com', '2026-09-30 22:28:47');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[terms].contentJson.sections[#0].body', '别墅每晚房价介于 $390 至 $480+ USD 之间，包含私人浸泳池使用、美食早餐及 24/7 专属管家服务。预订须通过官方预订渠道支付约定的订金或提供住宿凭证后方可确认。', 'Nightly villa rates range between $390 and $480+ USD and include private plunge pool access, gourmet breakfast, and 24/7 dedicated butler service. Confirmation requires an agreed deposit or voucher via official reservation channels.', 'info@zanzirangihouse.com', '2026-09-30 22:28:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[terms].contentJson.sections[#0].title', '1. 预订与付款', '1. Reservations & Payments', 'info@zanzirangihouse.com', '2026-09-30 22:28:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[terms].contentJson.sections[#1].body', '标准入住时间为 14:00（下午 2:00）起，退房时间为 11:00（上午 11:00）前。如需提前入住或延迟退房，可通过您的私人礼宾提出申请，视别墅空房情况而定。', 'Standard check-in is from 14:00 (2:00 PM), and check-out is by 11:00 (11:00 AM). Early arrival or late departure may be requested through your personal concierge, subject to villa availability.', 'info@zanzirangihouse.com', '2026-09-30 22:28:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[terms].contentJson.sections[#1].title', '2. 入住与退房时间', '2. Check-In & Check-Out Times', 'info@zanzirangihouse.com', '2026-09-30 22:28:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[terms].contentJson.sections[#2].body', 'Zanzirangi House 毗邻梅奈湾海洋保护区。参加单桅帆船航行及海豚观赏活动的宾客，同意遵守野生动物保护伦理规范，并依照当地环境法规与海洋野生动物保持适当距离。', 'Zanzirangi House borders the Menai Bay Marine Conservation Area. Guests participating in dhow sailing and dolphin excursions agree to follow ethical wildlife protocols, maintaining respectful distances from marine wildlife in compliance with local environmental regulations.', 'info@zanzirangihouse.com', '2026-09-30 22:28:50');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[terms].contentJson.sections[#2].title', '3. 海洋保护与野生动物礼仪', '3. Marine Conservation & Wildlife Etiquette', 'info@zanzirangihouse.com', '2026-09-30 22:28:49');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[terms].contentJson.sections[#3].body', '如需修改或取消预订，请直接通过电子邮件 concierge@zanzirangihouse.com 或 WhatsApp +255 777 890 123 联系我们的礼宾团队。', 'To modify or cancel a reservation, contact our concierge directly via email at concierge@zanzirangihouse.com or WhatsApp at +255 777 890 123.', 'info@zanzirangihouse.com', '2026-09-30 22:28:51');
