INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'pages', '[villas].description', '探索我们 8 栋面积从 78 m² 到 95 m² 不等的私人手工匠心居所。每栋别墅均配备 100% 私享的淡水浸泳池、地道的斯瓦希里珊瑚石建筑，以及 24/7 个性化专属管家服务。', 'Discover our 8 private artisanal residences ranging from 78 m² to 95 m². Each villa features a 100% private freshwater plunge pool, authentic Swahili coral-stone architecture, and personalized 24/7 dedicated butler service.', 'info@zanzirangihouse.com', '2026-09-30 22:28:45');
