INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'safari', '[dest-kilimanjaro].bestFor', '标志性空中视角与高山徒步', 'Iconic aerial perspectives & alpine trekking', 'info@zanzirangihouse.com', '2026-09-30 22:28:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'safari', '[dest-kilimanjaro].description', '非洲最高峰、世界最高的独立山峰，从热带平原上巍然拔起 5,895 米。从环绕乌呼鲁峰的私人直升机观光飞行，到穿越山麓繁茂雨林小径与咖啡庄园的一日徒步，感受坦桑尼亚的标志性王冠。', 'Africa’s highest peak and the world’s tallest free-standing mountain rises majestically 5,895 meters above tropical plains. From scenic private helicopter flights encircling Uhuru Peak to day treks along lush lower rainforest trails and coffee estates, experience Tanzania’s iconic crown.', 'info@zanzirangihouse.com', '2026-09-30 22:28:06');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'safari', '[dest-kilimanjaro].flightTimeFromZanzibar', '1 小时 10 分钟抵达乞力马扎罗国际机场', '1h 10m to Kilimanjaro Int’l', 'info@zanzirangihouse.com', '2026-09-30 22:28:05');
