INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'safari', '[dest-kilimanjaro].highlights[#1]', '马兰古或马切梅雨林线路私人一日徒步', 'Private day hikes on Marangu or Machame rainforest routes', 'info@zanzirangihouse.com', '2026-09-30 22:28:08');
