INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'safari', '[dest-ngorongoro].bestFor', '壮丽地质奇观与高密度野生动物', 'Geological splendor & concentrated wildlife density', 'info@zanzirangihouse.com', '2026-09-30 22:28:09');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'safari', '[dest-ngorongoro].description', '世界上最大的完整火山破火山口，形成深达 600 米、自成一体的生态天堂。穿过火山口边缘云雾缭绕的金合欢林，下行进入这座古老的天然圆形剧场，这里栖息着濒危的黑犀牛、河马，还有成千上万只在马加迪湖中涉水的粉红火烈鸟。', 'The world’s largest intact volcanic caldera, creating a self-contained ecological haven 600 meters deep. Descend through misty rim acacia forests into an ancient amphitheater bustling with endangered black rhinos, hippos, and thousands of pink flamingos wading in Lake Magadi.', 'info@zanzirangihouse.com', '2026-09-30 22:28:05');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'safari', '[dest-ngorongoro].flightTimeFromZanzibar', '1 小时 30 分钟抵达曼亚拉机场', '1h 30m to Manyara Airstrip', 'info@zanzirangihouse.com', '2026-09-30 22:28:04');
