INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'safari', '[dest-serengeti].bestFor', '观赏非洲五霸与壮观的野生动物奇景', 'Big Five sightings & dramatic wildlife spectacles', 'info@zanzirangihouse.com', '2026-09-30 22:28:09');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'safari', '[dest-serengeti].description', '辽阔的金色稀树草原无尽延伸至天际。见证数以百万计的角马与斑马勇渡鳄鱼出没的河流，常驻的狮群与独行的花豹相伴左右，夜宿星光璀璨的赤道天空下的奢华帐篷营地。', 'Vast golden savannahs that stretch endlessly to the horizon. Witness millions of wildebeest and zebras braving crocodile-laden rivers, accompanied by resident prides of lions, solitary leopards, and luxury tented bush retreats under star-strewn equatorial skies.', 'info@zanzirangihouse.com', '2026-09-30 22:28:05');
