INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'safari', '[dest-tarangire].bestFor', '猴面包树景观与近距离观象', 'Baobab landscapes & intimate elephant encounters', 'info@zanzirangihouse.com', '2026-09-30 22:28:10');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'safari', '[dest-tarangire].description', '以巨大的古老猴面包树闻名，它们如沉默的哨兵般矗立在崎岖的河谷之间。塔兰吉雷拥有东非密度最高的象群，威严的象群女族长带领幼象沿着孕育生命的塔兰吉雷河前行。', 'Famed for its colossal ancient baobab trees that stand like silent sentinels across a rugged river valley. Tarangire hosts East Africa’s highest concentration of elephant herds, where majestic family matriarchs guide their calves along the life-giving Tarangire River.', 'info@zanzirangihouse.com', '2026-09-30 22:28:06');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'safari', '[dest-tarangire].flightTimeFromZanzibar', '飞行 1 小时 20 分钟', '1h 20m Flight', 'info@zanzirangihouse.com', '2026-09-30 22:28:05');
