INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'testimonials', '[rev-01].reviewText', '从私人司机在桑给巴尔机场迎接我们，到最后一次乘单桅帆船欣赏日落，每个细节都安排得尽善尽美。悬于海潮之上的浸泳池简直如梦似幻。', 'From the moment our private chauffeur welcomed us at Zanzibar Airport to our final sunset dhow sail, every detail was orchestrated to absolute perfection. The plunge pool perched over the ocean tide was magical.', 'info@zanzirangihouse.com', '2026-09-30 22:28:33');
