INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'testimonials', '[rev-03].reviewText', '我们一家五口同行。拥有悬于珊瑚泻湖之上的私人无边泳池，还有私人主厨每晚烹制新鲜渔获，这彻底重新定义了我们心目中的奢华旅行。', 'We traveled as a family of five. Having our own private infinity pool suspended above the coral lagoon and our personal chef preparing fresh catches each evening redefined what luxury travel means to us.', 'info@zanzirangihouse.com', '2026-09-30 22:28:33');
