INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'testimonials', '[rev-04].reviewText', '古董黄铜雕花木门与私人长泳池营造出宁静祥和的氛围。在海风中醒来，并在日出单桅帆船之旅中看到野生海豚，是我们一生难忘的高光时刻。', 'The antique carved brass doors and private lap pool created a serene atmosphere. Waking up to ocean breezes and seeing wild dolphins on the sunrise dhow excursion was a lifelong highlight.', 'info@zanzirangihouse.com', '2026-09-30 22:28:34');
