INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'testimonials', '[rev-05].country', '南非', 'South Africa', 'info@zanzirangihouse.com', '2026-09-30 22:28:30');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'testimonials', '[rev-05].reviewText', '从别墅露台直接步入温暖碧蓝的印度洋，简直是纯粹的幸福。员工的热情与对细节的用心，让我们在坦桑尼亚感受到如尊贵家人般的礼遇。', 'Stepping directly from our villa deck into the warm turquoise Indian Ocean was pure bliss. The staff’s warmth and attention to detail made us feel like honored family in Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:28:34');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'testimonials', '[rev-05].stayDate', '2025 年 10 月', 'October 2025', 'info@zanzirangihouse.com', '2026-09-30 22:28:31');
