INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'villas', '[villa-01].description', '苏丹海景别墅代表着桑给巴尔赤足奢华的巅峰之作。灵感源自古典阿曼建筑与斯瓦希里航海传统，别墅拥有高挑的木梁天花板、光洁的石灰泥墙，以及通透的落地玻璃，让室内与印度洋浑然一体。步入私人日光甲板，畅游无边浸泳池；或在雕刻石材浴缸中放松身心，静观傍晚归航的单桅帆船。', 'The Sultan Oceanfront Villa represents the pinnacle of barefoot luxury in Zanzibar. Inspired by classical Omani architecture and Swahili maritime traditions, this sanctuary features high timber ceilings, polished lime plaster walls, and expansive floor-to-ceiling glass that dissolves the boundary between indoors and the Indian Ocean. Step out onto your private sun deck with an infinity plunge pool, or unwind in the carved stone soak tub overlooking the evening dhows.', 'info@zanzirangihouse.com', '2026-09-30 22:27:09');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'villas', '[villa-01].name', '苏丹海景别墅', 'Sultan Oceanfront Villa', 'info@zanzirangihouse.com', '2026-09-30 22:27:02');
