INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'villas', '[villa-02].description', '02 号别墅沉浸于原生热带花园之中，尽享全然的宁静与私密。别墅以可持续采伐的木材、椰子棕榈茅草与当地珊瑚毛石建造，即便在赤道烈日下也能保持天然清凉。午后慵懒地躺在日间床上伴着鸟鸣阅读，或在满天繁星下享受露天雨水淋浴。', 'Immersed in indigenous tropical gardens, Villa 02 offers complete tranquility and privacy. Constructed using sustainably harvested timber, coconut palm thatch, and local coral ragstone, the villa remains naturally cool under the equatorial sun. Enjoy lazy afternoons reading on the daybed surrounded by birdsong, or indulge in an open-air rainwater shower under the canopy of night stars.', 'info@zanzirangihouse.com', '2026-09-30 22:27:09');
