INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'villas', '[villa-03].description', '专为热爱海洋之人打造的海滨天堂。03 号别墅可直接私享桑给巴尔南部晶莹剔透的海水。定制硬木家具、手工织造的亚麻盖毯与精选非洲雕塑，营造出低调雅致的氛围。赤足走出门外，看传统渔民的单桅帆船在晨曦中缓缓漂过。', 'A beachfront haven designed for ocean lovers. Villa 03 provides direct, private access to the crystalline waters of southern Zanzibar. Custom hardwood furnishings, hand-loomed linen throws, and curated African sculpture create an atmosphere of understated sophistication. Step outside barefoot to watch traditional fisherman dhows drift across the sunrise.', 'info@zanzirangihouse.com', '2026-09-30 22:27:09');
