INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'villas', '[villa-03].shortDescription', '在棕榈叶的轻柔沙响中醒来，从木质露台一步踏上印度洋粉雪般的白色沙滩。', 'Wake up to the soft rustle of palms and step straight from your wooden deck onto the powdery white sand of the Indian Ocean.', 'info@zanzirangihouse.com', '2026-09-30 22:27:07');
