INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'villas', '[villa-04].description', '04 号别墅坐落于庄园的高处山脊，可将梅奈湾海洋保护区的 180 度壮阔景致尽收眼底。涨潮时，常可见海豚沿外礁线跃出水面。室内以极简的现代线条，搭配温暖的大地色调、黄铜配件与编织拉菲草点缀，相得益彰。', 'Set on an elevated crest of the property, Villa 04 commands sweeping 180-degree vistas across Menai Bay Marine Sanctuary. During high tide, dolphins can frequently be spotted jumping along the outer reef line. The interior balances minimalist contemporary lines with warm earth tones, brass fixtures, and woven raffia accents.', 'info@zanzirangihouse.com', '2026-09-30 22:27:09');
