INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'villas', '[villa-04].shortDescription', '地势高远，海风宜人，地平线一望无际；宽阔的全景露台是观赏海豚的绝佳之处。', 'Elevated for supreme sea breezes and unobstructed horizons, featuring a wide panoramic verandah perfect for dolphin watching.', 'info@zanzirangihouse.com', '2026-09-30 22:27:08');
