INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'villas', '[villa-05].description', '这座宽敞的双卧室亭阁环绕一棵备受敬仰的古老猴面包树而建，为结伴出游的旅人或家庭带来非凡舒适。阁内设有绿荫掩映的中央起居庭院、两间各带露天浴室的独立主卧套房，以及一座私人用餐凉亭。', 'Centered around an ancient, revered Baobab tree, this generous two-bedroom pavilion provides exceptional comfort for traveling companions or families. Featuring a shaded central living courtyard, two independent master suites each with their own open-air bathroom, and a private dining pergola.', 'info@zanzirangihouse.com', '2026-09-30 22:27:09');
