INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'villas', '[villa-06].description', '向香料岛手工艺黄金时代致敬之作。06 号别墅配有出自石头城雕刻大师之手的正宗黄铜钉雕花木门、手工浇筑的水磨石地面，以及一座长 12 米、四周丁香与香茅环绕的私人淡水长泳池。', 'A tribute to the Spice Island’s golden age of artisanal craftsmanship. Villa 06 features authentic brass-studded carved doors from Stone Town master carvers, hand-poured terrazzo floors, and a private 12-meter fresh water lap pool fringed by clove and lemongrass bushes.', 'info@zanzirangihouse.com', '2026-09-30 22:27:10');
