INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'villas', '[villa-07].description', '07 号别墅专为注重设计的旅人而构思，将日式与北欧极简主义同东非的质朴气息融为一体。舒缓的中性色调、手工编织的剑麻地毯，以及配备日间床的专属屋顶观景台，使这里成为月下休憩与静心冥想的理想之所。', 'Conceived for the design-conscious traveler, Villa 07 fuses Japanese-Scandinavian minimalism with East African earthiness. Soothing neutral tones, hand-woven sisal carpets, and an exclusive rooftop observation deck equipped with daybeds make this a haven for moonlit relaxation and tranquil meditation.', 'info@zanzirangihouse.com', '2026-09-30 22:27:10');
