INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'villas', '[villa-08].description', '庄园中最尊贵的所在。皇家总统别墅独踞一方幽静海岬，提供完全独立的私享空间、宽敞的宴客沙龙、悬于珊瑚泻湖之上的私人海滨无边泳池、可按需预约的私人主厨服务，以及直通私人海滩的通道。', 'The estate’s most exclusive address. Set on its own secluded promontory, The Royal Presidential Villa offers total autonomy, expansive entertaining salons, a private oceanfront infinity pool suspended over the coral lagoon, a private chef service on request, and direct private beach access.', 'info@zanzirangihouse.com', '2026-09-30 22:27:10');
