INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'villas', '[villa-08].shortDescription', 'Zanzirangi House 的旗舰官邸。无与伦比的海滨气派、多层无边泳池，以及低调私密的专属款待。', 'The flagship residence of Zanzirangi House. Unparalleled oceanfront grandeur, multi-level infinity pools, and discrete private hosting.', 'info@zanzirangihouse.com', '2026-09-30 22:27:08');
