INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'heading', '为何选择 Zanzirangi House', 'WHY ZANZIRANGI HOUSE', 'info@zanzirangihouse.com', '2026-09-30 22:28:11');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'pillars[pillar-1].description', '静卧于 Kizimkazi 原始的南部海岸线，远离游客的拥挤喧嚣。在这里，时间以潮起潮落、棕榈沙响与一望无际的海平线来丈量。', 'Tucked along the pristine southern coastline of Kizimkazi, far from tourist congestion. Here, time is measured by the tidal ebb and flow, the rustle of palms, and unobstructed ocean horizons.', 'info@zanzirangihouse.com', '2026-09-30 22:28:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'pillars[pillar-1].tagline', '远离喧嚣的私人秘境。', 'A private sanctuary away from the crowds.', 'info@zanzirangihouse.com', '2026-09-30 22:28:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'pillars[pillar-1].title', '私密与宁静', 'PRIVATE & PEACEFUL', 'info@zanzirangihouse.com', '2026-09-30 22:28:11');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'pillars[pillar-2].description', '从斯瓦希里木雕大师、百年传承的马库提茅草亭阁，到每日采自庄园花园的有机香料，感受香料岛最真挚的灵魂。', 'From master Swahili woodcarvers and centuries-old makuti thatched pavilions to organic spices harvested daily from our estate gardens, experience the genuine soul of the Spice Island.', 'info@zanzirangihouse.com', '2026-09-30 22:28:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'pillars[pillar-2].tagline', '透过当地的人、风味与文化感受这座海岛。', 'Experience the island through its people, flavours and culture.', 'info@zanzirangihouse.com', '2026-09-30 22:28:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'pillars[pillar-2].title', '地道桑给巴尔', 'AUTHENTIC ZANZIBAR', 'info@zanzirangihouse.com', '2026-09-30 22:28:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'pillars[pillar-3].description', '专属接待与礼宾团队悉心照料您的每一项需求：机场停机坪专属迎接、包船出海、别墅内用餐，以及全程低调周到的个性化款待。', 'A dedicated host and concierge team attentive to your every need. Private airport tarmac greetings, chartered boat launches, in-villa dining, and discreet personal hospitality throughout.', 'info@zanzirangihouse.com', '2026-09-30 22:28:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'pillars[pillar-3].tagline', '从机场抵达到狩猎行程规划，一应俱全。', 'From airport arrival to safari planning.', 'info@zanzirangihouse.com', '2026-09-30 22:28:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'pillars[pillar-3].title', '专属礼宾', 'PERSONAL CONCIERGE', 'info@zanzirangihouse.com', '2026-09-30 22:28:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'pillars[pillar-4].description', '将海滨休憩与前往塞伦盖蒂、恩戈罗恩戈罗火山口及塔兰吉雷的包机飞入式丛林狩猎无缝结合，成就一段完整而难忘的东非之旅。', 'Seamlessly combine oceanfront rest with chartered fly-in bush safaris to the Serengeti, Ngorongoro Crater, and Tarangire, creating a complete and unforgettable East African journey.', 'info@zanzirangihouse.com', '2026-09-30 22:28:14');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'pillars[pillar-4].tagline', '让您的桑给巴尔之旅与坦桑尼亚大陆的奇景相连。', 'Connect your Zanzibar stay with the wonders of mainland Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:28:13');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'pillars[pillar-4].title', '延伸至坦桑尼亚', 'TANZANIA BEYOND', 'info@zanzirangihouse.com', '2026-09-30 22:28:12');
INSERT INTO `content_translations` (`lang`, `entity`, `path`, `value`, `source`, `updated_by`, `updated_at`) VALUES ('zh', 'whystay', 'subhead', '四大核心理念定义了我们度假居所的每一刻，营造出难得的宁静、尊享氛围，以及与坦桑尼亚的深切联结。', 'Four guiding values define every moment at our retreat, creating a rare atmosphere of calm, exclusivity, and profound connection to Tanzania.', 'info@zanzirangihouse.com', '2026-09-30 22:28:11');
INSERT INTO `dining_categories` (`id`, `name`, `tab_label`, `subtitle`, `description`, `image_url`, `dishes_json`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('arabic', 'Authentic Arabic & Omani Cuisine', 'Arabic', 'Royal Omani Heritage, Clay-Oven Grills & Middle Eastern Mezze', 'A celebration of Zanzibar’s centuries-old royal Omani heritage and Arabian sea routes. Savor slow-braised spiced meats, clay-oven flatbreads, exquisite cold and hot mezze, fragrant saffron-infused rice dishes, and sweet rosewater delicacies prepared by master chefs.', 'https://images.unsplash.com/photo-1541518763669-27fef04b14ea?auto=format&fit=crop&w=1200&q=85', '[{\"name\":\"Omani Shuwa Spiced Slow-Roasted Lamb\",\"description\":\"Tender lamb slow-cooked for 24 hours with cloves, cardamom, coriander, dry lime, and banana leaves, served over fragrant golden saffron Kabsa rice.\"},{\"name\":\"Royal Mezze & Fresh Za’atar Khubz\",\"description\":\"Velvety pomegranate-drizzled hummus, smoky Mutabal, crispy herbed falafel, and handmade wood-fired Arabic flatbreads.\"},{\"name\":\"Mashwi Seafood & Charred Lime Platter\",\"description\":\"Charcoal-grilled Menai Bay jumbo prawns, calamari, and reef catch seasoned with Aleppo pepper, sumac, garlic, and wild herbs.\"},{\"name\":\"Warm Pistachio Baklava & Rosewater Muhallabia\",\"description\":\"Delicate flaky filo pastry layered with toasted pistachios and orange-blossom cardamom syrup alongside chilled rosewater milk pudding.\"}]', 2, 1, '2026-09-30 17:56:16', '2026-09-30 17:56:16', NULL);
INSERT INTO `dining_categories` (`id`, `name`, `tab_label`, `subtitle`, `description`, `image_url`, `dishes_json`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('beverages', 'Beverages, Cellar & Refreshments', 'Beverages', 'Fine Cellar Wines, Fresh Juices, Soft Drinks & Mineral Waters', 'An elevated beverage program curated for tropical indulgence. Enjoy world-class cellar vintages, pure cold-pressed Zanzibar tropical juices, house-crafted botanical soft drinks, and premium pristine mineral waters served beachfront or poolside.', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=1200&q=85', '[{\"name\":\"Curated Cellar Wines & Champagne (Wines)\",\"description\":\"Old and New World collections, crisp South African Chenin Blanc & Sauvignon Blanc, elegant French Champagnes, and full-bodied Tuscan & Bordeaux reds.\"},{\"name\":\"Cold-Pressed Zanzibar Tropical Nectars (Juice)\",\"description\":\"Sun-ripened passion fruit, sweet Alfonso mango, crushed pineapple with fresh mint, and young King coconut water straight from coastal palm groves.\"},{\"name\":\"Artisanal Botanical Sodas & Tonics (Soft Drinks)\",\"description\":\"House-brewed fiery ginger beer with crushed lemongrass, sparkling Tanzanian hibiscus cooler, craft botanical tonics, and classic iced sodas.\"},{\"name\":\"Pristine Mineral Waters (Waters)\",\"description\":\"Still and sparkling premium European & East African spring waters served crystal chilled with fresh garden cucumber, mint, and Makunduchi lime.\"}]', 5, 1, '2026-09-30 17:56:17', '2026-09-30 17:56:17', NULL);
INSERT INTO `dining_categories` (`id`, `name`, `tab_label`, `subtitle`, `description`, `image_url`, `dishes_json`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('fusion', 'Swahili Contemporary Fusion', 'Fusion', 'Where Tropical Island Meets Modern French Haute Cuisine', 'Our culinary signature. An imaginative dialogue between classical French technique and Zanzibar’s extraordinary spice terroir. Expect harmonious pairings like vanilla bean infused lobster butter, tamarind reductions, and passion fruit soufflés.', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=1200&q=85', '[{\"name\":\"Butter-Poached Rock Lobster with Pemba Vanilla\",\"description\":\"Sweet succulent lobster poached in clarified French butter scented with fragrant Pemba vanilla pods, sweet potato emulsion, and sea asparagus.\"},{\"name\":\"Seared Duck Breast with Tamarind & Hibiscus\",\"description\":\"Crispy skin Magret duck breast served medium rare with a tart hibiscus flower glaze, roasted baby carrots, and spiced cassava purée.\"},{\"name\":\"Valrhona Chocolate & Zanzibar Cardamom Fondant\",\"description\":\"Molten dark 70% chocolate cake perfumed with green cardamom, served with house-spun coconut gelato and passionfruit coulis.\"}]', 4, 1, '2026-09-30 17:56:17', '2026-09-30 17:56:17', NULL);
INSERT INTO `dining_categories` (`id`, `name`, `tab_label`, `subtitle`, `description`, `image_url`, `dishes_json`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('local', 'Authentic Swahili Cuisine', 'Swahili', 'Heritage Flavors & Zanzibar Spices', 'Centuries of Arab, Persian, Indian, and East African maritime trade converged in Zanzibar’s coastal kitchens. Our executive chefs prepare time-honored recipes featuring freshly harvested coconut milk, aromatic cardamom, cloves from Pemba, and line-caught seafood brought straight to our shores.', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=1200&q=85', '[{\"name\":\"Zanzibari Coral Reef Snapper in Coconut & Turmeric\",\"description\":\"Pan-seared wild reef snapper simmered with fresh green coriander, stone-ground turmeric, and hand-squeezed coastal coconut milk served with saffron rice.\"},{\"name\":\"Tanzanian Urojo & Tiger Prawn Stew\",\"description\":\"A tangy, slow-simmered mango and tamarind broth with tender prawns, spiced cassava crisps, and crushed chili coconut sambal.\"},{\"name\":\"Slow-Braised Goat with Pilau Spices\",\"description\":\"Fork-tender local lamb infused with star anise, cinnamon quills, and black cardamom, accompanied by pickled kachumbari salad.\"}]', 1, 1, '2026-09-30 17:56:16', '2026-10-01 00:43:36', NULL);
INSERT INTO `dining_categories` (`id`, `name`, `tab_label`, `subtitle`, `description`, `image_url`, `dishes_json`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('western', 'Modern Western Gastronomy', 'Western', 'International Standards with Refined Precision', 'Designed for international palates seeking comforting familiarity prepared with the highest fine-dining techniques. Prime imported beef cuts, fresh Mediterranean salads, homemade handmade pasta, and decadent desserts executed with crisp culinary precision.', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=85', '[{\"name\":\"Prime Wagyu Tenderloin with Truffle Glaze\",\"description\":\"Char-grilled to perfection, paired with smooth parsnip mousseline, blistered vine tomatoes, and a 24-hour reduced red wine jus.\"},{\"name\":\"Wild Yellowfin Tuna Tartare with Avocado\",\"description\":\"Line-caught local tuna diced with Hass avocado, cold-pressed olive oil, caper berries, and house-baked sourdough crisps.\"},{\"name\":\"Handmade Tagliolini with Rock Lobster\",\"description\":\"Fresh egg pasta tossed with sweet Kizimkazi rock lobster tail, garlic confit, baby cherry tomatoes, and a light Pinot Grigio bisque.\"}]', 3, 1, '2026-09-30 17:56:17', '2026-09-30 17:56:17', NULL);
INSERT INTO `dining_config` (`id`, `eyebrow`, `heading`, `subhead`, `intro`, `garden_eyebrow`, `garden_badge`, `garden_title`, `garden_desc`, `tag_zero_miles`, `tag_spices`, `tag_seafood`, `moments_json`, `created_at`, `updated_at`, `updated_by`, `extras_json`) VALUES (1, 'Gastronomic Soul', 'TASTE ZANZIBAR', '\"Fresh ingredients, island flavours and authentic Tanzanian hospitality.\"', 'Centuries of Swahili, Omani, and Indian Ocean sea trade come together at our tables. From line-caught fish brought ashore at sunrise to slow-simmered aromatic curries, dining at Zanzirangi House is an authentic sensory journey.', 'Culinary Storytelling', 'Estate Garden', 'FROM OUR GARDEN TO YOUR TABLE', 'Tucked within the grounds of Zanzirangi House is our private botanical garden, where our kitchen team cultivates organic lemongrass, green chilies, wild basil, sweet mint, fragrant cardamom, and seasonal vegetables. What is harvested in the morning directly shapes our daily tasting menus, pairing earth-grown vitality with the fresh catch of southern Zanzibar’s waters.', '🌱 Zero Food Miles', '🌶 Hand-Picked Daily Spices', '🐟 Sustainable Coastal Seafood', '[{\"title\":\"Artisanal Breakfast\",\"time\":\"07:00 – 10:30 AM\",\"desc\":\"Tropical papaya, passion fruit curds, warm freshly-baked brioche, and spiced Tanzanian coffee served overlooking the morning ocean.\"},{\"title\":\"Barefoot Coastal Lunch\",\"time\":\"12:30 – 03:30 PM\",\"desc\":\"Line-caught yellowfin tuna tartare, rock lobster salads, wood-fired flatbreads, and young King coconut water under the palms.\"},{\"title\":\"Sunset Tapas & Taarab\",\"time\":\"05:30 – 07:00 PM\",\"desc\":\"Crisp plantain crisps, spiced tamarind prawns, cellar wines, and handcrafted botanical cocktails as the ocean horizon turns violet.\"},{\"title\":\"Candlelit Dinner\",\"time\":\"07:30 – 10:30 PM\",\"desc\":\"Slow-simmered Zanzibari coconut curries, Omani spiced braised lamb, and Valrhona chocolate cardamom fondants.\"},{\"title\":\"The Restaurant\",\"time\":\"Open Daily\",\"desc\":\"Open-air makuti thatched dining pavilion capturing the cool cross-breezes of Menai Bay.\"}]', '2026-09-30 17:56:16', '2026-10-01 00:43:34', 'info@zanzirangihouse.com', NULL);
INSERT INTO `experiences` (`id`, `title`, `category`, `duration`, `tag`, `price_note`, `short_description`, `description`, `image_url`, `whatsapp_message`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('exp-cultural', 'Swahili Traditions, Taarab & Village Life', 'cultural', '3.5 Hours (Custom Timing)', 'Cultural Experiences', 'Price on Request', 'Engage authentically with local coastal artisans, learn palm-weaving and dhow restoration, and discover ancient Swahili heritage.', 'Visit the historic Kizimkazi fishing settlement and the ancient Dimbani Mosque (dating to 1107 AD). Meet local master craftsmen carving traditional dhows by hand, participate in a Swahili culinary workshop, or enjoy private taarab violin and kanun music under the night stars.', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=1200&q=85', 'Hello Zanzirangi House Concierge, I would like to learn more about Swahili Cultural Experiences.', 9, 1, '2026-09-30 17:56:19', '2026-09-30 17:56:19', NULL);
INSERT INTO `experiences` (`id`, `title`, `category`, `duration`, `tag`, `price_note`, `short_description`, `description`, `image_url`, `whatsapp_message`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('exp-dolphins', 'Kizimkazi Wild Dolphin Encounter', 'marine', '3.5 Hours (Early Morning Dawn Cruise)', 'Dolphin Experience', 'Price on Request', 'Set sail at sunrise from Kizimkazi into the protected waters of Menai Bay to witness pods of resident spinner and bottlenose dolphins.', 'Our location in Kizimkazi on Zanzibar’s southern coast provides direct access to East Africa’s most famous dolphin sanctuary. Depart at dawn on a private dhow or motor launch to watch dolphin pods playing in their natural ocean habitat before enjoying breakfast back at the property.', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=85', 'Hello Zanzirangi House Concierge, I would like to experience the Kizimkazi Wild Dolphin Encounter.', 3, 1, '2026-09-30 17:56:18', '2026-09-30 17:56:18', NULL);
INSERT INTO `experiences` (`id`, `title`, `category`, `duration`, `tag`, `price_note`, `short_description`, `description`, `image_url`, `whatsapp_message`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('exp-fishing', 'Deep Sea Big Game Sport Fishing', 'adventure', 'Half Day (5 Hours) or Full Day (8 Hours)', 'Deep Sea Fishing', 'Price on Request', 'Venture into the deep Pemba and Zanzibar channels for world-class sport fishing targeting yellowfin tuna, sailfish, and wahoo.', 'Aboard our chartered offshore sportfisher equipped with outriggers, Shimano tackle, and modern nautical electronics, experience the adrenaline of big game fishing in the deep currents of the Indian Ocean. Strictly adheres to catch-and-release protocols for billfish.', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=85', 'Hello Zanzirangi House Concierge, I would like details on Deep Sea Sport Fishing trips.', 7, 1, '2026-09-30 17:56:18', '2026-09-30 17:56:18', NULL);
INSERT INTO `experiences` (`id`, `title`, `category`, `duration`, `tag`, `price_note`, `short_description`, `description`, `image_url`, `whatsapp_message`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('exp-island-hopping', 'Private Island Hopping & Sandbank Safari', 'marine', 'Full Day (Private Speedboat)', 'Island Hopping', 'Price on Request', 'Cruise to secluded uninhabited coral islets, swim in deserted tidal lagoons, and enjoy a grilled seafood lunch on a private sandbank.', 'Chart your own course across the turquoise waters of southern and western Zanzibar. Disembark onto ephemeral powder-white sandbanks that emerge only at low tide, swim in warm crystalline waters, and savor a freshly prepared lunch of grilled Menai Bay lobster, calamari, and tropical fruit.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=85', 'Hello Zanzirangi House Concierge, I would like to inquire about the Private Island Hopping Sandbank Safari.', 2, 1, '2026-09-30 17:56:17', '2026-09-30 17:56:17', NULL);
INSERT INTO `experiences` (`id`, `title`, `category`, `duration`, `tag`, `price_note`, `short_description`, `description`, `image_url`, `whatsapp_message`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('exp-mnemba', 'Mnemba Atoll Luxury Marine Sanctuary', 'marine', 'Full Day Private Expedition', 'Mnemba Island', 'Price on Request', 'Sail to the crown jewel of Zanzibar marine reserves: unmatched turquoise clarity, pristine coral gardens, and sea turtle lagoons.', 'Located off Zanzibar’s northeast coast, Mnemba Atoll is recognized globally for its pristine underwater conditions. Enjoy private boat transfers, exclusive snorkeling over coral pinnacles, and a beachside gourmet picnic arranged by our private chef.', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1200&q=85', 'Hello Zanzirangi House Concierge, I would like to book the Mnemba Island Marine Sanctuary expedition.', 8, 1, '2026-09-30 17:56:19', '2026-09-30 17:56:19', NULL);
INSERT INTO `experiences` (`id`, `title`, `category`, `duration`, `tag`, `price_note`, `short_description`, `description`, `image_url`, `whatsapp_message`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('exp-nature-jozani', 'Jozani Forest & Red Colobus Eco-Sanctuary', 'nature', '4 Hours (Morning Recommended)', 'Nature Experiences', 'Price on Request', 'Trek through virgin groundwater mahogany forest to encounter the playful, endemic Zanzibar Red Colobus monkey.', 'Led by an authorized national park naturalist, journey into ancient hardwood forests protected within Jozani Chwaka Bay National Park. Observe monkey troops swinging through the canopy, walk the elevated mangrove boardwalk, and learn about the rare flora unique to Zanzibar.', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?auto=format&fit=crop&w=1200&q=85', 'Hello Zanzirangi House Concierge, I would like to reserve the Jozani Forest Nature Experience.', 10, 1, '2026-09-30 17:56:19', '2026-09-30 17:56:19', NULL);
INSERT INTO `experiences` (`id`, `title`, `category`, `duration`, `tag`, `price_note`, `short_description`, `description`, `image_url`, `whatsapp_message`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('exp-snorkeling-diving', 'Coral Reef Snorkeling & Deep Scuba Diving', 'marine', 'Half Day or Full Day Excursion', 'Snorkeling & Diving', 'Price on Request', 'Explore vibrant coral gardens, underwater marine walls, and meet sea turtles, spotted eagle rays, and exotic reef species.', 'Zanzibar’s barrier reefs are teeming with tropical biodiversity. Equipped with top-tier professional gear and accompanied by certified PADI divemasters, discover stunning drop-offs, swim-through caves, and crystal visibility extending up to 30 meters.', 'https://images.unsplash.com/photo-1544161515-4ab6ce6db874?auto=format&fit=crop&w=1200&q=85', 'Hello Zanzirangi House Concierge, I would like to arrange a Snorkeling & Diving excursion.', 4, 1, '2026-09-30 17:56:18', '2026-09-30 17:56:18', NULL);
INSERT INTO `experiences` (`id`, `title`, `category`, `duration`, `tag`, `price_note`, `short_description`, `description`, `image_url`, `whatsapp_message`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('exp-spice-farm', 'Organic Botanical Spice Farm Journey', 'nature', '4 Hours (Morning or Afternoon)', 'Spice Farm', 'Price on Request', 'Immerse your senses in centuries of aromatic history: pluck fresh cinnamon, crush green cardamom, and taste wild vanilla bean.', 'Walk alongside expert local botanists through verdant rural plantations. Touch, smell, and taste raw spices directly from the trees and vines—including black pepper, nutmeg, ginger, lemongrass, and turmeric—concluding with fresh King coconut water harvested high in the canopy.', 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?auto=format&fit=crop&w=1200&q=85', 'Hello Zanzirangi House Concierge, I am interested in the Organic Botanical Spice Farm Journey.', 6, 1, '2026-09-30 17:56:18', '2026-09-30 17:56:18', NULL);
INSERT INTO `experiences` (`id`, `title`, `category`, `duration`, `tag`, `price_note`, `short_description`, `description`, `image_url`, `whatsapp_message`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('exp-stonetown', 'Stone Town Heritage & Historic Quarters', 'cultural', 'Full Day (Private Chauffeur & Guide)', 'Culture & Heritage', 'Price on Request', 'Walk through labyrinthine coral ragstone alleyways, ornate Omani carved teak doors, historical spice bazaars, and the Sultan’s Palace.', 'A private journey through UNESCO World Heritage Stone Town. Led by a resident Swahili historian, explore the House of Wonders, the 17th-century Old Fort, the Anglican Cathedral and Old Slave Market memorial, and artisan workshops specializing in silver jewelry and woven textiles.', 'https://images.unsplash.com/photo-1578683010236-d716f9a3f461?auto=format&fit=crop&w=1200&q=85', 'Hello Zanzirangi House Concierge, I am interested in booking the private Stone Town Heritage Experience.', 1, 1, '2026-09-30 17:56:17', '2026-10-01 00:43:35', NULL);
INSERT INTO `experiences` (`id`, `title`, `category`, `duration`, `tag`, `price_note`, `short_description`, `description`, `image_url`, `whatsapp_message`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('exp-sunset-cruise', 'Traditional Wooden Dhow Sunset Cruise', 'sailing', '2.5 Hours (Late Afternoon Golden Hour)', 'Sunset Cruise', 'Price on Request', 'Glide across the calm Indian Ocean under billowed canvas sails as the equatorial sun paints the sky in shades of amber and rose gold.', 'Step aboard a handcrafted Swahili sailing dhow carved from indigenous mahogany. Relax upon plush cushions with chilled Champagne, artisanal canapés, and the hypnotic sounds of the ocean breeze and acoustic taarab melodies as daylight fades into dusk.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=1200&q=85', 'Hello Zanzirangi House Concierge, I would like to book a private Sunset Dhow Cruise.', 5, 1, '2026-09-30 17:56:18', '2026-09-30 17:56:18', NULL);
INSERT INTO `facilities` (`id`, `title`, `category`, `description`, `hours`, `highlight`, `image_url`, `icon`, `sort_order`, `visible`) VALUES ('bbq', 'Barefoot Beach BBQ & Firepit', 'Evening Gathering', 'As the sun dips into the Indian Ocean, gather around our shoreline firepit for grilled lobster, tiger prawns, and spiced tenderloins cooked over coconut husks under the African constellations.', 'Sunset from 18:30', 'Oceanfront candlelit dining with live acoustic Taarab music', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=1200&q=85', NULL, 4, 1);
INSERT INTO `facilities` (`id`, `title`, `category`, `description`, `hours`, `highlight`, `image_url`, `icon`, `sort_order`, `visible`) VALUES ('breakfast', 'Artisanal Gourmet Breakfast', 'Morning Ritual', 'Awaken to tropical fruit platters from local orchards, freshly baked brioche, passion fruit curd, Tanzanian arabica coffee, and eggs cooked to your preference in your villa or by the sea.', '07:00 – 11:00 (In-Villa or Pavilion)', 'Complimentary for all staying guests', 'https://images.unsplash.com/photo-1533089860892-a7c6f0a88666?auto=format&fit=crop&w=1200&q=85', NULL, 5, 1);
INSERT INTO `facilities` (`id`, `title`, `category`, `description`, `hours`, `highlight`, `image_url`, `icon`, `sort_order`, `visible`) VALUES ('dining', 'The Tamarind Dining Pavilion', 'Culinary Arts', 'An open-air pavilion beneath vaulted Makuti thatch offering panoramic ocean views. Experience fine dining infused with the aromas of Zanzibar spices and the freshest catches of the day.', 'Breakfast, Lunch & Dinner', 'Farm-to-table organic produce & fresh daily seafood', 'https://images.unsplash.com/photo-1544161515-4ab6ce6db874?auto=format&fit=crop&w=1200&q=85', NULL, 2, 1);
INSERT INTO `facilities` (`id`, `title`, `category`, `description`, `hours`, `highlight`, `image_url`, `icon`, `sort_order`, `visible`) VALUES ('massage', 'Swahili Botanical Spa & Massage', 'Holistic Wellness', 'Secluded open-air spa salas nestled in coastal gardens. Indulge in bespoke massages using cold-pressed Zanzibar coconut oil, lemongrass, ground cloves, and indigenous African botanicals.', '08:00 – 20:00 by Appointment', 'Authentic Clove & Lemongrass Aromatherapy', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1200&q=85', NULL, 3, 1);
INSERT INTO `facilities` (`id`, `title`, `category`, `description`, `hours`, `highlight`, `image_url`, `icon`, `sort_order`, `visible`) VALUES ('pool', 'Oceanfront Infinity Pool', 'Relaxation & Wellness', 'Suspended above the turquoise tides of the Indian Ocean, our 25-meter freshwater infinity pool mirrors the sky and ocean horizons with sunken sunbeds and attentive poolside service.', '06:30 – 22:00 Daily', 'Bespoke In-Villa Butler', 'https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1200&q=85', NULL, 1, 1);
INSERT INTO `facilities` (`id`, `title`, `category`, `description`, `hours`, `highlight`, `image_url`, `icon`, `sort_order`, `visible`) VALUES ('wifi', 'High-Speed Starlink Satellite Wi-Fi', 'Connectivity', 'Enjoy blazing-fast, low-latency satellite internet across the entire estate, private villas, beachfront loungers, and dining terraces, ensuring seamless communication and remote productivity.', '24/7 Unlimited High Speed', 'Reliable fiber-speed connectivity in every corner', 'https://images.unsplash.com/photo-1512918728675-ed5a9ecdebfd?auto=format&fit=crop&w=1200&q=85', NULL, 6, 1);
