INSERT INTO `page_contents` (`id`, `slug`, `title`, `eyebrow`, `heading`, `subheading`, `description`, `hero_image`, `sections_config`, `content_json`, `created_at`, `updated_at`, `updated_by`) VALUES ('about', 'about', 'About Zanzirangi House', 'BAREFOOT LUXURY • SWAHILI-OMANI HERITAGE', 'About Zanzirangi House', 'An Intimate Sanctuary on Zanzibar’s Peaceful South Coast', 'Nestled along the pristine southern coral coast of Kizimkazi Dimbani, Zanzirangi House is an ultra-boutique private sanctuary designed to offer total seclusion, architectural harmony, and intimate Zanzibar hospitality.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=2400&q=90', '[{\"id\":\"header\",\"name\":\"Page Header\",\"order\":1,\"visible\":true},{\"id\":\"property_intro\",\"name\":\"More Than A Stay Intro\",\"order\":2,\"visible\":true},{\"id\":\"property_experience\",\"name\":\"Discover The Retreat\",\"order\":3,\"visible\":true},{\"id\":\"why_stay\",\"name\":\"Why Zanzirangi House Pillars\",\"order\":4,\"visible\":true},{\"id\":\"internal_links\",\"name\":\"Exploration Links\",\"order\":5,\"visible\":true}]', NULL, '2026-09-30 17:56:15', '2026-10-01 00:43:33', 'info@zanzirangihouse.com');
INSERT INTO `page_contents` (`id`, `slug`, `title`, `eyebrow`, `heading`, `subheading`, `description`, `hero_image`, `sections_config`, `content_json`, `created_at`, `updated_at`, `updated_by`) VALUES ('contact', 'contact', 'Contact & Reservations', 'DIRECT CONCIERGE & INQUIRIES', 'Contact & Reservations', '24/7 Dedicated Butler & Concierge Service', 'Plan your bespoke stay with our concierge team. Whether arranging private villa availability, 45-minute airport transfers from ZNZ, or custom Tanzania safari itineraries, we are available 24/7.', 'https://images.unsplash.com/photo-1549399542-7e3f8b79c341?auto=format&fit=crop&w=2400&q=90', '[{\"id\":\"header\",\"name\":\"Page Header\",\"order\":1,\"visible\":true},{\"id\":\"concierge\",\"name\":\"24/7 Concierge Channels\",\"order\":2,\"visible\":true},{\"id\":\"shuttle\",\"name\":\"VIP Chauffeur & Transfers\",\"order\":3,\"visible\":true},{\"id\":\"map\",\"name\":\"Location & Interactive Map\",\"order\":4,\"visible\":true},{\"id\":\"internal_links\",\"name\":\"Exploration Links\",\"order\":5,\"visible\":true}]', NULL, '2026-09-30 17:56:15', '2026-09-30 17:56:15', NULL);
INSERT INTO `page_contents` (`id`, `slug`, `title`, `eyebrow`, `heading`, `subheading`, `description`, `hero_image`, `sections_config`, `content_json`, `created_at`, `updated_at`, `updated_by`) VALUES ('dining', 'dining', 'Oceanfront Dining', 'OCEAN-TO-TABLE & FARM-TO-TABLE GASTRONOMY', 'Oceanfront Dining', 'Authentic Flavours & Swahili Spices', 'Taste authentic Zanzibar culinary heritage blending Swahili spices with Indian Ocean seafood caught daily by Kizimkazi artisanal dhow fishermen. Enjoy private veranda dining, beach barbecues, and bespoke candlelit dinners under the stars.', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=2400&q=90', '[{\"id\":\"header\",\"name\":\"Page Header & Philosophy\",\"order\":1,\"visible\":true},{\"id\":\"dining_section\",\"name\":\"Culinary Soul & Tasting Portfolios\",\"order\":2,\"visible\":true},{\"id\":\"internal_links\",\"name\":\"Exploration Links\",\"order\":3,\"visible\":true}]', NULL, '2026-09-30 17:56:14', '2026-09-30 17:56:14', NULL);
INSERT INTO `page_contents` (`id`, `slug`, `title`, `eyebrow`, `heading`, `subheading`, `description`, `hero_image`, `sections_config`, `content_json`, `created_at`, `updated_at`, `updated_by`) VALUES ('experiences', 'experiences', 'Zanzibar Experiences', 'CURATED ISLAND ADVENTURES • MENAI BAY & BEYOND', 'Zanzibar Experiences', 'Intimate Discoveries With Private Guides', 'From ethical wild dolphin encounters in the Menai Bay Marine Reserve to private Stone Town UNESCO heritage tours, organic spice trails, and sunset dhow sailing—experience Zanzibar with our dedicated private guides.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=2400&q=90', '[{\"id\":\"header\",\"name\":\"Page Header\",\"order\":1,\"visible\":true},{\"id\":\"experiences_grid\",\"name\":\"Curated Experiences Collection\",\"order\":2,\"visible\":true},{\"id\":\"explore_zanzibar\",\"name\":\"Regional Island Highlights\",\"order\":3,\"visible\":true},{\"id\":\"internal_links\",\"name\":\"Exploration Links\",\"order\":4,\"visible\":true}]', NULL, '2026-09-30 17:56:15', '2026-09-30 17:56:15', NULL);
INSERT INTO `page_contents` (`id`, `slug`, `title`, `eyebrow`, `heading`, `subheading`, `description`, `hero_image`, `sections_config`, `content_json`, `created_at`, `updated_at`, `updated_by`) VALUES ('page_home', 'home', 'Home - Zanzirangi House', 'OCEANFRONT SANCTUARY', 'A Sanctuary of Quiet Splendour', 'Kizimkazi • Zanzibar', 'Exclusive ultra-luxury oceanfront private plunge pool villas overlooking the sapphire waters of Zanzibar.', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=2000&q=85', '[{\"id\":\"hero\",\"name\":\"Hero Slides & Narrative\",\"visible\":true,\"order\":1},{\"id\":\"intro\",\"name\":\"Narrative Introduction\",\"visible\":true,\"order\":2},{\"id\":\"villas\",\"name\":\"Villas & Accommodations\",\"visible\":true,\"order\":3},{\"id\":\"gallery\",\"name\":\"Curated Photo Gallery\",\"visible\":true,\"order\":4},{\"id\":\"facilities\",\"name\":\"Sanctuary Facilities & Spa\",\"visible\":true,\"order\":5},{\"id\":\"testimonials\",\"name\":\"Guest Testimonials & Reviews\",\"visible\":true,\"order\":6},{\"id\":\"video\",\"name\":\"Cinematic Brand Video Reel\",\"visible\":true,\"order\":7},{\"id\":\"concierge\",\"name\":\"Concierge & Direct Channels\",\"visible\":true,\"order\":8}]', '{\"badge\":\"Private Oceanfront Sanctuary\",\"homeSections\":{}}', '2026-09-30 18:17:19', '2026-10-01 00:43:32', 'info@zanzirangihouse.com');
INSERT INTO `page_contents` (`id`, `slug`, `title`, `eyebrow`, `heading`, `subheading`, `description`, `hero_image`, `sections_config`, `content_json`, `created_at`, `updated_at`, `updated_by`) VALUES ('page_stay', 'stay', 'Stay - Private Villas & Residences', 'THE RESIDENCES', 'Sanctuary Plunge Pool Villas', 'Kizimkazi, Zanzibar', 'Discover our 8 private plunge pool ocean villas and beachfront residences crafted in organic Swahili minimalism.', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=2000&q=85', '[{\"id\":\"hero\",\"name\":\"Stay Hero Header\",\"visible\":true,\"order\":1},{\"id\":\"villas_grid\",\"name\":\"Villas & Residences Collection\",\"visible\":true,\"order\":2},{\"id\":\"amenities\",\"name\":\"In-Villa Amenities & Privileges\",\"visible\":true,\"order\":3},{\"id\":\"booking_cta\",\"name\":\"Plan Your Stay Concierge CTA\",\"visible\":true,\"order\":4}]', '{\"amenitiesList\":[\"Private Plunge Pool\",\"Personal Butler Service\",\"Oceanfront Veranda\",\"High-Speed Starlink Wi-Fi\",\"Artisanal Breakfast Included\"]}', '2026-09-30 18:17:19', '2026-09-30 18:17:19', NULL);
INSERT INTO `page_contents` (`id`, `slug`, `title`, `eyebrow`, `heading`, `subheading`, `description`, `hero_image`, `sections_config`, `content_json`, `created_at`, `updated_at`, `updated_by`) VALUES ('privacy', 'privacy', 'Privacy Policy', 'LEGAL & TRUST ASSURANCE', 'Privacy Policy', 'Guest Data Protection & Trust Safeguards', 'At Zanzirangi House, safeguarding our guests’ personal data and privacy is of utmost importance.', '', '[{\"id\":\"header\",\"name\":\"Header & Version Date\",\"order\":1,\"visible\":true},{\"id\":\"content\",\"name\":\"Policy Clauses & Articles\",\"order\":2,\"visible\":true}]', '{\"lastUpdated\":\"September 2026\",\"introText\":\"At Zanzirangi House (accessible from https://zanzirangihouse.com/), safeguarding our guests’ personal data and privacy is of utmost importance. This Privacy Policy details how we collect, use, and protect information when you visit our website, submit booking inquiries, or communicate with our concierge team.\",\"sections\":[{\"title\":\"1. Information We Collect\",\"body\":\"When submitting an inquiry or reserving a private villa, you may provide details including your full name, email address, telephone/WhatsApp number, arrival/departure dates, guest party size, and special hospitality or dietary preferences.\"},{\"title\":\"2. How We Use Your Information\",\"items\":[\"Facilitating reservation inquiries and room availability checks.\",\"Coordinating airport chauffeur transfers from Abeid Amani Karume International Airport (ZNZ).\",\"Customizing private dining, marine dolphin tours, and mainland Tanzania safari connections.\",\"Providing 24/7 personal butler and concierge communications.\"]},{\"title\":\"3. Data Security & Third-Party Disclosure\",\"body\":\"We implement strict technical and administrative safeguards. We do not sell, rent, or lease guest information to third-party commercial marketing networks. Data is shared exclusively with licensed local service providers (such as official TANAPA safari charter operators) strictly to fulfill your agreed itinerary.\"},{\"title\":\"4. Contact Our Concierge\",\"body\":\"For any privacy inquiries or to request data removal, contact our data protection team directly at concierge@zanzirangihouse.com or via official telephone at +255 777 890 123.\"}]}', '2026-09-30 17:56:15', '2026-09-30 17:56:15', NULL);
INSERT INTO `page_contents` (`id`, `slug`, `title`, `eyebrow`, `heading`, `subheading`, `description`, `hero_image`, `sections_config`, `content_json`, `created_at`, `updated_at`, `updated_by`) VALUES ('safari', 'safari', 'Tanzania Safari', 'FLY-IN BUSH & BEACH EXPEDITIONS • TANZANIA MAINLAND', 'Tanzania Safari', 'Seamless Bush & Beach Connections', 'Combine your barefoot luxury retreat in Zanzibar with world-class mainland safaris. We coordinate 90-minute private air charters directly to Serengeti National Park, Ngorongoro Crater, and Mount Kilimanjaro with premier luxury safari camps.', 'https://images.unsplash.com/photo-1516426122078-c23e76319801?auto=format&fit=crop&w=2400&q=90', '[{\"id\":\"header\",\"name\":\"Page Header\",\"order\":1,\"visible\":true},{\"id\":\"safari_destinations\",\"name\":\"Mainland Safari Expeditions\",\"order\":2,\"visible\":true},{\"id\":\"itinerary_builder\",\"name\":\"Custom Itinerary Builder\",\"order\":3,\"visible\":true},{\"id\":\"internal_links\",\"name\":\"Exploration Links\",\"order\":4,\"visible\":true}]', NULL, '2026-09-30 17:56:15', '2026-09-30 17:56:15', NULL);
INSERT INTO `page_contents` (`id`, `slug`, `title`, `eyebrow`, `heading`, `subheading`, `description`, `hero_image`, `sections_config`, `content_json`, `created_at`, `updated_at`, `updated_by`) VALUES ('terms', 'terms', 'Terms & Conditions', 'HOSPITALITY POLICIES & TERMS', 'Terms & Conditions', 'Hospitality Guidelines & Reservation Policies', 'Welcome to Zanzirangi House. By accessing our website or submitting reservation requests, you agree to comply with our hospitality guidelines.', '', '[{\"id\":\"header\",\"name\":\"Header & Version Date\",\"order\":1,\"visible\":true},{\"id\":\"content\",\"name\":\"Terms Clauses & Articles\",\"order\":2,\"visible\":true}]', '{\"lastUpdated\":\"September 2026\",\"introText\":\"Welcome to Zanzirangi House. By accessing our website (https://zanzirangihouse.com/) or submitting accommodation and excursion requests, you agree to comply with the following hospitality terms and reservation guidelines.\",\"sections\":[{\"title\":\"1. Reservations & Payments\",\"body\":\"Nightly villa rates range between $390 and $480+ USD and include private plunge pool access, gourmet breakfast, and 24/7 dedicated butler service. Confirmation requires an agreed deposit or voucher via official reservation channels.\"},{\"title\":\"2. Check-In & Check-Out Times\",\"body\":\"Standard check-in is from 14:00 (2:00 PM), and check-out is by 11:00 (11:00 AM). Early arrival or late departure may be requested through your personal concierge, subject to villa availability.\"},{\"title\":\"3. Marine Conservation & Wildlife Etiquette\",\"body\":\"Zanzirangi House borders the Menai Bay Marine Conservation Area. Guests participating in dhow sailing and dolphin excursions agree to follow ethical wildlife protocols, maintaining respectful distances from marine wildlife in compliance with local environmental regulations.\"},{\"title\":\"4. Inquiries & Cancellations\",\"body\":\"To modify or cancel a reservation, contact our concierge directly via email at concierge@zanzirangihouse.com or WhatsApp at +255 777 890 123.\"}]}', '2026-09-30 17:56:16', '2026-09-30 17:56:16', NULL);
INSERT INTO `page_contents` (`id`, `slug`, `title`, `eyebrow`, `heading`, `subheading`, `description`, `hero_image`, `sections_config`, `content_json`, `created_at`, `updated_at`, `updated_by`) VALUES ('villas', 'villas', 'Private Villas in Zanzibar', 'KIZIMKAZI DIMBANI • SOUTH COAST ZANZIBAR', 'Private Villas in Zanzibar', 'Exclusive 8-Villa Coastal Sanctuary', 'Discover our 8 private artisanal residences ranging from 78 m² to 95 m². Each villa features a 100% private freshwater plunge pool, authentic Swahili coral-stone architecture, and personalized 24/7 dedicated butler service.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=2400&q=90', '[{\"id\":\"header\",\"name\":\"Page Header & Narrative\",\"order\":1,\"visible\":true},{\"id\":\"villas_grid\",\"name\":\"8 Private Villas Collection\",\"order\":2,\"visible\":true},{\"id\":\"facilities\",\"name\":\"Sanctuary Facilities & Spa\",\"order\":3,\"visible\":true},{\"id\":\"internal_links\",\"name\":\"Exploration Links\",\"order\":4,\"visible\":true}]', NULL, '2026-09-30 17:56:14', '2026-09-30 17:56:14', NULL);
INSERT INTO `safari_destinations` (`id`, `name`, `tagline`, `region`, `flight_time`, `hero_image`, `description`, `highlights_json`, `best_for`, `safari_type`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('dest-kilimanjaro', 'KILIMANJARO', 'Stand at the roof of Africa', 'North-Eastern Tanzania', '1h 10m to Kilimanjaro Int’l', 'https://images.unsplash.com/photo-1589553416260-f586c8f1514f?auto=format&fit=crop&w=1600&q=85', 'Africa’s highest peak and the world’s tallest free-standing mountain rises majestically 5,895 meters above tropical plains. From scenic private helicopter flights encircling Uhuru Peak to day treks along lush lower rainforest trails and coffee estates, experience Tanzania’s iconic crown.', '[\"Scenic helicopter mountain tours over the glacier summit\",\"Private day hikes on Marangu or Machame rainforest routes\",\"Organic Chagga coffee farm and waterfall visits\",\"Spectacular sunset silhouette photography\"]', 'Iconic aerial perspectives & alpine trekking', 'Scenic Flight & Guided Day Expedition', 3, 1, '2026-09-30 17:56:20', '2026-09-30 17:56:20', NULL);
INSERT INTO `safari_destinations` (`id`, `name`, `tagline`, `region`, `flight_time`, `hero_image`, `description`, `highlights_json`, `best_for`, `safari_type`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('dest-ngorongoro', 'NGORONGORO', 'One of Africa’s most extraordinary natural landscapes', 'Crater Highlands', '1h 30m to Manyara Airstrip', 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?auto=format&fit=crop&w=1600&q=85', 'The world’s largest intact volcanic caldera, creating a self-contained ecological haven 600 meters deep. Descend through misty rim acacia forests into an ancient amphitheater bustling with endangered black rhinos, hippos, and thousands of pink flamingos wading in Lake Magadi.', '[\"Rare critically endangered Black Rhino conservation zone\",\"Dramatic 600m caldera descent drive\",\"Massive soda lake with shimmering flamingo flocks\",\"Dramatic rim lodges with panoramic cloud vistas\"]', 'Geological splendor & concentrated wildlife density', 'Crater Floor Game Drives', 2, 1, '2026-09-30 17:56:19', '2026-09-30 17:56:19', NULL);
INSERT INTO `safari_destinations` (`id`, `name`, `tagline`, `region`, `flight_time`, `hero_image`, `description`, `highlights_json`, `best_for`, `safari_type`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('dest-serengeti', 'SERENGETI', 'Wildlife & the Great Migration', 'Arusha, Tanzania', '1h 45m Direct Bush Plane', 'https://images.unsplash.com/photo-1516426122078-c23e76319801?auto=format&fit=crop&w=1600&q=85', 'Vast golden savannahs that stretch endlessly to the horizon. Witness millions of wildebeest and zebras braving crocodile-laden rivers, accompanied by resident prides of lions, solitary leopards, and luxury tented bush retreats under star-strewn equatorial skies.', '[\"The Great Wildebeest Migration\",\"Predator tracking with veteran rangers\",\"Sunrise hot air balloon safaris with Champagne brunch\",\"Exclusive luxury tented bush camps\"]', 'Big Five sightings & dramatic wildlife spectacles', 'Fly-in Bush Plane Safari', 1, 1, '2026-09-30 17:56:19', '2026-10-01 02:12:19', NULL);
INSERT INTO `safari_destinations` (`id`, `name`, `tagline`, `region`, `flight_time`, `hero_image`, `description`, `highlights_json`, `best_for`, `safari_type`, `sort_order`, `visible`, `created_at`, `updated_at`, `extras_json`) VALUES ('dest-tarangire', 'TARANGIRE', 'Elephants, baobabs and untamed landscapes', 'Manyara Region', '1h 20m Flight', 'https://images.unsplash.com/photo-1534177616072-ef7dc120449d?auto=format&fit=crop&w=1600&q=85', 'Famed for its colossal ancient baobab trees that stand like silent sentinels across a rugged river valley. Tarangire hosts East Africa’s highest concentration of elephant herds, where majestic family matriarchs guide their calves along the life-giving Tarangire River.', '[\"Giant multi-centenary baobab tree forests\",\"Enormous elephant gatherings of up to 300 individuals\",\"Dry-season wildlife congregations along the river\",\"Tree-climbing pythons and over 550 bird species\"]', 'Baobab landscapes & intimate elephant encounters', 'River Valley 4x4 Expedition', 4, 1, '2026-09-30 17:56:20', '2026-09-30 17:56:20', NULL);
