INSERT INTO `seo_routes` (`route_path`, `title`, `description`, `canonical_url`, `og_title`, `og_description`, `og_image`, `robots`, `updated_at`) VALUES ('/', 'Zanzibar Luxury Villa - Zanzirangi House | Private Pool Retreat', 'Experience Zanzibar luxury villas with private plunge pools at Zanzirangi House in Kizimkazi. Enjoy ocean-to-table dining and bespoke Tanzania safari journeys.', 'https://zanzirangihouse.com/', 'Zanzibar Luxury Villa - Zanzirangi House | Private Pool Retreat', 'Experience Zanzibar luxury villas with private plunge pools at Zanzirangi House in Kizimkazi. Enjoy ocean-to-table dining and bespoke Tanzania safari journeys.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=2400&q=90', 'index, follow', '2026-09-27 19:08:18');
INSERT INTO `seo_routes` (`route_path`, `title`, `description`, `canonical_url`, `og_title`, `og_description`, `og_image`, `robots`, `updated_at`) VALUES ('/about', 'About Zanzirangi House | Barefoot Luxury Sanctuary in Kizimkazi', 'Learn about Zanzirangi House—an ultra-boutique 8-villa sanctuary in Kizimkazi Dimbani combining Swahili-Omani heritage with barefoot eco-luxury.', 'https://zanzirangihouse.com/about', 'About Zanzirangi House | Barefoot Luxury Sanctuary in Kizimkazi', 'Learn about Zanzirangi House—an ultra-boutique 8-villa sanctuary in Kizimkazi Dimbani combining Swahili-Omani heritage with barefoot eco-luxury.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=2400&q=90', 'index, follow', '2026-09-27 19:08:18');
INSERT INTO `seo_routes` (`route_path`, `title`, `description`, `canonical_url`, `og_title`, `og_description`, `og_image`, `robots`, `updated_at`) VALUES ('/contact', 'Contact & Book Zanzirangi House Zanzibar | Direct Reservations', 'Contact our 24/7 concierge for direct villa reservations, airport chauffeur transfers from ZNZ, and personalized Tanzania safari itinerary planning.', 'https://zanzirangihouse.com/contact', 'Contact & Book Zanzirangi House Zanzibar | Direct Reservations', 'Contact our 24/7 concierge for direct villa reservations, airport chauffeur transfers from ZNZ, and personalized Tanzania safari itinerary planning.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=2400&q=90', 'index, follow', '2026-09-27 19:08:18');
INSERT INTO `seo_routes` (`route_path`, `title`, `description`, `canonical_url`, `og_title`, `og_description`, `og_image`, `robots`, `updated_at`) VALUES ('/dining', 'Oceanfront Dining in Zanzibar | Zanzirangi House', 'Artisanal ocean-to-table gastronomy featuring line-caught Kizimkazi seafood, rare Swahili spices, and private sunset beach candlelit dinners.', 'https://zanzirangihouse.com/dining', 'Oceanfront Dining in Zanzibar | Zanzirangi House', 'Artisanal ocean-to-table gastronomy featuring line-caught Kizimkazi seafood, rare Swahili spices, and private sunset beach candlelit dinners.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=2400&q=90', 'index, follow', '2026-09-27 19:08:18');
INSERT INTO `seo_routes` (`route_path`, `title`, `description`, `canonical_url`, `og_title`, `og_description`, `og_image`, `robots`, `updated_at`) VALUES ('/experiences', 'Zanzibar Experiences & Private Tours | Zanzirangi House', 'Bespoke Zanzibar island tours: ethical Menai Bay dolphin dhow safaris, Stone Town UNESCO heritage walks, and organic spice farm excursions.', 'https://zanzirangihouse.com/experiences', 'Zanzibar Experiences & Private Tours | Zanzirangi House', 'Bespoke Zanzibar island tours: ethical Menai Bay dolphin dhow safaris, Stone Town UNESCO heritage walks, and organic spice farm excursions.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=2400&q=90', 'index, follow', '2026-09-27 19:08:18');
INSERT INTO `seo_routes` (`route_path`, `title`, `description`, `canonical_url`, `og_title`, `og_description`, `og_image`, `robots`, `updated_at`) VALUES ('/safari', 'Tanzania Safari from Zanzibar | Zanzirangi House', 'Seamless fly-in bush and beach safaris connecting Zanzibar to Serengeti National Park, Ngorongoro Crater, and Mount Kilimanjaro.', 'https://zanzirangihouse.com/safari', 'Tanzania Safari from Zanzibar | Zanzirangi House', 'Seamless fly-in bush and beach safaris connecting Zanzibar to Serengeti National Park, Ngorongoro Crater, and Mount Kilimanjaro.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=2400&q=90', 'index, follow', '2026-09-27 19:08:18');
INSERT INTO `seo_routes` (`route_path`, `title`, `description`, `canonical_url`, `og_title`, `og_description`, `og_image`, `robots`, `updated_at`) VALUES ('/villas', 'Private Luxury Villas in Zanzibar | Zanzirangi House', 'Explore 8 exclusive private plunge pool villas in Kizimkazi, Zanzibar. Handcrafted coral stone suites with dedicated 24/7 butler service.', 'https://zanzirangihouse.com/villas', 'Private Luxury Villas in Zanzibar | Zanzirangi House', 'Explore 8 exclusive private plunge pool villas in Kizimkazi, Zanzibar. Handcrafted coral stone suites with dedicated 24/7 butler service.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=2400&q=90', 'index, follow', '2026-09-27 19:08:18');
