INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_1790686343841_x4lw', 'What time is check in?', 'check iin will be from 12:00 AM to 23:00PM', 'General', 'en', 'PUBLISHED', 'CANDIDATE_FROM_ADMIN', '2026-09-29 05:52:23', '2026-09-29 05:52:23');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_1790686413745_eg9k', 'siapa kamu', 'This  Zanzirangi  Houses  how can we help?', 'General', 'en', 'PUBLISHED', 'CANDIDATE_FROM_ADMIN', '2026-09-29 05:53:33', '2026-09-29 05:53:33');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_beach_dining_01', 'Can we arrange a private romantic dinner on the beach?', 'Yes! We arrange unforgettable candlelight dinners directly on the soft white sands or elevated coral terraces with torchlight and a custom 5-course seafood tasting menu.', 'Dining', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_checkin_01', 'What are the check-in and check-out times?', 'Standard check-in is from 14:00 (2:00 PM) and check-out is until 11:00 AM. Flexible early check-in or late checkout can be accommodated complimentary whenever villa availability permits.', 'Check-in', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:37', '2026-09-27 20:27:37');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_dhow_01', 'How do we book a private sunset dhow sailing experience?', 'A private wooden dhow sailing experience is unforgettable. Glide across the turquoise Indian Ocean while enjoying chilled Champagne and fresh Swahili canapés as the sun dips below the horizon.', 'Other', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_dining_01', 'Is breakfast included and what dining options are available?', 'A gourmet tropical breakfast is included daily with your stay. Our oceanfront restaurant serves freshly landed Menai Bay seafood, authentic Swahili spice recipes, and international fine dining. In-villa dining is available around the clock.', 'Dining', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_diving_01', 'Where are the best snorkeling and diving spots nearby?', 'Partnering with certified PADI dive masters, we take you to the pristine coral reefs of Mnemba Atoll and Kizimkazi reef to observe sea turtles, manta rays, and vibrant marine life.', 'Other', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_dolphins_01', 'Can we swim with dolphins in Kizimkazi?', 'Kizimkazi is world-renowned for resident pods of wild bottlenose and spinner dolphins in the Menai Bay Conservation Area. We arrange ethical sunrise boat departures with licensed marine conservation guides right from our shore.', 'Other', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_family_01', 'Is Zanzirangi House suitable for families with children?', 'Families are warmly welcomed. We offer interconnecting villa sanctuaries, extra rollaway beds, tailored kids menus, and professional babysitting upon request.', 'Family', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_honeymoon_01', 'What special amenities are available for honeymoon couples?', 'For honeymooners, we prepare complimentary chilled Champagne, fresh tropical floral arrangements, an intimate sunset dhow cruise, and a romantic beach dinner under the stars.', 'Villa', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_payment_01', 'What payment methods and cancellation policies apply?', 'We accept major credit cards (Visa, MasterCard, Amex), international bank wire transfers, and mobile payments. Flexible cancellation terms apply up to 14 days prior to arrival with full refund.', 'Pricing', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_safari_01', 'How can we arrange a Serengeti fly-in safari expedition?', 'We organize chartered fly-in safaris directly from Zanzibar airport (approx. 1h 45m) to Serengeti National Park, Ngorongoro Crater, and Tarangire with luxury partner tented camps overlooking migration corridors.', 'Safari', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_spa_01', 'What spa treatments and massage therapies are offered?', 'Our in-villa holistic wellness treatments feature cold-pressed Zanzibari coconut oils, clove and cinnamon body scrubs, and soothing deep-tissue massages performed on your private oceanfront sun deck.', 'Wellness', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_stonetown_01', 'Can you organize a guided Stone Town and spice plantation tour?', 'We organize private cultural journeys with master Swahili historians through UNESCO-listed Stone Town, followed by a sensory walk through an organic spice plantation tasting fresh vanilla, nutmeg, and cloves.', 'Other', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_transfer_01', 'How does the airport transfer work and how far is it?', 'Zanzirangi House is located in Kizimkazi Dimbani, approximately 55 minutes from Abeid Amani Karume International Airport (ZNZ). We provide private luxury VIP chauffeur transfers with refreshing cold towels and tropical refreshments upon arrival.', 'Airport Transfer', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:37', '2026-09-27 20:27:37');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_villas_01', 'Do all villas have private plunge pools and beach access?', 'Every single one of our 8 luxury sanctuaries features its own private freshwater infinity plunge pool, sun loungers, outdoor stone showers, and direct private pathway access to the shores of the Indian Ocean.', 'Villa', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `support_knowledge_base` (`id`, `question`, `answer`, `category`, `language`, `status`, `source`, `created_at`, `updated_at`) VALUES ('kb_wifi_01', 'Is there high-speed Wi-Fi available across the property?', 'Yes! High-speed Starlink satellite Wi-Fi (150+ Mbps) is complimentary across all private villas, lush gardens, swimming pools, and dining pavilions, ensuring seamless connectivity for streaming or remote work.', 'Wi-Fi', 'en', 'PUBLISHED', 'FAQ_IMPORT', '2026-09-27 20:27:38', '2026-09-27 20:27:38');
INSERT INTO `testimonials` (`id`, `guest_name`, `country`, `avatar_url`, `rating`, `stay_date`, `villa_stayed`, `title`, `review_text`, `verified_stay`, `featured`, `sort_order`, `visible`) VALUES ('rev-01', 'Eleanor & Marcus Vance', 'United Kingdom', NULL, 5, 'November 2025', 'Sultan Oceanfront Villa', 'An absolute paradise beyond all expectations', 'From the moment our private chauffeur welcomed us at Zanzibar Airport to our final sunset dhow sail, every detail was orchestrated to absolute perfection. The plunge pool perched over the ocean tide was magical.', 1, 1, 1, 1);
INSERT INTO `testimonials` (`id`, `guest_name`, `country`, `avatar_url`, `rating`, `stay_date`, `villa_stayed`, `title`, `review_text`, `verified_stay`, `featured`, `sort_order`, `visible`) VALUES ('rev-02', 'Jean-Philippe de Montmirail', 'France', NULL, 5, 'January 2026', 'Makuti Garden Sanctuary', 'Authentic elegance and supreme tranquility', 'The architectural restraint, use of indigenous coral stone, and attentive but discrete butler service reminded us of the very finest Aman or Singita lodges. The Swahili coconut seafood dinner was unforgettable.', 1, 1, 2, 1);
INSERT INTO `testimonials` (`id`, `guest_name`, `country`, `avatar_url`, `rating`, `stay_date`, `villa_stayed`, `title`, `review_text`, `verified_stay`, `featured`, `sort_order`, `visible`) VALUES ('rev-03', 'Clara & Henrik Lindström', 'Sweden', NULL, 5, 'February 2026', 'The Royal Presidential Villa', 'The ultimate private sanctuary in East Africa', 'We traveled as a family of five. Having our own private infinity pool suspended above the coral lagoon and our personal chef preparing fresh catches each evening redefined what luxury travel means to us.', 1, 1, 3, 1);
INSERT INTO `testimonials` (`id`, `guest_name`, `country`, `avatar_url`, `rating`, `stay_date`, `villa_stayed`, `title`, `review_text`, `verified_stay`, `featured`, `sort_order`, `visible`) VALUES ('rev-04', 'Dr. Tariq & Amina Al-Mansoor', 'United Arab Emirates', NULL, 5, 'December 2025', 'Zanzibar Spice Villa', 'Deeply restorative and culturally rich', 'The antique carved brass doors and private lap pool created a serene atmosphere. Waking up to ocean breezes and seeing wild dolphins on the sunrise dhow excursion was a lifelong highlight.', 1, 0, 4, 1);
INSERT INTO `testimonials` (`id`, `guest_name`, `country`, `avatar_url`, `rating`, `stay_date`, `villa_stayed`, `title`, `review_text`, `verified_stay`, `featured`, `sort_order`, `visible`) VALUES ('rev-05', 'Sipho & Lerato Khumalo', 'South Africa', NULL, 5, 'October 2025', 'Coral Cove Villa', 'Genuine African hospitality at an international standard', 'Stepping directly from our villa deck into the warm turquoise Indian Ocean was pure bliss. The staff’s warmth and attention to detail made us feel like honored family in Tanzania.', 1, 0, 5, 1);
