INSERT INTO `video_storyboard` (`id`, `video_url`, `poster_image`, `scenes_json`) VALUES (1, './Zanzirangi-home.mp4', 'https://images.unsplash.com/photo-1540541338287-41700207dee6?auto=format&fit=crop&w=1600&q=85', '[{\"id\":\"sc-1\",\"order\":1,\"description\":\"Private airport chauffeur arrival & traditional iced lemongrass towel welcome\"},{\"id\":\"sc-2\",\"order\":2,\"description\":\"Makuti timber architecture nestled within ancient baobab groves\"},{\"id\":\"sc-3\",\"order\":3,\"description\":\"Handcrafted teak interiors, floor-to-ceiling glass, and limestone plunge pool\"},{\"id\":\"sc-4\",\"order\":4,\"description\":\"Freshwater infinity pool overlooking the turquoise Menai Bay reef\"},{\"id\":\"sc-5\",\"order\":5,\"description\":\"Farm-fresh Swahili spices, wild yellowfin tuna, and candlelit ocean pavilion\"},{\"id\":\"sc-6\",\"order\":6,\"description\":\"Hand-hewn dhow wooden boat sailing into the Indian Ocean golden twilight\"},{\"id\":\"sc-7\",\"order\":7,\"description\":\"The gateway to the Serengeti & wild Tanzanian mainland expeditions\"}]');
