INSERT INTO `villas` (`id`, `name`, `short_name`, `type`, `subtitle`, `short_description`, `description`, `price_per_night`, `price_unit`, `promotional_price`, `size_sqm`, `max_guests`, `bedrooms`, `bathrooms`, `beds_count`, `bed_type`, `bathroom_type`, `view_type`, `architectural_feature`, `hero_image`, `cover_image`, `status`, `featured`, `sort_order`) VALUES ('villa-01', 'Sultan Oceanfront Villa', 'Sultan Oceanfront Villa', 'Master Ocean Villa with Private Plunge Pool', '', 'Perched directly above the coral cliff with uninterrupted ocean vistas, private plunge pool, and dedicated butler service.', 'The Sultan Oceanfront Villa represents the pinnacle of barefoot luxury in Zanzibar. Inspired by classical Omani architecture and Swahili maritime traditions, this sanctuary features high timber ceilings, polished lime plaster walls, and expansive floor-to-ceiling glass that dissolves the boundary between indoors and the Indian Ocean. Step out onto your private sun deck with an infinity plunge pool, or unwind in the carved stone soak tub overlooking the evening dhows.', '0.00', 'USD', '0.00', 95, 2, 1, 1, 1, 'Handcrafted King Four-Poster Bed', 'En-suite Stone Wet Room & Outdoor Rain Shower', 'Direct Panoramic Indian Ocean & Sunset', 'Private plunge pool carved into coastal limestone with sunken sea lounge', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=1600&q=85', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=1600&q=85', 'draft', 1, 1);
INSERT INTO `villas` (`id`, `name`, `short_name`, `type`, `subtitle`, `short_description`, `description`, `price_per_night`, `price_unit`, `promotional_price`, `size_sqm`, `max_guests`, `bedrooms`, `bathrooms`, `beds_count`, `bed_type`, `bathroom_type`, `view_type`, `architectural_feature`, `hero_image`, `cover_image`, `status`, `featured`, `sort_order`) VALUES ('villa-02', 'Makuti Garden Sanctuary', 'Makuti Garden Sanctuary', 'Secluded Botanical Garden Villa', NULL, 'Tucked within fragrant frangipani and coconut palms, offering total seclusion, an open-air stone shower, and serene garden verandah.', 'Immersed in indigenous tropical gardens, Villa 02 offers complete tranquility and privacy. Constructed using sustainably harvested timber, coconut palm thatch, and local coral ragstone, the villa remains naturally cool under the equatorial sun. Enjoy lazy afternoons reading on the daybed surrounded by birdsong, or indulge in an open-air rainwater shower under the canopy of night stars.', '390.00', 'USD', '350.00', 78, 2, 1, 1, 1, 'King Canopy Bed with Fine Egyptian Linen', 'Tropical Outdoor Garden Shower & Double Vanity', 'Lush Botanical Gardens & Water Lilies', 'Traditional artisanal thatched makuti roof with natural cross-ventilation', './zanzirangi-villas.jpg', './zanzirangi-villas.jpg', 'published', 0, 2);
INSERT INTO `villas` (`id`, `name`, `short_name`, `type`, `subtitle`, `short_description`, `description`, `price_per_night`, `price_unit`, `promotional_price`, `size_sqm`, `max_guests`, `bedrooms`, `bathrooms`, `beds_count`, `bed_type`, `bathroom_type`, `view_type`, `architectural_feature`, `hero_image`, `cover_image`, `status`, `featured`, `sort_order`) VALUES ('villa-03', 'Coral Cove Villa', 'Coral Cove Villa', 'Direct Beach Access Ocean Villa', NULL, 'Wake up to the soft rustle of palms and step straight from your wooden deck onto the powdery white sand of the Indian Ocean.', 'A beachfront haven designed for ocean lovers. Villa 03 provides direct, private access to the crystalline waters of southern Zanzibar. Custom hardwood furnishings, hand-loomed linen throws, and curated African sculpture create an atmosphere of understated sophistication. Step outside barefoot to watch traditional fisherman dhows drift across the sunrise.', '440.00', 'USD', '400.00', 85, 2, 1, 1, 1, 'King Size Heritage Teak Bed', 'Marble En-Suite with Deep Bath', 'Direct Turquoise Lagoon & White Sand', 'Step-down sandy path directly reaching private sun loungers on the shore', 'https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1400&q=85', 'https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1400&q=85', 'published', 0, 3);
INSERT INTO `villas` (`id`, `name`, `short_name`, `type`, `subtitle`, `short_description`, `description`, `price_per_night`, `price_unit`, `promotional_price`, `size_sqm`, `max_guests`, `bedrooms`, `bathrooms`, `beds_count`, `bed_type`, `bathroom_type`, `view_type`, `architectural_feature`, `hero_image`, `cover_image`, `status`, `featured`, `sort_order`) VALUES ('villa-04', 'Kizimkazi Horizon Villa', 'Kizimkazi Horizon Villa', 'Elevated Oceanview Pavilion', NULL, 'Elevated for supreme sea breezes and unobstructed horizons, featuring a wide panoramic verandah perfect for dolphin watching.', 'Set on an elevated crest of the property, Villa 04 commands sweeping 180-degree vistas across Menai Bay Marine Sanctuary. During high tide, dolphins can frequently be spotted jumping along the outer reef line. The interior balances minimalist contemporary lines with warm earth tones, brass fixtures, and woven raffia accents.', '460.00', 'USD', '410.00', 90, 3, 1, 1, 1, 'King Bed + Daybed Lounger', 'Twin Vanities & Panoramic Walk-in Shower', 'Elevated 180° Ocean Horizon & Marine Reserve', 'Cantilevered timber deck extending out towards the marine sanctuary', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1400&q=85', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1400&q=85', 'published', 0, 4);
INSERT INTO `villas` (`id`, `name`, `short_name`, `type`, `subtitle`, `short_description`, `description`, `price_per_night`, `price_unit`, `promotional_price`, `size_sqm`, `max_guests`, `bedrooms`, `bathrooms`, `beds_count`, `bed_type`, `bathroom_type`, `view_type`, `architectural_feature`, `hero_image`, `cover_image`, `status`, `featured`, `sort_order`) VALUES ('villa-05', 'Baobab Palm Pavilion', 'Baobab Palm Pavilion', 'Two-Bedroom Family or Couple Suite', NULL, 'A spacious two-bedroom sanctuary surrounded by sculptural baobabs, perfect for families or small groups seeking quiet luxury.', 'Centered around an ancient, revered Baobab tree, this generous two-bedroom pavilion provides exceptional comfort for traveling companions or families. Featuring a shaded central living courtyard, two independent master suites each with their own open-air bathroom, and a private dining pergola.', '590.00', 'USD', '540.00', 130, 4, 2, 2, 2, 'Two King Beds (or King + Twin Suite)', '2 Private En-Suite Bathrooms', 'Ancient Baobab Trees & Distant Ocean Glimpse', 'Private enclosed courtyard wrapped around a centenary baobab tree', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1400&q=85', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1400&q=85', 'published', 0, 5);
INSERT INTO `villas` (`id`, `name`, `short_name`, `type`, `subtitle`, `short_description`, `description`, `price_per_night`, `price_unit`, `promotional_price`, `size_sqm`, `max_guests`, `bedrooms`, `bathrooms`, `beds_count`, `bed_type`, `bathroom_type`, `view_type`, `architectural_feature`, `hero_image`, `cover_image`, `status`, `featured`, `sort_order`) VALUES ('villa-06', 'Zanzibar Spice Villa', 'Zanzibar Spice Villa', 'Heritage Villa with Private Lap Pool', NULL, 'Celebrates Zanzibar’s fabled spice heritage with authentic carved doors, private lap pool, and aromatic botanical courtyard.', 'A tribute to the Spice Island’s golden age of artisanal craftsmanship. Villa 06 features authentic brass-studded carved doors from Stone Town master carvers, hand-poured terrazzo floors, and a private 12-meter fresh water lap pool fringed by clove and lemongrass bushes.', '520.00', 'USD', '470.00', 110, 2, 1, 1, 1, 'Hand-Carved Zanzibar Teak King Bed', 'Stone En-Suite & Copper Soaking Tub', 'Private Pool, Coconut Grove & Ocean Shimmer', 'Hand-chiseled antique Swahili brass-studded doors and 12m private lap pool', 'https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=1400&q=85', 'https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=1400&q=85', 'published', 0, 6);
INSERT INTO `villas` (`id`, `name`, `short_name`, `type`, `subtitle`, `short_description`, `description`, `price_per_night`, `price_unit`, `promotional_price`, `size_sqm`, `max_guests`, `bedrooms`, `bathrooms`, `beds_count`, `bed_type`, `bathroom_type`, `view_type`, `architectural_feature`, `hero_image`, `cover_image`, `status`, `featured`, `sort_order`) VALUES ('villa-07', 'Serengeti Breeze Villa', 'Serengeti Breeze Villa', 'Minimalist Modern Coastal Villa', NULL, 'Sleek architectural lines, warm natural materials, and an exclusive rooftop observation deck for equatorial stargazing.', 'Conceived for the design-conscious traveler, Villa 07 fuses Japanese-Scandinavian minimalism with East African earthiness. Soothing neutral tones, hand-woven sisal carpets, and an exclusive rooftop observation deck equipped with daybeds make this a haven for moonlit relaxation and tranquil meditation.', '450.00', 'USD', '410.00', 88, 2, 1, 1, 1, 'Ultra-Comfort King Bed with Natural Latex Mattress', 'Minimalist Terrazzo Shower & Garden Tub', 'Ocean Panorama & Rooftop Stargazing Deck', 'Private spiral stairs leading to rooftop starlight daybed', 'https://images.unsplash.com/photo-1618773928121-c32242e63f39?auto=format&fit=crop&w=1400&q=85', 'https://images.unsplash.com/photo-1618773928121-c32242e63f39?auto=format&fit=crop&w=1400&q=85', 'published', 0, 7);
INSERT INTO `villas` (`id`, `name`, `short_name`, `type`, `subtitle`, `short_description`, `description`, `price_per_night`, `price_unit`, `promotional_price`, `size_sqm`, `max_guests`, `bedrooms`, `bathrooms`, `beds_count`, `bed_type`, `bathroom_type`, `view_type`, `architectural_feature`, `hero_image`, `cover_image`, `status`, `featured`, `sort_order`) VALUES ('villa-08', 'The Royal Presidential Villa', 'The Royal Presidential Villa', 'Grand Two-Story Master Estate', NULL, 'The flagship residence of Zanzirangi House. Unparalleled oceanfront grandeur, multi-level infinity pools, and discrete private hosting.', 'The estate’s most exclusive address. Set on its own secluded promontory, The Royal Presidential Villa offers total autonomy, expansive entertaining salons, a private oceanfront infinity pool suspended over the coral lagoon, a private chef service on request, and direct private beach access.', '950.00', 'USD', '890.00', 240, 6, 3, 3, 3, '2 King Master Suites + Twin Bedroom', '3 Luxurious En-Suite Bathrooms + Powder Room', 'Unrivaled 360° Indian Ocean & Coastal Bluff', 'Private infinity pool, chef prep kitchen, private dhow jetty, and dedicated 24-hour butler team', 'https://images.unsplash.com/photo-1540541338287-41700207dee6?auto=format&fit=crop&w=1600&q=85', 'https://images.unsplash.com/photo-1540541338287-41700207dee6?auto=format&fit=crop&w=1600&q=85', 'published', 1, 8);
INSERT INTO `why_stay_config` (`id`, `eyebrow`, `heading`, `subhead`, `pillars_json`, `created_at`, `updated_at`, `updated_by`, `extras_json`) VALUES (1, 'The Sanctuary Difference', 'WHY ZANZIRANGI HOUSE', 'Four guiding values define every moment at our retreat, creating a rare atmosphere of calm, exclusivity, and profound connection to Tanzania.', '[{\"id\":\"pillar-1\",\"number\":\"01\",\"title\":\"PRIVATE & PEACEFUL\",\"tagline\":\"A private sanctuary away from the crowds.\",\"description\":\"Tucked along the pristine southern coastline of Kizimkazi, far from tourist congestion. Here, time is measured by the tidal ebb and flow, the rustle of palms, and unobstructed ocean horizons.\",\"image\":\"https://images.unsplash.com/photo-1540541338287-41700207dee6?auto=format&fit=crop&w=1200&q=85\",\"order\":1,\"visible\":true},{\"id\":\"pillar-2\",\"number\":\"02\",\"title\":\"AUTHENTIC ZANZIBAR\",\"tagline\":\"Experience the island through its people, flavours and culture.\",\"description\":\"From master Swahili woodcarvers and centuries-old makuti thatched pavilions to organic spices harvested daily from our estate gardens, experience the genuine soul of the Spice Island.\",\"image\":\"https://images.unsplash.com/photo-1578683010236-d716f9a3f461?auto=format&fit=crop&w=1200&q=85\",\"order\":2,\"visible\":true},{\"id\":\"pillar-3\",\"number\":\"03\",\"title\":\"PERSONAL CONCIERGE\",\"tagline\":\"From airport arrival to safari planning.\",\"description\":\"A dedicated host and concierge team attentive to your every need. Private airport tarmac greetings, chartered boat launches, in-villa dining, and discreet personal hospitality throughout.\",\"image\":\"https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=1200&q=85\",\"order\":3,\"visible\":true},{\"id\":\"pillar-4\",\"number\":\"04\",\"title\":\"TANZANIA BEYOND\",\"tagline\":\"Connect your Zanzibar stay with the wonders of mainland Tanzania.\",\"description\":\"Seamlessly combine oceanfront rest with chartered fly-in bush safaris to the Serengeti, Ngorongoro Crater, and Tarangire, creating a complete and unforgettable East African journey.\",\"image\":\"https://images.unsplash.com/photo-1516426122078-c23e76319801?auto=format&fit=crop&w=1200&q=85\",\"order\":4,\"visible\":true}]', '2026-09-30 17:56:16', '2026-10-01 00:43:34', 'info@zanzirangihouse.com', NULL);
