-- Zanzirangi House Staging Database Init
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `action` varchar(100) NOT NULL,
  `user_email` varchar(191) NOT NULL,
  `details` text DEFAULT NULL,
  `ip_address` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_audit_time` (`created_at` DESC)
) ENGINE=InnoDB AUTO_INCREMENT=290 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `chauffeur_config`;
CREATE TABLE `chauffeur_config` (
  `id` int(11) NOT NULL DEFAULT 1,
  `eyebrow` varchar(255) NOT NULL,
  `heading` varchar(255) NOT NULL,
  `subhead` text NOT NULL,
  `route_label` varchar(100) NOT NULL,
  `route_title` varchar(255) NOT NULL,
  `vehicle_image` varchar(500) NOT NULL,
  `specs_eyebrow` varchar(100) NOT NULL,
  `card_title` varchar(255) NOT NULL,
  `airport_title` varchar(255) NOT NULL,
  `airport_desc` text NOT NULL,
  `shuttle_title` varchar(255) NOT NULL,
  `shuttle_desc` text NOT NULL,
  `vehicle_type_title` varchar(100) NOT NULL,
  `vehicle_type_desc` varchar(255) NOT NULL,
  `passenger_luggage_title` varchar(100) NOT NULL,
  `passenger_luggage_desc` varchar(255) NOT NULL,
  `amenities_note` text NOT NULL,
  `cta_request_label` varchar(100) NOT NULL,
  `cta_add_booking_label` varchar(100) NOT NULL,
  `spec_items_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`spec_items_json`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `updated_by` varchar(191) DEFAULT NULL,
  `extras_json` longtext DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `contact_settings`;
CREATE TABLE `contact_settings` (
  `id` int(11) NOT NULL DEFAULT 1,
  `phone` varchar(100) DEFAULT NULL,
  `email` varchar(191) DEFAULT NULL,
  `whatsapp_number` varchar(100) DEFAULT NULL,
  `concierge_phone` varchar(100) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `google_maps_url` varchar(500) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `content_translations`;
CREATE TABLE `content_translations` (
  `lang` varchar(8) NOT NULL,
  `entity` varchar(64) NOT NULL,
  `path` varchar(255) NOT NULL,
  `value` mediumtext NOT NULL,
  `source` mediumtext DEFAULT NULL,
  `updated_by` varchar(255) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`lang`,`entity`,`path`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dining_categories`;
CREATE TABLE `dining_categories` (
  `id` varchar(100) NOT NULL,
  `name` varchar(191) NOT NULL,
  `tab_label` varchar(100) NOT NULL,
  `subtitle` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `image_url` varchar(500) NOT NULL,
  `dishes_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`dishes_json`)),
  `sort_order` int(11) DEFAULT 0,
  `visible` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `extras_json` longtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_dining_order` (`sort_order`,`visible`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `dining_config`;
CREATE TABLE `dining_config` (
  `id` int(11) NOT NULL DEFAULT 1,
  `eyebrow` varchar(255) NOT NULL,
  `heading` varchar(255) NOT NULL,
  `subhead` text NOT NULL,
  `intro` text NOT NULL,
  `garden_eyebrow` varchar(255) NOT NULL,
  `garden_badge` varchar(100) NOT NULL,
  `garden_title` varchar(255) NOT NULL,
  `garden_desc` text NOT NULL,
  `tag_zero_miles` varchar(100) NOT NULL,
  `tag_spices` varchar(100) NOT NULL,
  `tag_seafood` varchar(100) NOT NULL,
  `moments_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`moments_json`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `updated_by` varchar(191) DEFAULT NULL,
  `extras_json` longtext DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `experiences`;
CREATE TABLE `experiences` (
  `id` varchar(100) NOT NULL,
  `title` varchar(255) NOT NULL,
  `category` varchar(50) NOT NULL,
  `duration` varchar(100) DEFAULT NULL,
  `tag` varchar(100) DEFAULT NULL,
  `price_note` varchar(100) DEFAULT NULL,
  `short_description` text DEFAULT NULL,
  `description` text DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  `whatsapp_message` text DEFAULT NULL,
  `sort_order` int(11) DEFAULT 0,
  `visible` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `extras_json` longtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_exp_cat` (`category`,`sort_order`,`visible`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `facilities`;
CREATE TABLE `facilities` (
  `id` varchar(100) NOT NULL,
  `title` varchar(191) NOT NULL,
  `category` varchar(100) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `hours` varchar(100) DEFAULT NULL,
  `highlight` varchar(255) DEFAULT NULL,
  `image_url` varchar(500) NOT NULL,
  `icon` varchar(100) DEFAULT NULL,
  `sort_order` int(11) DEFAULT 0,
  `visible` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_facilities_order` (`sort_order`,`visible`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `gallery_categories`;
CREATE TABLE `gallery_categories` (
  `id` varchar(100) NOT NULL,
  `name` varchar(191) NOT NULL,
  `description` text DEFAULT NULL,
  `sort_order` int(11) DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `gallery_items`;
CREATE TABLE `gallery_items` (
  `id` varchar(100) NOT NULL,
  `category` varchar(100) NOT NULL,
  `title` varchar(191) NOT NULL,
  `caption` text DEFAULT NULL,
  `description` text DEFAULT NULL,
  `image_url` varchar(500) NOT NULL,
  `aspect_ratio` varchar(20) DEFAULT '4/3',
  `sort_order` int(11) DEFAULT 0,
  `published` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_gallery_cat` (`category`,`sort_order`,`published`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `global_content`;
CREATE TABLE `global_content` (
  `id` int(11) NOT NULL DEFAULT 1,
  `brand_name` varchar(191) NOT NULL DEFAULT 'Zanzirangi House',
  `nav_links_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`nav_links_json`)),
  `cta_plan_stay_label` varchar(100) NOT NULL DEFAULT 'PLAN YOUR STAY',
  `cta_plan_stay_link` varchar(255) NOT NULL DEFAULT '#stay',
  `footer_tagline` text DEFAULT NULL,
  `footer_copyright` text DEFAULT NULL,
  `contact_phone` varchar(100) DEFAULT NULL,
  `contact_email` varchar(191) DEFAULT NULL,
  `contact_whatsapp` varchar(100) DEFAULT NULL,
  `contact_address` text DEFAULT NULL,
  `socials_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`socials_json`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `updated_by` varchar(191) DEFAULT NULL,
  `extras_json` longtext DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `hero_slides`;
CREATE TABLE `hero_slides` (
  `id` varchar(100) NOT NULL,
  `title` varchar(255) NOT NULL,
  `subtitle` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `badge_text` varchar(100) DEFAULT NULL,
  `primary_cta_text` varchar(100) DEFAULT NULL,
  `primary_cta_link` varchar(255) DEFAULT NULL,
  `secondary_cta_text` varchar(100) DEFAULT NULL,
  `secondary_cta_link` varchar(255) DEFAULT NULL,
  `image_url` varchar(500) NOT NULL,
  `video_url` varchar(500) DEFAULT NULL,
  `alignment` varchar(50) DEFAULT 'center',
  `overlay_opacity` decimal(3,2) DEFAULT 0.40,
  `sort_order` int(11) DEFAULT 0,
  `visible` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_hero_slides_order` (`sort_order`,`visible`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `homepage_config`;
CREATE TABLE `homepage_config` (
  `id` int(11) NOT NULL DEFAULT 1,
  `hero_title` varchar(255) NOT NULL,
  `hero_subtitle` varchar(255) DEFAULT NULL,
  `hero_description` text DEFAULT NULL,
  `hero_badge_text` varchar(100) DEFAULT NULL,
  `hero_primary_cta_text` varchar(100) DEFAULT NULL,
  `hero_primary_cta_link` varchar(255) DEFAULT NULL,
  `hero_secondary_cta_text` varchar(100) DEFAULT NULL,
  `hero_secondary_cta_link` varchar(255) DEFAULT NULL,
  `hero_image` varchar(500) DEFAULT NULL,
  `auto_play_interval` int(11) DEFAULT 6,
  `intro_eyebrow` varchar(100) DEFAULT NULL,
  `intro_title` varchar(255) DEFAULT NULL,
  `intro_description` text DEFAULT NULL,
  `contact_phone` varchar(100) DEFAULT NULL,
  `contact_email` varchar(191) DEFAULT NULL,
  `contact_whatsapp` varchar(100) DEFAULT NULL,
  `contact_address` text DEFAULT NULL,
  `socials_json` text DEFAULT NULL,
  `footer_copyright` text DEFAULT NULL,
  `footer_tagline` text DEFAULT NULL,
  `meta_last_updated` timestamp NULL DEFAULT NULL,
  `meta_updated_by` varchar(191) DEFAULT NULL,
  `extras_json` longtext DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `homepage_sections`;
CREATE TABLE `homepage_sections` (
  `id` varchar(100) NOT NULL,
  `label` varchar(191) NOT NULL,
  `description` text DEFAULT NULL,
  `sort_order` int(11) DEFAULT 0,
  `visible` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_sections_order` (`sort_order`,`visible`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `media_assets`;
CREATE TABLE `media_assets` (
  `id` varchar(100) NOT NULL,
  `filename` varchar(255) NOT NULL,
  `original_filename` varchar(255) DEFAULT NULL,
  `mime_type` varchar(100) NOT NULL,
  `size` bigint(20) NOT NULL DEFAULT 0,
  `size_bytes` bigint(20) NOT NULL DEFAULT 0,
  `storage_path` varchar(500) DEFAULT NULL,
  `public_url` varchar(500) NOT NULL,
  `url` varchar(500) NOT NULL,
  `width` int(11) DEFAULT NULL,
  `height` int(11) DEFAULT NULL,
  `alt_text` varchar(255) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `caption` text DEFAULT NULL,
  `usage_count` int(11) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_media_filename` (`filename`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `page_contents`;
CREATE TABLE `page_contents` (
  `id` varchar(100) NOT NULL,
  `slug` varchar(100) NOT NULL,
  `title` varchar(255) NOT NULL,
  `eyebrow` varchar(255) DEFAULT NULL,
  `heading` varchar(255) DEFAULT NULL,
  `subheading` text DEFAULT NULL,
  `description` text DEFAULT NULL,
  `hero_image` varchar(500) DEFAULT NULL,
  `sections_config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`sections_config`)),
  `content_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`content_json`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `updated_by` varchar(191) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_page_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `safari_destinations`;
CREATE TABLE `safari_destinations` (
  `id` varchar(100) NOT NULL,
  `name` varchar(191) NOT NULL,
  `tagline` varchar(255) DEFAULT NULL,
  `region` varchar(100) DEFAULT NULL,
  `flight_time` varchar(100) DEFAULT NULL,
  `hero_image` varchar(500) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `highlights_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`highlights_json`)),
  `best_for` varchar(255) DEFAULT NULL,
  `safari_type` varchar(100) DEFAULT NULL,
  `sort_order` int(11) DEFAULT 0,
  `visible` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `extras_json` longtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_safari_order` (`sort_order`,`visible`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `schema_migrations`;
CREATE TABLE `schema_migrations` (
  `version` varchar(100) NOT NULL,
  `applied_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `seo_routes`;
CREATE TABLE `seo_routes` (
  `route_path` varchar(100) NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `canonical_url` varchar(500) DEFAULT NULL,
  `og_title` varchar(255) DEFAULT NULL,
  `og_description` text DEFAULT NULL,
  `og_image` varchar(500) DEFAULT NULL,
  `robots` varchar(100) DEFAULT 'index, follow',
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`route_path`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `site_settings`;
CREATE TABLE `site_settings` (
  `id` int(11) NOT NULL DEFAULT 1,
  `site_name` varchar(191) NOT NULL DEFAULT 'Zanzirangi House',
  `tagline` text DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `concierge_phone` varchar(50) DEFAULT NULL,
  `whatsapp` varchar(50) DEFAULT NULL,
  `email` varchar(191) DEFAULT NULL,
  `reservation_notification_email` varchar(191) DEFAULT NULL,
  `reservation_email` varchar(191) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `instagram` varchar(255) DEFAULT NULL,
  `facebook` varchar(255) DEFAULT NULL,
  `youtube` varchar(255) DEFAULT NULL,
  `booking_url` varchar(255) DEFAULT NULL,
  `currency` varchar(20) DEFAULT 'USD',
  `default_currency` varchar(20) DEFAULT 'USD ($)',
  `default_language` varchar(10) DEFAULT 'en',
  `logo` varchar(255) DEFAULT NULL,
  `favicon` varchar(255) DEFAULT NULL,
  `maintenance_mode` tinyint(1) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `support_ai_events`;
CREATE TABLE `support_ai_events` (
  `id` varchar(100) NOT NULL,
  `conversation_id` varchar(100) NOT NULL,
  `message_id` varchar(100) NOT NULL,
  `intent` varchar(100) NOT NULL,
  `confidence` decimal(4,3) NOT NULL,
  `knowledge_source` varchar(100) NOT NULL,
  `decision` enum('AUTO_ANSWER','SAFE_ANSWER','HANDOFF_TO_HUMAN') NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_ai_conv` (`conversation_id`),
  KEY `idx_ai_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `support_conversations`;
CREATE TABLE `support_conversations` (
  `id` varchar(100) NOT NULL,
  `visitor_id` varchar(100) NOT NULL,
  `session_id` varchar(100) NOT NULL,
  `status` enum('AI_ACTIVE','WAITING_HUMAN','HUMAN_ACTIVE','WAITING_FOR_VISITOR','RESOLVED','CLOSED') NOT NULL DEFAULT 'AI_ACTIVE',
  `language` varchar(10) NOT NULL DEFAULT 'en',
  `assigned_admin_id` varchar(100) DEFAULT NULL,
  `current_page` varchar(255) DEFAULT '/',
  `booking_id` varchar(100) DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `last_message_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_conv_visitor` (`visitor_id`),
  KEY `idx_conv_status` (`status`),
  KEY `idx_conv_last_message` (`last_message_at`),
  KEY `idx_conv_booking` (`booking_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `support_knowledge_base`;
CREATE TABLE `support_knowledge_base` (
  `id` varchar(100) NOT NULL,
  `question` text NOT NULL,
  `answer` text NOT NULL,
  `category` varchar(100) NOT NULL DEFAULT 'General',
  `language` varchar(10) NOT NULL DEFAULT 'en',
  `status` enum('PUBLISHED','DRAFT','UNPUBLISHED') NOT NULL DEFAULT 'PUBLISHED',
  `source` enum('MANUAL','CANDIDATE_FROM_ADMIN','FAQ_IMPORT') NOT NULL DEFAULT 'MANUAL',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_kb_status` (`status`),
  KEY `idx_kb_category` (`category`),
  KEY `idx_kb_language` (`language`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `support_messages`;
CREATE TABLE `support_messages` (
  `id` varchar(100) NOT NULL,
  `conversation_id` varchar(100) NOT NULL,
  `sender_type` enum('VISITOR','AI','ADMIN','SYSTEM') NOT NULL,
  `sender_id` varchar(100) NOT NULL,
  `message` text NOT NULL,
  `message_type` varchar(50) NOT NULL DEFAULT 'TEXT',
  `ai_confidence` decimal(4,3) DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_msg_conv` (`conversation_id`),
  KEY `idx_msg_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `testimonials`;
CREATE TABLE `testimonials` (
  `id` varchar(100) NOT NULL,
  `guest_name` varchar(191) NOT NULL,
  `country` varchar(100) DEFAULT NULL,
  `avatar_url` varchar(500) DEFAULT NULL,
  `rating` int(11) DEFAULT 5,
  `stay_date` varchar(100) DEFAULT NULL,
  `villa_stayed` varchar(191) DEFAULT NULL,
  `title` varchar(191) DEFAULT NULL,
  `review_text` text NOT NULL,
  `verified_stay` tinyint(1) DEFAULT 1,
  `featured` tinyint(1) DEFAULT 0,
  `sort_order` int(11) DEFAULT 0,
  `visible` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `idx_testimonials_order` (`sort_order`,`visible`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` varchar(100) NOT NULL,
  `email` varchar(191) NOT NULL,
  `name` varchar(191) NOT NULL,
  `role` varchar(50) NOT NULL DEFAULT 'admin',
  `password_hash` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `last_login` timestamp NULL DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'active',
  `permissions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`permissions`)),
  `token_version` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  KEY `idx_users_email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `video_items`;
CREATE TABLE `video_items` (
  `id` varchar(100) NOT NULL,
  `title` varchar(255) DEFAULT NULL,
  `video_url` varchar(500) NOT NULL,
  `poster_image` varchar(500) DEFAULT NULL,
  `sort_order` int(11) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `video_storyboard`;
CREATE TABLE `video_storyboard` (
  `id` int(11) NOT NULL DEFAULT 1,
  `video_url` varchar(500) NOT NULL,
  `poster_image` varchar(500) NOT NULL,
  `scenes_json` longtext NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `villa_amenities`;
CREATE TABLE `villa_amenities` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `villa_id` varchar(100) NOT NULL,
  `amenity_name` varchar(191) NOT NULL,
  `icon` varchar(100) DEFAULT NULL,
  `sort_order` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_villa_amenities` (`villa_id`),
  CONSTRAINT `villa_amenities_ibfk_1` FOREIGN KEY (`villa_id`) REFERENCES `villas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `villa_images`;
CREATE TABLE `villa_images` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `villa_id` varchar(100) NOT NULL,
  `image_url` varchar(500) NOT NULL,
  `alt_text` varchar(255) DEFAULT NULL,
  `sort_order` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_villa_images` (`villa_id`),
  CONSTRAINT `villa_images_ibfk_1` FOREIGN KEY (`villa_id`) REFERENCES `villas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `villas`;
CREATE TABLE `villas` (
  `id` varchar(100) NOT NULL,
  `name` varchar(191) NOT NULL,
  `short_name` varchar(100) DEFAULT NULL,
  `type` varchar(191) DEFAULT NULL,
  `subtitle` varchar(255) DEFAULT NULL,
  `short_description` text DEFAULT NULL,
  `description` text DEFAULT NULL,
  `price_per_night` decimal(10,2) NOT NULL DEFAULT 400.00,
  `price_unit` varchar(50) DEFAULT 'USD',
  `promotional_price` decimal(10,2) DEFAULT NULL,
  `size_sqm` int(11) DEFAULT 85,
  `max_guests` int(11) DEFAULT 2,
  `bedrooms` int(11) DEFAULT 1,
  `bathrooms` int(11) DEFAULT 1,
  `beds_count` int(11) DEFAULT 1,
  `bed_type` varchar(191) DEFAULT NULL,
  `bathroom_type` varchar(191) DEFAULT NULL,
  `view_type` varchar(191) DEFAULT NULL,
  `architectural_feature` text DEFAULT NULL,
  `hero_image` varchar(500) DEFAULT NULL,
  `cover_image` varchar(500) DEFAULT NULL,
  `status` varchar(50) DEFAULT 'published',
  `featured` tinyint(1) DEFAULT 0,
  `sort_order` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_villas_status` (`status`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `why_stay_config`;
CREATE TABLE `why_stay_config` (
  `id` int(11) NOT NULL DEFAULT 1,
  `eyebrow` varchar(255) NOT NULL,
  `heading` varchar(255) NOT NULL,
  `subhead` text NOT NULL,
  `pillars_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`pillars_json`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `updated_by` varchar(191) DEFAULT NULL,
  `extras_json` longtext DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


